        COALESCE(NEW.store_name, NEW.subdomain),
        NEW.tagline,
        NEW.logo_url,
        NEW.favicon_url,
        COALESCE(NEW.site_type, 'store'),
        COALESCE(NEW.subdomain, NEW.store_name),
        NEW.custom_domain,
        COALESCE(NEW.theme_id, 'modern'),
