DECLARE
  v_policy public.retention_policies;
BEGIN
  SELECT *
    INTO v_policy
    FROM public.retention_policies
   WHERE target_table = TG_TABLE_NAME
     AND lifecycle_mode IN ('partition-shadow', 'partition-live')
     AND deleted_at IS NULL;

  IF v_policy.id IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  IF to_regclass(format('public.%I', v_policy.shadow_table)) IS NULL THEN
    RAISE EXCEPTION 'partition shadow table % is missing', v_policy.shadow_table;
  END IF;

  IF TG_OP = 'DELETE' THEN
    EXECUTE format(
      'DELETE FROM public.%I WHERE id = ($1).id AND created_at = ($1).created_at',
      v_policy.shadow_table
    ) USING OLD;

    RETURN OLD;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    EXECUTE format(
      'DELETE FROM public.%I WHERE id = ($1).id AND created_at = ($1).created_at',
      v_policy.shadow_table
    ) USING NEW;
  END IF;

  EXECUTE format(
    'INSERT INTO public.%I SELECT ($1).* ON CONFLICT DO NOTHING',
    v_policy.shadow_table
  ) USING NEW;

  RETURN NEW;
END;

DECLARE
  v_statement text;
  v_trigger record;
  v_state text := CASE WHEN COALESCE(p_enabled, true) THEN 'ENABLE' ELSE 'DISABLE' END;
  v_changed text[] := ARRAY[]::text[];
BEGIN
  FOR v_trigger IN
    SELECT *
      FROM (VALUES
        ('worker_request_logs', 'mirror_worker_request_logs_partition_shadow'),
        ('runtime_telemetry_metrics', 'mirror_runtime_telemetry_metrics_partition_shadow'),
        ('outbox_events', 'mirror_outbox_events_partition_shadow'),
        ('platform_queue_jobs', 'mirror_platform_queue_jobs_partition_shadow'),
        ('webhook_deliveries', 'mirror_webhook_deliveries_partition_shadow')
      ) AS triggers(table_name, trigger_name)
  LOOP
    IF to_regclass(format('public.%I', v_trigger.table_name)) IS NOT NULL THEN
      v_statement := format(
        'ALTER TABLE public.%I %s TRIGGER %I',
        v_trigger.table_name,
        v_state,
        v_trigger.trigger_name
      );
      EXECUTE v_statement;
      v_changed := array_append(v_changed, v_trigger.table_name);
    END IF;
  END LOOP;

  UPDATE public.retention_policies
     SET notes = concat_ws(
           E'\n',
           NULLIF(notes, ''),
           format('Partition shadow mirror triggers %s at %s', lower(v_state), now())
         ),
         updated_at = now()
   WHERE target_table = ANY(v_changed)
     AND deleted_at IS NULL;

  RETURN jsonb_build_object(
    'enabled',
    COALESCE(p_enabled, true),
    'tables',
    v_changed
  );
END;

BEGIN
  PERFORM set_config('app.site_id', p_site_id::text, true);
END;

BEGIN
  RAISE EXCEPTION 'ledger is append-only; use reversing entries';
END;

DECLARE
  v_transaction_id uuid;
  v_delta bigint;
BEGIN
  v_transaction_id := COALESCE(NEW.transaction_id, OLD.transaction_id);

  SELECT COALESCE(SUM(
    CASE side
      WHEN 'debit' THEN amount_minor
      ELSE -amount_minor
    END
  ), 0)
    INTO v_delta
    FROM public.ledger_entries
   WHERE transaction_id = v_transaction_id;

  IF v_delta <> 0 THEN
    RAISE EXCEPTION 'ledger transaction % is not balanced: delta=%', v_transaction_id, v_delta;
  END IF;

  RETURN NULL;
END;

DECLARE
  v_account_id uuid;
BEGIN
  INSERT INTO public.ledger_accounts (site_id, currency, account_code, account_name)
  VALUES (p_site_id, p_currency, p_account_code, replace(p_account_code, '_', ' '))
  ON CONFLICT (site_id, currency, account_code)
  DO UPDATE SET updated_at = now()
  RETURNING id INTO v_account_id;

  RETURN v_account_id;
END;

DECLARE
  v_current_site_id uuid;
  v_transaction_id uuid;
  v_existing_id uuid;
  v_existing_currency text;
  v_existing_metadata jsonb;
  v_existing_lines jsonb;
  v_requested_lines jsonb;
  v_line jsonb;
  v_account_id uuid;
  v_sequence integer := 0;
  v_debits bigint := 0;
  v_credits bigint := 0;
  v_side text;
  v_amount bigint;
BEGIN
  v_current_site_id := public.current_site_id();
  IF v_current_site_id IS NULL OR v_current_site_id <> p_site_id THEN
    RAISE EXCEPTION 'tenant GUC site_id is required for ledger posting';
  END IF;

  IF p_currency IS DISTINCT FROM 'INR' THEN
    RAISE EXCEPTION 'ledger currency % is not supported', p_currency;
  END IF;

  IF jsonb_typeof(p_lines) IS DISTINCT FROM 'array' OR jsonb_array_length(p_lines) < 2 THEN
    RAISE EXCEPTION 'ledger posting requires at least two lines';
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'account_code', item.value->>'account_code',
    'side', item.value->>'side',
    'amount_minor', (item.value->>'amount_minor')::bigint,
    'sequence', item.ordinality::integer,
    'memo', NULLIF(item.value->>'memo', ''),
    'metadata', COALESCE(item.value->'metadata', '{}'::jsonb)
  ) ORDER BY item.ordinality), '[]'::jsonb)
    INTO v_requested_lines
    FROM jsonb_array_elements(p_lines) WITH ORDINALITY AS item(value, ordinality);

  INSERT INTO public.ledger_transactions (
    site_id,
    currency,
    source_type,
    source_id,
    idempotency_key,
    metadata,
    request_id
  )
  VALUES (
    p_site_id,
    p_currency,
    p_source_type,
    p_source_id,
    p_idempotency_key,
    COALESCE(p_metadata, '{}'::jsonb),
    p_request_id
  )
  ON CONFLICT (site_id, source_type, source_id, idempotency_key) DO NOTHING
  RETURNING id INTO v_transaction_id;

  IF v_transaction_id IS NULL THEN
    SELECT id, currency, metadata
      INTO v_existing_id, v_existing_currency, v_existing_metadata
      FROM public.ledger_transactions
     WHERE site_id = p_site_id
       AND source_type = p_source_type
       AND source_id = p_source_id
       AND idempotency_key = p_idempotency_key;

    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'account_code', account.account_code,
      'side', entry.side,
      'amount_minor', entry.amount_minor,
      'sequence', entry.sequence,
      'memo', entry.memo,
      'metadata', entry.metadata
    ) ORDER BY entry.sequence), '[]'::jsonb)
      INTO v_existing_lines
      FROM public.ledger_entries AS entry
      JOIN public.ledger_accounts AS account ON account.id = entry.account_id
     WHERE entry.transaction_id = v_existing_id;

    IF v_existing_id IS NULL
       OR v_existing_currency IS DISTINCT FROM p_currency
       -- A provider may deliver different authenticated event IDs for the same
       -- capture through verify and webhook paths. Those event receipts live in
       -- payment_webhook_events/payment_transactions; the ledger keeps the first
       -- event ID for reference, but it is not part of accounting request identity.
       OR (COALESCE(v_existing_metadata, '{}'::jsonb) - 'provider_event_id')
          IS DISTINCT FROM (COALESCE(p_metadata, '{}'::jsonb) - 'provider_event_id')
       OR v_existing_lines IS DISTINCT FROM v_requested_lines THEN
      RAISE EXCEPTION 'ledger idempotency key conflicts with a different request payload'
        USING ERRCODE = '23505';
    END IF;
    RETURN v_existing_id;
  END IF;

  FOR v_line IN SELECT value FROM jsonb_array_elements(p_lines)
  LOOP
    v_sequence := v_sequence + 1;
    v_side := v_line->>'side';
    v_amount := (v_line->>'amount_minor')::bigint;

    IF v_side NOT IN ('debit', 'credit') OR v_amount <= 0 THEN
      RAISE EXCEPTION 'invalid ledger line at sequence %', v_sequence;
    END IF;

    IF v_side = 'debit' THEN
      v_debits := v_debits + v_amount;
    ELSE
      v_credits := v_credits + v_amount;
    END IF;

    v_account_id := public.ensure_ledger_account(p_site_id, p_currency, v_line->>'account_code');

    INSERT INTO public.ledger_entries (
      transaction_id,
      site_id,
      account_id,
      currency,
      side,
      amount_minor,
      sequence,
      memo,
      metadata
    )
    VALUES (
      v_transaction_id,
      p_site_id,
      v_account_id,
      p_currency,
      v_side,
      v_amount,
      v_sequence,
      NULLIF(v_line->>'memo', ''),
      COALESCE(v_line->'metadata', '{}'::jsonb)
    );
  END LOOP;

  IF v_debits <> v_credits THEN
    RAISE EXCEPTION 'ledger posting must balance: debit=% credit=%', v_debits, v_credits;
  END IF;

  RETURN v_transaction_id;
END;

BEGIN
  IF NEW.store_id IS NULL THEN
    SELECT store_id INTO NEW.store_id
      FROM public.products
     WHERE id = NEW.product_id;
  END IF;
  RETURN NEW;
END;

BEGIN
  IF public.current_site_id() IS NULL OR public.current_site_id() <> p_store_id THEN
    RAISE EXCEPTION 'tenant GUC site_id is required for inventory mutation';
  END IF;
END;

DECLARE
  v_existing public.inventory_reservations%ROWTYPE;
  v_level public.inventory_levels%ROWTYPE;
  v_reservation public.inventory_reservations%ROWTYPE;
  v_expires_at timestamptz;
BEGIN
  PERFORM public.require_inventory_site_guc(p_store_id);

  IF p_quantity <= 0 THEN
    RAISE EXCEPTION 'inventory reservation quantity must be positive';
  END IF;

  IF p_idempotency_key IS NULL OR length(trim(p_idempotency_key)) < 8 THEN
    RAISE EXCEPTION 'inventory reservation idempotency key is required';
  END IF;

  SELECT * INTO v_existing
    FROM public.inventory_reservations
   WHERE store_id = p_store_id
     AND idempotency_key = p_idempotency_key
     AND deleted_at IS NULL
   LIMIT 1;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'reservation_id', v_existing.id,
      'status', v_existing.status,
      'quantity', v_existing.quantity,
      'expires_at', v_existing.expires_at,
      'idempotent', true
    );
  END IF;

  SELECT * INTO v_level
    FROM public.inventory_levels
   WHERE store_id = p_store_id
     AND product_id = p_product_id
     AND variant_id IS NOT DISTINCT FROM p_variant_id
     AND location_id = p_location_id
     AND deleted_at IS NULL
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'inventory level not found';
  END IF;

  IF (COALESCE(v_level.available, 0) - COALESCE(v_level.reserved, 0)) < p_quantity THEN
    RAISE EXCEPTION 'INSUFFICIENT_INVENTORY';
  END IF;

  v_expires_at := now() + make_interval(secs => LEAST(GREATEST(COALESCE(p_ttl_seconds, 1200), 60), 86400));

  UPDATE public.inventory_levels
     SET reserved = reserved + p_quantity,
         reserved_quantity = COALESCE(reserved_quantity, reserved) + p_quantity,
         available_quantity = COALESCE(available_quantity, available),
         on_hand_quantity = COALESCE(on_hand_quantity, available + reserved),
         updated_at = now()
   WHERE id = v_level.id;

  INSERT INTO public.inventory_reservations (
    store_id,
    product_id,
    variant_id,
    location_id,
    quantity,
    status,
    idempotency_key,
    expires_at,
    created_by
  ) VALUES (
    p_store_id,
    p_product_id,
    p_variant_id,
    p_location_id,
    p_quantity,
    'active',
    p_idempotency_key,
    v_expires_at,
    p_actor_id
  )
  RETURNING * INTO v_reservation;

  RETURN jsonb_build_object(
    'reservation_id', v_reservation.id,
    'status', v_reservation.status,
    'quantity', v_reservation.quantity,
    'expires_at', v_reservation.expires_at,
    'idempotent', false,
    'request_id', p_request_id
  );
END;

DECLARE
  v_reservation public.inventory_reservations%ROWTYPE;
  v_new_available integer;
BEGIN
  PERFORM public.require_inventory_site_guc(p_store_id);

  SELECT * INTO v_reservation
    FROM public.inventory_reservations
   WHERE id = p_reservation_id
     AND store_id = p_store_id
     AND deleted_at IS NULL
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'inventory reservation not found';
  END IF;

  IF v_reservation.status = 'committed' THEN
    RETURN jsonb_build_object('reservation_id', v_reservation.id, 'status', 'committed', 'idempotent', true);
  END IF;

  IF v_reservation.status NOT IN ('active', 'hold') THEN
    RAISE EXCEPTION 'inventory reservation cannot be committed from status %', v_reservation.status;
  END IF;

  UPDATE public.inventory_levels
     SET available = GREATEST(available - v_reservation.quantity, 0),
         reserved = GREATEST(reserved - v_reservation.quantity, 0),
         available_quantity = GREATEST(COALESCE(available_quantity, available) - v_reservation.quantity, 0),
         reserved_quantity = GREATEST(COALESCE(reserved_quantity, reserved) - v_reservation.quantity, 0),
         committed_quantity = COALESCE(committed_quantity, 0) + v_reservation.quantity,
         updated_at = now()
   WHERE store_id = p_store_id
     AND product_id = v_reservation.product_id
     AND variant_id IS NOT DISTINCT FROM v_reservation.variant_id
     AND location_id = v_reservation.location_id
   RETURNING available INTO v_new_available;

  -- T17: keep the shopper-visible cache in sync with the sale this reservation just finalized.
  IF v_reservation.variant_id IS NULL THEN
    UPDATE public.products SET stock = v_new_available, updated_at = now() WHERE id = v_reservation.product_id;
  ELSE
    UPDATE public.product_variants SET inventory_qty = v_new_available, updated_at = now() WHERE id = v_reservation.variant_id;
  END IF;

  UPDATE public.inventory_reservations
     SET status = 'committed',
         committed_at = now(),
         commit_idempotency_key = p_idempotency_key,
         updated_at = now()
   WHERE id = v_reservation.id
   RETURNING * INTO v_reservation;

  RETURN jsonb_build_object(
    'reservation_id', v_reservation.id,
    'status', v_reservation.status,
    'quantity', v_reservation.quantity,
    'request_id', p_request_id
  );
END;

DECLARE
  v_reservation public.inventory_reservations%ROWTYPE;
BEGIN
  PERFORM public.require_inventory_site_guc(p_store_id);

  SELECT * INTO v_reservation
    FROM public.inventory_reservations
   WHERE id = p_reservation_id
     AND store_id = p_store_id
     AND deleted_at IS NULL
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'inventory reservation not found';
  END IF;

  IF v_reservation.status IN ('released', 'expired', 'cancelled') THEN
    RETURN jsonb_build_object('reservation_id', v_reservation.id, 'status', v_reservation.status, 'idempotent', true);
  END IF;

  IF v_reservation.status NOT IN ('active', 'hold') THEN
    RAISE EXCEPTION 'inventory reservation cannot be released from status %', v_reservation.status;
  END IF;

  UPDATE public.inventory_levels
     SET reserved = GREATEST(reserved - v_reservation.quantity, 0),
         reserved_quantity = GREATEST(COALESCE(reserved_quantity, reserved) - v_reservation.quantity, 0),
         updated_at = now()
   WHERE store_id = p_store_id
     AND product_id = v_reservation.product_id
     AND variant_id IS NOT DISTINCT FROM v_reservation.variant_id
     AND location_id = v_reservation.location_id;

  UPDATE public.inventory_reservations
     SET status = 'released',
         released_at = now(),
         release_reason = COALESCE(p_reason, 'released'),
         release_idempotency_key = p_idempotency_key,
         updated_at = now()
   WHERE id = v_reservation.id
   RETURNING * INTO v_reservation;

  RETURN jsonb_build_object(
    'reservation_id', v_reservation.id,
    'status', v_reservation.status,
    'quantity', v_reservation.quantity,
    'request_id', p_request_id
  );
END;

