DECLARE
  v_entry public.wallet_ledger_entries%ROWTYPE;
  v_transaction_id uuid;
  v_lines jsonb;
  v_counts jsonb := '{}'::jsonb;
  v_site_id uuid;
  v_reconciliation public.money_ledger_site_reconciliations%ROWTYPE;
BEGIN
  FOR v_entry IN
    SELECT *
    FROM public.wallet_ledger_entries
    WHERE status = 'posted'
      AND deleted_at IS NULL
      AND canonical_ledger_transaction_id IS NULL
      AND amount_minor > 0
      AND (p_site_id IS NULL OR site_id = p_site_id)
    ORDER BY site_id, created_at, id
  LOOP
    PERFORM set_config('app.site_id', v_entry.site_id::text, true);
    IF v_entry.direction = 'credit' THEN
      v_lines := jsonb_build_array(
        jsonb_build_object('account_code', 'pa_clearing', 'side', 'debit', 'amount_minor', v_entry.amount_minor_bigint, 'memo', 'Wallet ledger compatibility backfill debit'),
        jsonb_build_object('account_code', 'merchant_payable', 'side', 'credit', 'amount_minor', v_entry.amount_minor_bigint, 'memo', 'Wallet ledger compatibility backfill credit')
      );
    ELSE
      v_lines := jsonb_build_array(
        jsonb_build_object('account_code', 'merchant_payable', 'side', 'debit', 'amount_minor', v_entry.amount_minor_bigint, 'memo', 'Wallet ledger compatibility backfill debit'),
        jsonb_build_object('account_code', 'pa_clearing', 'side', 'credit', 'amount_minor', v_entry.amount_minor_bigint, 'memo', 'Wallet ledger compatibility backfill credit')
      );
    END IF;

    v_transaction_id := public.post_settlement_ledger_transaction(
      v_entry.site_id,
      CASE WHEN v_entry.direction = 'credit' THEN 'settlement' ELSE 'payout' END,
      'wallet_ledger_entries:' || v_entry.id::text,
      COALESCE(v_entry.idempotency_key, 'wallet-ledger-backfill:' || v_entry.id::text),
      v_lines,
      jsonb_build_object('compatibility_table', 'wallet_ledger_entries', 'wallet_entry_id', v_entry.id),
      NULL
    );

    UPDATE public.wallet_ledger_entries
       SET canonical_ledger_transaction_id = v_transaction_id,
           amount_minor_bigint = COALESCE(amount_minor_bigint, amount_minor::bigint),
           updated_at = now()
     WHERE id = v_entry.id;

    v_counts := jsonb_set(
      v_counts,
      ARRAY[v_entry.site_id::text],
      to_jsonb(COALESCE((v_counts ->> v_entry.site_id::text)::integer, 0) + 1),
      true
    );
  END LOOP;

  FOR v_site_id IN
    SELECT DISTINCT site_id
    FROM public.wallet_ledger_entries
    WHERE deleted_at IS NULL
      AND (p_site_id IS NULL OR site_id = p_site_id)
  LOOP
    v_reconciliation := public.assert_money_ledger_site_reconciliation(v_site_id);
    reconciled_site_id := v_site_id;
    entries_backfilled := COALESCE((v_counts ->> v_site_id::text)::integer, 0);
    variance_minor := v_reconciliation.variance_minor;
    RETURN NEXT;
  END LOOP;
END;

DECLARE
  v_statement public.payout_statements%ROWTYPE;
  v_balance_minor bigint;
  v_reserved_minor bigint;
  v_available_minor bigint;
  v_existing_key text;
BEGIN
  -- A statement row lock alone cannot serialize two different statements for
  -- the same site. All claims now take this transaction-scoped site lock first.
  PERFORM pg_advisory_xact_lock(hashtextextended('payout-release:' || p_site_id::text, 0));

  SELECT *
    INTO v_statement
    FROM public.payout_statements
   WHERE id = p_statement_id
     AND site_id = p_site_id
     AND deleted_at IS NULL
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'payout statement not found';
  END IF;

  v_existing_key := COALESCE(v_statement.release_idempotency_key, v_statement.metadata ->> 'release_idempotency_key');
  IF v_existing_key = p_idempotency_key THEN
    RETURN v_statement;
  END IF;

  IF v_statement.status = 'released' THEN
    RETURN v_statement;
  END IF;

  IF v_statement.status <> 'pending' THEN
    RAISE EXCEPTION 'payout statement % is not pending for release', p_statement_id;
  END IF;

  v_balance_minor := public.ledger_account_balance_minor(p_site_id, 'merchant_payable');

  -- A transfer claim is an outstanding obligation until its canonical payout
  -- transaction exists. The transaction check closes the short gap between
  -- posting that debit and linking it back to the compatibility statement.
  SELECT COALESCE(sum(statement.net_amount_minor_bigint), 0)::bigint
    INTO v_reserved_minor
    FROM public.payout_statements AS statement
   WHERE statement.site_id = p_site_id
     AND statement.deleted_at IS NULL
     AND statement.status IN ('processing', 'released')
     AND NOT EXISTS (
       SELECT 1
         FROM public.ledger_transactions AS payout
        WHERE payout.site_id = statement.site_id
          AND payout.source_type = 'payout'
          AND payout.source_id = statement.id::text
     );

  v_available_minor := v_balance_minor - v_reserved_minor;
  IF v_available_minor < v_statement.net_amount_minor_bigint THEN
    RAISE EXCEPTION 'insufficient merchant payable balance for payout %, balance=%, reserved=%, available=%, required=%',
      p_statement_id,
      v_balance_minor,
      v_reserved_minor,
      v_available_minor,
      v_statement.net_amount_minor_bigint;
  END IF;

  UPDATE public.payout_statements
     SET status = 'processing',
         processing_at = COALESCE(processing_at, now()),
         release_idempotency_key = p_idempotency_key,
         release_claimed_by = p_actor_id,
         metadata = COALESCE(metadata, '{}'::jsonb)
           || jsonb_build_object('release_idempotency_key', p_idempotency_key, 'release_claimed_by', p_actor_id),
         updated_by = p_actor_id,
         updated_at = now()
   WHERE id = p_statement_id
     AND site_id = p_site_id
   RETURNING * INTO v_statement;

  RETURN v_statement;
END;

DECLARE
    v_now timestamp with time zone := now();
    v_token_hash text := encode(digest(coalesce(p_token, ''), 'sha256'), 'hex');
    v_reuse public.session_token_rotation_events%ROWTYPE;
    v_session public.sessions%ROWTYPE;
    v_new_token text := p_token;
    v_rotated boolean := false;
BEGIN
    IF p_token IS NULL OR length(btrim(p_token)) < 32 THEN
        RETURN QUERY SELECT false, 'malformed', NULL::uuid, NULL::uuid, NULL::text, false, NULL::timestamp with time zone;
        RETURN;
    END IF;

    SELECT *
      INTO v_reuse
      FROM public.session_token_rotation_events
     WHERE session_token_rotation_events.old_token_hash = v_token_hash
       AND session_token_rotation_events.expires_at > v_now
     LIMIT 1;

    IF FOUND THEN
        UPDATE public.sessions
           SET revoked_at = coalesce(revoked_at, v_now),
               revoked_reason = coalesce(revoked_reason, 'token_reuse_detected')
         WHERE id = v_reuse.session_id;

        UPDATE public.session_token_rotation_events
           SET reuse_detected_at = coalesce(reuse_detected_at, v_now)
         WHERE id = v_reuse.id;

        RETURN QUERY SELECT false, 'reuse_detected', v_reuse.session_id, v_reuse.user_id, NULL::text, false, NULL::timestamp with time zone;
        RETURN;
    END IF;

    SELECT *
      INTO v_session
      FROM public.sessions
     WHERE sessions.token = p_token
     FOR UPDATE;

    IF NOT FOUND THEN
        RETURN QUERY SELECT false, 'missing', NULL::uuid, NULL::uuid, NULL::text, false, NULL::timestamp with time zone;
        RETURN;
    END IF;

    IF v_session.revoked_at IS NOT NULL THEN
        RETURN QUERY SELECT false, 'revoked', v_session.id, v_session.user_id, NULL::text, false, v_session.expires_at;
        RETURN;
    END IF;

    IF v_session.expires_at <= v_now THEN
        UPDATE public.sessions
           SET revoked_at = coalesce(revoked_at, v_now),
               revoked_reason = coalesce(revoked_reason, 'expired')
         WHERE id = v_session.id;

        RETURN QUERY SELECT false, 'expired', v_session.id, v_session.user_id, NULL::text, false, v_session.expires_at;
        RETURN;
    END IF;

    IF v_session.last_active IS NOT NULL
       AND v_session.last_active < v_now - make_interval(secs => greatest(p_idle_timeout_seconds, 60)) THEN
        UPDATE public.sessions
           SET revoked_at = coalesce(revoked_at, v_now),
               revoked_reason = coalesce(revoked_reason, 'idle_timeout')
         WHERE id = v_session.id;

        RETURN QUERY SELECT false, 'idle_timeout', v_session.id, v_session.user_id, NULL::text, false, v_session.expires_at;
        RETURN;
    END IF;

    IF p_rotate
       AND coalesce(v_session.last_rotated_at, v_session.created_at, v_now)
           <= v_now - make_interval(secs => greatest(p_rotation_interval_seconds, 60)) THEN
        v_new_token := encode(gen_random_bytes(32), 'hex');
        v_rotated := true;

        INSERT INTO public.session_token_rotation_events (
            session_id,
            user_id,
            old_token_hash,
            new_token_hash,
            rotated_at,
            expires_at
        ) VALUES (
            v_session.id,
            v_session.user_id,
            v_token_hash,
            encode(digest(v_new_token, 'sha256'), 'hex'),
            v_now,
            v_session.expires_at
        )
        ON CONFLICT (old_token_hash) DO NOTHING;
    END IF;

    UPDATE public.sessions
       SET token = v_new_token,
           last_active = v_now,
           last_rotated_at = CASE WHEN v_rotated THEN v_now ELSE coalesce(last_rotated_at, v_now) END,
           rotation_count = CASE WHEN v_rotated THEN rotation_count + 1 ELSE rotation_count END
     WHERE id = v_session.id;

    RETURN QUERY SELECT true, 'accepted', v_session.id, v_session.user_id, v_new_token, v_rotated, v_session.expires_at;
END;

BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.expected_amount_minor_bigint := COALESCE(NEW.expected_amount_minor_bigint, NEW.expected_amount_minor::bigint);
    NEW.collected_amount_minor_bigint := COALESCE(NEW.collected_amount_minor_bigint, NEW.collected_amount_minor::bigint);
