DECLARE
  v_id_text text;
BEGIN
  v_id_text := NULLIF(COALESCE(p_metadata, '{}'::jsonb) ->> 'source_uuid', '');
  IF v_id_text IS NULL AND p_source_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_id_text := p_source_id;
  END IF;
  IF v_id_text IS NULL AND p_source_id ~* ':[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_id_text := substring(p_source_id from '([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})$');
  END IF;

  IF v_id_text IS NULL THEN
    RETURN NULL;
  END IF;

  RETURN v_id_text::uuid;
EXCEPTION
  WHEN invalid_text_representation THEN
    RETURN NULL;
END;

DECLARE
  v_source_uuid uuid;
  v_payment_uuid uuid;
  v_payment_transaction_uuid uuid;
  v_refund_uuid uuid;
  v_metadata_order_uuid uuid;
  v_source_order_uuid uuid;
  v_compat_table text;
  v_site_id uuid;
BEGIN
  v_source_uuid := public.money_ledger_source_uuid(p_source_id, p_metadata);
  v_payment_uuid := public.money_ledger_source_uuid(COALESCE(p_metadata ->> 'payment_id', ''), '{}'::jsonb);
  v_payment_transaction_uuid := public.money_ledger_source_uuid(COALESCE(p_metadata ->> 'payment_transaction_id', ''), '{}'::jsonb);
  v_refund_uuid := public.money_ledger_source_uuid(COALESCE(p_metadata ->> 'refund_id', ''), '{}'::jsonb);
  v_metadata_order_uuid := public.money_ledger_source_uuid(COALESCE(p_metadata ->> 'order_id', ''), '{}'::jsonb);
  v_compat_table := NULLIF(p_metadata ->> 'compatibility_table', '');

  IF p_source_type = 'payment_capture' THEN
    IF v_payment_transaction_uuid IS NOT NULL THEN
      SELECT site_id, order_id INTO v_site_id, v_source_order_uuid
        FROM public.payment_transactions
       WHERE id = v_payment_transaction_uuid
         AND deleted_at IS NULL;
    END IF;

    IF v_site_id IS NULL THEN
      SELECT site_id, order_id INTO v_site_id, v_source_order_uuid
        FROM public.payment_transactions
       WHERE provider_payment_id = COALESCE(NULLIF(p_metadata ->> 'provider_payment_id', ''), p_source_id)
         AND deleted_at IS NULL
       LIMIT 1;
    END IF;

    IF v_site_id IS NULL AND v_payment_uuid IS NOT NULL THEN
      SELECT site_id, order_id INTO v_site_id, v_source_order_uuid
        FROM public.payments
       WHERE id = v_payment_uuid
         AND deleted_at IS NULL;
    END IF;

    IF v_site_id IS NULL THEN
      SELECT site_id, order_id INTO v_site_id, v_source_order_uuid
        FROM public.payments
       WHERE provider_payment_id = p_source_id
         AND deleted_at IS NULL
       LIMIT 1;
    END IF;

    IF v_metadata_order_uuid IS NOT NULL
       AND v_source_order_uuid IS DISTINCT FROM v_metadata_order_uuid THEN
      RETURN NULL;
    END IF;

  ELSIF p_source_type = 'refund' THEN
    IF v_refund_uuid IS NOT NULL THEN
      SELECT site_id, order_id INTO v_site_id, v_source_order_uuid
        FROM public.refunds
       WHERE id = v_refund_uuid
         AND deleted_at IS NULL;
    END IF;

    IF v_site_id IS NULL AND v_payment_transaction_uuid IS NOT NULL THEN
      SELECT site_id, order_id INTO v_site_id, v_source_order_uuid
        FROM public.payment_transactions
       WHERE id = v_payment_transaction_uuid
         AND deleted_at IS NULL;
    END IF;

    IF v_site_id IS NULL AND v_payment_uuid IS NOT NULL THEN
      SELECT site_id, order_id INTO v_site_id, v_source_order_uuid
        FROM public.payments
       WHERE id = v_payment_uuid
         AND deleted_at IS NULL;
    END IF;

    IF v_metadata_order_uuid IS NOT NULL
       AND v_source_order_uuid IS DISTINCT FROM v_metadata_order_uuid THEN
      RETURN NULL;
    END IF;

  ELSIF p_source_type = 'settlement' THEN
    IF v_compat_table = 'payout_statements' AND v_source_uuid IS NOT NULL THEN
      SELECT site_id INTO v_site_id FROM public.payout_statements WHERE id = v_source_uuid AND deleted_at IS NULL;
    ELSIF v_compat_table = 'commission_reconciliation_entries' AND v_source_uuid IS NOT NULL THEN
      SELECT site_id INTO v_site_id FROM public.commission_reconciliation_entries WHERE id = v_source_uuid AND deleted_at IS NULL;
    ELSIF v_compat_table = 'wallet_ledger_entries' AND v_source_uuid IS NOT NULL THEN
      SELECT site_id INTO v_site_id FROM public.wallet_ledger_entries WHERE id = v_source_uuid AND deleted_at IS NULL;
    END IF;
    IF v_site_id IS NULL AND v_source_uuid IS NOT NULL THEN
      SELECT site_id INTO v_site_id FROM public.settlements WHERE id = v_source_uuid AND deleted_at IS NULL;
    END IF;
    IF v_site_id IS NULL AND v_source_uuid IS NOT NULL THEN
      SELECT site_id INTO v_site_id FROM public.payout_statements WHERE id = v_source_uuid AND deleted_at IS NULL;
    END IF;
    IF v_site_id IS NULL AND v_source_uuid IS NOT NULL THEN
      SELECT site_id INTO v_site_id FROM public.commission_reconciliation_entries WHERE id = v_source_uuid AND deleted_at IS NULL;
    END IF;
    IF v_site_id IS NULL AND v_source_uuid IS NOT NULL THEN
      SELECT site_id INTO v_site_id FROM public.wallet_ledger_entries WHERE id = v_source_uuid AND deleted_at IS NULL;
    END IF;

  ELSIF p_source_type = 'cod_remittance' THEN
    IF v_source_uuid IS NOT NULL THEN
      SELECT site_id INTO v_site_id FROM public.cod_reconciliation_entries
       WHERE id = v_source_uuid AND deleted_at IS NULL;
    END IF;

  ELSIF p_source_type = 'payout' THEN
    IF v_compat_table = 'wallet_ledger_entries' AND v_source_uuid IS NOT NULL THEN
      SELECT site_id INTO v_site_id FROM public.wallet_ledger_entries
       WHERE id = v_source_uuid AND deleted_at IS NULL;
    END IF;
    IF v_site_id IS NULL AND v_source_uuid IS NOT NULL THEN
      SELECT site_id INTO v_site_id FROM public.payouts WHERE id = v_source_uuid AND deleted_at IS NULL;
    END IF;
    IF v_site_id IS NULL AND v_source_uuid IS NOT NULL THEN
      SELECT site_id INTO v_site_id FROM public.payout_statements WHERE id = v_source_uuid AND deleted_at IS NULL;
    END IF;

  ELSIF p_source_type = 'ad_credit_purchase' THEN
    IF v_source_uuid IS NOT NULL THEN
      SELECT site_id INTO v_site_id FROM public.billing_history
       WHERE id = v_source_uuid;
    END IF;

  ELSIF p_source_type = 'reversal' THEN
    IF v_source_uuid IS NOT NULL THEN
      SELECT site_id INTO v_site_id FROM public.ledger_transactions
       WHERE id = v_source_uuid AND deleted_at IS NULL;
    END IF;
  END IF;

  RETURN v_site_id;
END;

DECLARE
  v_account gift_card_accounts%ROWTYPE;
  v_balance numeric(12,2);
BEGIN
  IF p_code IS NULL OR length(BTRIM(p_code)) < 4 THEN
    RETURN jsonb_build_object('found', false);
  END IF;

  SELECT * INTO v_account
    FROM gift_card_accounts
   WHERE site_id = p_store_id
     AND code_hash = encode(extensions.digest(p_code, 'sha256'), 'hex')
     AND deleted_at IS NULL
   LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('found', false);
  END IF;

  v_balance := public.gift_card_available_balance(v_account.id, v_account.site_id);

  RETURN jsonb_build_object(
    'found', true,
    'id', v_account.id,
    'code_last4', v_account.code_last4,
    'initial_value', v_account.initial_value,
    'balance', v_balance,
    'currency', v_account.currency,
    'status', v_account.status,
    'expires_at', v_account.expires_at,
    'redeemable', (
      v_account.status = 'active'
      AND (v_account.expires_at IS NULL OR v_account.expires_at >= NOW())
      AND v_balance > 0
    )
  );
END;

DECLARE
  v_account gift_card_accounts%ROWTYPE;
  v_balance numeric(12,2);
  v_entry_type text;
BEGIN
  IF p_status NOT IN ('active', 'held', 'disabled') THEN
    RAISE EXCEPTION 'invalid gift card status: %', p_status;
  END IF;

  SELECT * INTO v_account
    FROM gift_card_accounts
   WHERE id = p_account_id
     AND site_id = p_store_id
     AND deleted_at IS NULL
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'gift card not found';
  END IF;

  v_balance := public.gift_card_available_balance(v_account.id, v_account.site_id);

  UPDATE gift_card_accounts
     SET status = p_status,
         fraud_hold_reason = CASE WHEN p_status = 'active' THEN NULL ELSE COALESCE(p_reason, fraud_hold_reason) END,
         updated_by = p_actor_id,
         updated_at = NOW()
   WHERE id = p_account_id
     AND site_id = p_store_id
  RETURNING * INTO v_account;

  v_entry_type := CASE WHEN p_status = 'active' THEN 'release' ELSE 'fraud_hold' END;

  INSERT INTO gift_card_ledger_entries (
    site_id, gift_card_account_id, order_id, entry_type, amount, balance_after,
    idempotency_key, request_id, metadata, created_by
  )
  VALUES (
    p_store_id, v_account.id, NULL, v_entry_type, 0, v_balance,
    'gift_card.status:' || v_account.id::text || ':' || gen_random_uuid()::text,
    p_request_id,
    jsonb_strip_nulls(jsonb_build_object('status', p_status, 'reason', p_reason)),
    p_actor_id
  )
  ON CONFLICT (site_id, idempotency_key) DO NOTHING;

  RETURN jsonb_build_object(
    'id', v_account.id,
    'store_id', v_account.site_id,
    'code_last4', v_account.code_last4,
    'initial_value', v_account.initial_value,
    'balance', v_balance,
    'currency', v_account.currency,
    'status', v_account.status,
    'fraud_hold_reason', v_account.fraud_hold_reason,
    'expires_at', v_account.expires_at
  );
END;

DECLARE
  v_account gift_card_accounts%ROWTYPE;
  v_ledger jsonb;
  v_redemptions jsonb;
BEGIN
  SELECT * INTO v_account
    FROM gift_card_accounts
   WHERE id = p_account_id AND site_id = p_store_id AND deleted_at IS NULL;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('found', false);
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(l) ORDER BY l.created_at DESC), '[]'::jsonb)
    INTO v_ledger
  FROM (
    SELECT id, entry_type, amount, balance_after, order_id, created_at, metadata
    FROM gift_card_ledger_entries
    WHERE gift_card_account_id = p_account_id AND site_id = p_store_id AND deleted_at IS NULL
  ) l;

  SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY r.created_at DESC), '[]'::jsonb)
    INTO v_redemptions
  FROM (
    SELECT id, order_id, amount, status, created_at
    FROM gift_card_redemptions
    WHERE gift_card_account_id = p_account_id AND site_id = p_store_id AND deleted_at IS NULL
  ) r;

  RETURN jsonb_build_object(
    'found', true,
    'id', v_account.id,
    'code_last4', v_account.code_last4,
    'balance', public.gift_card_available_balance(v_account.id, v_account.site_id),
    'status', v_account.status,
    'ledger', v_ledger,
    'redemptions', v_redemptions
  );
END;

DECLARE
  v_redemption RECORD;
  v_balance numeric(12,2);
  v_restored_total numeric(12,2) := 0;
  v_restored_count integer := 0;
BEGIN
  IF p_store_id IS NULL OR p_order_id IS NULL THEN
    RAISE EXCEPTION 'store id and order id are required';
  END IF;

  FOR v_redemption IN
    SELECT *
      FROM gift_card_redemptions
     WHERE site_id = p_store_id
       AND order_id = p_order_id
       AND status = 'committed'
       AND deleted_at IS NULL
     FOR UPDATE
  LOOP
    -- current projected balance, then credit the redeemed amount back
    v_balance := public.gift_card_available_balance(v_redemption.gift_card_account_id, p_store_id);

    INSERT INTO gift_card_ledger_entries (
      site_id, gift_card_account_id, order_id, entry_type, amount, balance_after,
      idempotency_key, request_id, metadata, created_by
    )
    VALUES (
      p_store_id,
      v_redemption.gift_card_account_id,
      p_order_id,
      'refund_credit',
      v_redemption.amount,
      v_balance + v_redemption.amount,
      'gift_card.refund_credit:' || p_order_id::text || ':' || v_redemption.id::text,
      p_request_id,
      jsonb_build_object('redemption_id', v_redemption.id),
      p_actor_id
    )
    ON CONFLICT (site_id, idempotency_key) DO NOTHING;

    -- only mark released (and count) when this call actually wrote the credit
    IF FOUND THEN
      UPDATE gift_card_redemptions
         SET status = 'released',
             updated_by = p_actor_id,
             updated_at = NOW()
       WHERE id = v_redemption.id
         AND site_id = p_store_id;

      v_restored_total := v_restored_total + v_redemption.amount;
      v_restored_count := v_restored_count + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'order_id', p_order_id,
    'restored_count', v_restored_count,
    'restored_total', v_restored_total
  );
END;

BEGIN
    INSERT INTO outbox_events (
        store_id, site_id, aggregate_type, aggregate_id, event_type,
        payload, idempotency_key, actor_id, schema_version
    ) VALUES (
        p_site_id, p_site_id, 'founding', p_site_id::text, p_event_type,
        COALESCE(p_payload, '{}'::jsonb), p_idempotency_key, p_actor_id, 1
    )
    ON CONFLICT (idempotency_key) DO NOTHING;
END;

DECLARE
    v_program founding_merchant_program%ROWTYPE;
    v_existing founding_merchant_allocations%ROWTYPE;
    v_sub subscriptions%ROWTYPE;
    v_site sites%ROWTYPE;
    v_source text;
    v_number integer;
    v_plan_slug text;
    v_locked_monthly integer;
BEGIN
    IF p_site_id IS NULL THEN
        RAISE EXCEPTION 'p_site_id is required';
    END IF;

    -- Serialize ALL allocations on the singleton program row (race-safe core).
    SELECT * INTO v_program FROM founding_merchant_program
        WHERE program_key = 'v1' AND deleted_at IS NULL FOR UPDATE;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('allocated', false, 'reason', 'program_not_found');
    END IF;

    -- Idempotent replay (inside the serialized section): already allocated → return it.
    SELECT * INTO v_existing FROM founding_merchant_allocations
        WHERE site_id = p_site_id AND released_at IS NULL LIMIT 1;
    IF FOUND THEN
        RETURN jsonb_build_object('allocated', true, 'replayed', true,
            'founding_number', v_existing.founding_number,
            'allocation_source', v_existing.allocation_source,
            'plan_slug', v_existing.plan_slug,
            'locked_monthly_price', v_existing.locked_monthly_price);
    END IF;

    IF NOT v_program.active OR v_program.paused THEN
        RETURN jsonb_build_object('allocated', false, 'reason',
            CASE WHEN v_program.paused THEN 'program_paused' ELSE 'program_inactive' END);
    END IF;
    IF v_program.used_slots >= v_program.total_slots THEN
        RETURN jsonb_build_object('allocated', false, 'reason', 'program_full');
    END IF;

    SELECT * INTO v_site FROM sites WHERE id = p_site_id AND deleted_at IS NULL;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('allocated', false, 'reason', 'site_not_found');
    END IF;

    IF p_subscription_id IS NOT NULL THEN
        SELECT * INTO v_sub FROM subscriptions WHERE id = p_subscription_id;
    ELSE
        SELECT * INTO v_sub FROM subscriptions
            WHERE store_id = p_site_id AND status = 'active'
            ORDER BY created_at DESC LIMIT 1;
    END IF;

    -- Canonical eligibility (unless admin force): active + paid + trial_status=paid.
    IF NOT p_force THEN
        IF v_sub.id IS NULL OR v_sub.status <> 'active'
           OR COALESCE(v_sub.amount_paid, 0) <= 0
           OR v_site.trial_status <> 'paid' THEN
            RETURN jsonb_build_object('allocated', false, 'reason', 'not_eligible');
        END IF;
    END IF;

    -- Plan must be founding-eligible (launch/growth).
    v_plan_slug := COALESCE(v_sub.plan, '');
    IF v_plan_slug NOT IN ('launch', 'growth') THEN
        IF p_force THEN
            v_plan_slug := 'launch';
        ELSE
            RETURN jsonb_build_object('allocated', false, 'reason', 'plan_not_eligible');
        END IF;
    END IF;

    -- Resolve source + enforce per-pool cap.
    v_source := COALESCE(NULLIF(p_source_override, ''), v_site.intended_allocation_source, 'PUBLIC');
    IF v_source NOT IN ('PUBLIC', 'INVITED', 'PARTNER') THEN
        v_source := 'PUBLIC';
    END IF;
    IF v_source = 'PUBLIC' AND v_program.public_used >= v_program.public_slots THEN
        RETURN jsonb_build_object('allocated', false, 'reason', 'public_pool_full');
    ELSIF v_source = 'INVITED' AND v_program.invited_used >= v_program.invited_slots THEN
        RETURN jsonb_build_object('allocated', false, 'reason', 'invited_pool_full');
    ELSIF v_source = 'PARTNER' AND v_program.partner_used >= v_program.partner_slots THEN
        RETURN jsonb_build_object('allocated', false, 'reason', 'partner_pool_full');
    END IF;

    -- Monotonic join-order badge number (never reused; gaps from reclaims preserved).
    SELECT COALESCE(MAX(founding_number), 0) + 1 INTO v_number FROM founding_merchant_allocations;
    v_locked_monthly := CASE WHEN v_plan_slug = 'growth' THEN v_program.growth_price ELSE v_program.launch_price END;

    INSERT INTO founding_merchant_allocations (
        program_key, site_id, founding_number, allocation_source, subscription_id, plan_slug,
        locked_launch_price, locked_growth_price, locked_monthly_price,
        actor_type, actor_id, created_by
    ) VALUES (
        'v1', p_site_id, v_number, v_source, v_sub.id, v_plan_slug,
        v_program.launch_price, v_program.growth_price, v_locked_monthly,
        p_actor_type, p_actor_id, p_actor_id
    );

    UPDATE founding_merchant_program SET
        used_slots = used_slots + 1,
        public_used = public_used + CASE WHEN v_source = 'PUBLIC' THEN 1 ELSE 0 END,
        invited_used = invited_used + CASE WHEN v_source = 'INVITED' THEN 1 ELSE 0 END,
        partner_used = partner_used + CASE WHEN v_source = 'PARTNER' THEN 1 ELSE 0 END,
        updated_at = now(), updated_by = p_actor_id
    WHERE program_key = 'v1';

    -- Stamp the tenant — the lock lives here and survives upgrade/downgrade/cancel/reactivate.
    UPDATE sites SET
        is_founding_merchant = true,
        founding_number = v_number,
        founding_allocated_at = now(),
        price_lock_enabled = true,
        locked_launch_price = v_program.launch_price,
        locked_growth_price = v_program.growth_price,
        allocation_source = v_source,
        updated_at = now()
    WHERE id = p_site_id;

    -- Atomic domain events.
    PERFORM public.emit_founding_event(p_site_id, 'founding_slot_allocated',
        'founding_slot_allocated:' || p_site_id::text || ':' || v_number::text,
        jsonb_build_object('site_id', p_site_id, 'founding_number', v_number,
            'allocation_source', v_source, 'plan_slug', v_plan_slug,
            'locked_monthly_price', v_locked_monthly), p_actor_id);
    PERFORM public.emit_founding_event(p_site_id, 'merchant_price_locked',
        'merchant_price_locked:' || p_site_id::text || ':' || v_number::text,
        jsonb_build_object('site_id', p_site_id, 'founding_number', v_number,
            'locked_launch_price', v_program.launch_price,
            'locked_growth_price', v_program.growth_price), p_actor_id);
    IF (v_program.used_slots + 1) >= v_program.total_slots THEN
        PERFORM public.emit_founding_event(p_site_id, 'founding_program_full',
            'founding_program_full:v1',
            jsonb_build_object('total_slots', v_program.total_slots), p_actor_id);
    END IF;

    RETURN jsonb_build_object('allocated', true, 'replayed', false,
        'founding_number', v_number, 'allocation_source', v_source,
        'plan_slug', v_plan_slug, 'locked_monthly_price', v_locked_monthly);
END;

DECLARE
    v_program founding_merchant_program%ROWTYPE;
    v_alloc founding_merchant_allocations%ROWTYPE;
    v_within_window boolean;
BEGIN
    IF p_site_id IS NULL THEN
        RAISE EXCEPTION 'p_site_id is required';
    END IF;

    SELECT * INTO v_program FROM founding_merchant_program
        WHERE program_key = 'v1' FOR UPDATE;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('reclaimed', false, 'reason', 'program_not_found');
    END IF;

    SELECT * INTO v_alloc FROM founding_merchant_allocations
        WHERE site_id = p_site_id AND released_at IS NULL LIMIT 1;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('reclaimed', false, 'reason', 'no_active_allocation');
    END IF;

    -- ≤14 days → reclaim. >14 days → retain historical founder (unless admin force).
    v_within_window := (now() - v_alloc.allocated_at) <= INTERVAL '14 days';
    IF NOT v_within_window AND NOT p_force THEN
        RETURN jsonb_build_object('reclaimed', false, 'reason', 'outside_14d_window',
            'founding_number', v_alloc.founding_number);
    END IF;

    UPDATE founding_merchant_allocations SET
        released_at = now(),
        release_reason = COALESCE(p_reason, 'refund'),
        founding_released = true,
        actor_type = p_actor_type, updated_by = p_actor_id, updated_at = now()
    WHERE id = v_alloc.id;

    UPDATE founding_merchant_program SET
        used_slots = GREATEST(used_slots - 1, 0),
        public_used = public_used - CASE WHEN v_alloc.allocation_source = 'PUBLIC' THEN 1 ELSE 0 END,
        invited_used = invited_used - CASE WHEN v_alloc.allocation_source = 'INVITED' THEN 1 ELSE 0 END,
        partner_used = partner_used - CASE WHEN v_alloc.allocation_source = 'PARTNER' THEN 1 ELSE 0 END,
        updated_at = now(), updated_by = p_actor_id
    WHERE program_key = 'v1';

    -- Clear the lock on the tenant (no longer a founder).
    UPDATE sites SET
        is_founding_merchant = false,
        founding_number = NULL,
        founding_allocated_at = NULL,
        price_lock_enabled = false,
        locked_launch_price = NULL,
        locked_growth_price = NULL,
        allocation_source = NULL,
        updated_at = now()
    WHERE id = p_site_id;

    PERFORM public.emit_founding_event(p_site_id, 'founding_slot_reclaimed',
        'founding_slot_reclaimed:' || v_alloc.id::text,
        jsonb_build_object('site_id', p_site_id, 'founding_number', v_alloc.founding_number,
            'allocation_source', v_alloc.allocation_source,
            'release_reason', COALESCE(p_reason, 'refund'),
            'released_at', now(), 'forced', p_force), p_actor_id);

    RETURN jsonb_build_object('reclaimed', true,
        'founding_number', v_alloc.founding_number,
        'allocation_source', v_alloc.allocation_source,
        'within_14d', v_within_window);
END;

DECLARE
    v founding_merchant_program%ROWTYPE;
BEGIN
    SELECT * INTO v FROM founding_merchant_program WHERE program_key = 'v1' AND deleted_at IS NULL;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('available', false);
    END IF;
    RETURN jsonb_build_object(
        'available', true,
        'active', v.active,
        'paused', v.paused,
        'total_slots', v.total_slots,
        'used_slots', v.used_slots,
        'remaining_slots', v.remaining_slots,
        'public_remaining', GREATEST(v.public_slots - v.public_used, 0),
        'invited_remaining', GREATEST(v.invited_slots - v.invited_used, 0),
        'partner_remaining', GREATEST(v.partner_slots - v.partner_used, 0),
        'launch_price', v.launch_price,
        'growth_price', v.growth_price
    );
END;

DECLARE
    v founding_merchant_program%ROWTYPE;
BEGIN
    UPDATE founding_merchant_program SET
        active = COALESCE(p_active, active),
        paused = COALESCE(p_paused, paused),
        paused_reason = CASE WHEN COALESCE(p_paused, false) THEN p_reason ELSE NULL END,
        updated_at = now(), updated_by = p_actor_id, actor_type = 'super_admin'
    WHERE program_key = 'v1'
    RETURNING * INTO v;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('ok', false, 'reason', 'program_not_found');
    END IF;

    IF v.paused THEN
        PERFORM public.emit_founding_event(NULL, 'founding_program_paused',
            'founding_program_paused:v1:' || extract(epoch from now())::bigint::text,
            jsonb_build_object('reason', p_reason, 'active', v.active), p_actor_id);
    END IF;

    RETURN jsonb_build_object('ok', true, 'active', v.active, 'paused', v.paused);
END;

DECLARE
    v_site sites%ROWTYPE;
    v_catalog integer;
BEGIN
    SELECT * INTO v_site FROM sites WHERE id = p_site_id AND deleted_at IS NULL;
    IF FOUND AND v_site.price_lock_enabled THEN
        IF p_plan_slug = 'growth' AND v_site.locked_growth_price IS NOT NULL THEN
            RETURN v_site.locked_growth_price;
        ELSIF p_plan_slug = 'launch' AND v_site.locked_launch_price IS NOT NULL THEN
            RETURN v_site.locked_launch_price;
        END IF;
    END IF;

    SELECT price_monthly_inr INTO v_catalog FROM plans
        WHERE slug = p_plan_slug AND site_type = 'store' AND is_active = true
        ORDER BY version DESC LIMIT 1;
    RETURN COALESCE(v_catalog, 0);
END;

DECLARE
    v founding_merchant_program%ROWTYPE;
    v_actual_total integer;
    v_actual_public integer;
    v_actual_invited integer;
    v_actual_partner integer;
    v_mismatch boolean;
BEGIN
    SELECT * INTO v FROM founding_merchant_program WHERE program_key = 'v1' FOR UPDATE;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('status', 'program_not_found');
    END IF;

    SELECT
        count(*),
        count(*) FILTER (WHERE allocation_source = 'PUBLIC'),
        count(*) FILTER (WHERE allocation_source = 'INVITED'),
        count(*) FILTER (WHERE allocation_source = 'PARTNER')
    INTO v_actual_total, v_actual_public, v_actual_invited, v_actual_partner
    FROM founding_merchant_allocations WHERE released_at IS NULL;

    v_mismatch := (v.used_slots <> v_actual_total)
        OR (v.public_used <> v_actual_public)
        OR (v.invited_used <> v_actual_invited)
        OR (v.partner_used <> v_actual_partner);

    IF v_mismatch AND p_repair THEN
        UPDATE founding_merchant_program SET
            used_slots = v_actual_total,
            public_used = v_actual_public,
            invited_used = v_actual_invited,
            partner_used = v_actual_partner,
            updated_at = now()
        WHERE program_key = 'v1';
    END IF;

    RETURN jsonb_build_object(
        'status', CASE WHEN NOT v_mismatch THEN 'healthy'
                       WHEN p_repair THEN 'repaired' ELSE 'mismatch' END,
        'stored', jsonb_build_object('used', v.used_slots, 'public', v.public_used,
            'invited', v.invited_used, 'partner', v.partner_used),
        'actual', jsonb_build_object('used', v_actual_total, 'public', v_actual_public,
            'invited', v_actual_invited, 'partner', v_actual_partner),
        'repairable', v_mismatch
    );
END;

DECLARE
    v_alloc founding_merchant_allocations%ROWTYPE;
BEGIN
    SELECT * INTO v_alloc FROM founding_merchant_allocations
        WHERE site_id = p_site_id AND released_at IS NULL LIMIT 1;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('ok', false, 'reason', 'no_active_allocation');
    END IF;

    UPDATE sites SET
        is_founding_merchant = true,
        founding_number = v_alloc.founding_number,
        founding_allocated_at = v_alloc.allocated_at,
        price_lock_enabled = true,
        locked_launch_price = v_alloc.locked_launch_price,
        locked_growth_price = v_alloc.locked_growth_price,
        allocation_source = v_alloc.allocation_source,
        updated_at = now()
    WHERE id = p_site_id;

    PERFORM public.emit_founding_event(p_site_id, 'merchant_price_locked',
        'merchant_price_locked:repair:' || v_alloc.id::text || ':' || extract(epoch from now())::bigint::text,
        jsonb_build_object('site_id', p_site_id, 'founding_number', v_alloc.founding_number,
            'reason', p_reason, 'repaired', true), p_actor_id);

    RETURN jsonb_build_object('ok', true, 'founding_number', v_alloc.founding_number);
END;

declare
    v_coupon public.subscription_coupons%rowtype;
    v_discount_minor bigint := 0;
    v_used_by_merchant integer := 0;
begin
    if p_code is null or btrim(p_code) = '' then
        return jsonb_build_object('valid', false, 'message', 'Enter a coupon code');
    end if;

    select * into v_coupon
    from public.subscription_coupons
    where upper(code) = upper(btrim(p_code))
    limit 1;

    if not found then
        return jsonb_build_object('valid', false, 'message', 'Coupon not found');
    end if;
    if not v_coupon.is_active then
        return jsonb_build_object('valid', false, 'message', 'This coupon is no longer active');
    end if;
    if now() < v_coupon.valid_from then
        return jsonb_build_object('valid', false, 'message', 'This coupon is not active yet');
    end if;
    if v_coupon.valid_until is not null and now() > v_coupon.valid_until then
        return jsonb_build_object('valid', false, 'message', 'This coupon has expired');
    end if;
    if v_coupon.applies_to_plan_slugs is not null
        and not (p_plan_slug = any(v_coupon.applies_to_plan_slugs)) then
        return jsonb_build_object('valid', false, 'message', 'Coupon is not valid for this plan');
    end if;
    if v_coupon.applies_to_billing is not null and v_coupon.applies_to_billing <> p_billing_period then
        return jsonb_build_object('valid', false, 'message', 'Coupon is not valid for this billing period');
    end if;
    if p_amount_minor < v_coupon.min_amount_minor then
        return jsonb_build_object('valid', false, 'message', 'Order amount is too low for this coupon');
    end if;
    if v_coupon.max_redemptions is not null and v_coupon.used_count >= v_coupon.max_redemptions then
        return jsonb_build_object('valid', false, 'message', 'This coupon has reached its redemption limit');
    end if;

    select count(*) into v_used_by_merchant
    from public.subscription_coupon_redemptions
    where coupon_id = v_coupon.id and site_id = p_site_id;

    if v_used_by_merchant >= v_coupon.per_merchant_limit then
        return jsonb_build_object('valid', false, 'message', 'You have already used this coupon');
    end if;

    if v_coupon.discount_type = 'percentage' then
        v_discount_minor := floor(p_amount_minor::numeric * v_coupon.percent_off / 100.0)::bigint;
    else
        v_discount_minor := v_coupon.amount_off_minor;
    end if;

    if v_discount_minor > p_amount_minor then
        v_discount_minor := p_amount_minor;  -- never below zero
    end if;
    if v_discount_minor < 0 then
        v_discount_minor := 0;
    end if;

    return jsonb_build_object(
        'valid', true,
        'coupon_id', v_coupon.id,
        'code', upper(v_coupon.code),
        'discount_type', v_coupon.discount_type,
        'percent_off', v_coupon.percent_off,
        'amount_off_minor', v_coupon.amount_off_minor,
        'discount_minor', v_discount_minor,
        'final_minor', p_amount_minor - v_discount_minor,
        'description', v_coupon.description,
        'message', 'Coupon applied'
    );
end;

declare
    v_coupon public.subscription_coupons%rowtype;
    v_existing uuid;
begin
    select id into v_existing
    from public.subscription_coupon_redemptions
    where idempotency_key = p_idempotency_key;
    if found then
        return jsonb_build_object('recorded', true, 'idempotent', true);
    end if;

    select * into v_coupon
    from public.subscription_coupons
    where upper(code) = upper(btrim(p_code))
    for update;

    if not found then
        return jsonb_build_object('recorded', false, 'message', 'Coupon not found');
    end if;

    insert into public.subscription_coupon_redemptions (
        coupon_id, site_id, user_id, plan_slug, billing_period,
        amount_before_minor, discount_minor, amount_after_minor,
        razorpay_order_id, razorpay_payment_id, idempotency_key
    ) values (
        v_coupon.id, p_site_id, p_user_id, p_plan_slug, p_billing_period,
        p_amount_before_minor, p_discount_minor, p_amount_after_minor,
        p_razorpay_order_id, p_razorpay_payment_id, p_idempotency_key
    )
    on conflict (idempotency_key) do nothing;

    update public.subscription_coupons
    set used_count = used_count + 1, updated_at = now()
    where id = v_coupon.id;

    return jsonb_build_object('recorded', true, 'idempotent', false, 'coupon_id', v_coupon.id);
end;

declare
    v_target public.site_domains%rowtype;
    v_new_primary text;
begin
    v_new_primary := lower(btrim(p_domain));

    select * into v_target
    from public.site_domains
    where site_id = p_site_id and lower(domain) = v_new_primary and deleted_at is null
    for update;

    if not found then
        return jsonb_build_object('ok', false, 'message', 'Domain is not connected to this store');
    end if;
    if v_target.status <> 'active' then
        return jsonb_build_object('ok', false, 'message', 'Only an active, verified domain can be primary');
    end if;
    if v_target.role = 'primary' then
        return jsonb_build_object('ok', true, 'message', 'Domain is already primary', 'domain', v_target.domain);
    end if;

    -- Demote the existing primary to a redirect pointing at the new primary.
    update public.site_domains
    set role = 'redirect', redirect_to = v_new_primary, updated_at = now()
    where site_id = p_site_id and role = 'primary' and deleted_at is null;

    -- Promote the target.
    update public.site_domains
    set role = 'primary', redirect_to = null, updated_at = now()
    where id = v_target.id;

    -- Keep the legacy column in sync (storefront host resolution + back-compat).
    update public.sites
    set custom_domain = v_new_primary,
        custom_domain_status = v_target.status,
        custom_domain_verification_token = v_target.verification_token
    where id = p_site_id;

    return jsonb_build_object('ok', true, 'domain', v_new_primary, 'role', 'primary');
end;

declare
    v_id uuid;
begin
    insert into public.site_domain_verifications (
        site_id, site_domain_id, domain, check_type, status,
        txt_verified, cname_verified, ssl_active, result, checked_by
    ) values (
        p_site_id, p_site_domain_id, lower(btrim(p_domain)), p_check_type, p_status,
        coalesce(p_txt_verified, false), coalesce(p_cname_verified, false),
        coalesce(p_ssl_active, false), coalesce(p_result, '{}'::jsonb), p_checked_by
    )
    returning id into v_id;
    return v_id;
end;

BEGIN
    NEW.updated_at := now();
    RETURN NEW;
END;

