DECLARE
    v_row public.contact_requests%ROWTYPE;
BEGIN
    IF p_ticket_ref IS NULL OR p_email IS NULL THEN
        RETURN jsonb_build_object('found', false);
    END IF;

    SELECT * INTO v_row
    FROM public.contact_requests
    WHERE ticket_ref = upper(btrim(p_ticket_ref))
      AND lower(email) = lower(btrim(p_email))
    LIMIT 1;

    IF NOT FOUND THEN
        -- Same shape for "wrong reference" and "wrong email", so the response
        -- cannot be used to confirm that a reference exists.
        RETURN jsonb_build_object('found', false);
    END IF;

    RETURN jsonb_build_object(
        'found', true,
        'ticket_ref', v_row.ticket_ref,
        'status', v_row.status,
        'topic', v_row.topic,
        'subject_line', v_row.subject_line,
        'team', v_row.team,
        'response_hours', v_row.response_hours,
        'submitted_at', v_row.created_at,
        'first_response_due_at', v_row.first_response_due_at,
        'responded_at', v_row.responded_at,
        'resolved_at', v_row.resolved_at
    );
END;

DECLARE
    v_inserted_id uuid;
BEGIN
    IF p_jti IS NULL OR length(btrim(p_jti)) < 16 THEN
        RETURN false;
    END IF;

    INSERT INTO public.merchant_session_jti_consumptions (jti, user_id, expires_at)
    VALUES (btrim(p_jti), p_user_id, p_expires_at)
    ON CONFLICT (jti) DO NOTHING
    RETURNING id INTO v_inserted_id;

    RETURN v_inserted_id IS NOT NULL;
END;

DECLARE
    v_count integer;
BEGIN
    WITH expired AS (
        SELECT id
          FROM public.merchant_session_jti_consumptions
         WHERE expires_at <= now()
         ORDER BY expires_at ASC
         LIMIT LEAST(GREATEST(COALESCE(p_limit, 500), 1), 5000)
         FOR UPDATE SKIP LOCKED
    )
    DELETE FROM public.merchant_session_jti_consumptions
     WHERE id IN (SELECT id FROM expired);

    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;

DECLARE
  v_code_hash text;
  v_code_last4 text;
  v_account gift_card_accounts%ROWTYPE;
  v_balance numeric(12,2);
BEGIN
  IF p_idempotency_key IS NULL OR BTRIM(p_idempotency_key) = '' THEN
    RAISE EXCEPTION 'idempotency_key is required';
  END IF;
  IF p_code IS NULL OR length(BTRIM(p_code)) < 4 THEN
    RAISE EXCEPTION 'gift card code is required';
  END IF;
  IF COALESCE(p_initial_value, 0) <= 0 THEN
    RAISE EXCEPTION 'gift card value must be greater than zero';
  END IF;

  -- Idempotent replay: the same issue key returns the already-issued card.
  SELECT * INTO v_account
    FROM gift_card_accounts
   WHERE site_id = p_store_id
     AND metadata->>'issue_idempotency_key' = p_idempotency_key
     AND deleted_at IS NULL
   LIMIT 1;

  IF NOT FOUND THEN
    v_code_hash := encode(extensions.digest(p_code, 'sha256'), 'hex');
    v_code_last4 := right(regexp_replace(p_code, '[^A-Za-z0-9]', '', 'g'), 4);

    INSERT INTO gift_card_accounts (
      site_id, code_hash, code_last4, initial_value, balance, currency,
      status, expires_at, customer_id, metadata, created_by, updated_by
    )
    VALUES (
      p_store_id, v_code_hash, v_code_last4, p_initial_value, p_initial_value,
      COALESCE(NULLIF(BTRIM(p_currency), ''), 'INR'),
      'active', p_expires_at,
      NULLIF(p_recipient->>'customer_id', '')::uuid,
      jsonb_strip_nulls(jsonb_build_object(
        'issue_idempotency_key', p_idempotency_key,
        'recipient_email', p_recipient->>'recipient_email',
        'recipient_name', p_recipient->>'recipient_name',
        'note', p_recipient->>'note'
      )),
      p_actor_id, p_actor_id
    )
    ON CONFLICT (site_id, code_hash) DO NOTHING
    RETURNING * INTO v_account;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'gift card code collision; retry issuance';
    END IF;

    INSERT INTO gift_card_ledger_entries (
      site_id, gift_card_account_id, order_id, entry_type, amount, balance_after,
      idempotency_key, request_id, metadata, created_by
    )
    VALUES (
      p_store_id, v_account.id, NULL, 'issued', p_initial_value, p_initial_value,
      'gift_card.issued:' || v_account.id::text,
      p_request_id,
      jsonb_build_object('code_last4', v_account.code_last4),
      p_actor_id
    )
    ON CONFLICT (site_id, idempotency_key) DO NOTHING;
  END IF;

  v_balance := public.gift_card_available_balance(v_account.id, p_store_id);

  RETURN jsonb_build_object(
    'id', v_account.id,
    'site_id', v_account.site_id,
    'store_id', v_account.site_id,
    'code_last4', v_account.code_last4,
    'initial_value', v_account.initial_value,
    'balance', v_balance,
    'currency', v_account.currency,
    'status', v_account.status,
    'expires_at', v_account.expires_at,
    'created_at', v_account.created_at
  );
END;

DECLARE
  v_order RECORD;
  v_site RECORD;
  v_invoice_number text;
  v_taxable_amount_minor bigint;
  v_cgst_minor bigint := 0;
  v_sgst_minor bigint := 0;
  v_igst_minor bigint := 0;
  v_tax_minor bigint;
  v_total_minor bigint;
  v_supply_type text;
  v_lines jsonb;
  v_supplier jsonb;
  v_recipient jsonb;
  v_invoice_id uuid;
  v_invoice_date timestamptz := now();
  v_irn text;
  v_qr_payload text;
  v_result jsonb;
BEGIN
  -- Locks the order row; also serialises concurrent issue attempts for the SAME order.
  SELECT * INTO v_order FROM orders WHERE id = p_order_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found';
  END IF;

  -- Idempotent: return the existing invoice rather than raising, for a retried post-commit call.
  SELECT to_jsonb(gi) INTO v_result FROM gst_invoices gi WHERE gi.order_id = p_order_id AND gi.deleted_at IS NULL;
  IF v_result IS NOT NULL THEN
    RETURN v_result;
  END IF;

  IF v_order.place_of_supply_state IS NULL OR v_order.tax IS NULL THEN
    RAISE EXCEPTION 'order has no computed GST to invoice';
  END IF;

  -- Locks the site row: serialises concurrent invoice-number allocation for the SAME site.
  SELECT * INTO v_site FROM sites WHERE id = v_order.store_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'site not found';
  END IF;
  IF v_site.gstin IS NULL OR v_site.gst_state_code IS NULL THEN
    RAISE EXCEPTION 'store has no GST registration configured';
  END IF;

  v_invoice_number := COALESCE(v_site.invoice_prefix, 'LBY') || '-' || lpad(v_site.invoice_number_next::text, 6, '0');

  UPDATE sites SET invoice_number_next = invoice_number_next + 1 WHERE id = v_site.id;

  -- Aggregate tax figures come from order_tax_lines (T13's authoritative CGST/SGST/IGST
  -- breakdown) and orders.tax/subtotal/discount -- never recomputed here.
  SELECT
    COALESCE(SUM(CASE WHEN otl.title = 'CGST' THEN round(otl.amount * 100) ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN otl.title = 'SGST' THEN round(otl.amount * 100) ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN otl.title = 'IGST' THEN round(otl.amount * 100) ELSE 0 END), 0)
    INTO v_cgst_minor, v_sgst_minor, v_igst_minor
    FROM order_tax_lines otl
   WHERE otl.order_id = p_order_id
     AND otl.site_id = v_order.store_id
     AND otl.deleted_at IS NULL;

  v_tax_minor := round(v_order.tax * 100);
  v_taxable_amount_minor := round((COALESCE(v_order.subtotal, 0) - COALESCE(v_order.discount, 0)) * 100);
  v_total_minor := v_taxable_amount_minor + v_tax_minor;
  v_supply_type := CASE WHEN v_cgst_minor > 0 OR v_sgst_minor > 0 THEN 'intra_state' ELSE 'inter_state' END;

  -- Per-item display lines only (product/sku/hsn/qty/price) -- no per-line tax recomputation.
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'id', oi.id,
           'product_id', oi.product_id,
           'variant_id', oi.variant_id,
           'description', COALESCE(oi.title, oi.name, 'Order item'),
           'sku', oi.sku,
           'hsn_code', oi.hsn_code,
           'quantity', oi.quantity,
           'unit_amount_minor', round(COALESCE(oi.unit_price, oi.price, 0) * 100)
         )), '[]'::jsonb)
    INTO v_lines
    FROM order_items oi
   WHERE oi.order_id = p_order_id
     AND oi.site_id = v_order.store_id
     AND oi.deleted_at IS NULL;

  v_supplier := jsonb_build_object(
    'name', COALESCE(v_site.name, v_site.store_name, 'LetBuyy merchant'),
    'gstin', v_site.gstin,
    'state_code', v_site.gst_state_code
  );
  v_recipient := jsonb_build_object(
    'name', COALESCE(v_order.customer_name, v_order.customer_email, 'Customer'),
    'gstin', v_order.customer_gstin,
    'state_code', v_order.place_of_supply_state,
    'address', v_order.shipping_address
  );

  -- Sandbox-only, deterministic, locally-computed placeholder -- never a real IRP submission.
  -- pgcrypto's digest() lives in the `extensions` schema, not `public` -- this function's own
  -- `SET search_path TO 'public'` hides it unless fully qualified. Discovered empirically (the
  -- unqualified call failed live: "function digest(text, unknown) does not exist"). Noted, not
  -- fixed: create_checkout_order's gift-card redemption path (000_baseline.sql) calls
  -- digest(p_gift_card_code, 'sha256') the SAME unqualified way under the SAME search_path --
  -- the identical latent bug, apparently never exercised by any gift-card purchase to date.
  -- Out of scope for this phase (GST invoicing, not gift cards) -- flagged for a future phase.
  v_irn := 'SANDBOX-IRN-' || upper(substr(encode(extensions.digest(v_invoice_number || ':' || p_order_id::text, 'sha256'), 'hex'), 1, 16));
  v_qr_payload := 'letbuyy://gst-invoice/' || v_irn;

  INSERT INTO gst_invoices (
    site_id, order_id, invoice_number, invoice_date, currency,
    supplier, recipient, place_of_supply_state_code, supply_type, lines,
    taxable_amount_minor, cgst_amount_minor, sgst_amount_minor, igst_amount_minor,
    tax_amount_minor, total_amount_minor, marketplace_tcs_bps, tcs_amount_minor,
    irp_mode, irn, qr_payload, provider_ack, status, invoice, metadata, created_by
  ) VALUES (
    v_order.store_id, p_order_id, v_invoice_number, v_invoice_date, COALESCE(v_order.currency, 'INR'),
    v_supplier, v_recipient, v_order.place_of_supply_state, v_supply_type, v_lines,
    v_taxable_amount_minor, v_cgst_minor, v_sgst_minor, v_igst_minor,
    v_tax_minor, v_total_minor, 0, 0,
    'sandbox', v_irn, v_qr_payload, '{}'::jsonb, 'generated',
    jsonb_build_object('invoice_number', v_invoice_number, 'order_id', p_order_id, 'total_amount_minor', v_total_minor),
    jsonb_build_object('source', 'issue_gst_invoice', 'request_id', p_request_id),
    p_actor_id
  )
  RETURNING id INTO v_invoice_id;

  UPDATE orders
     SET gst_invoice_number = v_invoice_number,
         updated_at = now()
   WHERE id = p_order_id;

  SELECT to_jsonb(gi) INTO v_result FROM gst_invoices gi WHERE gi.id = v_invoice_id;
  RETURN v_result;
END;

DECLARE
  v_product_site uuid;
BEGIN
  SELECT COALESCE(p.site_id, p.store_id)
    INTO v_product_site
    FROM public.products p
   WHERE p.id = NEW.product_id;

  IF v_product_site IS NULL OR v_product_site <> NEW.site_id THEN
    RAISE EXCEPTION 'channel_listings.site_id must match the product''s site';
  END IF;
  RETURN NEW;
END;

BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status
     AND COALESCE(current_setting('app.channel_listing_transition', true), '') <> 'rpc' THEN
    RAISE EXCEPTION 'channel_listings.status changes only through transition_channel_listing()';
  END IF;
  RETURN NEW;
END;

DECLARE
  v_existing public.channel_listing_moderation_events%ROWTYPE;
  v_listing public.channel_listings%ROWTYPE;
  v_product_ok boolean;
  v_now timestamp with time zone := now();
  v_event_id uuid;
  v_allowed boolean := false;
BEGIN
  IF p_site_id IS NULL THEN
    RAISE EXCEPTION 'site_id is required';
  END IF;
  IF p_listing_id IS NULL THEN
    RAISE EXCEPTION 'listing_id is required';
  END IF;
  IF p_idempotency_key IS NULL OR length(p_idempotency_key) = 0 OR length(p_idempotency_key) > 200 THEN
    RAISE EXCEPTION 'idempotency_key is required';
  END IF;
  IF p_actor_realm IS NULL OR p_actor_realm NOT IN ('merchant', 'operator') THEN
    RAISE EXCEPTION 'unsupported actor_realm: %', p_actor_realm;
  END IF;
  IF p_to_status IS NULL OR p_to_status NOT IN ('draft', 'pending_review', 'approved', 'rejected', 'paused', 'delisted') THEN
    RAISE EXCEPTION 'unsupported status: %', p_to_status;
  END IF;

  -- Lock BEFORE the existence check (206:114): two concurrent replays of one key serialize here.
  PERFORM pg_advisory_xact_lock(hashtextextended(p_site_id::text || ':' || p_idempotency_key, 0));

  SELECT * INTO v_existing
    FROM public.channel_listing_moderation_events e
   WHERE e.site_id = p_site_id AND e.idempotency_key = p_idempotency_key;
  IF FOUND THEN
    RETURN QUERY SELECT v_existing.listing_id, v_existing.from_status, v_existing.to_status, v_existing.id, true;
    RETURN;
  END IF;

  -- Realm fence. Merchant edges must run inside the tenant transaction for this very site (GUC set by
  -- withTenantTx from a validated claim; an unset GUC fails closed). Operator edges are refused when the
  -- caller's role is app_tenant — the only role a merchant request can run as — and when a tenant GUC
  -- is set, because an operator never acts inside a tenant transaction. service_role is a member of
  -- app_tenant (164:21), so membership is NOT the test. Inside a SECURITY DEFINER function current_user
  -- is the DEFINER, not the caller (measured on postgres:16: current_user=postgres, role=app_tenant after
  -- SET LOCAL ROLE app_tenant), so the caller's SET ROLE is read through the `role` setting.
  IF p_actor_realm = 'merchant' THEN
    IF public.current_site_id() IS NULL OR public.current_site_id() <> p_site_id THEN
      RAISE EXCEPTION 'tenant context required for merchant transitions';
    END IF;
  ELSE
    IF current_setting('role', true) = 'app_tenant' OR public.current_site_id() IS NOT NULL THEN
      RAISE EXCEPTION 'operator transitions are not permitted from a tenant context';
    END IF;
  END IF;

  SELECT * INTO v_listing
    FROM public.channel_listings l
   WHERE l.id = p_listing_id AND l.site_id = p_site_id
   FOR UPDATE;
  IF NOT FOUND THEN
    -- Same message for "wrong site": no cross-tenant existence oracle.
    RAISE EXCEPTION 'listing not found';
  END IF;

  -- The edge matrix (MARKETPLACE_CHANNEL_MODEL.md §4).
  IF p_actor_realm = 'merchant' THEN
    v_allowed :=
         (v_listing.status = 'draft' AND p_to_status = 'pending_review')
      OR (v_listing.status = 'rejected' AND p_to_status = 'draft')
      OR (v_listing.status = 'approved' AND p_to_status = 'paused')
      OR (v_listing.status = 'paused' AND p_to_status = 'approved' AND v_listing.approved_at IS NOT NULL)
      OR (v_listing.status IN ('draft', 'pending_review', 'approved', 'paused', 'rejected') AND p_to_status = 'delisted');
  ELSE
    v_allowed :=
         (v_listing.status = 'pending_review' AND p_to_status IN ('approved', 'rejected'))
      OR (v_listing.status = 'approved' AND p_to_status = 'delisted');
  END IF;
  IF NOT v_allowed THEN
    RAISE EXCEPTION 'invalid_transition: % -> % by %', v_listing.status, p_to_status, p_actor_realm;
  END IF;

  IF p_to_status = 'pending_review' THEN
    IF v_listing.channel = 'marketplace' AND v_listing.marketplace_category_id IS NULL THEN
      RAISE EXCEPTION 'marketplace listings require a marketplace_category_id before review';
    END IF;
    SELECT (p.is_active = true AND p.deleted_at IS NULL AND COALESCE(p.site_id, p.store_id) = v_listing.site_id)
      INTO v_product_ok
      FROM public.products p
     WHERE p.id = v_listing.product_id;
    IF NOT COALESCE(v_product_ok, false) THEN
      RAISE EXCEPTION 'product is not sellable';
    END IF;
  END IF;

  IF p_actor_realm = 'operator' AND p_to_status IN ('rejected', 'delisted') AND (p_reason IS NULL OR length(btrim(p_reason)) = 0) THEN
    RAISE EXCEPTION 'a reason is required for operator % decisions', p_to_status;
  END IF;

  -- Mark the transaction so the status guard trigger lets exactly this write through.
  PERFORM set_config('app.channel_listing_transition', 'rpc', true);

  UPDATE public.channel_listings l
     SET status = p_to_status,
         version = l.version + 1,
         updated_at = v_now,
         updated_by = COALESCE(p_actor_id, l.updated_by),
         submitted_at = CASE WHEN p_to_status = 'pending_review' THEN v_now ELSE l.submitted_at END,
         approved_at = CASE WHEN p_to_status = 'approved' AND p_actor_realm = 'operator' THEN v_now ELSE l.approved_at END,
         reviewed_at = CASE WHEN p_actor_realm = 'operator' THEN v_now ELSE l.reviewed_at END,
         reviewed_by = CASE WHEN p_actor_realm = 'operator' THEN p_actor_id ELSE l.reviewed_by END,
         rejection_reason = CASE WHEN p_to_status = 'rejected' THEN p_reason
                                 WHEN p_to_status = 'draft' THEN NULL
                                 ELSE l.rejection_reason END
   WHERE l.id = v_listing.id;

  INSERT INTO public.channel_listing_moderation_events (site_id, listing_id, from_status, to_status, actor_realm, actor_id, reason, idempotency_key)
  VALUES (p_site_id, v_listing.id, v_listing.status, p_to_status, p_actor_realm, p_actor_id, p_reason, p_idempotency_key)
  RETURNING id INTO v_event_id;

  PERFORM set_config('app.channel_listing_transition', '', true);

  RETURN QUERY SELECT v_listing.id, v_listing.status, p_to_status, v_event_id, false;
END;

DECLARE
  v_order       RECORD;
  v_existing_id uuid;
  v_new_id      uuid;
BEGIN
  IF p_buyer_account_id IS NULL OR p_order_id IS NULL OR p_reason IS NULL THEN
    RAISE EXCEPTION 'buyer account, order and reason are required';
  END IF;

  -- Serialize per order. Without this, two concurrent requests both see no open return and both
  -- insert one. Keyed on the order because that is the thing a duplicate would be about.
  PERFORM pg_advisory_xact_lock(hashtextextended('return_request:' || p_order_id::text, 0));

  -- Ownership is the explicit order link (255), never an email match: a matching address proves
  -- nothing until its owner has verified it and claimed the order.
  SELECT o.id, o.site_id
    INTO v_order
    FROM public.orders o
    JOIN public.buyer_order_links bol
      ON bol.order_id = o.id
     AND bol.buyer_account_id = p_buyer_account_id
   WHERE o.id = p_order_id
   LIMIT 1;

  IF NOT FOUND THEN
    -- Not this buyer's order, or no such order. The caller cannot tell which, deliberately.
    RETURN;
  END IF;

  SELECT rr.id INTO v_existing_id
    FROM public.return_requests rr
   WHERE rr.order_id = v_order.id
     AND rr.status IN ('pending', 'approved', 'processing')
   LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE EXCEPTION 'a return request is already open for this order'
      USING ERRCODE = '23505';
  END IF;

  -- status is written here, never taken from the caller. return_requests also carries
  -- refund_amount, approved_at, refunded_at, processed_by and admin_notes -- all merchant-owned, and
  -- none of them is a parameter of this function, so a buyer cannot file a return that is already
  -- refunded for an amount of their choosing.
  INSERT INTO public.return_requests (order_id, store_id, reason, description, status)
  VALUES (v_order.id, v_order.site_id, p_reason, nullif(btrim(coalesce(p_description, '')), ''), 'pending')
  RETURNING return_requests.id INTO v_new_id;

  RETURN QUERY
  SELECT rr.id, rr.order_id, rr.reason, rr.description, rr.status, rr.created_at
    FROM public.return_requests rr
   WHERE rr.id = v_new_id;
END;

BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.sites s
     WHERE s.id = NEW.site_id
       AND s.status = 'published'
       AND s.deleted_at IS NULL
  ) THEN
    RAISE EXCEPTION 'site % is not followable (must be a published, non-deleted site)', NEW.site_id
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;

DECLARE
  v_program public.loyalty_programs%ROWTYPE;
  v_account public.loyalty_accounts%ROWTYPE;
  v_order_total numeric(12,2);
  v_order_buyer uuid;
  v_points bigint;
  v_balance bigint;
  v_existing public.loyalty_ledger_entries%ROWTYPE;
BEGIN
  -- Share the programme boundary before any account/order lock. A value decrease
  -- takes the exclusive counterpart, so it cannot miss an in-flight earn or refund.
  PERFORM pg_advisory_xact_lock_shared(hashtextextended(p_site_id::text || ':loyalty.program', 3));
  IF p_site_id IS NULL OR p_buyer_account_id IS NULL OR p_order_id IS NULL THEN
    RAISE EXCEPTION 'site, buyer and order are required';
  END IF;
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) = 0 THEN
    RAISE EXCEPTION 'idempotency key is required';
  END IF;

  -- Serialize the logical order as well as its caller-supplied retry key.
  PERFORM pg_advisory_xact_lock(hashtextextended(p_site_id::text || ':loyalty.earn:' || p_order_id::text, 2));
  PERFORM pg_advisory_xact_lock(hashtextextended(p_site_id::text || ':' || p_idempotency_key, 2));

  SELECT * INTO v_existing
    FROM public.loyalty_ledger_entries
   WHERE site_id = p_site_id AND idempotency_key = p_idempotency_key
   LIMIT 1;
  IF FOUND THEN
    IF v_existing.order_id IS DISTINCT FROM p_order_id OR v_existing.entry_type<>'earned'
      OR NOT EXISTS(SELECT 1 FROM public.loyalty_accounts a WHERE a.id=v_existing.loyalty_account_id
        AND a.site_id=p_site_id AND a.buyer_account_id=p_buyer_account_id) THEN
      RAISE EXCEPTION 'loyalty earning idempotency payload conflict';
    END IF;
    RETURN jsonb_build_object(
      'entry_id', v_existing.id, 'points', v_existing.points,
      'balance', v_existing.balance_after, 'replayed', true
    );
  END IF;

  SELECT * INTO v_program FROM public.loyalty_programs WHERE site_id = p_site_id;
  IF NOT FOUND OR NOT v_program.is_active THEN
    RETURN jsonb_build_object('points', 0, 'balance', NULL, 'awarded', false, 'reason', 'program_inactive');
  END IF;

  SELECT o.total INTO v_order_total
    FROM public.orders o
   WHERE o.id = p_order_id AND o.site_id = p_site_id AND o.payment_status = 'paid' AND o.deleted_at IS NULL
   FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'order % is not a paid order for site %', p_order_id, p_site_id;
  END IF;

  -- The source subject must still own this order inside the money transaction.
  -- FOR SHARE prevents a concurrent ownership edit from passing this check and
  -- changing the subject before the immutable credit commits.
  SELECT l.buyer_account_id INTO v_order_buyer FROM public.buyer_order_links l
   WHERE l.order_id=p_order_id AND l.site_id=p_site_id FOR SHARE;
  IF NOT FOUND OR v_order_buyer IS DISTINCT FROM p_buyer_account_id THEN
    RAISE EXCEPTION 'loyalty earning buyer does not own the paid order';
  END IF;

  SELECT * INTO v_existing FROM public.loyalty_ledger_entries
   WHERE site_id=p_site_id AND order_id=p_order_id AND entry_type='earned' LIMIT 1;
  IF FOUND THEN
    IF NOT EXISTS(SELECT 1 FROM public.loyalty_accounts a WHERE a.id=v_existing.loyalty_account_id
      AND a.site_id=p_site_id AND a.buyer_account_id=p_buyer_account_id) THEN
      RAISE EXCEPTION 'loyalty earning source ownership conflict; reviewed recovery required';
    END IF;
    RETURN jsonb_build_object('entry_id',v_existing.id,'points',v_existing.points,
      'balance',v_existing.balance_after,'awarded',false,'replayed',true,'reason','already_awarded');
  END IF;

  v_points := public.loyalty_points_for_order_total_v1(v_order_total,v_program.earn_rate_bps);
  IF v_points <= 0 THEN
    RETURN jsonb_build_object('points', 0, 'balance', NULL, 'awarded', false, 'reason', 'below_minimum');
  END IF;

  INSERT INTO public.loyalty_accounts (site_id, buyer_account_id)
  VALUES (p_site_id, p_buyer_account_id)
  ON CONFLICT (site_id, buyer_account_id) DO NOTHING;

  SELECT * INTO v_account
    FROM public.loyalty_accounts
   WHERE site_id = p_site_id AND buyer_account_id = p_buyer_account_id
   FOR UPDATE;

  -- CHANGED BY 235: a frozen or closed account means "do not award", exactly as a paused programme
  -- does. Raising here made the two identical situations behave oppositely, and on the money path
  -- the difference is a failed payment capture.
  IF v_account.status <> 'active' THEN
    RETURN jsonb_build_object('points', 0, 'balance', NULL, 'awarded', false, 'reason', 'account_' || v_account.status);
  END IF;

  v_balance := public.loyalty_balance(v_account.id) + v_points;

  INSERT INTO public.loyalty_ledger_entries (
    site_id, loyalty_account_id, order_id, entry_type, points, balance_after,
    idempotency_key, request_id, metadata, created_by
  ) VALUES (
    p_site_id, v_account.id, p_order_id, 'earned', v_points, v_balance,
    p_idempotency_key, p_request_id,
    -- ADDED BY 243: what a point was worth WHEN IT WAS EARNED. Redemption reads the programme's
    -- CURRENT point_value_minor, so lowering it revalues every outstanding point; until now nothing
    -- recorded the earlier value and the change could not be reconstructed afterwards. This records
    -- the fact and changes no behaviour: redemption still values points at the current rate.
    jsonb_build_object(
      'point_value_minor', v_program.point_value_minor,
      'value_minor', v_points * v_program.point_value_minor,
      'earn_rate_bps', v_program.earn_rate_bps
    ),
    p_actor_id
  );

  RETURN jsonb_build_object('points', v_points, 'balance', v_balance, 'awarded', true);
END;

SELECT COALESCE(SUM(
  CASE WHEN entry_type = 'spent' THEN amount_minor ELSE 0 END
), 0)::bigint
  FROM public.ad_credit_ledger_entries
 WHERE campaign_id = p_campaign_id;

DECLARE
  v_tenant_guc text;
  v_account public.ad_credit_accounts%ROWTYPE;
  v_balance bigint;
  v_existing public.ad_credit_ledger_entries%ROWTYPE;
BEGIN
  IF p_amount_minor IS NULL OR p_amount_minor <= 0 THEN
    RAISE EXCEPTION 'purchase amount must be greater than zero';
  END IF;
  IF p_payment_reference IS NULL OR length(btrim(p_payment_reference)) = 0 THEN
    RAISE EXCEPTION 'a payment reference is required: credits are prepaid (D-5)';
  END IF;
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) = 0 THEN
    RAISE EXCEPTION 'idempotency key is required';
  END IF;

  -- ADDED BY 238. Defence in depth, and what makes the merchant ads routes safe to run inside the
  -- tenant transaction: when app.site_id is set, the site the route resolved ownership for and the
  -- site this function moves money for must be the same one. A route that resolves store A and then
  -- passes store B is refused by the DATABASE, not merely by review. When the GUC is unset the check
  -- does not apply -- a service_role caller has no tenant context to compare against, and inventing
  -- one here would be a second answer to "which tenant is this".
  v_tenant_guc := NULLIF(current_setting('app.site_id', true), '');
  IF v_tenant_guc IS NOT NULL AND v_tenant_guc::uuid <> p_site_id THEN
    RAISE EXCEPTION 'tenant context % does not match the requested site %', v_tenant_guc, p_site_id;
  END IF;

  -- Seed 3 domain-separates ad credits from create_checkout_order (0), issue_gift_card (1) and
  -- loyalty (2).
  PERFORM pg_advisory_xact_lock(hashtextextended(p_site_id::text || ':' || p_idempotency_key, 3));

  SELECT * INTO v_existing
    FROM public.ad_credit_ledger_entries
   WHERE site_id = p_site_id AND idempotency_key = p_idempotency_key
   LIMIT 1;
  IF FOUND THEN
    IF v_existing.entry_type <> 'purchased'
       OR v_existing.amount_minor IS DISTINCT FROM p_amount_minor
       OR v_existing.payment_reference IS DISTINCT FROM btrim(p_payment_reference) THEN
      RAISE EXCEPTION 'ad credit idempotency key conflicts with a different request payload';
    END IF;
    RETURN jsonb_build_object('entry_id', v_existing.id, 'amount_minor', v_existing.amount_minor,
                              'balance_minor', v_existing.balance_after_minor, 'replayed', true);
  END IF;

  INSERT INTO public.ad_credit_accounts (site_id) VALUES (p_site_id)
  ON CONFLICT (site_id) DO NOTHING;
  SELECT * INTO v_account FROM public.ad_credit_accounts WHERE site_id = p_site_id FOR UPDATE;
  IF v_account.status <> 'active' THEN
    RAISE EXCEPTION 'ad credit account is %', v_account.status;
  END IF;

  v_balance := public.ad_credit_balance_minor(v_account.id) + p_amount_minor;

  INSERT INTO public.ad_credit_ledger_entries (
    site_id, ad_credit_account_id, entry_type, amount_minor, balance_after_minor,
    idempotency_key, payment_reference, request_id, created_by
  ) VALUES (
    p_site_id, v_account.id, 'purchased', p_amount_minor, v_balance,
    p_idempotency_key, btrim(p_payment_reference), p_request_id, p_actor_id
  );

  RETURN jsonb_build_object('amount_minor', p_amount_minor, 'balance_minor', v_balance, 'purchased', true);
END;

DECLARE
  v_tenant_guc text;
  v_actor_guc text;
  v_site public.sites%ROWTYPE;
  v_account public.ad_credit_accounts%ROWTYPE;
  v_campaign public.ad_campaigns%ROWTYPE;
  v_balance bigint;
  v_existing public.ad_credit_ledger_entries%ROWTYPE;
BEGIN
  IF p_amount_minor IS NULL OR p_amount_minor <= 0 THEN
    RAISE EXCEPTION 'allocation must be greater than zero';
  END IF;
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) = 0 THEN
    RAISE EXCEPTION 'idempotency key is required';
  END IF;

  -- Merchant budget authority is captured in this same tenant transaction.
  v_tenant_guc := NULLIF(current_setting('app.site_id', true), '');
  v_actor_guc := NULLIF(current_setting('app.user_id', true), '');
  BEGIN
    IF v_tenant_guc IS NULL OR v_tenant_guc::uuid IS DISTINCT FROM p_site_id THEN
      RAISE EXCEPTION 'Current tenant site context is required for campaign budget' USING ERRCODE = '42501';
    END IF;
    IF p_actor_id IS NULL OR v_actor_guc IS NULL OR v_actor_guc::uuid IS DISTINCT FROM p_actor_id THEN
      RAISE EXCEPTION 'Current captured actor context is required for campaign budget' USING ERRCODE = '42501';
    END IF;
  EXCEPTION WHEN invalid_text_representation THEN
    RAISE EXCEPTION 'Invalid current tenant or actor context for campaign budget' USING ERRCODE = '42501';
  END;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_site_id::text || ':' || p_idempotency_key, 3));

  -- Lock identity and current ownership before either a new effect or a replay.
  PERFORM 1 FROM public.users_custom WHERE id = p_actor_id FOR KEY SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Current campaign budget actor is not authorized' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_site FROM public.sites WHERE id = p_site_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND OR (v_site.user_id IS DISTINCT FROM p_actor_id AND v_site.custom_user_id IS DISTINCT FROM p_actor_id) THEN
    RAISE EXCEPTION 'Current campaign budget owner is not authorized' USING ERRCODE = '42501';
  END IF;


  -- The campaign must belong to THIS site. Allocating one merchant's prepaid credits to another's
  -- campaign is the transfer D-5 forbids.
  SELECT * INTO v_campaign
    FROM public.ad_campaigns WHERE id = p_campaign_id AND site_id = p_site_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'campaign % does not belong to site %', p_campaign_id, p_site_id;
  END IF;

  SELECT * INTO v_account FROM public.ad_credit_accounts WHERE site_id = p_site_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no prepaid ad credit account for site %', p_site_id;
  END IF;
  IF v_account.status <> 'active' THEN
    RAISE EXCEPTION 'ad credit account is %', v_account.status;
  END IF;

  -- Current owner/campaign/account authority is established before cached success.
  SELECT * INTO v_existing
    FROM public.ad_credit_ledger_entries
   WHERE site_id = p_site_id AND idempotency_key = p_idempotency_key
   LIMIT 1;
  IF FOUND THEN
    IF v_existing.entry_type <> 'allocated'
       OR v_existing.campaign_id IS DISTINCT FROM p_campaign_id
       OR v_existing.amount_minor IS DISTINCT FROM p_amount_minor THEN
      RAISE EXCEPTION 'ad credit idempotency key conflicts with a different request payload';
    END IF;
    RETURN jsonb_build_object('entry_id', v_existing.id, 'amount_minor', v_existing.amount_minor,
                              'balance_minor', v_existing.balance_after_minor, 'replayed', true);
  END IF;

  v_balance := public.ad_credit_balance_minor(v_account.id);
  IF p_amount_minor > v_balance THEN
    -- Prepaid: there is no overdraft, because an overdraft is credit extended.
    RAISE EXCEPTION 'insufficient ad credits: % requested, % available', p_amount_minor, v_balance;
  END IF;

  INSERT INTO public.ad_credit_ledger_entries (
    site_id, ad_credit_account_id, campaign_id, entry_type, amount_minor, balance_after_minor,
    idempotency_key, request_id, created_by
  ) VALUES (
    p_site_id, v_account.id, p_campaign_id, 'allocated', p_amount_minor, v_balance - p_amount_minor,
    p_idempotency_key, p_request_id, p_actor_id
  );

  UPDATE public.ad_campaigns
     SET allocated_minor = allocated_minor + p_amount_minor, updated_at = now()
   WHERE id = p_campaign_id;

  RETURN jsonb_build_object('amount_minor', p_amount_minor, 'balance_minor', v_balance - p_amount_minor,
                            'campaign_allocated_minor', v_campaign.allocated_minor + p_amount_minor, 'allocated', true);
END;

DECLARE
  v_program public.loyalty_programs%ROWTYPE;
  v_account public.loyalty_accounts%ROWTYPE;
  v_order_total numeric(12,2);
  v_basis_minor bigint;
  v_balance bigint;
  v_max_points bigint;
  v_value_minor bigint;
  v_existing public.loyalty_ledger_entries%ROWTYPE;
BEGIN
  -- Share the programme boundary before any account/order lock. A value decrease
  -- takes the exclusive counterpart, so it cannot miss an in-flight earn or refund.
  PERFORM pg_advisory_xact_lock_shared(hashtextextended(p_site_id::text || ':loyalty.program', 3));
  IF p_points IS NULL OR p_points <= 0 THEN
    RAISE EXCEPTION 'points to redeem must be greater than zero';
  END IF;
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) = 0 THEN
    RAISE EXCEPTION 'idempotency key is required';
  END IF;
  IF p_max_value_minor IS NOT NULL AND p_max_value_minor < 0 THEN
    RAISE EXCEPTION 'the payable amount cannot be negative';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_site_id::text || ':' || p_idempotency_key, 2));

  SELECT * INTO v_existing
    FROM public.loyalty_ledger_entries
   WHERE site_id = p_site_id AND idempotency_key = p_idempotency_key
   LIMIT 1;
  IF FOUND THEN
    RETURN jsonb_build_object(
      'entry_id', v_existing.id, 'points', v_existing.points,
      'balance', v_existing.balance_after,
      'value_minor', (v_existing.metadata->>'value_minor')::bigint, 'replayed', true
    );
  END IF;

  SELECT * INTO v_program FROM public.loyalty_programs WHERE site_id = p_site_id;
  IF NOT FOUND OR NOT v_program.is_active THEN
    RAISE EXCEPTION 'loyalty is not active for site %', p_site_id;
  END IF;

  SELECT o.total INTO v_order_total
    FROM public.orders o
   WHERE o.id = p_order_id AND o.site_id = p_site_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'order % does not belong to site %', p_order_id, p_site_id;
  END IF;

  SELECT * INTO v_account
    FROM public.loyalty_accounts
   WHERE site_id = p_site_id AND buyer_account_id = p_buyer_account_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no loyalty account for this buyer at this site';
  END IF;
  IF v_account.status <> 'active' THEN
    RAISE EXCEPTION 'loyalty account is %', v_account.status;
  END IF;

  v_balance := public.loyalty_balance(v_account.id);
  IF p_points > v_balance THEN
    RAISE EXCEPTION 'insufficient loyalty points: % requested, % available', p_points, v_balance;
  END IF;

  -- The basis for the cap: the caller's authoritative amount when given, otherwise the order row.
  -- LEAST of both when both are available, so passing an amount can only ever TIGHTEN the cap —
  -- a caller cannot use this parameter to redeem beyond the programme's limit.
  v_basis_minor := LEAST(
    COALESCE(p_max_value_minor, (COALESCE(v_order_total, 0) * 100)::bigint),
    (COALESCE(v_order_total, 0) * 100)::bigint
  );

  v_max_points := floor(v_basis_minor * v_program.redeem_cap_bps / 10000.0 / v_program.point_value_minor)::bigint;
  IF p_points > v_max_points THEN
    RAISE EXCEPTION 'redemption exceeds the programme cap: % requested, % allowed on this order', p_points, v_max_points;
  END IF;

  v_value_minor := p_points * v_program.point_value_minor;

  -- Belt and braces: the value applied can never exceed what the caller said is payable. The cap
  -- above already guarantees this; if a future edit loosens the cap arithmetic, this still holds.
  IF p_max_value_minor IS NOT NULL AND v_value_minor > p_max_value_minor THEN
    RAISE EXCEPTION 'redemption value % exceeds the payable amount %', v_value_minor, p_max_value_minor;
  END IF;

  INSERT INTO public.loyalty_ledger_entries (
    site_id, loyalty_account_id, order_id, entry_type, points, balance_after,
    idempotency_key, request_id, metadata, created_by
  ) VALUES (
    p_site_id, v_account.id, p_order_id, 'redeemed', p_points, v_balance - p_points,
    p_idempotency_key, p_request_id,
    jsonb_build_object(
      'value_minor', v_value_minor,
      'point_value_minor', v_program.point_value_minor,
      'basis_minor', v_basis_minor
    ),
    p_actor_id
  );

  RETURN jsonb_build_object(
    'points', p_points, 'balance', v_balance - p_points,
    'value_minor', v_value_minor, 'redeemed', true
  );
END;

SELECT COALESCE(SUM(public.loyalty_balance(a.id)), 0)::bigint
  FROM public.loyalty_accounts a
 WHERE a.site_id = p_site_id;

DECLARE
  v_tenant_guc text;
  v_before public.loyalty_programs%ROWTYPE;
  v_after public.loyalty_programs%ROWTYPE;
  v_created boolean := false;
  v_outstanding bigint;
  v_liability_delta bigint;
BEGIN
  IF p_site_id IS NULL THEN
    RAISE EXCEPTION 'site is required';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.sites WHERE id = p_site_id) THEN
    RAISE EXCEPTION 'site % does not exist', p_site_id;
  END IF;

  -- Missing context is forbidden for the pooled tenant role. Backend service
  -- calls retain their existing ABI; a supplied context must always agree.
  v_tenant_guc := NULLIF(current_setting('app.site_id', true), '');
  IF (current_setting('role', true) = 'app_tenant' OR session_user = 'app_tenant') AND v_tenant_guc IS NULL THEN
    RAISE EXCEPTION 'tenant context is required' USING ERRCODE='42501';
  END IF;
  IF v_tenant_guc IS NOT NULL AND v_tenant_guc::uuid <> p_site_id THEN
    RAISE EXCEPTION 'tenant context % does not match the requested site %', v_tenant_guc, p_site_id;
  END IF;
  IF current_setting('role', true) = 'app_tenant' OR session_user = 'app_tenant' THEN
    PERFORM 1 FROM public.sites WHERE id=p_site_id AND deleted_at IS NULL
      AND (custom_user_id=p_actor_id OR user_id=p_actor_id) FOR SHARE;
    IF NOT FOUND OR p_actor_type IS DISTINCT FROM 'user' THEN
      RAISE EXCEPTION 'loyalty programme owner is required' USING ERRCODE='42501';
    END IF;
    SELECT email INTO p_actor_email FROM public.users_custom WHERE id=p_actor_id FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'loyalty programme owner is required' USING ERRCODE='42501'; END IF;
  END IF;
  -- This also serializes first creation, when no programme row exists to lock.
  -- Its shared counterpart is held by every canonical loyalty ledger writer.
  PERFORM pg_advisory_xact_lock(hashtextextended(p_site_id::text || ':loyalty.program', 3));

  -- Range checks ahead of the table CHECKs. The constraints are the backstop; these exist so a route
  -- can map a named error instead of a raw constraint violation, and so the message says which value.
  IF p_earn_rate_bps IS NOT NULL AND (p_earn_rate_bps < 0 OR p_earn_rate_bps > 10000) THEN
    RAISE EXCEPTION 'earn_rate_bps must be between 0 and 10000, got %', p_earn_rate_bps;
  END IF;
  IF p_redeem_cap_bps IS NOT NULL AND (p_redeem_cap_bps < 0 OR p_redeem_cap_bps > 10000) THEN
    RAISE EXCEPTION 'redeem_cap_bps must be between 0 and 10000, got %', p_redeem_cap_bps;
  END IF;
  IF p_point_value_minor IS NOT NULL AND p_point_value_minor <= 0 THEN
    RAISE EXCEPTION 'point_value_minor must be greater than zero, got %', p_point_value_minor;
  END IF;
  -- audit_logs constrains actor_type; rejecting here keeps the settings change and its audit row
  -- from parting company at the very last statement.
  IF p_actor_type IS NULL OR p_actor_type NOT IN ('user', 'employee', 'super_admin', 'system') THEN
    RAISE EXCEPTION 'actor_type must be one of user, employee, super_admin, system';
  END IF;

  -- One writer at a time per site. Without the lock two concurrent edits can each read the same
  -- "before" row, and the audit trail would then show two changes from the same starting state.
  SELECT * INTO v_before FROM public.loyalty_programs WHERE site_id = p_site_id FOR UPDATE;
  v_created := NOT FOUND;

  -- Read BEFORE the write. The number does not change with the settings, but capturing it here ties
  -- it to the state the merchant was actually looking at.
  v_outstanding := public.loyalty_outstanding_points(p_site_id);
  -- Owner decision D-LOY-REVALUE, 16 October 2026. Test each canonical
  -- account balance: a historical negative account cannot offset another buyer.
  IF NOT v_created AND p_point_value_minor < v_before.point_value_minor
    AND EXISTS(SELECT 1 FROM public.loyalty_accounts a WHERE a.site_id=p_site_id AND public.loyalty_balance(a.id)>0) THEN
    RAISE EXCEPTION 'LOYALTY_VALUE_DECREASE_BLOCKED';
  END IF;


  INSERT INTO public.loyalty_programs AS lp (
    site_id, is_active, earn_rate_bps, redeem_cap_bps, point_value_minor
  ) VALUES (
    p_site_id,
    COALESCE(p_is_active, false),
    COALESCE(p_earn_rate_bps, 0),
    COALESCE(p_redeem_cap_bps, 5000),
    COALESCE(p_point_value_minor, 100)
  )
  ON CONFLICT (site_id) DO UPDATE SET
    is_active         = COALESCE(p_is_active, lp.is_active),
    earn_rate_bps     = COALESCE(p_earn_rate_bps, lp.earn_rate_bps),
    redeem_cap_bps    = COALESCE(p_redeem_cap_bps, lp.redeem_cap_bps),
    point_value_minor = COALESCE(p_point_value_minor, lp.point_value_minor),
    updated_at        = greatest(clock_timestamp(), lp.updated_at + interval '1 microsecond')
  RETURNING * INTO v_after;

  -- The size of the revaluation, in paise, stated rather than left to be inferred from two rates.
  -- NULL on creation: there was no prior value, so nothing was revalued.
  v_liability_delta := CASE
    WHEN v_created THEN NULL
    ELSE v_outstanding * (v_after.point_value_minor - v_before.point_value_minor)
  END;

  INSERT INTO public.audit_logs (
    actor_id, actor_type, actor_email, action, resource_type, resource_id,
    old_values, new_values, metadata
  ) VALUES (
    p_actor_id,
    p_actor_type,
    p_actor_email,
    CASE WHEN v_created THEN 'loyalty_program.created' ELSE 'loyalty_program.updated' END,
    'loyalty_program',
    p_site_id,
    CASE WHEN v_created THEN NULL ELSE to_jsonb(v_before) END,
    to_jsonb(v_after),
    jsonb_build_object(
      'request_id', p_request_id,
      'outstanding_points', v_outstanding,
      'point_value_minor_before', CASE WHEN v_created THEN NULL ELSE v_before.point_value_minor END,
      'point_value_minor_after', v_after.point_value_minor,
      'liability_delta_minor', v_liability_delta
    )
  );

  RETURN jsonb_build_object(
    'site_id', v_after.site_id,
    'is_active', v_after.is_active,
    'earn_rate_bps', v_after.earn_rate_bps,
    'redeem_cap_bps', v_after.redeem_cap_bps,
    'point_value_minor', v_after.point_value_minor,
    'updated_at', v_after.updated_at,
    'created', v_created,
    'outstanding_points', v_outstanding,
    'liability_delta_minor', v_liability_delta
  );
END;

SELECT GREATEST(
  COALESCE((SELECT allocated_minor FROM public.ad_campaigns WHERE id = p_campaign_id), 0)
    - public.ad_campaign_spent_minor(p_campaign_id),
  0
)::bigint;

DECLARE
  v_tenant_guc text;
  v_campaign public.ad_campaigns%ROWTYPE;
  v_account public.ad_credit_accounts%ROWTYPE;
  v_existing public.ad_credit_ledger_entries%ROWTYPE;
  v_cost bigint;
  v_charged bigint;
  v_remaining bigint;
  v_daily_remaining bigint;
  v_clamped boolean := false;
BEGIN
  IF p_event_type IS NULL OR p_event_type NOT IN ('click', 'impression') THEN
    RAISE EXCEPTION 'event type must be click or impression';
  END IF;
  IF p_quantity IS NULL OR p_quantity <= 0 THEN
    RAISE EXCEPTION 'quantity must be greater than zero';
  END IF;
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) = 0 THEN
    RAISE EXCEPTION 'idempotency key is required';
  END IF;

  -- The same fence 237 and 238 carry: when a tenant transaction is in force, the site it resolved
  -- and the site this function spends from must be the same one.
  v_tenant_guc := NULLIF(current_setting('app.site_id', true), '');
  IF v_tenant_guc IS NOT NULL AND v_tenant_guc::uuid <> p_site_id THEN
    RAISE EXCEPTION 'tenant context % does not match the requested site %', v_tenant_guc, p_site_id;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_site_id::text || ':' || p_idempotency_key, 3));

  SELECT * INTO v_existing
    FROM public.ad_credit_ledger_entries
   WHERE site_id = p_site_id AND idempotency_key = p_idempotency_key
   LIMIT 1;
  IF FOUND THEN
    IF v_existing.entry_type <> 'spent'
       OR v_existing.campaign_id IS DISTINCT FROM p_campaign_id
       OR v_existing.metadata->>'event_type' IS DISTINCT FROM p_event_type
       OR (v_existing.metadata->>'quantity')::integer IS DISTINCT FROM p_quantity THEN
      RAISE EXCEPTION 'ad credit idempotency key conflicts with a different request payload';
    END IF;
    RETURN jsonb_build_object('entry_id', v_existing.id, 'charged_minor', v_existing.amount_minor,
                              'charged', true, 'replayed', true);
  END IF;

  SELECT * INTO v_campaign
    FROM public.ad_campaigns WHERE id = p_campaign_id AND site_id = p_site_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'campaign % does not belong to site %', p_campaign_id, p_site_id;
  END IF;

  -- A campaign that is not serving must not be billable, whatever the caller believes it saw.
  IF v_campaign.status <> 'active' THEN
    RETURN jsonb_build_object('charged', false, 'charged_minor', 0, 'reason', 'campaign_' || v_campaign.status);
  END IF;
  IF (v_campaign.starts_at IS NOT NULL AND v_campaign.starts_at > now())
     OR (v_campaign.ends_at IS NOT NULL AND v_campaign.ends_at < now()) THEN
    RETURN jsonb_build_object('charged', false, 'charged_minor', 0, 'reason', 'outside_campaign_window');
  END IF;

  -- Server-computed cost. An event the pricing model does not bill for costs nothing and writes NO
  -- ledger row: this is a money ledger, and counting impressions is an analytics concern.
  v_cost := CASE
    WHEN v_campaign.pricing_model = 'cpc' AND p_event_type = 'click'
      THEN v_campaign.bid_minor::bigint * p_quantity
    WHEN v_campaign.pricing_model = 'cpm' AND p_event_type = 'impression'
      -- Integer division floors, so a partial thousand is never rounded up into a charge.
      THEN (v_campaign.bid_minor::bigint * p_quantity) / 1000
    ELSE 0
  END;
  IF v_cost <= 0 THEN
    RETURN jsonb_build_object('charged', false, 'charged_minor', 0, 'reason', 'no_charge_for_event');
  END IF;

  SELECT * INTO v_account FROM public.ad_credit_accounts WHERE site_id = p_site_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no prepaid ad credit account for site %', p_site_id;
  END IF;
  IF v_account.status <> 'active' THEN
    RETURN jsonb_build_object('charged', false, 'charged_minor', 0, 'reason', 'account_' || v_account.status);
  END IF;

  v_remaining := public.ad_campaign_remaining_minor(p_campaign_id);
  IF v_remaining <= 0 THEN
    UPDATE public.ad_campaigns SET status = 'exhausted', updated_at = now() WHERE id = p_campaign_id;
    RETURN jsonb_build_object('charged', false, 'charged_minor', 0, 'reason', 'budget_exhausted');
  END IF;

  -- Clamp rather than refuse or overdraw. The last click of a budget is charged what is left of it:
  -- refusing would serve it free, and overdrawing is the credit D-5 forbids. The clamp is recorded
  -- so a merchant reading the ledger can see why one charge differs from the bid.
  v_charged := LEAST(v_cost, v_remaining);

  IF v_campaign.daily_budget_minor IS NOT NULL THEN
    v_daily_remaining := v_campaign.daily_budget_minor - public.ad_campaign_spent_today_minor(p_campaign_id, NULL);
    IF v_daily_remaining <= 0 THEN
      -- NOT exhausted: the campaign resumes tomorrow on its own, because "today" is a window and
      -- not a counter somebody has to reset.
      RETURN jsonb_build_object('charged', false, 'charged_minor', 0, 'reason', 'daily_budget_reached');
    END IF;
    v_charged := LEAST(v_charged, v_daily_remaining);
  END IF;

  v_clamped := v_charged < v_cost;

  INSERT INTO public.ad_credit_ledger_entries (
    site_id, ad_credit_account_id, campaign_id, entry_type, amount_minor, balance_after_minor,
    idempotency_key, request_id, metadata, created_by
  ) VALUES (
    p_site_id, v_account.id, p_campaign_id, 'spent', v_charged,
    -- The ACCOUNT balance is unchanged by a spend, which is exactly what 239 fixes. Recording it
    -- here keeps every entry's balance_after_minor meaning the same thing: the account balance
    -- after this entry.
    public.ad_credit_balance_minor(v_account.id),
    p_idempotency_key, p_request_id,
    jsonb_build_object(
      'event_type', p_event_type, 'quantity', p_quantity,
      'pricing_model', v_campaign.pricing_model, 'bid_minor', v_campaign.bid_minor,
      'cost_minor', v_cost, 'clamped', v_clamped
    ),
    p_actor_id
  );

  IF v_remaining - v_charged <= 0 THEN
    UPDATE public.ad_campaigns SET status = 'exhausted', updated_at = now() WHERE id = p_campaign_id;
  END IF;

  RETURN jsonb_build_object(
    'charged', true, 'charged_minor', v_charged, 'cost_minor', v_cost, 'clamped', v_clamped,
    'campaign_remaining_minor', v_remaining - v_charged,
    'exhausted', (v_remaining - v_charged) <= 0
  );
END;

DECLARE r public.loyalty_ledger_entries;v_credit public.loyalty_ledger_entries;
 v_order public.orders;v_balance bigint;v_points bigint:=0;v_count integer:=0;v_key text;v_metadata jsonb;
BEGIN
 IF p_site_id IS NULL OR p_order_id IS NULL THEN RAISE EXCEPTION 'site id and order id are required'; END IF;
 IF nullif(current_setting('app.site_id',true),'') IS NOT NULL
  AND nullif(current_setting('app.site_id',true),'')::uuid<>p_site_id THEN
  RAISE EXCEPTION 'tenant context does not match the requested site' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended(p_site_id::text||':loyalty.program',3));
 PERFORM pg_advisory_xact_lock(hashtextextended(p_site_id::text||':loyalty.refund:'||p_order_id::text,2));
 SELECT * INTO v_order FROM public.orders WHERE id=p_order_id AND store_id=p_site_id FOR SHARE;
 IF v_order.id IS NULL THEN RAISE EXCEPTION 'loyalty reversal order scope mismatch' USING ERRCODE='22023'; END IF;
 -- A partial refund does not return the entire redeemed tender. Preserve the
 -- existing full-order cancellation/refunded semantics, regardless of who wrote it.
 IF NOT public.loyalty_order_reversal_eligible_v1(p_site_id,p_order_id) THEN
  RETURN jsonb_build_object('restored',false,'restored_points',0,'restored_entries',0,'reason','order_not_reversed'); END IF;
 FOR r IN SELECT * FROM public.loyalty_ledger_entries WHERE site_id=p_site_id AND order_id=p_order_id AND entry_type='redeemed'
  ORDER BY loyalty_account_id,id LOOP
  -- Same account boundary as earning/redemption, in stable order. Paused
  -- programmes and closed accounts still receive what was actually spent.
  PERFORM 1 FROM public.loyalty_accounts WHERE id=r.loyalty_account_id AND site_id=p_site_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'loyalty reversal account scope mismatch' USING ERRCODE='22023'; END IF;
  v_key:='loyalty.refund_credit:'||p_order_id::text||':'||r.id::text;
  v_metadata:=jsonb_build_object('redeemed_entry_id',r.id,'points',r.points,
   'point_value_minor_at_redemption',r.metadata->>'point_value_minor','value_minor_at_redemption',r.metadata->>'value_minor');
  SELECT * INTO v_credit FROM public.loyalty_ledger_entries WHERE site_id=p_site_id AND idempotency_key=v_key;
  IF v_credit.id IS NOT NULL THEN
   IF v_credit.entry_type<>'refund_credit' OR v_credit.order_id IS DISTINCT FROM p_order_id
    OR v_credit.loyalty_account_id<>r.loyalty_account_id OR v_credit.points<>r.points OR v_credit.metadata IS DISTINCT FROM v_metadata THEN
    RAISE EXCEPTION 'loyalty reversal receipt source mismatch' USING ERRCODE='22023'; END IF;
   CONTINUE;
  END IF;
  v_balance:=public.loyalty_balance(r.loyalty_account_id);
  INSERT INTO public.loyalty_ledger_entries(site_id,loyalty_account_id,order_id,entry_type,points,balance_after,idempotency_key,request_id,metadata,created_by)
   VALUES(p_site_id,r.loyalty_account_id,p_order_id,'refund_credit',r.points,v_balance+r.points,v_key,p_request_id,v_metadata,p_actor_id);
  v_points:=v_points+r.points;v_count:=v_count+1;
 END LOOP;
 RETURN jsonb_build_object('restored',v_count>0,'restored_points',v_points,'restored_entries',v_count);
END

DECLARE
  v_tenant_guc text;
  v_actor_guc text;
  v_site public.sites%ROWTYPE;
  v_campaign public.ad_campaigns%ROWTYPE;
  v_account public.ad_credit_accounts%ROWTYPE;
  v_existing public.ad_credit_ledger_entries%ROWTYPE;
  v_releasable bigint;
  v_amount bigint;
BEGIN
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) = 0 THEN
    RAISE EXCEPTION 'idempotency key is required';
  END IF;

  -- Merchant budget authority is captured in this same tenant transaction.
  v_tenant_guc := NULLIF(current_setting('app.site_id', true), '');
  v_actor_guc := NULLIF(current_setting('app.user_id', true), '');
  BEGIN
    IF v_tenant_guc IS NULL OR v_tenant_guc::uuid IS DISTINCT FROM p_site_id THEN
      RAISE EXCEPTION 'Current tenant site context is required for campaign budget' USING ERRCODE = '42501';
    END IF;
    IF p_actor_id IS NULL OR v_actor_guc IS NULL OR v_actor_guc::uuid IS DISTINCT FROM p_actor_id THEN
      RAISE EXCEPTION 'Current captured actor context is required for campaign budget' USING ERRCODE = '42501';
    END IF;
  EXCEPTION WHEN invalid_text_representation THEN
    RAISE EXCEPTION 'Invalid current tenant or actor context for campaign budget' USING ERRCODE = '42501';
  END;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_site_id::text || ':' || p_idempotency_key, 3));

  -- Lock identity and current ownership before either a new effect or a replay.
  PERFORM 1 FROM public.users_custom WHERE id = p_actor_id FOR KEY SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Current campaign budget actor is not authorized' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_site FROM public.sites WHERE id = p_site_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND OR (v_site.user_id IS DISTINCT FROM p_actor_id AND v_site.custom_user_id IS DISTINCT FROM p_actor_id) THEN
    RAISE EXCEPTION 'Current campaign budget owner is not authorized' USING ERRCODE = '42501';
  END IF;


  -- Campaign first, then account: the same lock order allocation uses, so the two cannot deadlock
  -- against each other under concurrency.
  SELECT * INTO v_campaign
    FROM public.ad_campaigns WHERE id = p_campaign_id AND site_id = p_site_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'campaign % does not belong to site %', p_campaign_id, p_site_id;
  END IF;

  SELECT * INTO v_account FROM public.ad_credit_accounts WHERE site_id = p_site_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no prepaid ad credit account for site %', p_site_id;
  END IF;
  IF v_account.status <> 'active' THEN
    RAISE EXCEPTION 'ad credit account is %', v_account.status;
  END IF;

  -- Current owner/campaign/account authority is established before cached success.
  SELECT * INTO v_existing
    FROM public.ad_credit_ledger_entries
   WHERE site_id = p_site_id AND idempotency_key = p_idempotency_key
   LIMIT 1;
  IF FOUND THEN
    IF v_existing.entry_type <> 'released'
       OR v_existing.campaign_id IS DISTINCT FROM p_campaign_id
       OR (v_existing.metadata ? 'requested_amount_minor'
           AND v_existing.metadata->>'requested_amount_minor' IS DISTINCT FROM p_amount_minor::text)
       OR (NOT (v_existing.metadata ? 'requested_amount_minor')
           AND ((p_amount_minor IS NULL
                 AND v_existing.metadata->>'releasable_minor' IS DISTINCT FROM v_existing.amount_minor::text)
             OR (p_amount_minor IS NOT NULL
                 AND p_amount_minor IS DISTINCT FROM v_existing.amount_minor))) THEN
      RAISE EXCEPTION 'ad credit idempotency key conflicts with a different request payload';
    END IF;
    RETURN jsonb_build_object('entry_id', v_existing.id, 'amount_minor', v_existing.amount_minor,
                              'balance_minor', v_existing.balance_after_minor, 'replayed', true);
  END IF;

  -- What is left after everything already spent. Reuses the projection rather than re-deriving it,
  -- so "remaining" means one thing across serving, spending and releasing.
  v_releasable := public.ad_campaign_remaining_minor(p_campaign_id);
  v_amount := COALESCE(p_amount_minor, v_releasable);

  IF v_amount <= 0 THEN
    RETURN jsonb_build_object('released', false, 'amount_minor', 0, 'reason', 'nothing_to_release');
  END IF;
  IF v_amount > v_releasable THEN
    -- Releasing more than remains would credit the account with money the campaign already spent,
    -- inventing credit out of a ledger that is supposed to conserve it.
    RAISE EXCEPTION 'cannot release % from a campaign with % remaining', v_amount, v_releasable;
  END IF;

  INSERT INTO public.ad_credit_ledger_entries (
    site_id, ad_credit_account_id, campaign_id, entry_type, amount_minor, balance_after_minor,
    idempotency_key, request_id, metadata, created_by
  ) VALUES (
    p_site_id, v_account.id, p_campaign_id, 'released', v_amount,
    -- 'released' is a credit, so the account balance rises by exactly this amount.
    public.ad_credit_balance_minor(v_account.id) + v_amount,
    p_idempotency_key, p_request_id,
    jsonb_build_object('campaign_allocated_before', v_campaign.allocated_minor, 'releasable_minor', v_releasable,
                       'requested_amount_minor', p_amount_minor),
    p_actor_id
  );

  -- Together with the entry above, in one transaction. A credit without this decrement would leave
  -- the campaign believing it holds budget the account has already been given back.
  UPDATE public.ad_campaigns
     SET allocated_minor = allocated_minor - v_amount, updated_at = now()
   WHERE id = p_campaign_id;

  RETURN jsonb_build_object(
    'released', true,
    'amount_minor', v_amount,
    'balance_minor', public.ad_credit_balance_minor(v_account.id),
    'campaign_allocated_minor', v_campaign.allocated_minor - v_amount
  );
END;

BEGIN
  IF NEW.store_id IS NULL THEN
    SELECT store_id INTO NEW.store_id
      FROM public.products
     WHERE id = NEW.product_id;
  END IF;
  RETURN NEW;
END;

BEGIN
  IF NOT NEW.email_verified THEN
    NEW.email_verified_at := NULL;
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF NEW.email IS DISTINCT FROM OLD.email THEN
      -- A changed address is unproven. It stays verified only when the writer records a fresh
      -- verification time for it, which is what a verified change-of-address flow does.
      IF NEW.email_verified_at IS NULL OR NEW.email_verified_at IS NOT DISTINCT FROM OLD.email_verified_at THEN
        NEW.email_verified := false;
        NEW.email_verified_at := NULL;
      END IF;
      RETURN NEW;
    END IF;
    NEW.email_verified_at := COALESCE(NEW.email_verified_at, OLD.email_verified_at, now());
    RETURN NEW;
  END IF;

  NEW.email_verified_at := COALESCE(NEW.email_verified_at, now());
  RETURN NEW;
END;

DECLARE
  v_buyer   public.buyer_accounts%ROWTYPE;
  v_sc_id   uuid;
  v_link    public.buyer_store_customers%ROWTYPE;
  v_other   uuid;
BEGIN
  IF p_buyer_account_id IS NULL OR p_site_id IS NULL THEN
    RAISE EXCEPTION 'buyer account and store are required';
  END IF;

  -- One linking decision per buyer and store at a time.
  PERFORM pg_advisory_xact_lock(hashtextextended('buyer_store_link:' || p_buyer_account_id::text || ':' || p_site_id::text, 0));

  SELECT * INTO v_buyer FROM public.buyer_accounts WHERE id = p_buyer_account_id FOR SHARE;
  IF NOT FOUND OR v_buyer.status <> 'active' THEN
    RETURN jsonb_build_object('outcome', 'buyer_unavailable');
  END IF;

  IF NOT v_buyer.email_verified THEN
    INSERT INTO public.audit_logs (actor_id, actor_type, action, resource_type, resource_id, metadata)
    VALUES (p_buyer_account_id, 'buyer', 'buyer_store_link.refused_unverified', 'buyer_account', p_buyer_account_id,
            jsonb_build_object('site_id', p_site_id));
    RETURN jsonb_build_object('outcome', 'unverified');
  END IF;

  PERFORM 1 FROM public.sites s
   WHERE s.id = p_site_id AND s.deleted_at IS NULL AND s.site_type = 'store';
  IF NOT FOUND THEN
    RETURN jsonb_build_object('outcome', 'store_unavailable');
  END IF;

  -- The customer record at this store for this verified address. Case variants of one address are
  -- one person; the oldest record is the relationship.
  SELECT sc.id INTO v_sc_id
    FROM public.store_customers sc
   WHERE sc.store_id = p_site_id
     AND lower(btrim(sc.email)) = v_buyer.email
     AND sc.deleted_at IS NULL
   ORDER BY sc.created_at, sc.id
   LIMIT 1
   FOR UPDATE;

  IF v_sc_id IS NULL THEN
    INSERT INTO public.store_customers (store_id, email)
    VALUES (p_site_id, v_buyer.email)
    ON CONFLICT (store_id, email) DO NOTHING
    RETURNING id INTO v_sc_id;
    IF v_sc_id IS NULL THEN
      SELECT sc.id INTO v_sc_id FROM public.store_customers sc
       WHERE sc.store_id = p_site_id AND sc.email = v_buyer.email FOR UPDATE;
    END IF;
  END IF;

  SELECT * INTO v_link FROM public.buyer_store_customers WHERE store_customer_id = v_sc_id FOR UPDATE;
  IF FOUND THEN
    IF v_link.buyer_account_id <> p_buyer_account_id THEN
      INSERT INTO public.audit_logs (actor_id, actor_type, action, resource_type, resource_id, metadata)
      VALUES (p_buyer_account_id, 'buyer', 'buyer_store_link.conflict', 'store_customer', v_sc_id,
              jsonb_build_object('site_id', p_site_id, 'requesting_buyer_account_id', p_buyer_account_id,
                                 'linked_buyer_account_id', v_link.buyer_account_id, 'linked_basis', v_link.link_basis));
      RETURN jsonb_build_object('outcome', 'conflict');
    END IF;
    IF v_link.link_basis = 'legacy_unverified' THEN
      UPDATE public.buyer_store_customers
         SET link_basis = 'verified_email', verified_at = now()
       WHERE store_customer_id = v_sc_id;
      INSERT INTO public.audit_logs (actor_id, actor_type, action, resource_type, resource_id, metadata)
      VALUES (p_buyer_account_id, 'buyer', 'buyer_store_link.verified', 'store_customer', v_sc_id,
              jsonb_build_object('site_id', p_site_id, 'previous_basis', 'legacy_unverified',
                                 'email_verified_at', v_buyer.email_verified_at));
      RETURN jsonb_build_object('outcome', 'linked', 'store_customer_id', v_sc_id);
    END IF;
    RETURN jsonb_build_object('outcome', 'already_linked', 'store_customer_id', v_sc_id);
  END IF;

  -- One customer record per buyer per store: a buyer already linked here through a different record
  -- (an earlier address) is a conflict for a person to resolve, not something to guess at.
  SELECT bsc.store_customer_id INTO v_other
    FROM public.buyer_store_customers bsc
   WHERE bsc.buyer_account_id = p_buyer_account_id AND bsc.site_id = p_site_id;
  IF v_other IS NOT NULL THEN
    INSERT INTO public.audit_logs (actor_id, actor_type, action, resource_type, resource_id, metadata)
    VALUES (p_buyer_account_id, 'buyer', 'buyer_store_link.conflict', 'store_customer', v_sc_id,
            jsonb_build_object('site_id', p_site_id, 'requesting_buyer_account_id', p_buyer_account_id,
                               'existing_store_customer_id', v_other));
    RETURN jsonb_build_object('outcome', 'conflict');
  END IF;

  INSERT INTO public.buyer_store_customers (buyer_account_id, store_customer_id, site_id, link_basis, verified_at)
  VALUES (p_buyer_account_id, v_sc_id, p_site_id, 'verified_email', now());

  INSERT INTO public.audit_logs (actor_id, actor_type, action, resource_type, resource_id, metadata)
  VALUES (p_buyer_account_id, 'buyer', 'buyer_store_link.linked', 'store_customer', v_sc_id,
          jsonb_build_object('site_id', p_site_id, 'basis', 'verified_email',
                             'email_verified_at', v_buyer.email_verified_at));

  RETURN jsonb_build_object('outcome', 'linked', 'store_customer_id', v_sc_id);
END;

DECLARE
  v_buyer      public.buyer_accounts%ROWTYPE;
  v_linked     integer := 0;
  v_already    integer := 0;
  v_conflicts  uuid[] := ARRAY[]::uuid[];
  v_order      RECORD;
  v_owner      uuid;
BEGIN
  IF p_buyer_account_id IS NULL THEN
    RAISE EXCEPTION 'buyer account is required';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('buyer_order_claim:' || p_buyer_account_id::text, 0));

  SELECT * INTO v_buyer FROM public.buyer_accounts WHERE id = p_buyer_account_id FOR SHARE;
  IF NOT FOUND OR v_buyer.status <> 'active' THEN
    RETURN jsonb_build_object('outcome', 'buyer_unavailable');
  END IF;

  IF NOT v_buyer.email_verified THEN
    INSERT INTO public.audit_logs (actor_id, actor_type, action, resource_type, resource_id, metadata)
    VALUES (p_buyer_account_id, 'buyer', 'buyer_orders.claim_refused_unverified', 'buyer_account', p_buyer_account_id,
            jsonb_build_object('site_id', p_site_id));
    RETURN jsonb_build_object('outcome', 'unverified');
  END IF;

  -- No row lock on orders: the payment and fulfilment paths own those rows. The primary key of
  -- buyer_order_links is what makes a race between two claimants (or a claim and a checkout) safe:
  -- the second insert does nothing, and the owner is then read back.
  FOR v_order IN
    SELECT o.id, o.site_id
      FROM public.orders o
     WHERE lower(btrim(o.customer_email)) = v_buyer.email
       AND o.site_id IS NOT NULL
       AND o.deleted_at IS NULL
       AND (p_site_id IS NULL OR o.site_id = p_site_id)
     ORDER BY o.created_at, o.id
  LOOP
    INSERT INTO public.buyer_order_links (order_id, buyer_account_id, site_id, link_basis)
    VALUES (v_order.id, p_buyer_account_id, v_order.site_id, 'verified_email')
    ON CONFLICT (order_id) DO NOTHING;
    IF FOUND THEN
      v_linked := v_linked + 1;
    ELSE
      SELECT bol.buyer_account_id INTO v_owner FROM public.buyer_order_links bol WHERE bol.order_id = v_order.id;
      IF v_owner = p_buyer_account_id THEN
        v_already := v_already + 1;
      ELSE
        v_conflicts := v_conflicts || v_order.id;
      END IF;
    END IF;
  END LOOP;

  INSERT INTO public.audit_logs (actor_id, actor_type, action, resource_type, resource_id, metadata)
  VALUES (p_buyer_account_id, 'buyer', 'buyer_orders.claimed', 'buyer_account', p_buyer_account_id,
          jsonb_build_object('site_id', p_site_id, 'linked', v_linked, 'already_linked', v_already,
                             'conflict_order_ids', to_jsonb(v_conflicts),
                             'email_verified_at', v_buyer.email_verified_at));

  RETURN jsonb_build_object('outcome', 'claimed', 'linked', v_linked, 'already_linked', v_already,
                            'conflicts', coalesce(array_length(v_conflicts, 1), 0));
END;

DECLARE
  v_site     uuid;
  v_previous public.buyer_store_customers%ROWTYPE;
  v_other    uuid;
BEGIN
  IF p_store_customer_id IS NULL OR p_buyer_account_id IS NULL OR p_operator_id IS NULL
     OR nullif(btrim(coalesce(p_reason, '')), '') IS NULL THEN
    RAISE EXCEPTION 'store customer, buyer account, operator and reason are required';
  END IF;

  SELECT sc.store_id INTO v_site FROM public.store_customers sc WHERE sc.id = p_store_customer_id FOR UPDATE;
  IF v_site IS NULL THEN
    RETURN jsonb_build_object('outcome', 'store_customer_unavailable');
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('buyer_store_link:' || p_buyer_account_id::text || ':' || v_site::text, 0));

  PERFORM 1 FROM public.buyer_accounts b
   WHERE b.id = p_buyer_account_id AND b.status = 'active' AND b.email_verified;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('outcome', 'buyer_unavailable_or_unverified');
  END IF;

  SELECT bsc.store_customer_id INTO v_other
    FROM public.buyer_store_customers bsc
   WHERE bsc.buyer_account_id = p_buyer_account_id AND bsc.site_id = v_site
     AND bsc.store_customer_id <> p_store_customer_id;
  IF v_other IS NOT NULL THEN
    RETURN jsonb_build_object('outcome', 'buyer_has_other_record_at_store');
  END IF;

  SELECT * INTO v_previous FROM public.buyer_store_customers WHERE store_customer_id = p_store_customer_id FOR UPDATE;
  DELETE FROM public.buyer_store_customers WHERE store_customer_id = p_store_customer_id;

  INSERT INTO public.buyer_store_customers (buyer_account_id, store_customer_id, site_id, link_basis, verified_at)
  VALUES (p_buyer_account_id, p_store_customer_id, v_site, 'operator_resolution', now());

  INSERT INTO public.audit_logs (actor_id, actor_type, action, resource_type, resource_id, metadata)
  VALUES (p_operator_id, 'employee', 'buyer_store_link.operator_resolved', 'store_customer', p_store_customer_id,
          jsonb_build_object('site_id', v_site, 'buyer_account_id', p_buyer_account_id,
                             'previous_buyer_account_id', v_previous.buyer_account_id,
                             'previous_basis', v_previous.link_basis, 'reason', btrim(p_reason)));

  RETURN jsonb_build_object('outcome', 'resolved');
END;

DECLARE
  v_site     uuid;
  v_previous public.buyer_order_links%ROWTYPE;
BEGIN
  IF p_order_id IS NULL OR p_buyer_account_id IS NULL OR p_operator_id IS NULL
     OR nullif(btrim(coalesce(p_reason, '')), '') IS NULL THEN
    RAISE EXCEPTION 'order, buyer account, operator and reason are required';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('buyer_order_link:' || p_order_id::text, 0));

  SELECT o.site_id INTO v_site FROM public.orders o WHERE o.id = p_order_id AND o.site_id IS NOT NULL;
  IF v_site IS NULL THEN
    RETURN jsonb_build_object('outcome', 'order_unavailable');
  END IF;

  PERFORM 1 FROM public.buyer_accounts b
   WHERE b.id = p_buyer_account_id AND b.status = 'active' AND b.email_verified;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('outcome', 'buyer_unavailable_or_unverified');
  END IF;

  SELECT * INTO v_previous FROM public.buyer_order_links WHERE order_id = p_order_id FOR UPDATE;

  INSERT INTO public.buyer_order_links (order_id, buyer_account_id, site_id, link_basis, linked_at)
  VALUES (p_order_id, p_buyer_account_id, v_site, 'operator_resolution', now())
  ON CONFLICT (order_id) DO UPDATE
     SET buyer_account_id = EXCLUDED.buyer_account_id,
         link_basis = 'operator_resolution',
         linked_at = now();

  INSERT INTO public.audit_logs (actor_id, actor_type, action, resource_type, resource_id, metadata)
  VALUES (p_operator_id, 'employee', 'buyer_order_link.operator_resolved', 'order', p_order_id,
          jsonb_build_object('site_id', v_site, 'buyer_account_id', p_buyer_account_id,
                             'previous_buyer_account_id', v_previous.buyer_account_id,
                             'previous_basis', v_previous.link_basis, 'reason', btrim(p_reason)));

  RETURN jsonb_build_object('outcome', 'resolved');
END;

DECLARE
  v_buyer  public.buyer_accounts%ROWTYPE;
  v_recent integer;
  v_code   text;
  v_salt   text;
  v_id     uuid;
  v_expiry timestamptz := now() + interval '10 minutes';
BEGIN
  IF p_buyer_account_id IS NULL OR p_purpose NOT IN ('verify_email', 'reset_password') THEN
    RAISE EXCEPTION 'buyer account and a known purpose are required';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('buyer_email_challenge:' || p_buyer_account_id::text || ':' || p_purpose, 0));

  SELECT * INTO v_buyer FROM public.buyer_accounts WHERE id = p_buyer_account_id FOR SHARE;
  IF NOT FOUND OR v_buyer.status <> 'active' THEN
    RETURN jsonb_build_object('outcome', 'buyer_unavailable');
  END IF;

  SELECT count(*) INTO v_recent
    FROM public.buyer_email_challenges
   WHERE buyer_account_id = p_buyer_account_id AND purpose = p_purpose
     AND created_at > now() - interval '1 hour';
  IF v_recent >= 5 THEN
    RETURN jsonb_build_object('outcome', 'rate_limited');
  END IF;

  UPDATE public.buyer_email_challenges
     SET consumed_at = now(), outcome = 'superseded'
   WHERE buyer_account_id = p_buyer_account_id AND purpose = p_purpose AND consumed_at IS NULL;

  -- Six uniform digits: 4 random bytes reduced modulo 10^6 (a bias below 0.03%, immaterial for a
  -- code limited to 5 guesses).
  v_code := lpad(((('x' || encode(extensions.gen_random_bytes(4), 'hex'))::bit(32)::bigint & 4294967295) % 1000000)::text, 6, '0');
  v_salt := encode(extensions.gen_random_bytes(16), 'hex');

  INSERT INTO public.buyer_email_challenges (buyer_account_id, purpose, email, code_salt, code_hash, expires_at)
  VALUES (p_buyer_account_id, p_purpose, v_buyer.email, v_salt,
          encode(extensions.digest(v_salt || v_code, 'sha256'), 'hex'), v_expiry)
  RETURNING id INTO v_id;

  INSERT INTO public.audit_logs (actor_id, actor_type, action, resource_type, resource_id, metadata)
  VALUES (p_buyer_account_id, 'buyer', 'buyer_email_challenge.started', 'buyer_account', p_buyer_account_id,
          jsonb_build_object('purpose', p_purpose, 'challenge_id', v_id));

  RETURN jsonb_build_object('outcome', 'started', 'challenge_id', v_id, 'code', v_code,
                            'email', v_buyer.email, 'expires_at', v_expiry);
END;

DECLARE
  v_ch     public.buyer_email_challenges%ROWTYPE;
  v_buyer  public.buyer_accounts%ROWTYPE;
  v_epoch  integer;
BEGIN
  IF p_buyer_account_id IS NULL OR p_purpose IS NULL OR p_code IS NULL THEN
    RETURN jsonb_build_object('outcome', 'invalid');
  END IF;
  IF p_purpose = 'reset_password' AND nullif(p_new_password_hash, '') IS NULL THEN
    RAISE EXCEPTION 'a new password hash is required to reset a password';
  END IF;

  -- Row-locked, so two requests carrying the right code cannot both succeed: the second re-reads the
  -- row after the first commits, finds it consumed, and gets 'invalid'.
  SELECT * INTO v_ch
    FROM public.buyer_email_challenges
   WHERE buyer_account_id = p_buyer_account_id AND purpose = p_purpose AND consumed_at IS NULL
   ORDER BY created_at DESC
   LIMIT 1
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('outcome', 'invalid');
  END IF;
  IF v_ch.expires_at <= now() THEN
    RETURN jsonb_build_object('outcome', 'expired');
  END IF;

  IF encode(extensions.digest(v_ch.code_salt || p_code, 'sha256'), 'hex') <> v_ch.code_hash THEN
    UPDATE public.buyer_email_challenges
       SET attempts = attempts + 1,
           consumed_at = CASE WHEN attempts + 1 >= max_attempts THEN now() END,
           outcome = CASE WHEN attempts + 1 >= max_attempts THEN 'locked' END
     WHERE id = v_ch.id;
    RETURN jsonb_build_object('outcome', CASE WHEN v_ch.attempts + 1 >= v_ch.max_attempts THEN 'locked' ELSE 'invalid' END);
  END IF;

  SELECT * INTO v_buyer FROM public.buyer_accounts WHERE id = v_ch.buyer_account_id FOR UPDATE;
  IF NOT FOUND OR v_buyer.status <> 'active' THEN
    UPDATE public.buyer_email_challenges SET consumed_at = now() WHERE id = v_ch.id;
    RETURN jsonb_build_object('outcome', 'buyer_unavailable');
  END IF;
  -- The code proves control of the address it was sent to, and nothing else.
  IF v_buyer.email <> v_ch.email THEN
    UPDATE public.buyer_email_challenges SET consumed_at = now(), outcome = 'address_changed' WHERE id = v_ch.id;
    RETURN jsonb_build_object('outcome', 'address_changed');
  END IF;

  IF v_ch.purpose = 'verify_email' THEN
    UPDATE public.buyer_accounts SET email_verified = true, updated_at = now() WHERE id = v_buyer.id;
    UPDATE public.buyer_email_challenges SET consumed_at = now(), outcome = 'verified' WHERE id = v_ch.id;
    INSERT INTO public.audit_logs (actor_id, actor_type, action, resource_type, resource_id, metadata)
    VALUES (v_buyer.id, 'buyer', 'buyer_email.verified', 'buyer_account', v_buyer.id,
            jsonb_build_object('challenge_id', v_ch.id));
    RETURN jsonb_build_object('outcome', 'verified', 'buyer_account_id', v_buyer.id, 'session_epoch', v_buyer.session_epoch);
  END IF;

  -- reset_password: proving the address also verifies it, and every existing session ends.
  UPDATE public.buyer_accounts
     SET password_hash = p_new_password_hash,
         email_verified = true,
         session_epoch = session_epoch + 1,
         updated_at = now()
   WHERE id = v_buyer.id
  RETURNING session_epoch INTO v_epoch;
  UPDATE public.buyer_email_challenges SET consumed_at = now(), outcome = 'password_reset' WHERE id = v_ch.id;
  INSERT INTO public.audit_logs (actor_id, actor_type, action, resource_type, resource_id, metadata)
  VALUES (v_buyer.id, 'buyer', 'buyer_password.reset', 'buyer_account', v_buyer.id,
          jsonb_build_object('challenge_id', v_ch.id, 'session_epoch', v_epoch));
  RETURN jsonb_build_object('outcome', 'password_reset', 'buyer_account_id', v_buyer.id, 'session_epoch', v_epoch);
END;

DECLARE
  v_epoch integer;
BEGIN
  IF p_buyer_account_id IS NULL THEN
    RAISE EXCEPTION 'buyer account is required';
  END IF;
  UPDATE public.buyer_accounts
     SET session_epoch = session_epoch + 1, updated_at = now()
   WHERE id = p_buyer_account_id
  RETURNING session_epoch INTO v_epoch;
  IF v_epoch IS NULL THEN
    RETURN jsonb_build_object('outcome', 'buyer_unavailable');
  END IF;
  INSERT INTO public.audit_logs (actor_id, actor_type, action, resource_type, resource_id, metadata)
  VALUES (p_buyer_account_id, 'buyer', 'buyer_sessions.revoked', 'buyer_account', p_buyer_account_id,
          jsonb_build_object('session_epoch', v_epoch));
  RETURN jsonb_build_object('outcome', 'revoked', 'session_epoch', v_epoch);
END;

DECLARE
  v_buyer  public.buyer_accounts%ROWTYPE;
  v_code   text;
  v_expiry timestamptz := now() + interval '60 seconds';
BEGIN
  IF p_redirect_uri IS NULL OR p_redirect_uri = ''
     OR p_code_challenge IS NULL OR p_code_challenge !~ '^[A-Za-z0-9_-]{43}$' THEN
    RETURN jsonb_build_object('outcome', 'invalid_request');
  END IF;

  IF p_client_id = 'letbuyy-storefront' THEN
    -- 258's rule: a storefront code names a live site; the gateway resolved it from the callback's host.
    IF p_site_id IS NULL THEN
      RETURN jsonb_build_object('outcome', 'invalid_request');
    END IF;
  ELSIF p_client_id = 'letbuyy-marketplace-app' THEN
    -- The app is platform-wide and has exactly one callback.
    IF p_site_id IS NOT NULL OR p_redirect_uri <> 'com.letbuyy.letbuyy:/oauth/callback' THEN
      RETURN jsonb_build_object('outcome', 'invalid_request');
    END IF;
  ELSE
    RETURN jsonb_build_object('outcome', 'invalid_request');
  END IF;

  SELECT * INTO v_buyer FROM public.buyer_accounts WHERE id = p_buyer_account_id FOR SHARE;
  IF NOT FOUND OR v_buyer.status <> 'active' THEN
    RETURN jsonb_build_object('outcome', 'buyer_unavailable');
  END IF;

  IF p_site_id IS NOT NULL THEN
    PERFORM 1 FROM public.sites s WHERE s.id = p_site_id AND s.deleted_at IS NULL;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('outcome', 'invalid_request');
    END IF;
  END IF;

  -- base64url, unpadded: 43 characters from 32 random bytes.
  v_code := rtrim(translate(encode(extensions.gen_random_bytes(32), 'base64'), '+/', '-_'), '=');

  INSERT INTO public.buyer_authorization_codes
    (code_hash, buyer_account_id, client_id, redirect_uri, site_id, code_challenge, session_epoch, expires_at)
  VALUES
    (encode(extensions.digest(v_code, 'sha256'), 'hex'), v_buyer.id, p_client_id, p_redirect_uri, p_site_id,
     p_code_challenge, v_buyer.session_epoch, v_expiry);

  INSERT INTO public.audit_logs (actor_id, actor_type, action, resource_type, resource_id, metadata)
  VALUES (v_buyer.id, 'buyer', 'buyer_authorization_code.issued', 'buyer_account', v_buyer.id,
          jsonb_build_object('client_id', p_client_id, 'site_id', p_site_id));

  RETURN jsonb_build_object('outcome', 'issued', 'code', v_code, 'expires_at', v_expiry);
END;

DECLARE
  v_row    public.buyer_authorization_codes%ROWTYPE;
  v_buyer  public.buyer_accounts%ROWTYPE;
  v_reason text;
BEGIN
  IF p_code IS NULL OR p_code !~ '^[A-Za-z0-9_-]{43}$' THEN
    RETURN jsonb_build_object('outcome', 'invalid_grant');
  END IF;

  SELECT * INTO v_row
    FROM public.buyer_authorization_codes
   WHERE code_hash = encode(extensions.digest(p_code, 'sha256'), 'hex')
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('outcome', 'invalid_grant');
  END IF;

  IF v_row.redeemed_at IS NOT NULL THEN
    v_reason := 'already_redeemed';
  ELSIF v_row.expires_at <= now() THEN
    v_reason := 'expired';
  ELSIF p_client_id IS DISTINCT FROM v_row.client_id OR p_redirect_uri IS DISTINCT FROM v_row.redirect_uri THEN
    v_reason := 'client_or_redirect_mismatch';
  ELSIF p_code_verifier IS NULL OR p_code_verifier !~ '^[A-Za-z0-9._~-]{43,128}$'
     OR rtrim(translate(encode(extensions.digest(p_code_verifier, 'sha256'), 'base64'), '+/', '-_'), '=')
        <> v_row.code_challenge THEN
    v_reason := 'pkce_mismatch';
  END IF;

  IF v_reason IS NULL THEN
    SELECT * INTO v_buyer FROM public.buyer_accounts WHERE id = v_row.buyer_account_id FOR SHARE;
    IF NOT FOUND OR v_buyer.status <> 'active' THEN
      v_reason := 'buyer_unavailable';
    ELSIF v_buyer.session_epoch <> v_row.session_epoch THEN
      v_reason := 'session_ended';
    END IF;
  END IF;

  -- A real code is used up by any attempt: a refused one cannot be retried.
  UPDATE public.buyer_authorization_codes
     SET redeemed_at = COALESCE(redeemed_at, now())
   WHERE id = v_row.id;

  IF v_reason IS NOT NULL THEN
    INSERT INTO public.audit_logs (actor_id, actor_type, action, resource_type, resource_id, metadata)
    VALUES (v_row.buyer_account_id, 'buyer', 'buyer_authorization_code.refused', 'buyer_account', v_row.buyer_account_id,
            jsonb_build_object('reason', v_reason, 'client_id', v_row.client_id, 'site_id', v_row.site_id));
    RETURN jsonb_build_object('outcome', 'invalid_grant');
  END IF;

  INSERT INTO public.audit_logs (actor_id, actor_type, action, resource_type, resource_id, metadata)
  VALUES (v_row.buyer_account_id, 'buyer', 'buyer_authorization_code.redeemed', 'buyer_account', v_row.buyer_account_id,
          jsonb_build_object('client_id', v_row.client_id, 'site_id', v_row.site_id));

  RETURN jsonb_build_object('outcome', 'redeemed', 'buyer_account_id', v_row.buyer_account_id,
                            'site_id', v_row.site_id, 'client_id', v_row.client_id,
                            'session_epoch', v_row.session_epoch);
END;

DECLARE
  v_buyer public.buyer_accounts%ROWTYPE;
  v_link  public.buyer_firebase_links%ROWTYPE;
  v_email text := lower(btrim(coalesce(p_firebase_email, '')));
BEGIN
  IF p_buyer_account_id IS NULL OR coalesce(p_firebase_uid, '') = '' OR coalesce(p_firebase_project, '') = '' OR v_email = '' THEN
    RAISE EXCEPTION 'buyer, Firebase uid, project and email are required';
  END IF;

  SELECT * INTO v_buyer FROM public.buyer_accounts WHERE id = p_buyer_account_id FOR UPDATE;
  IF NOT FOUND OR v_buyer.status <> 'active' THEN
    RETURN jsonb_build_object('outcome', 'buyer_unavailable');
  END IF;
  -- The buyer's own address must be proven, not merely typed: linking on an unverified address would
  -- let whoever registered it first claim someone's Firebase-era data.
  IF NOT v_buyer.email_verified THEN
    RETURN jsonb_build_object('outcome', 'unverified');
  END IF;
  IF v_buyer.email <> v_email THEN
    INSERT INTO public.audit_logs (actor_id, actor_type, action, resource_type, resource_id, metadata)
    VALUES (v_buyer.id, 'buyer', 'buyer_firebase_link.email_mismatch', 'buyer_account', v_buyer.id,
            jsonb_build_object('firebase_project', p_firebase_project));
    RETURN jsonb_build_object('outcome', 'email_mismatch');
  END IF;

  SELECT * INTO v_link FROM public.buyer_firebase_links WHERE firebase_uid = p_firebase_uid FOR UPDATE;
  IF FOUND THEN
    IF v_link.buyer_account_id = v_buyer.id THEN
      RETURN jsonb_build_object('outcome', 'already_linked');
    END IF;
    -- Never re-point a uid: the first verified owner keeps it, and the conflict is left for a person.
    INSERT INTO public.audit_logs (actor_id, actor_type, action, resource_type, resource_id, metadata)
    VALUES (v_buyer.id, 'buyer', 'buyer_firebase_link.conflict', 'buyer_account', v_buyer.id,
            jsonb_build_object('firebase_project', p_firebase_project, 'linked_buyer_account_id', v_link.buyer_account_id));
    RETURN jsonb_build_object('outcome', 'conflict');
  END IF;

  INSERT INTO public.buyer_firebase_links (firebase_uid, buyer_account_id, firebase_project, email_at_link)
  VALUES (p_firebase_uid, v_buyer.id, p_firebase_project, v_email);
  INSERT INTO public.audit_logs (actor_id, actor_type, action, resource_type, resource_id, metadata)
  VALUES (v_buyer.id, 'buyer', 'buyer_firebase_link.linked', 'buyer_account', v_buyer.id,
          jsonb_build_object('firebase_project', p_firebase_project));
  RETURN jsonb_build_object('outcome', 'linked');
END;

BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;

DECLARE
  v_ticket public.support_tickets%ROWTYPE;
  v_message public.ticket_messages%ROWTYPE;
  v_previous_status text;
  v_status text;
  v_first_response_at timestamptz;
  v_now timestamptz;
  v_constraint text;
BEGIN
  IF p_ticket_id IS NULL OR p_actor_id IS NULL THEN
    RAISE EXCEPTION 'reply_to_support_ticket: a ticket and an actor are required' USING ERRCODE = '22023';
  END IF;
  IF p_visibility IS NULL OR p_visibility NOT IN ('public', 'internal') THEN
    RAISE EXCEPTION 'reply_to_support_ticket: visibility must be public or internal' USING ERRCODE = '22023';
  END IF;
  IF p_body IS NULL OR btrim(p_body) = '' THEN
    RAISE EXCEPTION 'reply_to_support_ticket: a reply needs a body' USING ERRCODE = '22023';
  END IF;
  IF p_reason IS NULL OR btrim(p_reason) = '' THEN
    RAISE EXCEPTION 'reply_to_support_ticket: a reply needs a reason' USING ERRCODE = '22023';
  END IF;
  IF p_status IS NOT NULL AND p_status NOT IN ('open', 'pending_customer', 'pending_internal', 'escalated', 'resolved', 'closed') THEN
    RAISE EXCEPTION 'reply_to_support_ticket: unknown status' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_ticket
    FROM public.support_tickets
   WHERE id = p_ticket_id
     AND deleted_at IS NULL
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'support ticket not found' USING ERRCODE = 'P0002';
  END IF;

  v_now := clock_timestamp();
  v_previous_status := v_ticket.status;
  v_status := coalesce(p_status, CASE WHEN p_visibility = 'public' THEN 'pending_customer' ELSE v_ticket.status END);
  v_first_response_at := CASE WHEN p_visibility = 'public' THEN coalesce(v_ticket.first_response_at, v_now) ELSE v_ticket.first_response_at END;

  BEGIN
    UPDATE public.support_tickets
       SET status = v_status,
           first_response_at = v_first_response_at,
           last_agent_message_at = v_now,
           updated_by = p_actor_id
     WHERE id = p_ticket_id
    RETURNING * INTO v_ticket;
  EXCEPTION WHEN unique_violation THEN
    GET STACKED DIAGNOSTICS v_constraint = CONSTRAINT_NAME;
    IF v_constraint = 'support_tickets_privacy_open_request_uidx' THEN
      RAISE EXCEPTION 'support_ticket_privacy_request_conflict' USING ERRCODE = '23505';
    END IF;
    RAISE;
  END;

  INSERT INTO public.ticket_messages (
    ticket_id, author_type, author_id, author_email, visibility, body, macro_id, attachments, metadata, created_at, created_by
  )
  VALUES (
    p_ticket_id, 'agent', p_actor_id, p_actor_email, p_visibility, p_body, p_macro_id,
    coalesce(p_attachments, '[]'::jsonb), coalesce(p_metadata, '{}'::jsonb), v_now, p_actor_id
  )
  RETURNING * INTO v_message;

  IF v_first_response_at IS NOT NULL THEN
    UPDATE public.ticket_sla_clocks
       SET satisfied_at = v_first_response_at,
           updated_by = p_actor_id
     WHERE ticket_id = p_ticket_id
       AND clock_type = 'first_response';
  END IF;
  IF v_status = 'pending_customer' THEN
    UPDATE public.ticket_sla_clocks
       SET paused = true,
           paused_at = v_now,
           updated_by = p_actor_id
     WHERE ticket_id = p_ticket_id
       AND clock_type = 'resolution'
       AND satisfied_at IS NULL;
  END IF;

  INSERT INTO public.audit_logs (actor_id, actor_type, actor_email, action, resource_type, resource_id, metadata, created_at)
  VALUES (
    p_actor_id,
    'employee',
    p_actor_email,
    CASE WHEN p_visibility = 'internal' THEN 'support.ticket.internal_note' ELSE 'support.ticket.reply' END,
    'support_ticket',
    p_ticket_id,
    jsonb_build_object(
      'visibility', p_visibility,
      'status', v_status,
      'previous_status', v_previous_status,
      'message_id', v_message.id,
      'reason', p_reason
    ),
    v_now
  );

  RETURN jsonb_build_object('ticket', to_jsonb(v_ticket), 'message', to_jsonb(v_message));
END;

DECLARE v_ticket public.support_tickets%ROWTYPE; v_case_id uuid;
BEGIN
  SELECT * INTO STRICT v_ticket FROM public.support_tickets WHERE id=p_ticket_id AND deleted_at IS NULL FOR UPDATE;
  -- Reuse the existing canonical case, including explicit escalation retries with a new key.
  IF v_ticket.linked_ts_case_id IS NOT NULL THEN RETURN v_ticket.linked_ts_case_id; END IF;
  INSERT INTO public.ts_cases (site_id,subject_type,subject_id,category,severity,status,title,summary,opened_by,metadata,created_by)
  VALUES (v_ticket.site_id,CASE WHEN v_ticket.site_id IS NULL THEN 'custom' ELSE 'site' END,
    coalesce(v_ticket.site_id,p_ticket_id)::text,'abuse_report','high','open','Support escalation: '||v_ticket.subject,
    p_reason,p_actor_id,jsonb_build_object('source','support-ticket','support_ticket_id',p_ticket_id),p_actor_id)
  RETURNING id INTO v_case_id;
  INSERT INTO public.ts_evidence (case_id,evidence_type,source,title,description,content,metadata,created_by)
  VALUES (v_case_id,'support_ticket','support','Support ticket escalation evidence',p_reason,
    jsonb_build_object('support_ticket_id',p_ticket_id,'subject',v_ticket.subject,'requester_email',v_ticket.requester_email),
    jsonb_build_object('actor_email',p_actor_email),p_actor_id);
  INSERT INTO public.ts_case_events (case_id,event_type,actor_type,actor_id,reason,evidence,metadata,created_by)
  VALUES (v_case_id,'case_opened','employee',p_actor_id,p_reason,jsonb_build_object('support_ticket_id',p_ticket_id),
    jsonb_build_object('source','support-ticket'),p_actor_id);
  UPDATE public.support_tickets SET linked_ts_case_id=v_case_id,updated_by=p_actor_id WHERE id=p_ticket_id;
  RETURN v_case_id;
END

DECLARE
  v_target text := coalesce(p_target_id::text,'new');
  v_hash text;
  v_receipt public.support_mutation_receipts%ROWTYPE;
  v_ticket public.support_tickets%ROWTYPE;
  v_macro public.ticket_macros%ROWTYPE;
  v_csat public.ticket_csat%ROWTYPE;
  v_reply jsonb;
  v_result jsonb;
  v_escalation jsonb := jsonb_build_object('status','not_triggered');
  v_now timestamptz;
  v_due timestamptz;
  v_days integer;
  v_case_id uuid;
  v_survey text;
  v_action text;
  v_resource text := 'support_ticket';
  v_resource_id uuid;
  v_audit jsonb := '{}'::jsonb;
  v_note text;
  v_note_metadata jsonb := '{}'::jsonb;
  v_constraint text;
BEGIN
  IF p_actor_id IS NULL OR p_operation IS NULL OR p_operation NOT IN ('create','reply','assign','escalate','resolve','csat','macro')
     OR p_payload IS NULL OR jsonb_typeof(p_payload)<>'object'
     OR p_idempotency_key IS NULL OR length(p_idempotency_key) NOT BETWEEN 8 AND 200
     OR length(btrim(coalesce(p_payload->>'reason',''))) < 8
     OR ((p_operation IN ('create','macro')) <> (p_target_id IS NULL)) THEN
    RAISE EXCEPTION 'Invalid support mutation' USING ERRCODE='22023';
  END IF;
  IF p_operation='create' AND p_payload->>'topic'='privacy' THEN
    RAISE EXCEPTION 'Privacy requests use buyer intake' USING ERRCODE='22023';
  END IF;
  v_hash := encode(sha256(convert_to(p_payload::text,'UTF8')),'hex');
  -- A concurrent insertion waits on this unique key. A failed transaction removes its claim;
  -- the waiter can then insert. After a successful commit the next SELECT sees its complete receipt.
  INSERT INTO public.support_mutation_receipts (actor_id,operation,target,idempotency_key,request_hash)
  VALUES (p_actor_id,p_operation,v_target,p_idempotency_key,v_hash)
  ON CONFLICT (actor_id,operation,target,idempotency_key) DO NOTHING;
  SELECT * INTO STRICT v_receipt FROM public.support_mutation_receipts
    WHERE actor_id=p_actor_id AND operation=p_operation AND target=v_target AND idempotency_key=p_idempotency_key FOR UPDATE;
  IF v_receipt.request_hash <> v_hash THEN
    RAISE EXCEPTION 'Support mutation key payload conflict' USING ERRCODE='PT409';
  END IF;
  IF p_target_id IS NOT NULL THEN
    SELECT * INTO v_ticket FROM public.support_tickets WHERE id=p_target_id AND deleted_at IS NULL FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Support ticket not found' USING ERRCODE='P0002'; END IF;
  END IF;
  IF v_receipt.response IS NOT NULL THEN RETURN v_receipt.response; END IF;
  v_now := clock_timestamp();

  IF p_operation='create' THEN
    IF p_first_response_hours NOT BETWEEN 1 AND 168 OR p_resolution_business_days NOT BETWEEN 1 AND 90 THEN
      RAISE EXCEPTION 'Invalid support SLA defaults' USING ERRCODE='22023';
    END IF;
    v_due := v_now; v_days := p_resolution_business_days;
    WHILE v_days > 0 LOOP
      v_due := v_due + interval '1 day';
      IF extract(isodow FROM v_due AT TIME ZONE 'UTC') < 6 THEN v_days := v_days-1; END IF;
    END LOOP;
    INSERT INTO public.support_tickets (ticket_ref,site_id,requester_type,requester_email,requester_user_id,subject,channel,topic,
      priority,status,assignee_id,first_response_due_at,resolution_due_at,last_customer_message_at,metadata,created_by,updated_by)
    VALUES ('SUP-'||extract(year FROM v_now AT TIME ZONE 'UTC')::text||'-'||upper(left(replace(gen_random_uuid()::text,'-',''),8)),
      (p_payload->>'site_id')::uuid,p_payload->>'requester_type',p_payload->>'requester_email',(p_payload->>'requester_user_id')::uuid,
      p_payload->>'subject',p_payload->>'channel',p_payload->>'topic',p_payload->>'priority','open',(p_payload->>'assignee_id')::uuid,
      v_now + make_interval(hours=>p_first_response_hours),v_due,v_now,p_payload->'metadata',p_actor_id,p_actor_id)
    RETURNING * INTO v_ticket;
    INSERT INTO public.ticket_messages (ticket_id,author_type,author_id,author_email,visibility,body,created_by)
    VALUES (v_ticket.id,'requester',(p_payload->>'requester_user_id')::uuid,p_payload->>'requester_email','public',p_payload->>'body',p_actor_id);
    INSERT INTO public.ticket_sla_clocks (ticket_id,clock_type,due_at,created_by,updated_by) VALUES
      (v_ticket.id,'first_response',v_ticket.first_response_due_at,p_actor_id,p_actor_id),
      (v_ticket.id,'resolution',v_ticket.resolution_due_at,p_actor_id,p_actor_id);
    v_action := 'support.ticket.create';
    v_audit := jsonb_build_object('site_id',v_ticket.site_id);
  ELSIF p_operation='reply' THEN
    v_reply := public.reply_to_support_ticket(p_target_id,p_actor_id,p_actor_email,p_payload->>'visibility',p_payload->>'body',
      p_payload->>'status',(p_payload->>'macro_id')::uuid,p_payload->'attachments',p_payload->'metadata',p_payload->>'reason');
    SELECT * INTO STRICT v_ticket FROM public.support_tickets WHERE id=p_target_id;
    -- Migration 264 already writes the reply audit, inside THIS transaction.
  ELSIF p_operation='assign' THEN
    UPDATE public.support_tickets SET assignee_id=(p_payload->>'assignee_id')::uuid,status='pending_internal',updated_by=p_actor_id
      WHERE id=p_target_id RETURNING * INTO v_ticket;
    v_action := 'support.ticket.assign'; v_note := 'Ticket assignment changed.';
    v_audit := jsonb_build_object('assignee_id',v_ticket.assignee_id); v_note_metadata := v_audit;
  ELSIF p_operation='escalate' THEN
    UPDATE public.support_tickets SET status='escalated',escalated_to=p_payload->>'target',
      linked_incident_id=coalesce((p_payload->>'linked_incident_id')::uuid,linked_incident_id),
      metadata=metadata||jsonb_build_object('escalation',coalesce(p_payload->'metadata','{}'::jsonb)),updated_by=p_actor_id
      WHERE id=p_target_id RETURNING * INTO v_ticket;
    IF v_ticket.escalated_to='trust_safety' THEN
      v_case_id := public.link_support_trust_safety_case(v_ticket.id,p_actor_id,p_actor_email,p_payload->>'reason');
      v_escalation := jsonb_build_object('status','linked','ts_case_id',v_case_id);
    END IF;
    v_action := 'support.ticket.escalate';
    v_note := 'Ticket escalated to '||replace(v_ticket.escalated_to,'_',' ')||'.';
    v_audit := jsonb_build_object('target',v_ticket.escalated_to,'linked_ts_case_id',v_case_id,'linked_incident_id',v_ticket.linked_incident_id);
    v_note_metadata := v_audit;
  ELSIF p_operation='resolve' THEN
    v_survey := gen_random_uuid()::text;
    UPDATE public.support_tickets SET status='resolved',resolved_at=v_now,updated_by=p_actor_id WHERE id=p_target_id RETURNING * INTO v_ticket;
    UPDATE public.ticket_sla_clocks SET satisfied_at=v_now,paused=false,updated_by=p_actor_id
      WHERE ticket_id=p_target_id AND clock_type='resolution' AND deleted_at IS NULL;
    INSERT INTO public.ticket_csat (ticket_id,survey_token,requester_email,sent_at,metadata,created_by)
      VALUES (p_target_id,v_survey,v_ticket.requester_email,v_now,'{"delivery_mode":"dry_run"}',p_actor_id);
    v_note := coalesce(nullif(p_payload->>'resolution_note',''),'Ticket resolved. CSAT survey queued on the dry-run path.');
    v_note_metadata := jsonb_build_object('survey_token',v_survey);
    v_action := 'support.ticket.resolve'; v_audit := v_note_metadata;
  ELSIF p_operation='csat' THEN
    SELECT * INTO v_csat FROM public.ticket_csat WHERE ticket_id=p_target_id AND deleted_at IS NULL
      ORDER BY created_at DESC,id DESC LIMIT 1 FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'CSAT survey not found' USING ERRCODE='P0002'; END IF;
    UPDATE public.ticket_csat SET score=(p_payload->>'score')::integer,comment=p_payload->>'comment',responded_at=v_now,updated_by=p_actor_id
      WHERE id=v_csat.id RETURNING * INTO v_csat;
    v_action := 'support.csat.record'; v_audit := jsonb_build_object('score',v_csat.score);
  ELSE
    INSERT INTO public.ticket_macros (name,description,topic,body,is_active,tags,metadata,created_by,updated_by)
    VALUES (p_payload->>'name',p_payload->>'description',p_payload->>'topic',p_payload->>'body',(p_payload->>'is_active')::boolean,
      ARRAY(SELECT jsonb_array_elements_text(p_payload->'tags')),p_payload->'metadata',p_actor_id,p_actor_id) RETURNING * INTO v_macro;
    v_action := 'support.macro.create'; v_resource := 'ticket_macro'; v_audit := jsonb_build_object('topic',v_macro.topic);
  END IF;

  -- Automatic keyword escalation is inside the action transaction. A privacy-rule refusal keeps
  -- the valid reply but records that refusal; every case/evidence/event/link failure rolls it ALL back.
  IF p_operation IN ('create','reply') AND EXISTS (SELECT 1 FROM unnest(p_escalation_keywords) keyword WHERE position(lower(keyword) in lower(concat_ws(' ',v_ticket.subject,p_payload->>'body',p_payload->>'reason'))) > 0) AND v_ticket.linked_ts_case_id IS NULL THEN
    BEGIN
      UPDATE public.support_tickets SET status='escalated',escalated_to='trust_safety',updated_by=p_actor_id WHERE id=v_ticket.id;
    EXCEPTION WHEN unique_violation THEN
      GET STACKED DIAGNOSTICS v_constraint=CONSTRAINT_NAME;
      IF v_constraint='support_tickets_privacy_open_request_uidx' THEN
        v_escalation := jsonb_build_object('status','refused','reason','privacy_request_conflict');
      ELSE RAISE; END IF;
    END;
    IF v_escalation->>'status'<>'refused' THEN
      v_case_id := public.link_support_trust_safety_case(v_ticket.id,p_actor_id,p_actor_email,p_payload->>'reason');
      v_escalation := jsonb_build_object('status','linked','ts_case_id',v_case_id);
      INSERT INTO public.ticket_messages (ticket_id,author_type,author_id,visibility,body,metadata,created_by)
      VALUES (v_ticket.id,'system',p_actor_id,'internal','Ticket escalated to Trust & Safety because the thread mentioned fraud, abuse, or chargeback risk.',
        jsonb_build_object('linked_ts_case_id',v_case_id),p_actor_id);
      INSERT INTO public.audit_logs (actor_id,actor_type,actor_email,action,resource_type,resource_id,metadata,created_at)
      VALUES (p_actor_id,'employee',p_actor_email,'support.ticket.escalate','support_ticket',v_ticket.id,
        jsonb_build_object('target','trust_safety','trigger','keyword','linked_ts_case_id',v_case_id,'reason',p_payload->>'reason'),clock_timestamp());
    END IF;
  END IF;
  IF v_note IS NOT NULL THEN
    INSERT INTO public.ticket_messages (ticket_id,author_type,author_id,visibility,body,metadata,created_by)
    VALUES (v_ticket.id,'system',p_actor_id,'internal',v_note,v_note_metadata,p_actor_id);
  END IF;
  IF v_action IS NOT NULL THEN
    v_resource_id := CASE WHEN p_operation='macro' THEN v_macro.id ELSE v_ticket.id END;
    INSERT INTO public.audit_logs (actor_id,actor_type,actor_email,action,resource_type,resource_id,metadata)
    VALUES (p_actor_id,'employee',p_actor_email,v_action,v_resource,v_resource_id,
      v_audit||jsonb_build_object('reason',p_payload->>'reason'));
  END IF;
  IF p_operation='macro' THEN v_result := jsonb_build_object('macro',to_jsonb(v_macro));
  ELSIF p_operation='csat' THEN v_result := jsonb_build_object('csat',to_jsonb(v_csat));
  ELSE
    SELECT * INTO STRICT v_ticket FROM public.support_tickets WHERE id=v_ticket.id;
    v_result := jsonb_build_object('ticket',to_jsonb(v_ticket));
    IF p_operation IN ('create','reply','escalate') THEN
      v_result := v_result||jsonb_build_object('trust_safety_escalation',v_escalation,'linked_ts_case_id',v_case_id);
    END IF;
    IF p_operation='reply' THEN v_result := v_result||jsonb_build_object('message',v_reply->'message'); END IF;
    IF p_operation='resolve' THEN v_result := v_result||jsonb_build_object('csat_survey_token',v_survey); END IF;
  END IF;
  UPDATE public.support_mutation_receipts SET response=v_result
    WHERE actor_id=p_actor_id AND operation=p_operation AND target=v_target AND idempotency_key=p_idempotency_key;
  RETURN v_result;
EXCEPTION WHEN unique_violation THEN
  GET STACKED DIAGNOSTICS v_constraint=CONSTRAINT_NAME;
  IF v_constraint='support_tickets_privacy_open_request_uidx' THEN
    RAISE EXCEPTION 'support_ticket_privacy_request_conflict' USING ERRCODE='23505';
  END IF;
  RAISE;
END

DECLARE
  v_row public.buyer_addresses%ROWTYPE;
  v_fields jsonb;
BEGIN
  IF p_buyer_account_id IS NULL OR p_address IS NULL OR jsonb_typeof(p_address) <> 'object' THEN
    RAISE EXCEPTION 'buyer and address object are required' USING ERRCODE = '22023';
  END IF;
  -- Serialize mutations for ONE buyer, including the first address (no address
  -- row exists to lock yet). Lock order is always buyer, then owned address.
  PERFORM id FROM public.buyer_accounts WHERE id = p_buyer_account_id FOR NO KEY UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'buyer is unavailable' USING ERRCODE = '22023'; END IF;

  SELECT coalesce(jsonb_object_agg(key, value), '{}'::jsonb) INTO v_fields
  FROM jsonb_each(p_address)
  WHERE key = ANY(ARRAY['label','full_name','phone','address_line1','address_line2',
    'city','state','postal_code','country','landmark','is_default','gstin','state_code']);

  IF p_address_id IS NOT NULL THEN
    SELECT * INTO v_row FROM public.buyer_addresses
      WHERE id = p_address_id AND buyer_account_id = p_buyer_account_id FOR UPDATE;
    -- No partial default switch when the requested row belongs to someone else.
    IF NOT FOUND THEN RETURN NULL; END IF;
    v_row := jsonb_populate_record(v_row, v_fields);
  ELSE
    v_row := jsonb_populate_record(NULL::public.buyer_addresses,
      jsonb_build_object('label','home','country','IN','is_default',false) || v_fields);
  END IF;

  IF v_row.is_default THEN
    UPDATE public.buyer_addresses SET is_default = false
      WHERE buyer_account_id = p_buyer_account_id AND is_default
        AND (p_address_id IS NULL OR id <> p_address_id);
  END IF;

  IF p_address_id IS NULL THEN
    INSERT INTO public.buyer_addresses (buyer_account_id,label,full_name,phone,
      address_line1,address_line2,city,state,postal_code,country,landmark,is_default,gstin,state_code)
    VALUES (p_buyer_account_id,v_row.label,v_row.full_name,v_row.phone,
      v_row.address_line1,v_row.address_line2,v_row.city,v_row.state,v_row.postal_code,
      v_row.country,v_row.landmark,v_row.is_default,v_row.gstin,v_row.state_code)
    RETURNING * INTO v_row;
  ELSE
    UPDATE public.buyer_addresses SET label=v_row.label,full_name=v_row.full_name,
      phone=v_row.phone,address_line1=v_row.address_line1,address_line2=v_row.address_line2,
      city=v_row.city,state=v_row.state,postal_code=v_row.postal_code,country=v_row.country,
      landmark=v_row.landmark,is_default=v_row.is_default,gstin=v_row.gstin,state_code=v_row.state_code
    WHERE id=p_address_id AND buyer_account_id=p_buyer_account_id RETURNING * INTO v_row;
  END IF;
  -- Let constraint errors escape: PostgREST rolls back the entire switch + save.
  RETURN to_jsonb(v_row);
END;

DECLARE
  v_status text;
  v_session_epoch integer;
  v_existing_order_id uuid;
  v_order jsonb;
  v_order_id uuid;
  v_order_site_id uuid;
  v_link public.buyer_order_links%ROWTYPE;
BEGIN
  IF p_buyer_account_id IS NULL OR p_buyer_session_epoch IS NULL OR p_store_id IS NULL
     OR p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' THEN
    RAISE EXCEPTION 'authenticated checkout identity is incomplete' USING ERRCODE = '22023';
  END IF;

  -- Match create_checkout_order's idempotency lock. Holding it across the preflight, canonical
  -- RPC and ownership insert prevents guest/authenticated or cross-buyer races on one order key.
  PERFORM pg_advisory_xact_lock(hashtextextended(p_store_id::text || ':' || p_idempotency_key, 0));

  SELECT status, session_epoch INTO v_status, v_session_epoch
    FROM public.buyer_accounts
   WHERE id = p_buyer_account_id
   FOR SHARE;
  IF NOT FOUND OR v_status <> 'active' OR v_session_epoch <> p_buyer_session_epoch THEN
    RAISE EXCEPTION 'buyer session is no longer active' USING ERRCODE = '28000';
  END IF;

  -- An existing guest order must not become owned merely because a buyer later reuses its key.
  -- An existing authenticated order may be replayed only by its original recorded owner.
  SELECT order_id INTO v_existing_order_id
    FROM public.checkout_sessions
   WHERE site_id = p_store_id AND idempotency_key = p_idempotency_key
   FOR SHARE;
  IF v_existing_order_id IS NOT NULL THEN
    SELECT * INTO v_link FROM public.buyer_order_links WHERE order_id = v_existing_order_id FOR SHARE;
    IF NOT FOUND OR v_link.buyer_account_id <> p_buyer_account_id OR v_link.site_id <> p_store_id
       OR v_link.link_basis <> 'authenticated_checkout' THEN
      RAISE EXCEPTION 'checkout idempotency key is already bound to another checkout' USING ERRCODE = '23505';
    END IF;
  END IF;

  v_order := public.create_checkout_order(
    p_store_id, p_customer_name, p_customer_email, p_customer_phone, p_shipping_address,
    p_items, p_payment_method, p_notes, p_coupon_code, p_gift_card_code, p_shipping_method,
    p_idempotency_key, p_actor_id, p_request_id, p_shipping_rate_id, p_tax_amount,
    p_place_of_supply_state, p_tax_lines, p_buyer_account_id, p_loyalty_points
  );
  v_order_id := NULLIF(v_order ->> 'id', '')::uuid;
  IF v_order_id IS NULL THEN
    RAISE EXCEPTION 'canonical checkout did not return an order id' USING ERRCODE = 'P0001';
  END IF;

  SELECT store_id INTO v_order_site_id FROM public.orders WHERE id = v_order_id FOR SHARE;
  IF NOT FOUND OR v_order_site_id <> p_store_id THEN
    RAISE EXCEPTION 'canonical checkout returned an order for another site' USING ERRCODE = '23514';
  END IF;

  INSERT INTO public.buyer_order_links (order_id, buyer_account_id, site_id, link_basis)
  VALUES (v_order_id, p_buyer_account_id, p_store_id, 'authenticated_checkout')
  ON CONFLICT (order_id) DO NOTHING;
  SELECT * INTO v_link FROM public.buyer_order_links WHERE order_id = v_order_id FOR SHARE;
  IF NOT FOUND OR v_link.buyer_account_id <> p_buyer_account_id OR v_link.site_id <> p_store_id
     OR v_link.link_basis <> 'authenticated_checkout' THEN
    RAISE EXCEPTION 'checkout order ownership conflicts with an existing owner' USING ERRCODE = '23505';
  END IF;

  RETURN v_order;
END;

DECLARE
  v_status text;
  v_live_epoch integer;
  v_checkout public.checkout_sessions%ROWTYPE;
BEGIN
  IF p_site_id IS NULL OR p_cart_id IS NULL OR p_cart_token IS NULL
     OR btrim(p_cart_token) = '' OR p_channel IS NULL OR p_channel NOT IN ('web','whatsapp','instagram','pos','api')
     OR p_buyer_account_id IS NULL OR p_buyer_session_epoch IS NULL OR p_buyer_session_epoch < 0 THEN
    RAISE EXCEPTION 'hosted checkout buyer binding is invalid' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_site_id::text || ':' || p_cart_id::text, 0));

  SELECT status, session_epoch INTO v_status, v_live_epoch
    FROM public.buyer_accounts
   WHERE id = p_buyer_account_id
   FOR SHARE;
  IF NOT FOUND OR v_status <> 'active' OR v_live_epoch <> p_buyer_session_epoch THEN
    RAISE EXCEPTION 'buyer session is no longer active' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_checkout
    FROM public.checkout_sessions
   WHERE site_id = p_site_id AND cart_id = p_cart_id AND deleted_at IS NULL
   FOR UPDATE;

  IF FOUND THEN
    IF v_checkout.order_id IS NOT NULL OR v_checkout.checkout_state IN ('completed','failed','cancelled','expired') THEN
      RAISE EXCEPTION 'hosted checkout is no longer available for buyer binding' USING ERRCODE = '23505';
    END IF;
    IF v_checkout.cart_token IS DISTINCT FROM p_cart_token THEN
      RAISE EXCEPTION 'hosted checkout cart binding conflicts' USING ERRCODE = '23505';
    END IF;
    IF v_checkout.buyer_account_id IS NOT NULL AND v_checkout.buyer_account_id <> p_buyer_account_id THEN
      RAISE EXCEPTION 'hosted checkout is already bound to another buyer' USING ERRCODE = '23505';
    END IF;

    UPDATE public.checkout_sessions
       SET buyer_account_id = p_buyer_account_id,
           buyer_session_epoch = p_buyer_session_epoch
     WHERE id = v_checkout.id;
    RETURN v_checkout.id;
  END IF;

  INSERT INTO public.checkout_sessions (
    site_id, cart_id, cart_token, channel, status, checkout_state,
    idempotency_key, metadata, buyer_account_id, buyer_session_epoch
  ) VALUES (
    p_site_id, p_cart_id, p_cart_token, p_channel, 'contact', 'contact',
    'checkout:' || p_site_id::text || ':' || p_cart_id::text,
    jsonb_build_object('source','hosted_checkout_v1','buyer_bound',true),
    p_buyer_account_id, p_buyer_session_epoch
  )
  RETURNING id INTO v_checkout.id;
  RETURN v_checkout.id;
END;

BEGIN
    IF TG_TABLE_NAME = 'products' THEN
        IF TG_OP = 'INSERT'
           OR NEW.store_id IS DISTINCT FROM OLD.store_id
           OR NEW.site_id IS DISTINCT FROM OLD.site_id
           OR NEW.price IS DISTINCT FROM OLD.price
           OR NEW.compare_price IS DISTINCT FROM OLD.compare_price
           OR NEW.is_active IS DISTINCT FROM OLD.is_active
           OR NEW.deleted_at IS DISTINCT FROM OLD.deleted_at THEN
            IF TG_OP = 'UPDATE'
               AND (NEW.store_id IS DISTINCT FROM OLD.store_id OR NEW.site_id IS DISTINCT FROM OLD.site_id) THEN
                PERFORM public.capture_channel_offer_price_observations(NEW.id, 'store_reassignment_baseline');
            ELSE
                PERFORM public.capture_channel_offer_price_observations(NEW.id, 'product_write');
            END IF;
        END IF;
        RETURN NEW;
    END IF;

    IF TG_OP = 'INSERT'
       OR NEW.product_id IS DISTINCT FROM OLD.product_id
       OR NEW.price IS DISTINCT FROM OLD.price
       OR NEW.compare_price IS DISTINCT FROM OLD.compare_price THEN
        IF TG_OP = 'UPDATE' AND NEW.product_id IS DISTINCT FROM OLD.product_id THEN
            PERFORM public.capture_channel_offer_price_observations(OLD.product_id, 'product_write');
        END IF;
        PERFORM public.capture_channel_offer_price_observations(NEW.product_id, 'variant_write');
    END IF;
    RETURN NEW;
END;

DECLARE
    v_product public.products%ROWTYPE;
    v_at timestamptz := clock_timestamp();
    v_storefront_available boolean;
    v_marketplace_available boolean;
BEGIN
    SELECT * INTO v_product FROM public.products WHERE id = p_product_id;
    IF NOT FOUND OR COALESCE(v_product.site_id, v_product.store_id) IS NULL THEN
        RETURN;
    END IF;

    SELECT (v_product.is_active IS TRUE AND v_product.deleted_at IS NULL
            AND s.status = 'published' AND s.deleted_at IS NULL)
      INTO v_storefront_available
      FROM public.sites s
     WHERE s.id = COALESCE(v_product.site_id, v_product.store_id);
    v_storefront_available := COALESCE(v_storefront_available, false);

    INSERT INTO public.product_price_observations (
        store_id, product_id, variant_id, price, compare_price,
        prior_lowest_price_30d, prior_coverage_complete, observed_at,
        observation_source, offer_channel, is_available
    ) VALUES (
        COALESCE(v_product.site_id, v_product.store_id), v_product.id, NULL,
        v_product.price, v_product.compare_price, NULL, false, v_at,
        p_source, 'storefront', v_storefront_available
    );

    INSERT INTO public.product_price_observations (
        store_id, product_id, variant_id, price, compare_price,
        prior_lowest_price_30d, prior_coverage_complete, observed_at,
        observation_source, offer_channel, is_available
    )
    SELECT COALESCE(v_product.site_id, v_product.store_id), v_product.id, v.id,
           v.price, v.compare_price, NULL, false, v_at, p_source,
           'storefront', v_storefront_available
      FROM public.product_variants v WHERE v.product_id = v_product.id;

    IF EXISTS (SELECT 1 FROM public.channel_listings cl
                WHERE cl.product_id = v_product.id AND cl.channel = 'marketplace') THEN
        SELECT (v_product.is_active IS TRUE AND v_product.deleted_at IS NULL
                AND s.status = 'published' AND s.deleted_at IS NULL
                AND cl.status = 'approved' AND cl.visibility = 'public')
          INTO v_marketplace_available
          FROM public.channel_listings cl
          JOIN public.sites s ON s.id = cl.site_id
         WHERE cl.product_id = v_product.id AND cl.channel = 'marketplace';
        v_marketplace_available := COALESCE(v_marketplace_available, false);

        INSERT INTO public.product_price_observations (
            store_id, product_id, variant_id, price, compare_price,
            prior_lowest_price_30d, prior_coverage_complete, observed_at,
            observation_source, offer_channel, is_available
        ) VALUES (
            COALESCE(v_product.site_id, v_product.store_id), v_product.id, NULL,
            v_product.price, v_product.compare_price, NULL, false, v_at,
            p_source, 'marketplace', v_marketplace_available
        );

        INSERT INTO public.product_price_observations (
            store_id, product_id, variant_id, price, compare_price,
            prior_lowest_price_30d, prior_coverage_complete, observed_at,
            observation_source, offer_channel, is_available
        )
        SELECT COALESCE(v_product.site_id, v_product.store_id), v_product.id, v.id,
               v.price, v.compare_price, NULL, false, v_at, p_source,
               'marketplace', v_marketplace_available
          FROM public.product_variants v WHERE v.product_id = v_product.id;
    END IF;
END;

BEGIN
    IF TG_OP = 'DELETE' THEN
        IF OLD.channel = 'marketplace' THEN
            PERFORM public.capture_removed_marketplace_offer_price_observation(OLD.product_id, OLD.site_id);
        END IF;
        RETURN OLD;
    END IF;

    IF TG_OP = 'UPDATE' AND OLD.channel = 'marketplace'
       AND (NEW.channel <> 'marketplace' OR NEW.product_id IS DISTINCT FROM OLD.product_id) THEN
        PERFORM public.capture_removed_marketplace_offer_price_observation(OLD.product_id, OLD.site_id);
    END IF;

    IF NEW.channel = 'marketplace'
       AND (TG_OP = 'INSERT'
            OR OLD.channel IS DISTINCT FROM NEW.channel
            OR NEW.status IS DISTINCT FROM OLD.status
            OR NEW.visibility IS DISTINCT FROM OLD.visibility
            OR NEW.product_id IS DISTINCT FROM OLD.product_id) THEN
        PERFORM public.capture_channel_offer_price_observations(NEW.product_id, 'product_write');
    END IF;
    RETURN NEW;
END;

DECLARE
    v_product public.products%ROWTYPE;
    v_at timestamptz := clock_timestamp();
    v_store_id uuid;
BEGIN
    SELECT * INTO v_product FROM public.products WHERE id = p_product_id;
    IF NOT FOUND THEN RETURN; END IF;
    v_store_id := COALESCE(p_site_id, v_product.site_id, v_product.store_id);
    IF v_store_id IS NULL THEN RETURN; END IF;

    INSERT INTO public.product_price_observations (
        store_id, product_id, variant_id, price, compare_price,
        prior_lowest_price_30d, prior_coverage_complete, observed_at,
        observation_source, offer_channel, is_available
    ) VALUES (
        v_store_id, v_product.id, NULL, v_product.price, v_product.compare_price,
        NULL, false, v_at, 'product_write', 'marketplace', false
    );
    INSERT INTO public.product_price_observations (
        store_id, product_id, variant_id, price, compare_price,
        prior_lowest_price_30d, prior_coverage_complete, observed_at,
        observation_source, offer_channel, is_available
    )
    SELECT v_store_id, v_product.id, v.id, v.price, v.compare_price,
           NULL, false, v_at, 'product_write', 'marketplace', false
      FROM public.product_variants v WHERE v.product_id = v_product.id;
END;

DECLARE v_product_id uuid;
BEGIN
    IF NEW.status IS DISTINCT FROM OLD.status OR NEW.deleted_at IS DISTINCT FROM OLD.deleted_at THEN
        FOR v_product_id IN
            SELECT p.id FROM public.products p
             WHERE COALESCE(p.site_id, p.store_id) = NEW.id
        LOOP
            PERFORM public.capture_channel_offer_price_observations(v_product_id, 'product_write');
        END LOOP;
    END IF;
    RETURN NEW;
END;

SELECT encode(extensions.digest(convert_to(snapshot.payload::text, 'UTF8'), 'sha256'), 'hex')
  FROM (SELECT public.marketplace_listing_review_snapshot(p_listing_id) AS payload) snapshot
 WHERE snapshot.payload IS NOT NULL;

DECLARE
  v_fingerprint text;
  v_snapshot jsonb;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'draft' OR NEW.submitted_product_fingerprint IS NOT NULL
       OR NEW.approved_product_fingerprint IS NOT NULL OR NEW.submitted_product_snapshot IS NOT NULL
       OR NEW.approved_product_snapshot IS NOT NULL THEN
      RAISE EXCEPTION 'channel listings must be created as an unreviewed draft';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.status IS NOT DISTINCT FROM OLD.status THEN
    IF NEW.submitted_product_fingerprint IS DISTINCT FROM OLD.submitted_product_fingerprint
       OR NEW.approved_product_fingerprint IS DISTINCT FROM OLD.approved_product_fingerprint
       OR NEW.submitted_product_snapshot IS DISTINCT FROM OLD.submitted_product_snapshot
       OR NEW.approved_product_snapshot IS DISTINCT FROM OLD.approved_product_snapshot THEN
      RAISE EXCEPTION 'review fingerprints change only with a valid listing transition';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.status = 'pending_review' AND OLD.status = 'draft' THEN
    v_snapshot := public.marketplace_listing_review_snapshot(OLD.id);
    v_fingerprint := encode(extensions.digest(convert_to(v_snapshot::text, 'UTF8'), 'sha256'), 'hex');
    IF v_fingerprint IS NULL THEN RAISE EXCEPTION 'marketplace review revision is unavailable'; END IF;
    NEW.submitted_product_fingerprint := v_fingerprint;
    NEW.approved_product_fingerprint := OLD.approved_product_fingerprint;
    NEW.submitted_product_snapshot := v_snapshot;
    NEW.approved_product_snapshot := OLD.approved_product_snapshot;
  ELSIF NEW.status = 'approved' AND OLD.status = 'pending_review' THEN
    -- The gateway pre-check improves the response, but is not the authority: assignment may
    -- change after that read. transition_channel_listing locks the listing row, so this trigger
    -- compares the actor carried by the same atomic transition with the current locked assignment.
    IF OLD.assigned_reviewer_id IS NULL OR NEW.reviewed_by IS DISTINCT FROM OLD.assigned_reviewer_id THEN
      RAISE EXCEPTION 'marketplace_review_assignment_required';
    END IF;
    v_snapshot := public.marketplace_listing_review_snapshot(OLD.id);
    v_fingerprint := encode(extensions.digest(convert_to(v_snapshot::text, 'UTF8'), 'sha256'), 'hex');
    IF OLD.submitted_product_fingerprint IS NULL OR OLD.submitted_product_fingerprint IS DISTINCT FROM v_fingerprint THEN
      RAISE EXCEPTION 'marketplace product changed after submission; return to draft and resubmit';
    END IF;
    NEW.submitted_product_fingerprint := OLD.submitted_product_fingerprint;
    NEW.approved_product_fingerprint := v_fingerprint;
    NEW.submitted_product_snapshot := OLD.submitted_product_snapshot;
    NEW.approved_product_snapshot := v_snapshot;
  ELSIF NEW.status = 'approved' AND OLD.status = 'paused' THEN
    v_fingerprint := public.marketplace_listing_review_fingerprint(OLD.id);
    IF OLD.approved_product_fingerprint IS NULL OR OLD.approved_product_fingerprint IS DISTINCT FROM v_fingerprint THEN
      RAISE EXCEPTION 'marketplace product changed after approval; resubmission is required';
    END IF;
    NEW.submitted_product_fingerprint := OLD.submitted_product_fingerprint;
    NEW.approved_product_fingerprint := OLD.approved_product_fingerprint;
    NEW.submitted_product_snapshot := OLD.submitted_product_snapshot;
    NEW.approved_product_snapshot := OLD.approved_product_snapshot;
  ELSIF NEW.status = 'draft' AND OLD.status IN ('rejected', 'pending_review', 'approved', 'paused') THEN
    NEW.submitted_product_fingerprint := NULL;
    NEW.approved_product_fingerprint := OLD.approved_product_fingerprint;
    NEW.submitted_product_snapshot := NULL;
    NEW.approved_product_snapshot := OLD.approved_product_snapshot;
    NEW.assigned_reviewer_id := NULL;
    NEW.reviewer_assigned_at := NULL;
    NEW.reviewer_assigned_by := NULL;
  ELSIF NEW.status = 'rejected' AND OLD.status = 'pending_review' THEN
    IF OLD.assigned_reviewer_id IS NULL OR NEW.reviewed_by IS DISTINCT FROM OLD.assigned_reviewer_id THEN
      RAISE EXCEPTION 'marketplace_review_assignment_required';
    END IF;
    NEW.submitted_product_fingerprint := OLD.submitted_product_fingerprint;
    NEW.approved_product_fingerprint := OLD.approved_product_fingerprint;
    NEW.submitted_product_snapshot := OLD.submitted_product_snapshot;
    NEW.approved_product_snapshot := OLD.approved_product_snapshot;
    NULL;
  ELSIF NEW.status = 'paused' AND OLD.status = 'approved' THEN
    IF OLD.approved_product_fingerprint IS DISTINCT FROM public.marketplace_listing_review_fingerprint(OLD.id) THEN
      RAISE EXCEPTION 'marketplace product changed after approval; resubmission is required';
    END IF;
    NEW.submitted_product_fingerprint := OLD.submitted_product_fingerprint;
    NEW.approved_product_fingerprint := OLD.approved_product_fingerprint;
    NEW.submitted_product_snapshot := OLD.submitted_product_snapshot;
    NEW.approved_product_snapshot := OLD.approved_product_snapshot;
  ELSIF NEW.status = 'delisted' AND OLD.status IN ('draft', 'pending_review', 'approved', 'paused', 'rejected') THEN
    NEW.submitted_product_fingerprint := OLD.submitted_product_fingerprint;
    NEW.approved_product_fingerprint := OLD.approved_product_fingerprint;
    NEW.submitted_product_snapshot := OLD.submitted_product_snapshot;
    NEW.approved_product_snapshot := OLD.approved_product_snapshot;
    NULL;
  ELSE
    RAISE EXCEPTION 'invalid listing status transition: % -> %', OLD.status, NEW.status;
  END IF;

  RETURN NEW;
END;

BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.assigned_reviewer_id IS NOT NULL OR NEW.reviewer_assigned_at IS NOT NULL OR NEW.reviewer_assigned_by IS NOT NULL THEN
      RAISE EXCEPTION 'reviewer assignment must be created through the claim RPC';
    END IF;
    RETURN NEW;
  END IF;
  IF ROW(NEW.assigned_reviewer_id, NEW.reviewer_assigned_at, NEW.reviewer_assigned_by)
     IS DISTINCT FROM ROW(OLD.assigned_reviewer_id, OLD.reviewer_assigned_at, OLD.reviewer_assigned_by) THEN
    IF current_setting('role', true) = 'app_tenant' OR public.current_site_id() IS NOT NULL
       OR current_setting('app.channel_listing_assignment_transition', true) IS DISTINCT FROM 'rpc' THEN
      RAISE EXCEPTION 'reviewer assignment changes only through the operator claim RPC';
    END IF;
  END IF;
  RETURN NEW;
END;

DECLARE
  v_listing public.channel_listings%ROWTYPE;
  v_existing public.channel_listing_moderation_events%ROWTYPE;
  v_event_id uuid;
  v_now timestamptz := now();
BEGIN
  IF p_site_id IS NULL OR p_listing_id IS NULL OR p_reviewer_id IS NULL THEN
    RAISE EXCEPTION 'site_id, listing_id and reviewer_id are required';
  END IF;
  IF p_reason IS NULL OR length(btrim(p_reason)) < 8 OR length(p_reason) > 1000 THEN
    RAISE EXCEPTION 'reviewer claim requires a reason of 8 to 1000 characters';
  END IF;
  IF p_idempotency_key IS NULL OR length(p_idempotency_key) = 0 OR length(p_idempotency_key) > 200 THEN
    RAISE EXCEPTION 'idempotency_key is required';
  END IF;
  IF p_expected_version IS NULL OR p_expected_version < 1 THEN
    RAISE EXCEPTION 'expected listing version is required';
  END IF;
  IF current_setting('role', true) = 'app_tenant' OR public.current_site_id() IS NOT NULL THEN
    RAISE EXCEPTION 'operator claims are not permitted from a tenant context';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_site_id::text || ':claim:' || p_idempotency_key, 0));
  SELECT * INTO v_existing FROM public.channel_listing_moderation_events e
   WHERE e.site_id = p_site_id AND e.idempotency_key = p_idempotency_key;
  IF FOUND THEN
    IF v_existing.event_type <> 'reviewer_assignment' OR v_existing.listing_id <> p_listing_id
       OR v_existing.assigned_reviewer_id <> p_reviewer_id OR v_existing.actor_id <> p_reviewer_id
       OR v_existing.reason IS DISTINCT FROM p_reason THEN
      RAISE EXCEPTION 'idempotency_key_conflict';
    END IF;
    RETURN QUERY SELECT p_listing_id, p_reviewer_id,
      (SELECT l.version FROM public.channel_listings l WHERE l.id = p_listing_id AND l.site_id = p_site_id),
      v_existing.id, true;
    RETURN;
  END IF;

  SELECT * INTO v_listing FROM public.channel_listings l
   WHERE l.id = p_listing_id AND l.site_id = p_site_id FOR UPDATE;
  IF NOT FOUND OR v_listing.channel <> 'marketplace' THEN RAISE EXCEPTION 'listing not found'; END IF;
  IF v_listing.status <> 'pending_review' THEN RAISE EXCEPTION 'listing is not awaiting review'; END IF;
  IF v_listing.version <> p_expected_version THEN RAISE EXCEPTION 'stale_listing_version'; END IF;
  IF v_listing.assigned_reviewer_id IS NOT NULL THEN RAISE EXCEPTION 'listing_already_claimed'; END IF;

  PERFORM set_config('app.channel_listing_assignment_transition', 'rpc', true);
  UPDATE public.channel_listings SET assigned_reviewer_id = p_reviewer_id,
      reviewer_assigned_at = v_now, reviewer_assigned_by = p_reviewer_id,
      updated_at = v_now
   WHERE id = v_listing.id;
  INSERT INTO public.channel_listing_moderation_events
    (site_id, listing_id, from_status, to_status, actor_realm, actor_id, reason, idempotency_key,
     event_type, assigned_reviewer_id)
  VALUES (p_site_id, p_listing_id, v_listing.status, v_listing.status, 'operator', p_reviewer_id,
      btrim(p_reason), p_idempotency_key, 'reviewer_assignment', p_reviewer_id)
  RETURNING id INTO v_event_id;
  PERFORM set_config('app.channel_listing_assignment_transition', '', true);

  RETURN QUERY SELECT p_listing_id, p_reviewer_id, v_listing.version, v_event_id, false;
END;

DECLARE
  v_listing public.channel_listings%ROWTYPE;
  v_existing public.channel_listing_moderation_events%ROWTYPE;
  v_event_id uuid;
  v_now timestamptz := now();
BEGIN
  IF p_site_id IS NULL OR p_listing_id IS NULL OR p_assigning_operator_id IS NULL OR p_reviewer_id IS NULL THEN
    RAISE EXCEPTION 'site, listing, assigning operator and reviewer are required';
  END IF;
  IF p_assigning_operator_id = p_reviewer_id THEN
    RAISE EXCEPTION 'lead reassignment must select another reviewer';
  END IF;
  IF p_reason IS NULL OR length(btrim(p_reason)) < 8 OR length(p_reason) > 1000 THEN
    RAISE EXCEPTION 'reviewer assignment requires a reason of 8 to 1000 characters';
  END IF;
  IF p_idempotency_key IS NULL OR length(p_idempotency_key) = 0 OR length(p_idempotency_key) > 200 THEN
    RAISE EXCEPTION 'idempotency_key is required';
  END IF;
  IF p_expected_version IS NULL OR p_expected_version < 1 THEN
    RAISE EXCEPTION 'expected listing version is required';
  END IF;
  IF current_setting('role', true) = 'app_tenant' OR public.current_site_id() IS NOT NULL THEN
    RAISE EXCEPTION 'operator assignment is not permitted from a tenant context';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_site_id::text || ':assign:' || p_idempotency_key, 0));
  SELECT * INTO v_existing FROM public.channel_listing_moderation_events e
   WHERE e.site_id = p_site_id AND e.idempotency_key = p_idempotency_key;
  IF FOUND THEN
    IF v_existing.event_type <> 'reviewer_assignment' OR v_existing.listing_id <> p_listing_id
       OR v_existing.actor_id <> p_assigning_operator_id OR v_existing.assigned_reviewer_id <> p_reviewer_id
       OR v_existing.reason IS DISTINCT FROM p_reason THEN
      RAISE EXCEPTION 'idempotency_key_conflict';
    END IF;
    RETURN QUERY SELECT p_listing_id, v_existing.previous_assigned_reviewer_id, p_reviewer_id,
      (SELECT l.version FROM public.channel_listings l WHERE l.id = p_listing_id AND l.site_id = p_site_id),
      v_existing.id, true;
    RETURN;
  END IF;

  SELECT * INTO v_listing FROM public.channel_listings l
   WHERE l.id = p_listing_id AND l.site_id = p_site_id FOR UPDATE;
  IF NOT FOUND OR v_listing.channel <> 'marketplace' THEN RAISE EXCEPTION 'listing not found'; END IF;
  IF v_listing.status <> 'pending_review' THEN RAISE EXCEPTION 'listing is not awaiting review'; END IF;
  IF v_listing.version <> p_expected_version THEN RAISE EXCEPTION 'stale_listing_version'; END IF;
  IF v_listing.assigned_reviewer_id IS NOT NULL AND v_listing.assigned_reviewer_id = p_reviewer_id THEN
    RAISE EXCEPTION 'reviewer_already_assigned';
  END IF;

  PERFORM set_config('app.channel_listing_assignment_transition', 'rpc', true);
  UPDATE public.channel_listings AS listing SET assigned_reviewer_id = p_reviewer_id,
      reviewer_assigned_at = v_now, reviewer_assigned_by = p_assigning_operator_id,
      version = listing.version + 1, updated_at = v_now
   WHERE listing.id = v_listing.id;
  INSERT INTO public.channel_listing_moderation_events
    (site_id, listing_id, from_status, to_status, actor_realm, actor_id, reason, idempotency_key,
     event_type, assigned_reviewer_id, previous_assigned_reviewer_id)
  VALUES (p_site_id, p_listing_id, v_listing.status, v_listing.status, 'operator', p_assigning_operator_id,
      btrim(p_reason), p_idempotency_key, 'reviewer_assignment', p_reviewer_id, v_listing.assigned_reviewer_id)
  RETURNING id INTO v_event_id;
  PERFORM set_config('app.channel_listing_assignment_transition', '', true);

  RETURN QUERY SELECT p_listing_id, v_listing.assigned_reviewer_id, p_reviewer_id,
    v_listing.version + 1, v_event_id, false;
END;

DECLARE
  v_listing public.channel_listings%ROWTYPE;
  v_count integer := 0;
BEGIN
  FOR v_listing IN
    SELECT * FROM public.channel_listings
     WHERE product_id = p_product_id AND channel = 'marketplace'
       AND status IN ('pending_review', 'approved', 'paused')
     FOR UPDATE
  LOOP
    PERFORM set_config('app.channel_listing_transition', 'rpc', true);
    UPDATE public.channel_listings
       SET status = 'draft', submitted_product_fingerprint = NULL,
           submitted_product_snapshot = NULL, version = version + 1, updated_at = now()
     WHERE id = v_listing.id;
    INSERT INTO public.channel_listing_moderation_events
      (site_id, listing_id, from_status, to_status, actor_realm, actor_id, reason, idempotency_key)
    VALUES
      (v_listing.site_id, v_listing.id, v_listing.status, 'draft', 'system', NULL,
       p_reason, 'revision-invalidation:' || v_listing.id::text || ':' || gen_random_uuid()::text);
    PERFORM set_config('app.channel_listing_transition', '', true);
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END;

BEGIN
  IF ROW(
       NEW.site_id, NEW.store_id, NEW.name, NEW.slug, NEW.url_handle, NEW.description,
       NEW.price, NEW.compare_price, NEW.images, NEW.thumbnail_url, NEW.category, NEW.tags,
       NEW.seo_title, NEW.seo_description, NEW.product_type, NEW.vendor,
       NEW.country_of_origin, NEW.importer_details, NEW.hs_code, NEW.hsn_code,
       NEW.charge_tax, NEW.is_physical, NEW.weight, NEW.weight_unit
     ) IS DISTINCT FROM ROW(
       OLD.site_id, OLD.store_id, OLD.name, OLD.slug, OLD.url_handle, OLD.description,
       OLD.price, OLD.compare_price, OLD.images, OLD.thumbnail_url, OLD.category, OLD.tags,
       OLD.seo_title, OLD.seo_description, OLD.product_type, OLD.vendor,
       OLD.country_of_origin, OLD.importer_details, OLD.hs_code, OLD.hsn_code,
       OLD.charge_tax, OLD.is_physical, OLD.weight, OLD.weight_unit
     ) THEN
    PERFORM public.invalidate_marketplace_listing_review(
      NEW.id, 'Material product details changed; merchant resubmission is required.'
    );
  END IF;
  RETURN NEW;
END;

DECLARE
  v_product_id uuid;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_product_id := NEW.product_id;
  ELSIF TG_OP = 'DELETE' THEN
    v_product_id := OLD.product_id;
  ELSE
    IF ROW(NEW.product_id, NEW.title, NEW.price, NEW.compare_price, NEW.weight, NEW.weight_unit,
           NEW.option1, NEW.option2, NEW.option3, NEW.image_url, NEW."position") IS NOT DISTINCT FROM
       ROW(OLD.product_id, OLD.title, OLD.price, OLD.compare_price, OLD.weight, OLD.weight_unit,
           OLD.option1, OLD.option2, OLD.option3, OLD.image_url, OLD."position") THEN RETURN NEW; END IF;
    PERFORM public.invalidate_marketplace_listing_review(
      OLD.product_id, 'Material product variant changed; merchant resubmission is required.'
    );
    v_product_id := NEW.product_id;
  END IF;
  PERFORM public.invalidate_marketplace_listing_review(
    v_product_id, 'Material product variant changed; merchant resubmission is required.'
  );
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;

DECLARE
  v_product_id uuid;
BEGIN
  IF TG_OP = 'INSERT' THEN v_product_id := NEW.product_id;
  ELSIF TG_OP = 'DELETE' THEN v_product_id := OLD.product_id;
  ELSE
    IF ROW(NEW.product_id, NEW.name, NEW."values", NEW."position") IS NOT DISTINCT FROM
       ROW(OLD.product_id, OLD.name, OLD."values", OLD."position") THEN RETURN NEW; END IF;
    v_product_id := OLD.product_id;
    PERFORM public.invalidate_marketplace_listing_review(
      OLD.product_id, 'Material product options changed; merchant resubmission is required.'
    );
    IF NEW.product_id IS DISTINCT FROM OLD.product_id THEN v_product_id := NEW.product_id; END IF;
  END IF;
  PERFORM public.invalidate_marketplace_listing_review(
    v_product_id, 'Material product options changed; merchant resubmission is required.'
  );
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;

BEGIN
  IF ROW(NEW.channel, NEW.marketplace_category_id, NEW.pricing_policy, NEW.compliance_flags)
     IS DISTINCT FROM ROW(OLD.channel, OLD.marketplace_category_id, OLD.pricing_policy, OLD.compliance_flags) THEN
    PERFORM public.invalidate_marketplace_listing_review(
      NEW.product_id, 'Material marketplace listing details changed; merchant resubmission is required.'
    );
  END IF;
  RETURN NEW;
END;

DECLARE
  v_existing public.channel_listing_moderation_events%ROWTYPE;
  v_listing public.channel_listings%ROWTYPE;
  v_step record;
  v_final record;
  v_draft_key text;
BEGIN
  IF p_site_id IS NULL OR p_listing_id IS NULL OR p_actor_id IS NULL THEN
    RAISE EXCEPTION 'site, listing and merchant actor are required';
  END IF;
  IF p_reason IS NULL OR length(btrim(p_reason)) < 8 OR length(btrim(p_reason)) > 500 THEN
    RAISE EXCEPTION 'merchant correction response must contain 8 to 500 characters';
  END IF;
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) = 0 OR length(p_idempotency_key) > 120 THEN
    RAISE EXCEPTION 'idempotency_key is required';
  END IF;
  IF current_setting('role', true) IS DISTINCT FROM 'app_tenant'
     OR public.current_site_id() IS NULL
     OR public.current_site_id() <> p_site_id THEN
    RAISE EXCEPTION 'tenant context required for merchant resubmission';
  END IF;

  -- The root key serializes retries before checking the final append-only event receipt.
  PERFORM pg_advisory_xact_lock(hashtextextended(p_site_id::text || ':resubmit:' || p_idempotency_key, 0));
  SELECT * INTO v_existing
    FROM public.channel_listing_moderation_events e
   WHERE e.site_id = p_site_id AND e.idempotency_key = p_idempotency_key;
  IF FOUND THEN
    IF v_existing.listing_id IS DISTINCT FROM p_listing_id
       OR v_existing.from_status IS DISTINCT FROM 'draft'
       OR v_existing.to_status IS DISTINCT FROM 'pending_review'
       OR v_existing.actor_realm IS DISTINCT FROM 'merchant'
       OR v_existing.actor_id IS DISTINCT FROM p_actor_id
       OR v_existing.reason IS DISTINCT FROM btrim(p_reason) THEN
      RAISE EXCEPTION USING ERRCODE = '23505', MESSAGE = 'idempotency_key_conflict: resubmission key belongs to a different request';
    END IF;
    RETURN QUERY SELECT p_listing_id, v_existing.from_status, v_existing.to_status, v_existing.id, true;
    RETURN;
  END IF;

  SELECT * INTO v_listing
    FROM public.channel_listings l
   WHERE l.id = p_listing_id AND l.site_id = p_site_id
   FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'listing not found'; END IF;
  IF v_listing.channel <> 'marketplace' OR v_listing.status <> 'rejected' THEN
    RAISE EXCEPTION 'invalid_transition: only rejected marketplace listings can be resubmitted';
  END IF;

  v_draft_key := 'resubmit-draft:' || p_listing_id::text || ':' || p_idempotency_key;
  IF length(v_draft_key) > 200 THEN RAISE EXCEPTION 'idempotency_key is too long for resubmission'; END IF;

  -- Reuse the canonical transition writer and its revision snapshot/guards. Both calls participate
  -- in this function's transaction, so a failure on the second edge rolls the first edge back.
  SELECT * INTO v_step FROM public.transition_channel_listing(
    p_site_id, p_listing_id, 'draft', 'merchant', p_actor_id, NULL, v_draft_key
  );
  SELECT * INTO v_final FROM public.transition_channel_listing(
    p_site_id, p_listing_id, 'pending_review', 'merchant', p_actor_id, btrim(p_reason), p_idempotency_key
  );
  RETURN QUERY SELECT v_final.listing_id, v_final.from_status, v_final.to_status, v_final.event_id, v_final.replayed;
END;

BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.marketplace_listing_id IS NOT NULL OR NEW.marketplace_approved_fingerprint IS NOT NULL THEN
      RAISE EXCEPTION 'marketplace order listing identity is bound only by checkout';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.marketplace_listing_id IS DISTINCT FROM OLD.marketplace_listing_id
     OR NEW.marketplace_approved_fingerprint IS DISTINCT FROM OLD.marketplace_approved_fingerprint THEN
    IF OLD.marketplace_listing_id IS NOT NULL
       OR NEW.marketplace_listing_id IS NULL
       OR NEW.marketplace_approved_fingerprint IS NULL
       OR current_setting('app.marketplace_order_creation', true) IS DISTINCT FROM 'on' THEN
      RAISE EXCEPTION 'marketplace order listing identity is immutable';
    END IF;
  END IF;
  RETURN NEW;
END;

DECLARE
  v_line record;
  v_listing record;
  v_fingerprint text;
  v_items jsonb := '[]'::jsonb;
  v_order jsonb;
  v_order_id uuid;
  v_existing_order_id uuid;
  v_purchase_channel text;
  v_expected_count integer := 0;
  v_bound_count integer := 0;
  v_duplicate_count integer := 0;
BEGIN
  IF p_store_id IS NULL OR p_idempotency_key IS NULL OR btrim(p_idempotency_key) = ''
     OR jsonb_typeof(p_items) IS DISTINCT FROM 'array' OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'marketplace checkout identity and items are required' USING ERRCODE = '22023';
  END IF;
  IF p_buyer_account_id IS NULL AND p_buyer_session_epoch IS NOT NULL
     OR p_buyer_account_id IS NOT NULL AND p_buyer_session_epoch IS NULL THEN
    RAISE EXCEPTION 'marketplace buyer session binding is incomplete' USING ERRCODE = '22023';
  END IF;
  SELECT count(*) INTO v_duplicate_count
    FROM (
      SELECT value ->> 'product_id' AS product_id,
             COALESCE(value ->> 'variant_id', '') AS variant_id
        FROM jsonb_array_elements(p_items)
       GROUP BY value ->> 'product_id', COALESCE(value ->> 'variant_id', ''),
         coalesce(value->'cart_fact_ref'->>'configuration_fingerprint',''),coalesce(value->>'marketplace_listing_id','')
      HAVING count(*) > 1
    ) duplicates;
  IF v_duplicate_count > 0 THEN
    RAISE EXCEPTION 'marketplace checkout has duplicate product variants' USING ERRCODE = '22023';
  END IF;

  -- Use the canonical order lock before taking listing locks, matching the storefront writer's
  -- lock order and making origin/listing binding safe under concurrent retries.
  PERFORM pg_advisory_xact_lock(hashtextextended(p_store_id::text || ':' || p_idempotency_key, 0));
  SELECT order_id INTO v_existing_order_id
    FROM public.checkout_sessions
   WHERE site_id = p_store_id AND idempotency_key = p_idempotency_key AND deleted_at IS NULL
   LIMIT 1;

  IF v_existing_order_id IS NOT NULL THEN
    SELECT p.channel INTO v_purchase_channel FROM public.orders o JOIN public.purchases p ON p.id=o.purchase_id
      WHERE o.id=v_existing_order_id AND o.store_id=p_store_id AND o.deleted_at IS NULL;
    IF v_purchase_channel IS DISTINCT FROM 'marketplace' THEN RAISE EXCEPTION 'checkout idempotency key is already bound to another sales origin' USING ERRCODE='23505'; END IF;
    IF (SELECT jsonb_agg(jsonb_build_array(i->>'product_id',nullif(i->>'variant_id',''),(i->>'quantity')::integer,i->>'marketplace_listing_id')
        ORDER BY i->>'product_id',i->>'variant_id',i->>'marketplace_listing_id',(i->>'quantity')::integer) FROM jsonb_array_elements(p_items) i)
      IS DISTINCT FROM (SELECT jsonb_agg(jsonb_build_array(oi.product_id::text,nullif(oi.variant_id,''),oi.quantity,oi.marketplace_listing_id::text)
        ORDER BY oi.product_id::text,oi.variant_id,oi.marketplace_listing_id::text,oi.quantity) FROM public.order_items oi WHERE oi.order_id=v_existing_order_id AND oi.deleted_at IS NULL) THEN
      RAISE EXCEPTION 'marketplace checkout retry item binding conflicts' USING ERRCODE='23505'; END IF;
    IF p_buyer_account_id IS NOT NULL THEN
      v_order := public.create_checkout_order_for_buyer(
        p_buyer_account_id,p_buyer_session_epoch,p_store_id,p_customer_name,p_customer_email,p_customer_phone,p_shipping_address,p_items,
        p_payment_method,p_notes,p_coupon_code,p_gift_card_code,p_shipping_method,p_idempotency_key,p_actor_id,p_request_id,
        p_shipping_rate_id,p_tax_amount,p_place_of_supply_state,p_tax_lines,NULL);
    ELSE
      v_order := public.create_checkout_order(p_store_id,p_customer_name,p_customer_email,p_customer_phone,p_shipping_address,p_items,
        p_payment_method,p_notes,p_coupon_code,p_gift_card_code,p_shipping_method,p_idempotency_key,p_actor_id,p_request_id,
        p_shipping_rate_id,p_tax_amount,p_place_of_supply_state,p_tax_lines,NULL,NULL);
    END IF;
    RETURN v_order;
  END IF;

  -- Lock cart capabilities in deterministic order before product/inventory locks.
  PERFORM c.id FROM public.carts c WHERE c.store_id=p_store_id AND c.id IN
    (SELECT (i->'cart_fact_ref'->>'cart_id')::uuid FROM jsonb_array_elements(p_items) i WHERE i ? 'cart_fact_ref')
    ORDER BY c.id FOR UPDATE;
  PERFORM il.id FROM public.inventory_levels il WHERE il.store_id=p_store_id AND il.product_id IN
    (SELECT (i->>'product_id')::uuid FROM jsonb_array_elements(p_items) i) ORDER BY il.id FOR UPDATE;
  PERFORM pv.id FROM public.product_variants pv JOIN public.products p ON p.id=pv.product_id
    WHERE p.store_id=p_store_id AND pv.product_id IN (SELECT (i->>'product_id')::uuid FROM jsonb_array_elements(p_items) i)
    ORDER BY pv.id FOR UPDATE OF pv;
  PERFORM po.id FROM public.product_options po JOIN public.products p ON p.id=po.product_id
    WHERE p.store_id=p_store_id AND po.product_id IN (SELECT (i->>'product_id')::uuid FROM jsonb_array_elements(p_items) i)
    ORDER BY po.id FOR UPDATE OF po;
  PERFORM p.id FROM public.products p WHERE p.store_id=p_store_id AND p.id IN
    (SELECT (i->>'product_id')::uuid FROM jsonb_array_elements(p_items) i) ORDER BY p.id FOR UPDATE;

  FOR v_line IN
    SELECT value, ordinality FROM jsonb_array_elements(p_items) WITH ORDINALITY AS item(value, ordinality)
  LOOP
    v_expected_count := v_expected_count + 1;
    IF jsonb_typeof(v_line.value) IS DISTINCT FROM 'object'
       OR NULLIF(v_line.value ->> 'marketplace_listing_id', '') IS NULL
       OR NULLIF(v_line.value ->> 'product_id', '') IS NULL
       OR COALESCE((v_line.value ->> 'quantity')::integer, 0) < 1 THEN
      RAISE EXCEPTION 'marketplace checkout item is missing listing identity' USING ERRCODE = '22023';
    END IF;

    -- Cart/inventory/variant/options/product locks above match385 and the inner writer.
    -- Retain the existing site/publication and approved-listing checks under these locks.
    SELECT p.id, p.site_id, p.is_active, p.deleted_at, s.status AS site_status,
           s.deleted_at AS site_deleted_at
      INTO v_listing
      FROM public.products p
      JOIN public.sites s ON s.id = p.site_id
     WHERE p.id = (v_line.value ->> 'product_id')::uuid
       AND p.store_id = p_store_id
     FOR SHARE OF p, s;

    IF NOT FOUND OR v_listing.site_id <> p_store_id OR v_listing.is_active IS DISTINCT FROM true
       OR v_listing.deleted_at IS NOT NULL OR v_listing.site_status <> 'published'
       OR v_listing.site_deleted_at IS NOT NULL THEN
      RAISE EXCEPTION 'marketplace listing is unavailable for checkout' USING ERRCODE = '23514';
    END IF;

    SELECT cl.id, cl.site_id, cl.product_id, cl.channel, cl.status, cl.visibility,
           cl.approved_product_fingerprint
      INTO v_listing
      FROM public.channel_listings cl
     WHERE cl.id = (v_line.value ->> 'marketplace_listing_id')::uuid
     FOR SHARE;

    IF NOT FOUND OR v_listing.site_id <> p_store_id OR v_listing.product_id <> (v_line.value ->> 'product_id')::uuid
       OR v_listing.channel <> 'marketplace' OR v_listing.status <> 'approved' OR v_listing.visibility <> 'public'
       OR v_listing.approved_product_fingerprint IS NULL THEN
      RAISE EXCEPTION 'marketplace listing is unavailable for checkout' USING ERRCODE = '23514';
    END IF;

    v_fingerprint := public.marketplace_listing_review_fingerprint(v_listing.id);
    IF v_fingerprint IS NULL OR v_fingerprint IS DISTINCT FROM v_listing.approved_product_fingerprint THEN
      RAISE EXCEPTION 'marketplace listing revision is no longer approved' USING ERRCODE = '23514';
    END IF;

    v_items := v_items || jsonb_build_array(
      jsonb_set(v_line.value, '{marketplace_approved_fingerprint}', to_jsonb(v_fingerprint), true)
    );
  END LOOP;

  IF p_buyer_account_id IS NOT NULL THEN
    v_order := public.create_checkout_order_for_buyer(
      p_buyer_account_id, p_buyer_session_epoch, p_store_id, p_customer_name, p_customer_email,
      p_customer_phone, p_shipping_address, v_items, p_payment_method, p_notes, p_coupon_code,
      p_gift_card_code, p_shipping_method, p_idempotency_key, p_actor_id, p_request_id,
      p_shipping_rate_id, p_tax_amount, p_place_of_supply_state, p_tax_lines, NULL
    );
  ELSE
    v_order := public.create_checkout_order(
      p_store_id, p_customer_name, p_customer_email, p_customer_phone, p_shipping_address,
      v_items, p_payment_method, p_notes, p_coupon_code, p_gift_card_code, p_shipping_method,
      p_idempotency_key, p_actor_id, p_request_id, p_shipping_rate_id, p_tax_amount,
      p_place_of_supply_state, p_tax_lines, NULL, NULL
    );
  END IF;

  v_order_id := NULLIF(v_order ->> 'id', '')::uuid;
  IF v_order_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.orders WHERE id = v_order_id AND store_id = p_store_id AND deleted_at IS NULL
  ) THEN
    RAISE EXCEPTION 'canonical marketplace checkout returned an invalid order' USING ERRCODE = '23514';
  END IF;

  IF v_existing_order_id IS NOT NULL AND v_existing_order_id <> v_order_id THEN
    RAISE EXCEPTION 'marketplace checkout idempotency binding changed' USING ERRCODE = '23505';
  END IF;

  IF v_existing_order_id IS NOT NULL THEN
    SELECT p.channel INTO v_purchase_channel
      FROM public.orders o JOIN public.purchases p ON p.id = o.purchase_id
     WHERE o.id = v_order_id AND o.store_id = p_store_id;
    IF v_purchase_channel IS DISTINCT FROM 'marketplace' THEN
      RAISE EXCEPTION 'checkout idempotency key is already bound to another sales origin' USING ERRCODE = '23505';
    END IF;
    SELECT count(*) INTO v_bound_count
      FROM public.order_items oi
      JOIN jsonb_to_recordset(v_items) AS item(product_id uuid, variant_id text, quantity integer, marketplace_listing_id uuid, marketplace_approved_fingerprint text, cart_fact_ref jsonb)
        ON oi.product_id = item.product_id
       AND oi.variant_id IS NOT DISTINCT FROM item.variant_id
       AND oi.quantity = item.quantity
       AND coalesce(oi.product_snapshot->>'cart_id','')=coalesce(item.cart_fact_ref->>'cart_id','')
       AND coalesce(oi.product_snapshot->>'cart_line_id','')=coalesce(item.cart_fact_ref->>'line_id','')
       AND coalesce(oi.product_snapshot->>'configuration_fingerprint','')=coalesce(item.cart_fact_ref->>'configuration_fingerprint','')
       AND coalesce(oi.product_snapshot->>'snapshot_fingerprint','')=coalesce(item.cart_fact_ref->>'snapshot_fingerprint','')
       AND oi.marketplace_listing_id = item.marketplace_listing_id
       AND oi.marketplace_approved_fingerprint = item.marketplace_approved_fingerprint
     WHERE oi.order_id = v_order_id;
    IF v_bound_count <> v_expected_count THEN
      RAISE EXCEPTION 'marketplace checkout retry item binding conflicts' USING ERRCODE = '23505';
    END IF;
  ELSE
    UPDATE public.purchases SET channel = 'marketplace'
     WHERE id = (SELECT purchase_id FROM public.orders WHERE id = v_order_id)
       AND origin_site_id = p_store_id AND idempotency_key = p_idempotency_key AND channel = 'storefront';
    IF NOT FOUND THEN
      RAISE EXCEPTION 'marketplace checkout purchase origin could not be bound' USING ERRCODE = '23514';
    END IF;

    PERFORM set_config('app.marketplace_order_creation', 'on', true);
    UPDATE public.order_items oi
       SET marketplace_listing_id = item.marketplace_listing_id,
           marketplace_approved_fingerprint = item.marketplace_approved_fingerprint
      FROM jsonb_to_recordset(v_items) AS item(product_id uuid, variant_id text, quantity integer, marketplace_listing_id uuid, marketplace_approved_fingerprint text, cart_fact_ref jsonb)
     WHERE oi.order_id = v_order_id
       AND oi.product_id = item.product_id
       AND oi.variant_id IS NOT DISTINCT FROM item.variant_id
       AND oi.quantity = item.quantity
       AND coalesce(oi.product_snapshot->>'cart_id','')=coalesce(item.cart_fact_ref->>'cart_id','')
       AND coalesce(oi.product_snapshot->>'cart_line_id','')=coalesce(item.cart_fact_ref->>'line_id','')
       AND coalesce(oi.product_snapshot->>'configuration_fingerprint','')=coalesce(item.cart_fact_ref->>'configuration_fingerprint','')
       AND coalesce(oi.product_snapshot->>'snapshot_fingerprint','')=coalesce(item.cart_fact_ref->>'snapshot_fingerprint','');
    GET DIAGNOSTICS v_bound_count = ROW_COUNT;
    PERFORM set_config('app.marketplace_order_creation', '', true);
    IF v_bound_count <> v_expected_count THEN
      RAISE EXCEPTION 'marketplace checkout order lines could not be bound to approved listings' USING ERRCODE = '23514';
    END IF;
  END IF;

  RETURN v_order;
END;

DECLARE
  v_rate record;
  v_shipping_amount numeric(10,2);
  v_country text := lower(btrim(coalesce(p_shipping_address ->> 'country', '')));
  v_state text := lower(btrim(coalesce(p_shipping_address ->> 'state', '')));
  v_state_code text := lower(btrim(coalesce(p_shipping_address ->> 'state_code', '')));
  v_pincode text := btrim(coalesce(p_shipping_address ->> 'zip', p_shipping_address ->> 'pincode', ''));
BEGIN
  IF p_shipping_rate_id IS NULL OR p_expected_shipping_amount IS NULL
     OR p_expected_shipping_amount < 0 OR round(p_expected_shipping_amount, 2) <> p_expected_shipping_amount THEN
    RAISE EXCEPTION 'marketplace delivery rate quote is incomplete' USING ERRCODE = '22023';
  END IF;
  IF v_country NOT IN ('in', 'india') OR v_pincode !~ '^[1-9][0-9]{5}$' OR v_state = '' THEN
    RAISE EXCEPTION 'marketplace delivery address is invalid' USING ERRCODE = '22023';
  END IF;

  SELECT sr.type, sr.price, sr.cod_enabled AS rate_cod_enabled,
         sz.countries, sz.states, sz.zip_codes, sz.cod_enabled AS zone_cod_enabled
    INTO v_rate
    FROM public.shipping_rates sr
    JOIN public.shipping_zones sz ON sz.id = sr.zone_id
   WHERE sr.id = p_shipping_rate_id
     AND sr.site_id = p_store_id
     AND sz.store_id = p_store_id
     AND sz.site_id = p_store_id
     AND sr.is_active IS TRUE
     AND sr.deleted_at IS NULL
     AND sz.deleted_at IS NULL
   FOR SHARE OF sr, sz;
  IF NOT FOUND OR v_rate.rate_cod_enabled IS DISTINCT FROM true
     OR v_rate.zone_cod_enabled IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'marketplace delivery rate is no longer available' USING ERRCODE = '23514';
  END IF;

  IF NOT EXISTS (
       SELECT 1 FROM unnest(coalesce(v_rate.countries, ARRAY[]::text[])) AS country(value)
        WHERE lower(btrim(country.value)) IN ('in', 'india')
     )
     OR (coalesce(cardinality(v_rate.states), 0) > 0 AND NOT EXISTS (
       SELECT 1 FROM unnest(v_rate.states) AS state(value)
        WHERE lower(btrim(state.value)) IN (v_state, v_state_code)
     ))
     OR (coalesce(cardinality(v_rate.zip_codes), 0) > 0 AND NOT (v_pincode = ANY(v_rate.zip_codes))) THEN
    RAISE EXCEPTION 'marketplace delivery rate does not cover this address' USING ERRCODE = '23514';
  END IF;

  IF v_rate.type IS NULL OR v_rate.type NOT IN ('flat', 'free', 'price_based') THEN
    RAISE EXCEPTION 'marketplace delivery rate type is not supported for checkout' USING ERRCODE = '23514';
  END IF;
  v_shipping_amount := CASE WHEN v_rate.type = 'free' THEN 0 ELSE coalesce(v_rate.price, 0) END;
  IF round(v_shipping_amount, 2) IS DISTINCT FROM round(p_expected_shipping_amount, 2) THEN
    RAISE EXCEPTION 'marketplace delivery rate quote changed before order creation' USING ERRCODE = '23514';
  END IF;

  RETURN public.create_marketplace_checkout_order(
    p_store_id, p_customer_name, p_customer_email, p_customer_phone,
    p_shipping_address, p_items, p_payment_method, p_notes, p_coupon_code,
    p_gift_card_code, p_shipping_method, p_idempotency_key, p_actor_id,
    p_request_id, p_shipping_rate_id, p_tax_amount, p_place_of_supply_state,
    p_tax_lines, p_buyer_account_id, p_buyer_session_epoch
  );
END;

DECLARE
  v_rate record;
  v_shipping_amount numeric(10,2);
  v_subtotal numeric(12,2);
  v_country text := lower(btrim(coalesce(p_shipping_address ->> 'country', '')));
  v_state text := lower(btrim(coalesce(p_shipping_address ->> 'state', '')));
  v_state_code text := lower(btrim(coalesce(p_shipping_address ->> 'state_code', '')));
  v_pincode text := btrim(coalesce(p_shipping_address ->> 'zip', p_shipping_address ->> 'pincode', ''));
BEGIN
  IF p_shipping_rate_id IS NULL OR p_expected_shipping_amount IS NULL
     OR p_expected_shipping_amount < 0 OR round(p_expected_shipping_amount, 2) <> p_expected_shipping_amount THEN
    RAISE EXCEPTION 'storefront delivery rate quote is incomplete' USING ERRCODE = '22023';
  END IF;
  IF v_country NOT IN ('in', 'india') OR v_pincode !~ '^[1-9][0-9]{5}$' OR v_state = '' THEN
    RAISE EXCEPTION 'storefront delivery address is invalid' USING ERRCODE = '22023';
  END IF;

  SELECT sr.type, sr.price, sr.min_order_amount, sr.max_order_amount,
         sr.cod_enabled AS rate_cod_enabled,
         sz.countries, sz.states, sz.zip_codes, sz.cod_enabled AS zone_cod_enabled
    INTO v_rate
    FROM public.shipping_rates sr
    JOIN public.shipping_zones sz ON sz.id = sr.zone_id
   WHERE sr.id = p_shipping_rate_id
     AND sr.site_id = p_store_id
     AND sz.store_id = p_store_id
     AND sz.site_id = p_store_id
     AND sr.is_active IS TRUE
     AND sr.deleted_at IS NULL
     AND sz.deleted_at IS NULL
   FOR SHARE OF sr, sz;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'storefront delivery rate is no longer available' USING ERRCODE = '23514';
  END IF;

  IF (p_payment_method = 'cod'
      AND (v_rate.rate_cod_enabled IS DISTINCT FROM true OR v_rate.zone_cod_enabled IS DISTINCT FROM true)) THEN
    RAISE EXCEPTION 'storefront delivery rate does not support COD' USING ERRCODE = '23514';
  END IF;
  IF NOT EXISTS (
       SELECT 1 FROM unnest(coalesce(v_rate.countries, ARRAY[]::text[])) AS country(value)
        WHERE lower(btrim(country.value)) IN ('in', 'india')
     )
     OR (coalesce(cardinality(v_rate.states), 0) > 0 AND NOT EXISTS (
       SELECT 1 FROM unnest(v_rate.states) AS state(value)
        WHERE lower(btrim(state.value)) IN (v_state, v_state_code)
     ))
     OR (coalesce(cardinality(v_rate.zip_codes), 0) > 0 AND NOT (v_pincode = ANY(v_rate.zip_codes))) THEN
    RAISE EXCEPTION 'storefront delivery rate does not cover this address' USING ERRCODE = '23514';
  END IF;
  IF v_rate.type IS NULL OR v_rate.type NOT IN ('flat', 'free', 'price_based') THEN
    RAISE EXCEPTION 'storefront delivery rate type is unsupported' USING ERRCODE = '23514';
  END IF;

  SELECT coalesce(sum(
      coalesce(nullif(pv.price, 0), p.price, 0) * (item.value ->> 'quantity')::numeric
    ), 0)
    INTO v_subtotal
    FROM jsonb_array_elements(p_items) AS item(value)
    JOIN public.products p
      ON p.id = (item.value ->> 'product_id')::uuid
     AND p.store_id = p_store_id
     AND p.deleted_at IS NULL
    LEFT JOIN public.product_variants pv
      ON pv.id = nullif(item.value ->> 'variant_id', '')::uuid
     AND pv.product_id = p.id;
  IF (v_rate.min_order_amount IS NOT NULL AND v_subtotal < v_rate.min_order_amount)
     OR (v_rate.max_order_amount IS NOT NULL AND v_subtotal > v_rate.max_order_amount) THEN
    RAISE EXCEPTION 'storefront delivery rate subtotal range changed' USING ERRCODE = '23514';
  END IF;

  v_shipping_amount := CASE WHEN v_rate.type = 'free' THEN 0 ELSE coalesce(v_rate.price, 0) END;
  IF round(v_shipping_amount, 2) IS DISTINCT FROM round(p_expected_shipping_amount, 2) THEN
    RAISE EXCEPTION 'storefront delivery rate quote changed before order creation' USING ERRCODE = '23514';
  END IF;

  IF p_buyer_account_id IS NOT NULL THEN
    IF p_buyer_session_epoch IS NULL THEN
      RAISE EXCEPTION 'buyer session epoch is required' USING ERRCODE = '22023';
    END IF;
    RETURN public.create_checkout_order_for_buyer(
      p_buyer_account_id, p_buyer_session_epoch, p_store_id,
      p_customer_name, p_customer_email, p_customer_phone, p_shipping_address,
      p_items, p_payment_method, p_notes, p_coupon_code, p_gift_card_code,
      p_shipping_method, p_idempotency_key, p_actor_id, p_request_id,
      p_shipping_rate_id, p_tax_amount, p_place_of_supply_state, p_tax_lines, NULL
    );
  END IF;

  RETURN public.create_checkout_order(
    p_store_id, p_customer_name, p_customer_email, p_customer_phone,
    p_shipping_address, p_items, p_payment_method, p_notes, p_coupon_code,
    p_gift_card_code, p_shipping_method, p_idempotency_key, p_actor_id,
    p_request_id, p_shipping_rate_id, p_tax_amount, p_place_of_supply_state,
    p_tax_lines
  );
END;

DECLARE
  v_payment jsonb;
BEGIN
  IF p_provider IS DISTINCT FROM 'razorpay'
     OR NULLIF(btrim(p_provider_payment_id), '') IS NULL THEN
    RAISE EXCEPTION 'valid provider payment reference is required';
  END IF;

  SELECT jsonb_build_object(
    'id', id,
    'site_id', site_id,
    'order_id', order_id,
    'provider', provider,
    'provider_payment_id', provider_payment_id,
    'mode', mode
  ) INTO v_payment
    FROM public.payments
   WHERE provider = p_provider
     AND provider_payment_id = p_provider_payment_id
     AND deleted_at IS NULL;
  RETURN v_payment;
END;

DECLARE
  v_payment public.payments%ROWTYPE;
  v_attempt public.payment_attempts%ROWTYPE;
  v_reserved_minor bigint;
BEGIN
  IF p_payment_id IS NULL OR NULLIF(btrim(p_idempotency_key), '') IS NULL
     OR p_amount_minor IS NULL OR p_amount_minor <= 0 THEN
    RAISE EXCEPTION 'payment, refund amount and idempotency key are required';
  END IF;

  SELECT * INTO v_payment
    FROM public.payments
   WHERE id = p_payment_id
     AND deleted_at IS NULL
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'payment not found';
  END IF;
  IF v_payment.status <> 'captured' OR p_amount_minor > v_payment.amount_minor THEN
    RAISE EXCEPTION 'payment is not eligible for refund';
  END IF;

  SELECT * INTO v_attempt
    FROM public.payment_attempts
   WHERE payment_id = p_payment_id
     AND idempotency_key = p_idempotency_key
     AND attempt_type = 'refund'
     AND deleted_at IS NULL
   FOR UPDATE;
  IF FOUND THEN
    IF round(v_attempt.amount * 100)::bigint <> p_amount_minor THEN
      RAISE EXCEPTION 'refund idempotency key was reused with a different amount';
    END IF;
    RETURN jsonb_build_object(
      'attempt_id', v_attempt.id,
      'status', v_attempt.status,
      'created', false,
      'amount_minor', p_amount_minor,
      'provider_refund_id', v_attempt.metadata ->> 'provider_refund_id'
    );
  END IF;

  SELECT COALESCE(SUM(round(amount * 100)::bigint), 0)
    INTO v_reserved_minor
    FROM public.payment_attempts
   WHERE payment_id = p_payment_id
     AND attempt_type = 'refund'
     AND status IN ('pending', 'processing')
     AND deleted_at IS NULL;
  v_reserved_minor := COALESCE(v_payment.refunded_amount_minor, 0) + v_reserved_minor;
  IF v_reserved_minor + p_amount_minor > v_payment.amount_minor THEN
    RAISE EXCEPTION 'refund amount exceeds remaining captured payment';
  END IF;

  INSERT INTO public.payment_attempts (
    site_id, order_id, payment_id, provider, attempt_type, status,
    amount, currency, provider_order_id, provider_payment_id,
    idempotency_key, request_id, metadata, created_by, updated_by
  ) VALUES (
    v_payment.site_id, v_payment.order_id, v_payment.id, v_payment.provider,
    'refund', 'pending', p_amount_minor::numeric / 100, v_payment.currency,
    v_payment.provider_order_id, v_payment.provider_payment_id,
    p_idempotency_key, p_request_id,
    COALESCE(p_metadata, '{}'::jsonb) || jsonb_build_object('refund_amount_minor', p_amount_minor),
    p_actor_id, p_actor_id
  ) RETURNING * INTO v_attempt;

  RETURN jsonb_build_object(
    'attempt_id', v_attempt.id,
    'status', v_attempt.status,
    'created', true,
    'amount_minor', p_amount_minor,
    'provider_refund_id', NULL
  );
END;

DECLARE
  v_payment public.payments%ROWTYPE;
  v_attempt public.payment_attempts%ROWTYPE;
  v_cumulative_refund_minor bigint;
  v_ledger_transaction_id uuid;
BEGIN
  IF p_payment_id IS NULL OR p_attempt_id IS NULL
     OR NULLIF(btrim(p_provider_refund_id), '') IS NULL
     OR NULLIF(btrim(p_provider_event_id), '') IS NULL THEN
    RAISE EXCEPTION 'payment, attempt, provider refund and event references are required';
  END IF;
  IF p_event_type IS NULL OR p_status IS NULL
     OR p_event_type NOT IN ('refund.created', 'refund.processed', 'refund.failed')
     OR p_status NOT IN ('created', 'processed', 'failed') THEN
    RAISE EXCEPTION 'unsupported provider refund state';
  END IF;
  IF (p_event_type = 'refund.created' AND p_status <> 'created')
     OR (p_event_type = 'refund.processed' AND p_status <> 'processed')
     OR (p_event_type = 'refund.failed' AND p_status <> 'failed') THEN
    RAISE EXCEPTION 'provider refund event and entity status disagree';
  END IF;
  IF p_currency IS DISTINCT FROM 'INR' OR p_amount_minor IS NULL OR p_amount_minor <= 0 THEN
    RAISE EXCEPTION 'provider refund amount must be positive INR minor units';
  END IF;

  SELECT * INTO v_payment
    FROM public.payments
   WHERE id = p_payment_id
     AND deleted_at IS NULL
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'payment not found';
  END IF;
  IF v_payment.provider <> 'razorpay'
     OR v_payment.status NOT IN ('captured', 'refunded')
     OR v_payment.provider_payment_id IS NULL THEN
    RAISE EXCEPTION 'payment is not eligible for provider refund reconciliation';
  END IF;

  SELECT * INTO v_attempt
    FROM public.payment_attempts
   WHERE id = p_attempt_id
     AND payment_id = p_payment_id
     AND site_id = v_payment.site_id
     AND order_id = v_payment.order_id
     AND provider = v_payment.provider
     AND attempt_type = 'refund'
     AND deleted_at IS NULL
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'refund attempt does not belong to payment';
  END IF;
  IF round(v_attempt.amount * 100)::bigint <> p_amount_minor
     OR v_attempt.currency <> p_currency THEN
    RAISE EXCEPTION 'provider refund amount does not match reserved attempt';
  END IF;
  IF v_attempt.metadata ? 'provider_refund_id'
     AND v_attempt.metadata ->> 'provider_refund_id' <> p_provider_refund_id THEN
    RAISE EXCEPTION 'provider refund id does not match reserved attempt';
  END IF;

  IF v_attempt.status = 'succeeded' THEN
    RETURN jsonb_build_object(
      'outcome', 'processed',
      'replayed', true,
      'payment_id', p_payment_id,
      'attempt_id', p_attempt_id,
      'refunded_amount_minor', v_payment.refunded_amount_minor,
      'payment_amount_minor', v_payment.amount_minor,
      'fully_refunded', v_payment.status = 'refunded',
      'ledger_transaction_id', v_attempt.metadata ->> 'canonical_ledger_transaction_id'
    );
  END IF;

  IF p_event_type = 'refund.created' THEN
    UPDATE public.payment_attempts
       SET provider_event_id = p_provider_event_id,
           metadata = COALESCE(metadata, '{}'::jsonb)
             || jsonb_build_object(
                  'provider_refund_id', p_provider_refund_id,
                  'last_provider_event_type', p_event_type,
                  'last_provider_status', p_status
                ),
           updated_at = now()
     WHERE id = p_attempt_id;
    RETURN jsonb_build_object('outcome', 'pending', 'replayed', false, 'attempt_id', p_attempt_id);
  END IF;

  IF p_event_type = 'refund.failed' THEN
    UPDATE public.payment_attempts
       SET status = 'failed',
           provider_event_id = p_provider_event_id,
           failure_reason = 'Provider reported refund failure',
           metadata = COALESCE(metadata, '{}'::jsonb)
             || jsonb_build_object(
                  'provider_refund_id', p_provider_refund_id,
                  'last_provider_event_type', p_event_type,
                  'last_provider_status', p_status
                ),
           updated_at = now()
     WHERE id = p_attempt_id;
    RETURN jsonb_build_object('outcome', 'failed', 'replayed', false, 'attempt_id', p_attempt_id);
  END IF;

  v_cumulative_refund_minor := COALESCE(v_payment.refunded_amount_minor, 0) + p_amount_minor;
  IF v_cumulative_refund_minor > v_payment.amount_minor THEN
    RAISE EXCEPTION 'cumulative provider refunds exceed captured payment';
  END IF;

  v_ledger_transaction_id := public.post_settlement_ledger_transaction(
    v_payment.site_id,
    'refund',
    p_provider_refund_id,
    'payment.refund:' || p_payment_id::text || ':' || p_provider_refund_id,
    jsonb_build_array(
      jsonb_build_object(
        'account_code', 'merchant_payable',
        'side', 'debit',
        'amount_minor', p_amount_minor,
        'memo', 'Merchant payable refund ' || p_payment_id::text
      ),
      jsonb_build_object(
        'account_code', 'refund_clearing',
        'side', 'credit',
        'amount_minor', p_amount_minor,
        'memo', 'Provider refund ' || p_provider_refund_id
      )
    ),
    jsonb_build_object(
      'payment_id', p_payment_id,
      'order_id', v_payment.order_id,
      'provider_refund_id', p_provider_refund_id,
      'provider_event_id', p_provider_event_id,
      'refund_amount_minor', p_amount_minor
    ),
    p_request_id
  );

  UPDATE public.payment_attempts
     SET status = 'succeeded',
         provider_event_id = p_provider_event_id,
         failure_reason = NULL,
         metadata = COALESCE(metadata, '{}'::jsonb)
           || jsonb_build_object(
                'provider_refund_id', p_provider_refund_id,
                'last_provider_event_type', p_event_type,
                'last_provider_status', p_status,
                'canonical_ledger_transaction_id', v_ledger_transaction_id
              ),
         updated_at = now()
   WHERE id = p_attempt_id;

  UPDATE public.payments
     SET status = CASE WHEN v_cumulative_refund_minor = amount_minor THEN 'refunded' ELSE 'captured' END,
         refunded_amount_minor = v_cumulative_refund_minor,
         refunded_at = CASE WHEN v_cumulative_refund_minor = amount_minor THEN COALESCE(refunded_at, now()) ELSE refunded_at END,
         refund_ledger_transaction_id = v_ledger_transaction_id,
         request_id = p_request_id,
         updated_at = now()
   WHERE id = p_payment_id;

  RETURN jsonb_build_object(
    'outcome', 'processed',
    'replayed', false,
    'payment_id', p_payment_id,
    'attempt_id', p_attempt_id,
    'refunded_amount_minor', v_cumulative_refund_minor,
    'payment_amount_minor', v_payment.amount_minor,
    'fully_refunded', v_cumulative_refund_minor = v_payment.amount_minor,
    'ledger_transaction_id', v_ledger_transaction_id
  );
END;

DECLARE
  v_payment public.payments%ROWTYPE;
  v_attempt public.payment_attempts%ROWTYPE;
  v_cumulative_refund_minor bigint;
  v_ledger_transaction_id uuid;
  v_provider_event_id text;
  v_outbox_idempotency_key text;
  v_fully_refunded boolean;
BEGIN
  IF p_payment_id IS NULL OR p_attempt_id IS NULL
     OR NULLIF(btrim(p_provider_refund_id), '') IS NULL
     OR p_currency IS DISTINCT FROM 'INR'
     OR p_amount_minor IS NULL OR p_amount_minor <= 0 THEN
    RAISE EXCEPTION 'manual refund requires a payment, attempt, provider reference and positive INR amount';
  END IF;

  SELECT * INTO v_payment
    FROM public.payments
   WHERE id = p_payment_id
     AND deleted_at IS NULL
   FOR UPDATE;
  IF NOT FOUND OR v_payment.provider = 'razorpay'
     OR v_payment.status NOT IN ('captured', 'refunded') THEN
    RAISE EXCEPTION 'payment is not eligible for manual refund finalization';
  END IF;

  SELECT * INTO v_attempt
    FROM public.payment_attempts
   WHERE id = p_attempt_id
     AND payment_id = p_payment_id
     AND site_id = v_payment.site_id
     AND order_id = v_payment.order_id
     AND provider = v_payment.provider
     AND attempt_type = 'refund'
     AND deleted_at IS NULL
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'manual refund attempt does not belong to payment';
  END IF;
  IF round(v_attempt.amount * 100)::bigint <> p_amount_minor
     OR v_attempt.currency <> p_currency THEN
    RAISE EXCEPTION 'manual refund amount does not match reserved attempt';
  END IF;
  IF v_attempt.metadata ? 'provider_refund_id'
     AND v_attempt.metadata ->> 'provider_refund_id' <> p_provider_refund_id THEN
    RAISE EXCEPTION 'manual refund reference does not match reserved attempt';
  END IF;

  v_provider_event_id := 'manual.refund:' || p_provider_refund_id;
  v_outbox_idempotency_key := 'payment.refund:' || p_payment_id::text || ':' || v_payment.provider || ':' || p_provider_refund_id;
  IF v_attempt.status = 'succeeded' THEN
    IF v_attempt.provider_event_id IS DISTINCT FROM v_provider_event_id THEN
      RAISE EXCEPTION 'manual refund attempt was already finalized with a different provider reference';
    END IF;
    RETURN jsonb_build_object(
      'outcome', 'processed',
      'replayed', true,
      'payment_id', p_payment_id,
      'attempt_id', p_attempt_id,
      'refunded_amount_minor', v_payment.refunded_amount_minor,
      'payment_amount_minor', v_payment.amount_minor,
      'fully_refunded', v_payment.status = 'refunded',
      'ledger_transaction_id', v_attempt.metadata ->> 'canonical_ledger_transaction_id'
    );
  END IF;
  IF v_attempt.status NOT IN ('pending', 'processing') THEN
    RAISE EXCEPTION 'manual refund attempt is not pending';
  END IF;

  v_cumulative_refund_minor := COALESCE(v_payment.refunded_amount_minor, 0) + p_amount_minor;
  IF v_cumulative_refund_minor > v_payment.amount_minor THEN
    RAISE EXCEPTION 'cumulative manual refunds exceed captured payment';
  END IF;
  v_fully_refunded := v_cumulative_refund_minor = v_payment.amount_minor;

  v_ledger_transaction_id := public.post_settlement_ledger_transaction(
    v_payment.site_id,
    'refund',
    p_provider_refund_id,
    v_outbox_idempotency_key,
    jsonb_build_array(
      jsonb_build_object(
        'account_code', 'merchant_payable',
        'side', 'debit',
        'amount_minor', p_amount_minor,
        'memo', 'Merchant payable refund ' || p_payment_id::text
      ),
      jsonb_build_object(
        'account_code', 'refund_clearing',
        'side', 'credit',
        'amount_minor', p_amount_minor,
        'memo', 'Provider refund ' || p_provider_refund_id
      )
    ),
    jsonb_build_object(
      'payment_id', p_payment_id,
      'order_id', v_payment.order_id,
      'provider', v_payment.provider,
      'provider_refund_id', p_provider_refund_id,
      'refund_amount_minor', p_amount_minor,
      'cumulative_refund_amount_minor', v_cumulative_refund_minor,
      'confirmation_source', 'merchant_step_up'
    ),
    p_request_id
  );

  UPDATE public.payment_attempts
     SET status = 'succeeded',
         provider_event_id = v_provider_event_id,
         failure_reason = NULL,
         metadata = COALESCE(metadata, '{}'::jsonb)
           || jsonb_build_object(
                'provider_refund_id', p_provider_refund_id,
                'last_provider_event_type', 'manual.refund',
                'last_provider_status', 'processed',
                'canonical_ledger_transaction_id', v_ledger_transaction_id
              ),
         request_id = p_request_id,
         updated_by = p_actor_id,
         updated_at = now()
   WHERE id = p_attempt_id;

  UPDATE public.payments
     SET status = CASE WHEN v_fully_refunded THEN 'refunded' ELSE 'captured' END,
         refunded_amount_minor = v_cumulative_refund_minor,
         refunded_at = CASE WHEN v_fully_refunded THEN COALESCE(refunded_at, now()) ELSE refunded_at END,
         refund_ledger_transaction_id = v_ledger_transaction_id,
         request_id = p_request_id,
         updated_by = p_actor_id,
         updated_at = now()
   WHERE id = p_payment_id;

  INSERT INTO public.outbox_events (
    store_id, aggregate_type, aggregate_id, event_type, payload,
    idempotency_key, request_id, actor_id, schema_version
  ) VALUES (
    v_payment.site_id,
    'order',
    v_payment.order_id::text,
    'payment.refunded',
    jsonb_build_object(
      'order_id', v_payment.order_id,
      'payment_id', v_payment.id,
      'provider', v_payment.provider,
      'provider_event_id', v_provider_event_id,
      'payment_status', CASE WHEN v_fully_refunded THEN 'refunded' ELSE 'paid' END
    ),
    v_outbox_idempotency_key,
    p_request_id,
    p_actor_id,
    1
  ) ON CONFLICT (idempotency_key) DO NOTHING;

  RETURN jsonb_build_object(
    'outcome', 'processed',
    'replayed', false,
    'payment_id', p_payment_id,
    'attempt_id', p_attempt_id,
    'refunded_amount_minor', v_cumulative_refund_minor,
    'payment_amount_minor', v_payment.amount_minor,
    'fully_refunded', v_fully_refunded,
    'ledger_transaction_id', v_ledger_transaction_id
  );
END;

DECLARE
  v_attempt public.onboarding_attempts%ROWTYPE;
  v_owned_store_id uuid;
  v_owned_store_subdomain text;
BEGIN
  IF p_user_id IS NULL OR p_attempt_id IS NULL OR p_store_id IS NULL THEN
    RAISE EXCEPTION 'Invalid onboarding completion scope' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_user_id::text || ':storefront-web-onboarding-draft', 0));

  SELECT id, subdomain INTO v_owned_store_id, v_owned_store_subdomain
  FROM public.sites
  WHERE id = p_store_id
    AND (custom_user_id = p_user_id OR user_id = p_user_id)
    AND deleted_at IS NULL
  FOR UPDATE;
  IF v_owned_store_id IS NULL THEN
    RAISE EXCEPTION 'Onboarding store is not owned by this user' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_attempt
  FROM public.onboarding_attempts
  WHERE id = p_attempt_id AND user_id = p_user_id AND site_type = 'store'
    AND survey_data ? 'web_draft'
  FOR UPDATE;
  IF v_attempt.id IS NULL THEN
    RAISE EXCEPTION 'Onboarding draft not found' USING ERRCODE = 'P0002';
  END IF;
  IF v_attempt.requested_subdomain <> v_owned_store_subdomain THEN
    RAISE EXCEPTION 'Onboarding draft handle does not match store' USING ERRCODE = '22023';
  END IF;

  IF v_attempt.status = 'completed' AND v_attempt.store_id = p_store_id THEN
    RETURN jsonb_build_object('completed', true, 'attempt_id', v_attempt.id, 'store_id', p_store_id);
  END IF;
  IF v_attempt.status <> 'in_progress' OR v_attempt.store_id IS NOT NULL THEN
    RAISE EXCEPTION 'Onboarding draft is already finalized' USING ERRCODE = '55000';
  END IF;

  UPDATE public.onboarding_attempts
  SET status = 'completed',
      store_id = p_store_id,
      current_step = 4,
      completed_steps = ARRAY[1, 2, 3]::integer[],
      completed_at = now(),
      last_activity_at = now()
  WHERE id = v_attempt.id;

  RETURN jsonb_build_object('completed', true, 'attempt_id', v_attempt.id, 'store_id', p_store_id);
END;

DECLARE
  v_attempt public.onboarding_attempts%ROWTYPE;
  v_name text := nullif(btrim(p_store_name), '');
  v_subdomain text := nullif(lower(btrim(p_subdomain)), '');
  v_industry text := coalesce(nullif(btrim(p_industry), ''), 'general');
  v_channels text[] := coalesce(p_channels, ARRAY['online']::text[]);
  v_draft jsonb;
BEGIN
  IF p_user_id IS NULL OR p_step NOT BETWEEN 1 AND 3 THEN
    RAISE EXCEPTION 'Invalid onboarding draft scope or step' USING ERRCODE = '22023';
  END IF;
  IF length(coalesce(v_name, '')) > 100 THEN
    RAISE EXCEPTION 'Store name exceeds limit' USING ERRCODE = '22023';
  END IF;
  IF v_subdomain IS NOT NULL AND (length(v_subdomain) > 63 OR v_subdomain !~ '^[a-z0-9]([a-z0-9-]*[a-z0-9])?$') THEN
    RAISE EXCEPTION 'Invalid store subdomain' USING ERRCODE = '22023';
  END IF;
  IF v_industry NOT IN ('electronics', 'fashion', 'beauty', 'furniture', 'food', 'sports', 'books', 'pet', 'general') THEN
    RAISE EXCEPTION 'Invalid store industry' USING ERRCODE = '22023';
  END IF;
  IF cardinality(v_channels) > 5 OR EXISTS (
    SELECT 1 FROM unnest(v_channels) AS supplied(channel)
    WHERE channel IS NULL OR channel NOT IN ('online', 'retail', 'social', 'marketplace', 'events')
  ) THEN
    RAISE EXCEPTION 'Invalid sales channel selection' USING ERRCODE = '22023';
  END IF;
  SELECT coalesce(array_agg(DISTINCT channel ORDER BY channel), ARRAY[]::text[])
  INTO v_channels
  FROM unnest(v_channels) AS supplied(channel);

  -- Advisory lock prevents duplicate active web attempts when autosaves race.
  PERFORM pg_advisory_xact_lock(hashtextextended(p_user_id::text || ':storefront-web-onboarding-draft', 0));

  SELECT * INTO v_attempt
  FROM public.onboarding_attempts
  WHERE user_id = p_user_id
    AND site_type = 'store'
    AND status = 'in_progress'
    AND deleted_at IS NULL
    AND survey_data ? 'web_draft'
  ORDER BY updated_at DESC NULLS LAST, created_at DESC, id DESC
  LIMIT 1
  FOR UPDATE;

  v_draft := jsonb_build_object(
    'version', 1,
    'store_name', coalesce(v_name, ''),
    'subdomain', coalesce(v_subdomain, ''),
    'industry', v_industry
  );

  IF v_attempt.id IS NULL THEN
    INSERT INTO public.onboarding_attempts (
      user_id, requested_name, requested_subdomain, site_type, status,
      current_step, completed_steps, survey_data, last_activity_at
    ) VALUES (
      p_user_id,
      coalesce(v_name, 'store-setup'),
      coalesce(v_subdomain, 'draft-' || left(p_user_id::text, 8)),
      'store', 'in_progress', p_step,
      CASE WHEN p_step > 1 THEN ARRAY(SELECT generate_series(1, p_step - 1)) ELSE ARRAY[]::integer[] END,
      jsonb_build_object('web_draft', v_draft, 'channels', to_jsonb(v_channels)),
      now()
    )
    RETURNING * INTO v_attempt;
  ELSE
    UPDATE public.onboarding_attempts
    SET requested_name = coalesce(v_name, 'store-setup'),
        requested_subdomain = coalesce(v_subdomain, 'draft-' || left(p_user_id::text, 8)),
        current_step = p_step,
        completed_steps = CASE WHEN p_step > 1 THEN ARRAY(SELECT generate_series(1, p_step - 1)) ELSE ARRAY[]::integer[] END,
        survey_data = coalesce(survey_data, '{}'::jsonb) || jsonb_build_object('web_draft', v_draft, 'channels', to_jsonb(v_channels)),
        last_activity_at = now()
    WHERE id = v_attempt.id
    RETURNING * INTO v_attempt;
  END IF;

  RETURN jsonb_build_object(
    'attempt_id', v_attempt.id,
    'current_step', v_attempt.current_step,
    'site_type', v_attempt.site_type,
    'draft', v_draft,
    'channels', to_jsonb(v_channels),
    'updated_at', v_attempt.updated_at
  );
END;

DECLARE
  v_email text := lower(btrim(p_customer_email));
  v_row public.customer_addresses%ROWTYPE;
  v_fields jsonb;
BEGIN
  IF p_store_id IS NULL OR v_email = '' OR p_address IS NULL OR jsonb_typeof(p_address) <> 'object' THEN
    RAISE EXCEPTION 'store, customer email and address object are required' USING ERRCODE = '22023';
  END IF;

  -- Storefront callers bind their signed session to a live store customer in
  -- this same transaction. Merchant callers pass NULL after their store-owner
  -- permission check and retain the pre-existing merchant address API scope.
  IF p_customer_id IS NOT NULL THEN
    PERFORM 1 FROM public.store_customers
     WHERE id = p_customer_id AND store_id = p_store_id
       AND lower(email) = v_email AND status = 'active' AND deleted_at IS NULL
     FOR NO KEY UPDATE;
    IF NOT FOUND THEN RETURN NULL; END IF;
  END IF;

  -- Advisory transaction lock covers the no-row-yet case and serializes every
  -- supported create/update for this store/customer pair without changing data.
  PERFORM pg_advisory_xact_lock(hashtextextended(p_store_id::text || ':' || v_email, 0));

  SELECT coalesce(jsonb_object_agg(key, value), '{}'::jsonb) INTO v_fields
    FROM jsonb_each(p_address)
   WHERE key = ANY(ARRAY[
     'customer_phone','label','full_name','address_line1','address_line2',
     'city','state','postal_code','country','landmark','is_default','gstin','state_code'
   ]);

  IF p_address_id IS NOT NULL THEN
    SELECT * INTO v_row
      FROM public.customer_addresses
     WHERE id = p_address_id
       AND store_id = p_store_id
       AND lower(customer_email) = v_email
     FOR UPDATE;
    IF NOT FOUND THEN RETURN NULL; END IF;
    v_row := jsonb_populate_record(v_row, v_fields);
  ELSE
    v_row := jsonb_populate_record(NULL::public.customer_addresses,
      jsonb_build_object('label','home','country','IN','is_default',false) || v_fields);
  END IF;

  v_row.label := coalesce(v_row.label, 'home');
  v_row.country := coalesce(v_row.country, 'IN');
  v_row.is_default := coalesce(v_row.is_default, false);

  IF v_row.is_default THEN
    UPDATE public.customer_addresses
       SET is_default = false
     WHERE store_id = p_store_id
       AND lower(customer_email) = v_email
       AND (p_address_id IS NULL OR id <> p_address_id)
       AND is_default;
  END IF;

  IF p_address_id IS NULL THEN
    INSERT INTO public.customer_addresses (
      store_id,customer_email,customer_phone,label,full_name,address_line1,address_line2,
      city,state,postal_code,country,landmark,is_default,gstin,state_code
    ) VALUES (
      p_store_id,v_email,v_row.customer_phone,v_row.label,v_row.full_name,v_row.address_line1,
      v_row.address_line2,v_row.city,v_row.state,v_row.postal_code,v_row.country,
      v_row.landmark,v_row.is_default,v_row.gstin,v_row.state_code
    ) RETURNING * INTO v_row;
  ELSE
    UPDATE public.customer_addresses SET
      customer_phone=v_row.customer_phone,label=v_row.label,full_name=v_row.full_name,
      address_line1=v_row.address_line1,address_line2=v_row.address_line2,city=v_row.city,
      state=v_row.state,postal_code=v_row.postal_code,country=v_row.country,
      landmark=v_row.landmark,is_default=v_row.is_default,gstin=v_row.gstin,state_code=v_row.state_code
     WHERE id=p_address_id AND store_id=p_store_id AND lower(customer_email)=v_email
     RETURNING * INTO v_row;
  END IF;

  RETURN to_jsonb(v_row);
END;

DECLARE
  v_now timestamptz := clock_timestamp();
  v_ticket public.support_tickets%ROWTYPE;
  v_message public.ticket_messages%ROWTYPE;
BEGIN
  IF p_ticket_ref IS NULL OR btrim(p_ticket_ref) = ''
     OR p_requester_user_id IS NULL
     OR p_subject IS NULL OR btrim(p_subject) = ''
     OR p_body IS NULL OR btrim(p_body) = ''
     OR p_first_response_due_at IS NULL
     OR p_resolution_due_at IS NULL THEN
    RAISE EXCEPTION 'buyer support intake requires a reference, buyer, subject, body and SLA deadlines'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.support_tickets (
    ticket_ref, first_response_due_at, resolution_due_at, site_id,
    requester_type, requester_user_id, subject, channel, status,
    last_customer_message_at, created_at
  )
  VALUES (
    p_ticket_ref, p_first_response_due_at, p_resolution_due_at, p_site_id,
    'customer', p_requester_user_id, btrim(p_subject), 'chat', 'open',
    v_now, v_now
  )
  RETURNING * INTO v_ticket;

  INSERT INTO public.ticket_messages (
    ticket_id, author_type, author_id, visibility, body, created_at
  )
  VALUES (
    v_ticket.id, 'requester', p_requester_user_id, 'public', btrim(p_body), v_now
  )
  RETURNING * INTO v_message;

  RETURN jsonb_build_object(
    'ticket', jsonb_build_object(
      'id', v_ticket.id,
      'ticket_ref', v_ticket.ticket_ref,
      'subject', v_ticket.subject,
      'status', v_ticket.status,
      'topic', v_ticket.topic,
      'created_at', v_ticket.created_at,
      'last_agent_message_at', v_ticket.last_agent_message_at
    ),
    'message', jsonb_build_object(
      'id', v_message.id,
      'author_type', v_message.author_type,
      'body', v_message.body,
      'created_at', v_message.created_at
    )
  );
END;

DECLARE
  v_charge public.billing_history%ROWTYPE;
  v_credited jsonb;
  v_ledger_id uuid;
BEGIN
  IF p_site_id IS NULL OR p_billing_history_id IS NULL
     OR NULLIF(btrim(p_provider_order_id), '') IS NULL
     OR NULLIF(btrim(p_provider_payment_id), '') IS NULL THEN
    RAISE EXCEPTION 'ad credit payment binding is incomplete';
  END IF;

  SELECT * INTO v_charge FROM public.billing_history
   WHERE id = p_billing_history_id AND site_id = p_site_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ad credit billing record not found for site'; END IF;

  IF v_charge.payment_gateway IS DISTINCT FROM 'razorpay'
     OR v_charge.payment_id IS DISTINCT FROM p_provider_order_id
     OR v_charge.currency IS DISTINCT FROM 'INR'
     OR v_charge.amount <= 0
     OR v_charge.amount <> trunc(v_charge.amount) THEN
    RAISE EXCEPTION 'ad credit payment does not match its stored order';
  END IF;

  IF v_charge.payment_status = 'paid' THEN
    IF v_charge.provider_payment_reference IS DISTINCT FROM p_provider_payment_id THEN
      RAISE EXCEPTION 'ad credit billing record was finalized by a different payment';
    END IF;
  ELSIF v_charge.payment_status = 'pending' THEN
    IF v_charge.provider_payment_reference IS NOT NULL THEN
      RAISE EXCEPTION 'pending ad credit billing record already has a payment reference';
    END IF;
  ELSE
    RAISE EXCEPTION 'ad credit billing record is not payable';
  END IF;

  v_ledger_id := public.post_settlement_ledger_transaction(
    p_site_id,
    'ad_credit_purchase',
    p_billing_history_id::text,
    'ad-credit-purchase:' || p_billing_history_id::text,
    jsonb_build_array(
      jsonb_build_object('account_code', 'pa_clearing', 'side', 'debit',
        'amount_minor', v_charge.amount::bigint, 'memo', 'Razorpay ad-credit purchase clearing'),
      jsonb_build_object('account_code', 'ad_credit_liability', 'side', 'credit',
        'amount_minor', v_charge.amount::bigint, 'memo', 'Prepaid advertising service entitlement')
    ),
    jsonb_build_object('compatibility_table', 'billing_history',
      'billing_history_id', p_billing_history_id,
      'provider_payment_reference', p_provider_payment_id),
    p_request_id
  );

  v_credited := public.record_ad_credit_purchase(
    p_site_id,
    v_charge.amount::bigint,
    p_provider_payment_id,
    'ad.purchase:' || p_provider_payment_id,
    p_request_id,
    p_actor_id
  );

  IF v_charge.payment_status = 'pending'
     OR v_charge.canonical_ledger_transaction_id IS NULL THEN
    UPDATE public.billing_history
       SET payment_status = 'paid',
           provider_payment_reference = COALESCE(provider_payment_reference, p_provider_payment_id),
           canonical_ledger_transaction_id = v_ledger_id,
           updated_at = now(),
           updated_by = p_actor_id
     WHERE id = p_billing_history_id AND site_id = p_site_id
       AND (payment_status = 'pending' OR canonical_ledger_transaction_id IS NULL);
    IF NOT FOUND THEN RAISE EXCEPTION 'ad credit billing record finalization lost its payable state'; END IF;
  ELSIF v_charge.canonical_ledger_transaction_id IS DISTINCT FROM v_ledger_id THEN
    RAISE EXCEPTION 'ad credit billing record is missing its canonical purchase posting';
  END IF;

  RETURN v_credited || jsonb_build_object(
    'billing_history_id', p_billing_history_id,
    'canonical_ledger_transaction_id', v_ledger_id,
    'payment_status', 'paid'
  );
END;

DECLARE
  v_statement public.payout_statements%ROWTYPE;
  v_settlement_net bigint;
  v_source_count bigint;
  v_source_gross bigint;
  v_order_lines jsonb;
  v_wallet_key text;
  v_wallet public.wallet_ledger_entries%ROWTYPE;
  v_fee_ledger_id uuid;
  v_fee_total bigint;
  v_fee_lines jsonb := '[]'::jsonb;
BEGIN
  IF p_site_id IS NULL
     OR NULLIF(btrim(p_statement_number), '') IS NULL
     OR NULLIF(btrim(p_idempotency_key), '') IS NULL
     OR p_provider IS NULL OR p_provider NOT IN ('razorpay_route', 'cashfree', 'manual')
     OR p_provider_mode IS NULL OR p_provider_mode NOT IN ('sandbox', 'live')
     OR p_rail IS NULL OR p_rail NOT IN ('razorpay_route', 'cashfree_easy_split', 'manual')
     OR p_gross_amount_minor IS NULL
     OR p_platform_fee_minor IS NULL
     OR p_tax_minor IS NULL
     OR p_net_amount_minor IS NULL
     OR p_metadata IS NULL
     OR p_gross_amount_minor <= 0
     OR p_platform_fee_minor < 0
     OR p_tax_minor < 0
     OR p_net_amount_minor < 0
     OR p_gross_amount_minor <> p_platform_fee_minor + p_tax_minor + p_net_amount_minor
     OR p_gross_amount_minor > 2147483647
     OR p_platform_fee_minor > 2147483647
     OR p_tax_minor > 2147483647
     OR p_net_amount_minor > 2147483647
     OR (p_period_start IS NOT NULL AND p_period_end IS NOT NULL AND p_period_end < p_period_start) THEN
    RAISE EXCEPTION 'payout statement payload is invalid' USING ERRCODE = '22023';
  END IF;

  IF COALESCE(p_metadata->'source_order_ids', '[]'::jsonb)
       IS DISTINCT FROM to_jsonb(COALESCE(p_source_order_ids, ARRAY[]::uuid[])) THEN
    RAISE EXCEPTION 'payout source ids differ from their metadata snapshot' USING ERRCODE = '22023';
  END IF;

  IF p_source_settlement_id IS NOT NULL THEN
    IF cardinality(COALESCE(p_source_order_ids, ARRAY[]::uuid[])) <> 0
       OR p_metadata->>'source_type' IS DISTINCT FROM 'settlement'
       OR (p_metadata->>'source_settlement_id')::uuid IS DISTINCT FROM p_source_settlement_id THEN
      RAISE EXCEPTION 'settlement payout source payload is invalid' USING ERRCODE = '22023';
    END IF;

    SELECT net_amount_minor INTO v_settlement_net
      FROM public.settlements
     WHERE id = p_source_settlement_id
       AND site_id = p_site_id
       AND deleted_at IS NULL
       AND status = 'recorded'
     FOR UPDATE;
    IF NOT FOUND OR v_settlement_net IS DISTINCT FROM p_gross_amount_minor THEN
      RAISE EXCEPTION 'settlement payout does not match a recorded tenant settlement' USING ERRCODE = '23505';
    END IF;
  ELSIF p_metadata->>'source_type' = 'settlement' THEN
    RAISE EXCEPTION 'settlement payout source is required' USING ERRCODE = '22023';
  END IF;

  -- Serialize all statement creation for a site. This makes the source-order
  -- uniqueness check safe across different idempotency keys as well as retries.
  PERFORM pg_advisory_xact_lock(hashtextextended('payout-create:' || p_site_id::text, 0));

  SELECT * INTO v_statement
    FROM public.payout_statements
   WHERE site_id = p_site_id
     AND idempotency_key = p_idempotency_key
     AND deleted_at IS NULL
   FOR UPDATE;

  IF FOUND THEN
    IF v_statement.provider IS DISTINCT FROM p_provider
       OR v_statement.provider_mode IS DISTINCT FROM p_provider_mode
       OR v_statement.rail IS DISTINCT FROM p_rail
       OR v_statement.currency IS DISTINCT FROM 'INR'
       OR v_statement.gross_amount_minor_bigint IS DISTINCT FROM p_gross_amount_minor
       OR v_statement.platform_fee_minor_bigint IS DISTINCT FROM p_platform_fee_minor
       OR v_statement.tax_minor_bigint IS DISTINCT FROM p_tax_minor
       OR v_statement.net_amount_minor_bigint IS DISTINCT FROM p_net_amount_minor
       OR v_statement.period_start IS DISTINCT FROM p_period_start
       OR v_statement.period_end IS DISTINCT FROM p_period_end
       OR COALESCE(v_statement.metadata->'source_order_ids', '[]'::jsonb)
            IS DISTINCT FROM COALESCE(p_metadata->'source_order_ids', '[]'::jsonb)
       OR COALESCE(v_statement.metadata->'source_order_numbers', '[]'::jsonb)
            IS DISTINCT FROM COALESCE(p_metadata->'source_order_numbers', '[]'::jsonb)
       OR v_statement.metadata->>'commission_bps' IS DISTINCT FROM p_metadata->>'commission_bps'
       OR v_statement.metadata->>'gst_bps' IS DISTINCT FROM p_metadata->>'gst_bps'
       OR v_statement.metadata->>'source_settlement_id' IS DISTINCT FROM p_metadata->>'source_settlement_id' THEN
      RAISE EXCEPTION 'payout idempotency key conflicts with a different request' USING ERRCODE = '23505';
    END IF;
  ELSE
    IF p_source_settlement_id IS NOT NULL THEN
      NULL; -- The tenant settlement was validated and locked before idempotency lookup.
      IF EXISTS (
        SELECT 1
          FROM public.payout_statements AS prior
         WHERE prior.site_id = p_site_id
           AND prior.deleted_at IS NULL
           AND prior.metadata->>'source_settlement_id' = p_source_settlement_id::text
      ) THEN
        RAISE EXCEPTION 'settlement already has a payout statement' USING ERRCODE = '23505';
      END IF;
    ELSE
      IF cardinality(COALESCE(p_source_order_ids, ARRAY[]::uuid[])) = 0 THEN
        RAISE EXCEPTION 'payout statement requires paid source orders or a recorded settlement' USING ERRCODE = '22023';
      END IF;

      IF cardinality(p_source_order_ids) <> (
        SELECT count(DISTINCT source_id) FROM unnest(p_source_order_ids) AS source_id
      ) THEN
        RAISE EXCEPTION 'payout source order ids must be unique' USING ERRCODE = '22023';
      END IF;

      PERFORM order_row.id
        FROM public.orders AS order_row
       WHERE order_row.id = ANY(p_source_order_ids)
         AND order_row.store_id = p_site_id
         AND order_row.site_id = p_site_id
         AND order_row.payment_status = 'paid'
         AND order_row.currency = 'INR'
         AND (p_period_start IS NULL OR order_row.created_at >= (p_period_start::timestamp AT TIME ZONE 'UTC'))
         AND (p_period_end IS NULL OR order_row.created_at <= (((p_period_end + 1)::timestamp AT TIME ZONE 'UTC') - interval '1 millisecond'))
         AND order_row.deleted_at IS NULL
       ORDER BY order_row.id
       FOR UPDATE;

      GET DIAGNOSTICS v_source_count = ROW_COUNT;
      IF v_source_count <> cardinality(p_source_order_ids) THEN
        RAISE EXCEPTION 'payout source orders are not all paid and owned by this site' USING ERRCODE = '23505';
      END IF;

      SELECT COALESCE(sum(round(order_row.total * 100)::bigint), 0),
             COALESCE(jsonb_agg(order_row.order_number ORDER BY order_row.created_at, order_row.id), '[]'::jsonb)
        INTO v_source_gross, v_order_lines
        FROM public.orders AS order_row
       WHERE order_row.id = ANY(p_source_order_ids)
         AND order_row.store_id = p_site_id
         AND order_row.site_id = p_site_id
         AND order_row.payment_status = 'paid'
         AND order_row.currency = 'INR'
         AND (p_period_start IS NULL OR order_row.created_at >= (p_period_start::timestamp AT TIME ZONE 'UTC'))
         AND (p_period_end IS NULL OR order_row.created_at <= (((p_period_end + 1)::timestamp AT TIME ZONE 'UTC') - interval '1 millisecond'))
         AND order_row.deleted_at IS NULL;

      IF v_source_gross IS DISTINCT FROM p_gross_amount_minor THEN
        RAISE EXCEPTION 'payout gross amount does not equal its paid source orders' USING ERRCODE = '23514';
      END IF;

      IF EXISTS (
        SELECT 1
          FROM public.payout_statements AS prior
          CROSS JOIN LATERAL jsonb_array_elements_text(COALESCE(prior.metadata->'source_order_ids', '[]'::jsonb)) AS source_id(value)
         WHERE prior.site_id = p_site_id
           AND prior.deleted_at IS NULL
           AND source_id.value = ANY(SELECT unnest(p_source_order_ids)::text)
      ) THEN
        RAISE EXCEPTION 'one or more payout source orders are already included in a statement' USING ERRCODE = '23505';
      END IF;

      IF p_metadata->'source_order_numbers' IS DISTINCT FROM v_order_lines THEN
        RAISE EXCEPTION 'payout source metadata does not match its locked orders' USING ERRCODE = '23514';
      END IF;
    END IF;

    INSERT INTO public.payout_statements (
      site_id, statement_number, status, provider, provider_mode, rail, currency,
      gross_amount_minor, platform_fee_minor, tax_minor, net_amount_minor,
      period_start, period_end, available_on, idempotency_key, metadata,
      created_by, updated_by
    ) VALUES (
      p_site_id, p_statement_number, 'pending', p_provider, p_provider_mode, p_rail, 'INR',
      p_gross_amount_minor::integer, p_platform_fee_minor::integer, p_tax_minor::integer, p_net_amount_minor::integer,
      p_period_start, p_period_end, p_available_on, p_idempotency_key, COALESCE(p_metadata, '{}'::jsonb),
      p_actor_id, p_actor_id
    ) RETURNING * INTO v_statement;
  END IF;

  IF p_source_settlement_id IS NOT NULL THEN
    v_wallet_key := 'settlement-payout-credit:' || p_source_settlement_id::text;
  ELSE
    v_wallet_key := 'payout-credit:' || v_statement.id::text;
  END IF;

  INSERT INTO public.wallet_ledger_entries (
    site_id, payout_statement_id, entry_type, direction, status, currency,
    amount_minor, available_on, reference_type, reference_id, description,
    idempotency_key, metadata, created_by, updated_by
  ) VALUES (
    p_site_id, v_statement.id, 'payout_credit', 'credit', 'pending', 'INR',
    p_net_amount_minor::integer, v_statement.available_on,
    CASE WHEN p_source_settlement_id IS NULL THEN 'payout_statement' ELSE 'settlement' END,
    CASE WHEN p_source_settlement_id IS NULL THEN v_statement.id::text ELSE p_source_settlement_id::text END,
    CASE WHEN p_source_settlement_id IS NULL
      THEN 'Payout ' || v_statement.statement_number || ' pending settlement'
      ELSE 'Settlement payout ' || COALESCE(p_metadata->>'source_settlement_reference', p_source_settlement_id::text) || ' pending release'
    END,
    v_wallet_key,
    CASE WHEN p_source_settlement_id IS NULL
      THEN jsonb_build_object('source_order_ids', COALESCE(p_metadata->'source_order_ids', '[]'::jsonb))
      ELSE jsonb_build_object('source_type', 'settlement', 'source_settlement_id', p_source_settlement_id,
        'source_settlement_reference', p_metadata->>'source_settlement_reference')
    END,
    p_actor_id, p_actor_id
  ) ON CONFLICT DO NOTHING;

  SELECT * INTO v_wallet
    FROM public.wallet_ledger_entries
   WHERE site_id = p_site_id
     AND idempotency_key = v_wallet_key
     AND deleted_at IS NULL
   FOR UPDATE;

  IF NOT FOUND
     OR v_wallet.payout_statement_id IS DISTINCT FROM v_statement.id
     OR v_wallet.entry_type IS DISTINCT FROM 'payout_credit'
     OR v_wallet.direction IS DISTINCT FROM 'credit'
     OR v_wallet.status NOT IN ('pending', 'posted')
     OR v_wallet.currency IS DISTINCT FROM 'INR'
     OR v_wallet.amount_minor_bigint IS DISTINCT FROM p_net_amount_minor THEN
    RAISE EXCEPTION 'payout pending wallet credit conflicts with its statement' USING ERRCODE = '23505';
  END IF;

  v_fee_total := p_platform_fee_minor + p_tax_minor;
  IF v_fee_total > 0 THEN
    v_fee_lines := jsonb_build_array(jsonb_build_object(
      'account_code', 'merchant_payable', 'side', 'debit', 'amount_minor', v_fee_total,
      'memo', 'Merchant fee and tax assessment ' || v_statement.statement_number
    ));
    IF p_platform_fee_minor > 0 THEN
      v_fee_lines := v_fee_lines || jsonb_build_array(jsonb_build_object(
        'account_code', 'platform_revenue', 'side', 'credit', 'amount_minor', p_platform_fee_minor,
        'memo', 'Platform fee assessment ' || v_statement.statement_number
      ));
    END IF;
    IF p_tax_minor > 0 THEN
      v_fee_lines := v_fee_lines || jsonb_build_array(jsonb_build_object(
        'account_code', 'gst_payable', 'side', 'credit', 'amount_minor', p_tax_minor,
        'memo', 'Tax on platform fee assessment ' || v_statement.statement_number
      ));
    END IF;

    v_fee_ledger_id := public.post_settlement_ledger_transaction(
      p_site_id, 'settlement', v_statement.id::text,
      'payout-fee-assessment:' || v_statement.id::text,
      v_fee_lines,
      jsonb_build_object('compatibility_table', 'payout_statements',
        'statement_number', v_statement.statement_number, 'ledger_role', 'fee_assessment'),
      NULL
    );

    UPDATE public.payout_statements
       SET canonical_ledger_transaction_id = v_fee_ledger_id,
           updated_by = p_actor_id
     WHERE id = v_statement.id
       AND site_id = p_site_id
       AND canonical_ledger_transaction_id IS DISTINCT FROM v_fee_ledger_id
     RETURNING * INTO v_statement;
  END IF;

  RETURN v_statement.id;
END;

DECLARE
  v_category_id uuid;
  v_store_id uuid;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.marketplace_listing_id IS NOT NULL
       OR NEW.marketplace_approved_fingerprint IS NOT NULL
       OR NEW.marketplace_category_id IS NOT NULL THEN
      RAISE EXCEPTION 'marketplace order identity is bound only by checkout';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.marketplace_category_id IS DISTINCT FROM OLD.marketplace_category_id THEN
    IF OLD.marketplace_listing_id IS NOT NULL
       OR OLD.marketplace_approved_fingerprint IS NOT NULL
       OR OLD.marketplace_category_id IS NOT NULL
       OR NEW.marketplace_listing_id IS NULL
       OR NEW.marketplace_approved_fingerprint IS NULL
       OR current_setting('app.marketplace_order_creation', true) IS DISTINCT FROM 'on' THEN
      RAISE EXCEPTION 'marketplace category snapshot is immutable';
    END IF;
  END IF;

  IF OLD.marketplace_listing_id IS NULL AND NEW.marketplace_listing_id IS NOT NULL THEN
    IF current_setting('app.marketplace_order_creation', true) IS DISTINCT FROM 'on'
       OR OLD.marketplace_approved_fingerprint IS NOT NULL
       OR OLD.marketplace_category_id IS NOT NULL
       OR NEW.marketplace_approved_fingerprint IS NULL THEN
      RAISE EXCEPTION 'marketplace category snapshot is checkout-bound';
    END IF;
    SELECT order_row.store_id INTO v_store_id
      FROM public.orders AS order_row
     WHERE order_row.id = NEW.order_id;
    SELECT listing.marketplace_category_id INTO v_category_id
      FROM public.channel_listings AS listing
     WHERE listing.id = NEW.marketplace_listing_id
       AND listing.site_id = v_store_id
       AND listing.channel = 'marketplace';

    IF NOT FOUND OR v_category_id IS NULL THEN
      RAISE EXCEPTION 'approved marketplace category snapshot is unavailable';
    END IF;
    NEW.marketplace_category_id := v_category_id;
  END IF;

  RETURN NEW;
END;

DECLARE
  v_replay public.cod_reconciliation_entries%ROWTYPE;
  v_result public.cod_reconciliation_entries%ROWTYPE;
  v_request jsonb;
  v_stored_request jsonb;
  v_expected_amount bigint;
BEGIN
  IF p_site_id IS NULL OR p_entry_id IS NULL OR p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' THEN
    RAISE EXCEPTION 'site_id, entry_id, and idempotency_key are required' USING ERRCODE = '22023';
  END IF;

  v_request := jsonb_build_object(
    'entry_id', p_entry_id,
    'deposited_amount_minor', p_deposited_amount_minor,
    'notes', p_notes
  );
  PERFORM pg_advisory_xact_lock(hashtextextended(p_site_id::text || ':' || p_idempotency_key, 0));

  SELECT * INTO v_replay
    FROM public.cod_reconciliation_entries
   WHERE site_id = p_site_id
     AND reconciliation_idempotency_key = p_idempotency_key
     AND deleted_at IS NULL
   LIMIT 1
   FOR UPDATE;

  IF FOUND THEN
    v_stored_request := v_replay.metadata -> 'cod_reconciliation_request';
    IF v_stored_request IS NOT NULL THEN
      IF v_stored_request IS DISTINCT FROM v_request THEN
        RAISE EXCEPTION 'idempotency key is bound to a different COD reconciliation request' USING ERRCODE = '23505';
      END IF;
    ELSE
      -- Existing pre-migration rows have no request snapshot. Accept only when
      -- their durable result proves that this is an equivalent legacy retry.
      v_expected_amount := COALESCE(
        p_deposited_amount_minor,
        COALESCE(NULLIF(v_replay.collected_amount_minor_bigint, 0),
          v_replay.expected_amount_minor_bigint,
          v_replay.expected_amount_minor::bigint,
          0)
      );
      IF v_replay.id IS DISTINCT FROM p_entry_id
         OR v_expected_amount IS DISTINCT FROM COALESCE(v_replay.deposited_amount_minor_bigint, v_replay.deposited_amount_minor::bigint)
         OR (p_notes IS NOT NULL AND p_notes IS DISTINCT FROM v_replay.notes) THEN
        RAISE EXCEPTION 'idempotency key is bound to a different COD reconciliation request' USING ERRCODE = '23505';
      END IF;
      UPDATE public.cod_reconciliation_entries
         SET metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object('cod_reconciliation_request', v_request)
       WHERE id = v_replay.id AND site_id = p_site_id
       RETURNING * INTO v_replay;
    END IF;
    RETURN v_replay;
  END IF;

  v_result := public.reconcile_cod_remittance_with_ledger(
    p_site_id,
    p_entry_id,
    p_deposited_amount_minor,
    p_notes,
    p_idempotency_key,
    p_actor_id,
    p_request_id
  );

  UPDATE public.cod_reconciliation_entries
     SET metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object('cod_reconciliation_request', v_request)
   WHERE id = v_result.id
     AND site_id = p_site_id
     AND reconciliation_idempotency_key = p_idempotency_key
   RETURNING * INTO v_result;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'COD reconciliation request binding could not be stored' USING ERRCODE = '23514';
  END IF;
  RETURN v_result;
END;

DECLARE
  v_order public.orders%ROWTYPE;
  v_entry public.cod_reconciliation_entries%ROWTYPE;
  v_replay public.cod_reconciliation_entries%ROWTYPE;
  v_request jsonb;
  v_stored_request jsonb;
  v_expected_minor bigint;
  v_collected_minor bigint;
BEGIN
  IF p_site_id IS NULL OR p_order_id IS NULL OR p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' THEN
    RAISE EXCEPTION 'site_id, order_id, and idempotency_key are required' USING ERRCODE = '22023';
  END IF;
  IF p_collected_amount_minor IS NOT NULL AND (p_collected_amount_minor < 0 OR p_collected_amount_minor > 2147483647) THEN
    RAISE EXCEPTION 'collected_amount_minor is outside the supported range' USING ERRCODE = '22023';
  END IF;

  v_request := jsonb_build_object(
    'order_id', p_order_id,
    'collected_amount_minor', p_collected_amount_minor,
    'notes', p_notes
  );
  PERFORM pg_advisory_xact_lock(hashtextextended(p_site_id::text || ':' || p_idempotency_key, 0));

  SELECT * INTO v_replay
    FROM public.cod_reconciliation_entries
   WHERE site_id = p_site_id
     AND collection_idempotency_key = p_idempotency_key
     AND deleted_at IS NULL
   LIMIT 1
   FOR UPDATE;
  IF FOUND THEN
    v_stored_request := v_replay.metadata -> 'cod_collection_request';
    IF v_stored_request IS NOT NULL THEN
      IF v_stored_request IS DISTINCT FROM v_request THEN
        RAISE EXCEPTION 'idempotency key is bound to a different COD collection request' USING ERRCODE = '23505';
      END IF;
    ELSE
      v_expected_minor := COALESCE(v_replay.expected_amount_minor_bigint, v_replay.expected_amount_minor::bigint, 0);
      v_collected_minor := COALESCE(p_collected_amount_minor, v_expected_minor);
      IF v_replay.order_id IS DISTINCT FROM p_order_id
         OR v_collected_minor IS DISTINCT FROM COALESCE(v_replay.collected_amount_minor_bigint, v_replay.collected_amount_minor::bigint)
         OR (p_notes IS NOT NULL AND p_notes IS DISTINCT FROM v_replay.notes) THEN
        RAISE EXCEPTION 'idempotency key is bound to a different COD collection request' USING ERRCODE = '23505';
      END IF;
      UPDATE public.cod_reconciliation_entries
         SET metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object('cod_collection_request', v_request)
       WHERE id = v_replay.id AND site_id = p_site_id
       RETURNING * INTO v_replay;
    END IF;
    RETURN v_replay;
  END IF;

  SELECT * INTO v_order
    FROM public.orders AS order_row
   WHERE order_row.id = p_order_id
     AND order_row.store_id = p_site_id
     AND order_row.payment_method = 'cod'
     AND order_row.deleted_at IS NULL
     AND order_row.status NOT IN ('cancelled', 'refunded')
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'COD order not found' USING ERRCODE = 'P0002';
  END IF;

  v_expected_minor := round(COALESCE(v_order.total, 0) * 100)::bigint;
  IF v_expected_minor <= 0 OR v_expected_minor > 2147483647 THEN
    RAISE EXCEPTION 'COD order amount is outside the supported reconciliation range' USING ERRCODE = '22023';
  END IF;
  v_collected_minor := COALESCE(p_collected_amount_minor, v_expected_minor);

  INSERT INTO public.cod_reconciliation_entries (
    site_id, order_id, status, currency, expected_amount_minor,
    collected_amount_minor, deposited_amount_minor, difference_amount_minor,
    metadata, created_by, updated_by
  ) VALUES (
    p_site_id, p_order_id, 'pending', COALESCE(v_order.currency, 'INR'),
    v_expected_minor::integer, 0, 0, 0,
    jsonb_build_object('order_number', v_order.order_number,
      'payment_status', v_order.payment_status, 'source', 'mobile_cod_reconciliation'),
    p_actor_id, p_actor_id
  )
  ON CONFLICT (site_id, order_id) WHERE deleted_at IS NULL DO NOTHING;

  SELECT * INTO v_entry
    FROM public.cod_reconciliation_entries
   WHERE site_id = p_site_id AND order_id = p_order_id AND deleted_at IS NULL
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'COD reconciliation entry could not be created' USING ERRCODE = '23514';
  END IF;
  IF v_entry.status NOT IN ('pending', 'collected') THEN
    RAISE EXCEPTION 'COD reconciliation entry is no longer collectible' USING ERRCODE = '23514';
  END IF;
  IF v_entry.collection_idempotency_key IS NOT NULL THEN
    RAISE EXCEPTION 'COD order already has a different collection request' USING ERRCODE = '23505';
  END IF;
  IF v_collected_minor > 2147483647 THEN
    RAISE EXCEPTION 'collected_amount_minor is outside the supported range' USING ERRCODE = '22023';
  END IF;

  UPDATE public.cod_reconciliation_entries
     SET status = 'collected',
         collected_amount_minor = v_collected_minor::integer,
         collected_amount_minor_bigint = v_collected_minor,
         collected_at = COALESCE(collected_at, now()),
         collection_idempotency_key = p_idempotency_key,
         notes = COALESCE(p_notes, notes),
         metadata = COALESCE(metadata, '{}'::jsonb)
           || jsonb_build_object('collected_by', 'merchant_mobile', 'cod_collection_request', v_request),
         updated_by = p_actor_id,
         updated_at = now()
   WHERE id = v_entry.id AND site_id = p_site_id
   RETURNING * INTO v_entry;

  RETURN v_entry;
END;

DECLARE
  v_settlement public.settlements%ROWTYPE;
  v_statement_id uuid;
  v_statement public.payout_statements%ROWTYPE;
  v_payout public.payouts%ROWTYPE;
  v_payout_item public.payout_items%ROWTYPE;
  v_event public.outbox_events%ROWTYPE;
  v_payout_key text;
  v_statement_key text;
  v_statement_number text;
  v_item_count integer;
  v_matching_item_count integer;
  v_preview jsonb;
  v_event_key text;
  v_event_payload jsonb;
  v_statement_metadata jsonb;
BEGIN
  IF p_site_id IS NULL OR p_settlement_id IS NULL
     OR p_expected_amount_minor IS NULL OR p_expected_amount_minor <= 0
     OR p_expected_amount_minor > 2147483647 OR p_available_on IS NULL THEN
    RAISE EXCEPTION 'settlement payout request is invalid' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_settlement
    FROM public.settlements
   WHERE id = p_settlement_id
     AND site_id = p_site_id
     AND deleted_at IS NULL
   FOR UPDATE;
  IF NOT FOUND
     OR v_settlement.status IS DISTINCT FROM 'recorded'
     OR v_settlement.rail IS DISTINCT FROM 'pa_split'
     OR v_settlement.provider IS DISTINCT FROM 'razorpay_route'
     OR v_settlement.net_amount_minor IS DISTINCT FROM p_expected_amount_minor
     OR v_settlement.ledger_transaction_id IS NULL THEN
    RAISE EXCEPTION 'settlement is not eligible for a Route payout instruction' USING ERRCODE = '23505';
  END IF;

  v_statement_key := 'settlement-payout:' || v_settlement.id::text;
  v_statement_number := 'STL-' || upper(substr(replace(v_settlement.id::text, '-', ''), 1, 12));
  v_statement_metadata := jsonb_build_object(
    'source_type', 'settlement',
    'source_settlement_id', v_settlement.id,
    'source_settlement_reference', v_settlement.settlement_reference,
    'canonical_executor', 'payout_statements',
    'no_custody', true
  );

  v_statement_id := public.create_payout_statement_with_effects(
    p_site_id,
    v_statement_number,
    'razorpay_route',
    v_settlement.provider_mode,
    'razorpay_route',
    p_expected_amount_minor,
    0,
    0,
    p_expected_amount_minor,
    NULL,
    NULL,
    p_available_on,
    v_statement_key,
    ARRAY[]::uuid[],
    v_settlement.id,
    v_statement_metadata,
    p_actor_id
  );

  SELECT * INTO v_statement
    FROM public.payout_statements
   WHERE id = v_statement_id
     AND site_id = p_site_id
     AND deleted_at IS NULL
   FOR UPDATE;
  IF NOT FOUND
     OR v_statement.metadata->>'source_settlement_id' IS DISTINCT FROM v_settlement.id::text
     OR v_statement.provider IS DISTINCT FROM 'razorpay_route'
     OR v_statement.rail IS DISTINCT FROM 'razorpay_route'
     OR v_statement.gross_amount_minor_bigint IS DISTINCT FROM p_expected_amount_minor
     OR v_statement.net_amount_minor_bigint IS DISTINCT FROM p_expected_amount_minor THEN
    RAISE EXCEPTION 'settlement payout statement conflicts with the source settlement' USING ERRCODE = '23505';
  END IF;

  v_payout_key := 'payout:' || v_settlement.idempotency_key;
  INSERT INTO public.payouts (
    site_id, settlement_id, payout_statement_id, status, provider,
    provider_mode, rail, currency, amount_minor, idempotency_key,
    requires_step_up, maker_actor_id, metadata, created_by, updated_by
  ) VALUES (
    p_site_id, v_settlement.id, v_statement.id, 'scheduled',
    'razorpay_route', v_settlement.provider_mode, 'razorpay_route', 'INR',
    p_expected_amount_minor, v_payout_key, true, p_actor_id,
    jsonb_build_object(
      'no_custody', true,
      'instruction_only', true,
      'canonical_executor', 'payout_statements',
      'payout_statement_id', v_statement.id
    ),
    p_actor_id, p_actor_id
  ) ON CONFLICT (site_id, idempotency_key) DO NOTHING;

  SELECT * INTO v_payout
    FROM public.payouts
   WHERE site_id = p_site_id
     AND idempotency_key = v_payout_key
     AND deleted_at IS NULL
   FOR UPDATE;
  IF NOT FOUND
     OR v_payout.settlement_id IS DISTINCT FROM v_settlement.id
     OR v_payout.payout_statement_id IS DISTINCT FROM v_statement.id
     OR v_payout.provider IS DISTINCT FROM 'razorpay_route'
     OR v_payout.provider_mode IS DISTINCT FROM v_settlement.provider_mode
     OR v_payout.rail IS DISTINCT FROM 'razorpay_route'
     OR v_payout.currency IS DISTINCT FROM 'INR'
     OR v_payout.amount_minor IS DISTINCT FROM p_expected_amount_minor
     OR v_payout.requires_step_up IS DISTINCT FROM true
     OR v_payout.metadata->>'instruction_only' IS DISTINCT FROM 'true' THEN
    RAISE EXCEPTION 'payout instruction key conflicts with different settlement terms' USING ERRCODE = '23505';
  END IF;

  v_preview := jsonb_build_object('lines', jsonb_build_array(
    jsonb_build_object(
      'account_code', 'merchant_payable',
      'side', 'debit',
      'amount_minor', p_expected_amount_minor,
      'memo', 'Merchant payable released ' || v_payout.id::text
    ),
    jsonb_build_object(
      'account_code', 'pa_clearing',
      'side', 'credit',
      'amount_minor', p_expected_amount_minor,
      'memo', 'PA split payout released ' || v_payout.id::text
    )
  ));

  SELECT count(*)::integer,
         count(*) FILTER (
           WHERE settlement_id = v_settlement.id
             AND source_type = 'settlement'
             AND source_id = v_settlement.id::text
         )::integer
    INTO v_item_count, v_matching_item_count
    FROM public.payout_items
   WHERE site_id = p_site_id
     AND payout_id = v_payout.id
     AND deleted_at IS NULL;
  IF v_item_count <> v_matching_item_count OR v_matching_item_count > 1 THEN
    RAISE EXCEPTION 'payout contains conflicting settlement items' USING ERRCODE = '23505';
  END IF;

  IF v_matching_item_count = 0 THEN
    INSERT INTO public.payout_items (
      site_id, payout_id, settlement_id, source_type, source_id,
      currency, amount_minor, ledger_transaction_id, ledger_preview,
      metadata, created_by, updated_by
    ) VALUES (
      p_site_id, v_payout.id, v_settlement.id, 'settlement', v_settlement.id::text,
      'INR', p_expected_amount_minor, v_settlement.ledger_transaction_id,
      v_preview, jsonb_build_object('payout_statement_id', v_statement.id),
      p_actor_id, p_actor_id
    ) RETURNING * INTO v_payout_item;
  ELSE
    SELECT * INTO v_payout_item
      FROM public.payout_items
     WHERE site_id = p_site_id
       AND payout_id = v_payout.id
       AND settlement_id = v_settlement.id
       AND source_type = 'settlement'
       AND source_id = v_settlement.id::text
       AND deleted_at IS NULL
     FOR UPDATE;
    IF NOT FOUND
       OR v_payout_item.currency IS DISTINCT FROM 'INR'
       OR v_payout_item.amount_minor IS DISTINCT FROM p_expected_amount_minor
       OR v_payout_item.ledger_transaction_id IS DISTINCT FROM v_settlement.ledger_transaction_id
       OR v_payout_item.ledger_preview IS DISTINCT FROM v_preview
       OR v_payout_item.metadata->>'payout_statement_id' IS DISTINCT FROM v_statement.id::text THEN
      RAISE EXCEPTION 'payout item conflicts with its settlement statement' USING ERRCODE = '23505';
    END IF;
  END IF;

  v_event_key := 'event:payout.scheduled:' || v_payout.id::text;
  v_event_payload := jsonb_build_object(
    'site_id', p_site_id,
    'payout_id', v_payout.id,
    'settlement_id', v_settlement.id,
    'amount', jsonb_build_object('amount_minor', p_expected_amount_minor, 'currency', 'INR'),
    'rail', 'razorpay_route'
  );
  INSERT INTO public.outbox_events (
    store_id, site_id, aggregate_type, aggregate_id, event_type,
    payload, idempotency_key, request_id, actor_id, schema_version
  ) VALUES (
    p_site_id, p_site_id, 'payout', v_payout.id::text, 'payout.scheduled',
    v_event_payload, v_event_key, p_request_id, p_actor_id, 1
  ) ON CONFLICT (idempotency_key) DO NOTHING;

  SELECT * INTO v_event
    FROM public.outbox_events
   WHERE idempotency_key = v_event_key
   FOR UPDATE;
  IF NOT FOUND
     OR v_event.store_id IS DISTINCT FROM p_site_id
     OR v_event.site_id IS DISTINCT FROM p_site_id
     OR v_event.aggregate_type IS DISTINCT FROM 'payout'
     OR v_event.aggregate_id IS DISTINCT FROM v_payout.id::text
     OR v_event.event_type IS DISTINCT FROM 'payout.scheduled'
     OR v_event.payload IS DISTINCT FROM v_event_payload
     OR v_event.schema_version IS DISTINCT FROM 1 THEN
    RAISE EXCEPTION 'payout scheduled event conflicts with its instruction' USING ERRCODE = '23505';
  END IF;

  RETURN to_jsonb(v_payout);
END;

DECLARE
  v_statement public.payout_statements%ROWTYPE;
  v_wallet public.wallet_ledger_entries%ROWTYPE;
  v_ledger_id uuid;
  v_ledger_lines jsonb;
  v_wallet_key text;
  v_wallet_count integer;
  v_instruction_count integer;
  v_instruction public.payouts%ROWTYPE;
  v_instruction_status text;
  v_stored_release_key text;
BEGIN
  IF p_site_id IS NULL OR p_statement_id IS NULL
     OR NULLIF(btrim(p_release_idempotency_key), '') IS NULL
     OR p_result_status NOT IN ('processing', 'released', 'failed')
     OR p_processed_at IS NULL OR p_actor_id IS NULL
     OR p_step_up_metadata IS NULL OR jsonb_typeof(p_step_up_metadata) <> 'object' THEN
    RAISE EXCEPTION 'payout release result is invalid' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_statement
    FROM public.payout_statements
   WHERE id = p_statement_id
     AND site_id = p_site_id
     AND deleted_at IS NULL
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'payout statement not found' USING ERRCODE = 'P0002';
  END IF;

  v_stored_release_key := COALESCE(v_statement.release_idempotency_key, v_statement.metadata->>'release_idempotency_key');
  IF v_stored_release_key IS DISTINCT FROM p_release_idempotency_key THEN
    RAISE EXCEPTION 'payout release result does not match its durable claim' USING ERRCODE = '23505';
  END IF;
  IF v_statement.status NOT IN ('processing', 'released', 'failed') THEN
    RAISE EXCEPTION 'payout statement has no active release claim' USING ERRCODE = '23505';
  END IF;
  IF v_statement.status IN ('released', 'failed') AND v_statement.status IS DISTINCT FROM p_result_status THEN
    RAISE EXCEPTION 'payout release result conflicts with its finalized statement' USING ERRCODE = '23505';
  END IF;
  IF v_statement.status IN ('released', 'failed')
     AND (v_statement.provider_reference IS DISTINCT FROM p_provider_reference
       OR v_statement.utr IS DISTINCT FROM p_utr
       OR v_statement.failure_reason IS DISTINCT FROM p_failure_reason) THEN
    RAISE EXCEPTION 'payout release result differs from its finalized provider response' USING ERRCODE = '23505';
  END IF;

  IF p_result_status = 'released' THEN
    IF v_statement.net_amount_minor <= 0 OR v_statement.currency <> 'INR' THEN
      RAISE EXCEPTION 'payout statement amount is not releasable' USING ERRCODE = '23514';
    END IF;
    v_wallet_key := 'payout-debit:' || v_statement.id::text;
    v_ledger_lines := jsonb_build_array(
      jsonb_build_object(
        'account_code', 'merchant_payable',
        'side', 'debit',
        'amount_minor', v_statement.net_amount_minor,
        'memo', 'Merchant payable released ' || v_statement.statement_number
      ),
      jsonb_build_object(
        'account_code', 'pa_clearing',
        'side', 'credit',
        'amount_minor', v_statement.net_amount_minor,
        'memo', 'PA split payout released ' || v_statement.statement_number
      )
    );
    v_ledger_id := public.post_settlement_ledger_transaction(
      p_site_id,
      'payout',
      v_statement.id::text,
      'payout-release:' || v_statement.id::text,
      v_ledger_lines,
      jsonb_build_object('compatibility_table', 'payout_statements', 'statement_number', v_statement.statement_number),
      NULL
    );

    INSERT INTO public.wallet_ledger_entries (
      site_id, payout_statement_id, entry_type, direction, status, currency,
      amount_minor, reference_type, reference_id, description,
      idempotency_key, canonical_ledger_transaction_id, metadata, created_by, updated_by
    ) VALUES (
      p_site_id, v_statement.id, 'payout_debit', 'debit', 'posted',
      v_statement.currency, v_statement.net_amount_minor,
      'payout_statement', v_statement.id::text,
      'Payout ' || v_statement.statement_number || ' released',
      v_wallet_key, v_ledger_id,
      jsonb_build_object('provider_reference', p_provider_reference, 'utr', p_utr),
      p_actor_id, p_actor_id
    ) ON CONFLICT DO NOTHING;

    SELECT count(*)::integer INTO v_wallet_count
      FROM public.wallet_ledger_entries
     WHERE site_id = p_site_id
       AND idempotency_key = v_wallet_key
       AND deleted_at IS NULL;
    IF v_wallet_count <> 1 THEN
      RAISE EXCEPTION 'payout debit projection is missing or duplicated' USING ERRCODE = '23505';
    END IF;
    SELECT * INTO v_wallet
      FROM public.wallet_ledger_entries
     WHERE site_id = p_site_id
       AND idempotency_key = v_wallet_key
       AND deleted_at IS NULL
     FOR UPDATE;
    IF v_wallet.payout_statement_id IS DISTINCT FROM v_statement.id
       OR v_wallet.entry_type IS DISTINCT FROM 'payout_debit'
       OR v_wallet.direction IS DISTINCT FROM 'debit'
       OR v_wallet.status IS DISTINCT FROM 'posted'
       OR v_wallet.currency IS DISTINCT FROM v_statement.currency
       OR v_wallet.amount_minor IS DISTINCT FROM v_statement.net_amount_minor
       OR v_wallet.canonical_ledger_transaction_id IS DISTINCT FROM v_ledger_id
       OR v_wallet.metadata IS DISTINCT FROM jsonb_build_object('provider_reference', p_provider_reference, 'utr', p_utr) THEN
      RAISE EXCEPTION 'payout debit projection conflicts with its canonical release' USING ERRCODE = '23505';
    END IF;

    UPDATE public.payout_statements
       SET status = 'released',
           released_at = COALESCE(released_at, p_processed_at),
           failed_at = NULL,
           provider_reference = p_provider_reference,
           utr = p_utr,
           failure_reason = NULL,
           release_ledger_transaction_id = v_ledger_id,
           metadata = COALESCE(metadata, '{}'::jsonb) || p_step_up_metadata,
           updated_by = p_actor_id,
           updated_at = p_processed_at
     WHERE id = v_statement.id AND site_id = p_site_id
     RETURNING * INTO v_statement;
    v_instruction_status := 'paid';
  ELSIF p_result_status = 'failed' THEN
    IF v_statement.release_ledger_transaction_id IS NOT NULL
       OR EXISTS (
         SELECT 1 FROM public.ledger_transactions AS ledger
          WHERE ledger.site_id = p_site_id
            AND ledger.source_type = 'payout'
            AND ledger.source_id = v_statement.id::text
       )
       OR EXISTS (
         SELECT 1 FROM public.wallet_ledger_entries AS wallet
          WHERE wallet.site_id = p_site_id
            AND wallet.idempotency_key = 'payout-debit:' || v_statement.id::text
            AND wallet.deleted_at IS NULL
       ) THEN
      RAISE EXCEPTION 'failed provider result conflicts with an existing payout release posting' USING ERRCODE = '23505';
    END IF;
    UPDATE public.payout_statements
       SET status = 'failed',
           failed_at = COALESCE(failed_at, p_processed_at),
           released_at = NULL,
           provider_reference = p_provider_reference,
           utr = p_utr,
           failure_reason = p_failure_reason,
           metadata = COALESCE(metadata, '{}'::jsonb) || p_step_up_metadata,
           updated_by = p_actor_id,
           updated_at = p_processed_at
     WHERE id = v_statement.id AND site_id = p_site_id
     RETURNING * INTO v_statement;
    v_instruction_status := 'failed';
  ELSE
    UPDATE public.payout_statements
       SET status = 'processing',
           provider_reference = COALESCE(p_provider_reference, provider_reference),
           utr = COALESCE(p_utr, utr),
           failure_reason = NULL,
           metadata = COALESCE(metadata, '{}'::jsonb) || p_step_up_metadata,
           updated_by = p_actor_id,
           updated_at = p_processed_at
     WHERE id = v_statement.id AND site_id = p_site_id
     RETURNING * INTO v_statement;
    v_instruction_status := 'processing';
  END IF;

  SELECT count(*)::integer INTO v_instruction_count
    FROM public.payouts
   WHERE site_id = p_site_id
     AND payout_statement_id = v_statement.id
     AND deleted_at IS NULL;
  IF v_instruction_count > 1
     OR (v_statement.metadata->>'source_settlement_id' IS NOT NULL AND v_instruction_count <> 1) THEN
    RAISE EXCEPTION 'settlement payout instruction is missing or duplicated' USING ERRCODE = '23505';
  END IF;

  IF v_instruction_count = 1 THEN
    UPDATE public.payouts
       SET status = v_instruction_status,
           provider_reference = p_provider_reference,
           utr = p_utr,
           failure_reason = p_failure_reason,
           ledger_transaction_id = CASE WHEN p_result_status = 'released' THEN v_ledger_id ELSE ledger_transaction_id END,
           checker_actor_id = p_actor_id,
           checked_at = p_processed_at,
           updated_by = p_actor_id,
           updated_at = p_processed_at
     WHERE site_id = p_site_id
       AND payout_statement_id = v_statement.id
       AND deleted_at IS NULL
     RETURNING * INTO v_instruction;
    IF NOT FOUND
       OR v_instruction.settlement_id::text IS DISTINCT FROM v_statement.metadata->>'source_settlement_id'
       OR v_instruction.amount_minor IS DISTINCT FROM v_statement.net_amount_minor THEN
      RAISE EXCEPTION 'settlement payout instruction differs from its statement' USING ERRCODE = '23505';
    END IF;
  END IF;

  RETURN v_statement;
END;

BEGIN
  IF jsonb_typeof(COALESCE(NEW.metadata->'source_order_ids', '[]'::jsonb)) = 'array'
     AND jsonb_array_length(COALESCE(NEW.metadata->'source_order_ids', '[]'::jsonb)) > 0 THEN
    PERFORM public.record_payout_statement_source_ledger_lineage(
      NEW.id, NEW.site_id, NEW.metadata->'source_order_ids', NEW.created_at
    );
  END IF;
  RETURN NEW;
END;

DECLARE
    v_claimed boolean := false;
    v_rows integer;
    v_now timestamptz := clock_timestamp();
BEGIN
    IF p_auth_kind IS NULL OR p_auth_kind !~ '^(identity|session|app:[A-Za-z0-9_-]{1,64})$'
       OR p_jti IS NULL OR p_jti !~ '^[A-Za-z0-9._~-]{16,128}$'
       OR p_ttl_seconds IS NULL OR p_ttl_seconds < 1 OR p_ttl_seconds > 600 THEN
        RAISE EXCEPTION 'invalid internal auth replay claim' USING ERRCODE = '22023';
    END IF;

    -- The unique key arbitrates simultaneous claims across every PostgREST and
    -- worker instance. An expired key may be atomically renewed by one caller.
    INSERT INTO public.internal_auth_replay_claims AS current_claim (auth_kind, jti, claimed_at, expires_at)
    VALUES (p_auth_kind, p_jti, v_now, v_now + make_interval(secs => p_ttl_seconds))
    ON CONFLICT (auth_kind, jti) DO UPDATE
       SET claimed_at = EXCLUDED.claimed_at,
           expires_at = EXCLUDED.expires_at
     WHERE current_claim.expires_at <= v_now;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    v_claimed := v_rows = 1;

    -- Bound cleanup work on each request while eventually removing expired JTIs.
    DELETE FROM public.internal_auth_replay_claims AS stale
     WHERE (stale.auth_kind, stale.jti) IN (
        SELECT expired.auth_kind, expired.jti
          FROM public.internal_auth_replay_claims AS expired
         WHERE expired.expires_at <= v_now
         ORDER BY expired.expires_at
         LIMIT 100
     );

    RETURN v_claimed;
END;

DECLARE v_user public.users_custom%ROWTYPE; v_count integer; v_super boolean;
BEGIN
  SELECT count(*) INTO v_count FROM public.users_custom WHERE lower(email)=lower(p_email) AND email_verified=true;
  IF v_count<>1 THEN RETURN jsonb_build_object('accepted',false,'code','CONSOLE_IDENTITY_REQUIRED'); END IF;
  SELECT * INTO v_user FROM public.users_custom WHERE lower(email)=lower(p_email) AND email_verified=true;
  IF p_actor_id IS NOT NULL AND p_actor_id<>v_user.id THEN
    RETURN jsonb_build_object('accepted',false,'code','CONSOLE_IDENTITY_MISMATCH');
  END IF;
  SELECT EXISTS(SELECT 1 FROM public.super_admin_allowlist a WHERE a.is_active=true
    AND lower(a.email)=lower(v_user.email) AND (a.user_id=v_user.id OR a.user_id IS NULL)) INTO v_super;
  IF NOT v_super AND NOT EXISTS(SELECT 1 FROM public.employees e WHERE e.user_id=v_user.id
    AND e.store_id IS NULL AND e.status='active' AND e.is_active=true AND e.deleted_at IS NULL) THEN
    RETURN jsonb_build_object('accepted',false,'code','CONSOLE_ACCESS_REVOKED');
  END IF;
  RETURN jsonb_build_object('accepted',true,'actor_id',v_user.id,'email',lower(v_user.email),'is_super_admin',v_super);
END

DECLARE v_session public.sessions_v2%ROWTYPE; v_principal public.principals%ROWTYPE; v_identity jsonb;
BEGIN
  SELECT * INTO v_session FROM public.sessions_v2 WHERE id=p_session_id FOR UPDATE;
  IF NOT FOUND OR v_session.realm<>'admin' OR v_session.site_id IS NOT NULL OR v_session.deleted_at IS NOT NULL
    OR v_session.metadata->>'protocol' IS DISTINCT FROM 'platform-console-v1'
    OR v_session.metadata->>'cookie_sha256' IS DISTINCT FROM p_cookie_sha256
    OR p_cookie_sha256 IS NULL OR p_cookie_sha256 !~ '^[0-9a-f]{64}$'
    OR v_session.sid IS DISTINCT FROM p_session_id::text OR v_session.status<>'active'
    OR v_session.revoked_at IS NOT NULL THEN
    RETURN jsonb_build_object('accepted',false,'code','CONSOLE_SESSION_INVALID');
  END IF;
  SELECT * INTO v_principal FROM public.principals WHERE id=v_session.principal_id;
  IF v_session.absolute_expires_at<=clock_timestamp()
    OR (v_session.idle_expires_at IS NOT NULL AND v_session.idle_expires_at<=clock_timestamp()) THEN
    UPDATE public.sessions_v2 SET status='expired',revoke_reason='expired' WHERE id=v_session.id;
    RETURN jsonb_build_object('accepted',false,'code','CONSOLE_SESSION_EXPIRED');
  END IF;
  IF v_principal.realm<>'admin' OR v_principal.status<>'active' OR v_principal.deleted_at IS NOT NULL
    OR v_principal.legacy_user_id IS NULL THEN
    UPDATE public.sessions_v2 SET status='revoked',revoked_at=clock_timestamp(),revoke_reason='principal_revoked' WHERE id=v_session.id;
    RETURN jsonb_build_object('accepted',false,'code','CONSOLE_ACCESS_REVOKED');
  END IF;
  v_identity:=public.resolve_console_operator_v1(v_principal.email,v_principal.legacy_user_id);
  IF NOT coalesce((v_identity->>'accepted')::boolean,false) THEN
    UPDATE public.sessions_v2 SET status='revoked',revoked_at=clock_timestamp(),revoke_reason='membership_revoked' WHERE id=v_session.id;
    RETURN v_identity;
  END IF;
  RETURN v_identity || jsonb_build_object('session_id',v_session.id,
    'mfa_verified',v_session.metadata->>'mfa_verified_at' IS NOT NULL,
    'mfa_verified_at',v_session.metadata->'mfa_verified_at',
    'expires_at',v_session.absolute_expires_at);
END

DECLARE v_identity jsonb; v_state jsonb; v_principal public.principals%ROWTYPE; v_count integer;
  v_existing public.sessions_v2%ROWTYPE; v_actor uuid;
BEGIN
  IF p_operation NOT IN ('register','validate','revoke') OR p_operation IS NULL THEN
    RETURN jsonb_build_object('accepted',false,'code','CONSOLE_SESSION_OPERATION_INVALID');
  END IF;
  IF p_operation<>'register' THEN
    v_state:=public.console_session_state_v1(p_session_id,p_cookie_sha256);
    IF NOT coalesce((v_state->>'accepted')::boolean,false) THEN RETURN v_state; END IF;
    IF p_operation='revoke' THEN
      UPDATE public.sessions_v2 SET status='revoked',revoked_at=clock_timestamp(),revoke_reason='logout' WHERE id=p_session_id;
      INSERT INTO public.audit_logs(actor_id,actor_type,actor_email,action,resource_type,resource_id,metadata)
        VALUES((v_state->>'actor_id')::uuid,CASE WHEN (v_state->>'is_super_admin')::boolean THEN 'super_admin' ELSE 'employee' END,v_state->>'email','platform_console_session.revoked',
          'platform_console_session',p_session_id,'{"reason":"logout"}'::jsonb);
    END IF;
    RETURN v_state;
  END IF;
  IF p_session_id IS NULL OR p_cookie_sha256 IS NULL OR p_cookie_sha256 !~ '^[0-9a-f]{64}$'
    OR p_issued_at IS NULL OR p_expires_at IS NULL OR p_expires_at<=p_issued_at
    OR p_expires_at>p_issued_at+interval '8 hours' OR p_issued_at>clock_timestamp()+interval '30 seconds'
    OR p_expires_at<=clock_timestamp() OR (p_mfa_verified_at IS NOT NULL
      AND (p_mfa_verified_at<p_issued_at OR p_mfa_verified_at>=p_expires_at OR p_mfa_verified_at>clock_timestamp()+interval '30 seconds')) THEN
    RETURN jsonb_build_object('accepted',false,'code','CONSOLE_SESSION_INVALID');
  END IF;
  v_identity:=public.resolve_console_operator_v1(p_email,p_actor_id);
  IF NOT coalesce((v_identity->>'accepted')::boolean,false) THEN RETURN v_identity; END IF;
  v_actor:=(v_identity->>'actor_id')::uuid;
  -- A single ordering covers concurrent first login, MFA rotation and registration retry.
  PERFORM pg_advisory_xact_lock(hashtextextended('letbuyy:console-actor:'||v_actor::text,0));
  SELECT * INTO v_existing FROM public.sessions_v2 WHERE id=p_session_id FOR UPDATE;
  IF FOUND THEN RETURN public.console_session_state_v1(p_session_id,p_cookie_sha256); END IF;
  -- Canonical principal deletion may cascade its sessions. An immutable audit
  -- receipt still prevents re-registering a previously issued cookie identity.
  IF EXISTS(SELECT 1 FROM public.audit_logs WHERE resource_id=p_session_id
    AND action='platform_console_session.registered' AND resource_type='platform_console_session') THEN
    RETURN jsonb_build_object('accepted',false,'code','CONSOLE_SESSION_INVALID');
  END IF;
  IF p_issued_at<clock_timestamp()-interval '60 seconds' THEN
    RETURN jsonb_build_object('accepted',false,'code','CONSOLE_SESSION_REGISTRATION_EXPIRED');
  END IF;
  IF p_mfa_verified_at IS NOT NULL THEN
    v_state:=public.console_session_state_v1(p_previous_session_id,p_previous_cookie_sha256);
    IF NOT coalesce((v_state->>'accepted')::boolean,false) OR v_state->>'actor_id'<>v_actor::text
      OR p_previous_session_id=p_session_id THEN
      RETURN jsonb_build_object('accepted',false,'code','CONSOLE_PREVIOUS_SESSION_REQUIRED');
    END IF;
  ELSIF p_previous_session_id IS NOT NULL OR p_previous_cookie_sha256 IS NOT NULL THEN
    RETURN jsonb_build_object('accepted',false,'code','CONSOLE_SESSION_INVALID');
  END IF;
  SELECT count(*) INTO v_count FROM public.principals WHERE realm='admin' AND legacy_user_id=v_actor AND deleted_at IS NULL;
  IF v_count>1 THEN RETURN jsonb_build_object('accepted',false,'code','CONSOLE_PRINCIPAL_AMBIGUOUS'); END IF;
  IF v_count=0 THEN
    INSERT INTO public.principals(realm,actor_type,legacy_user_id,email,status,metadata)
      VALUES('admin','platform-operator',v_actor,v_identity->>'email','active','{"source":"platform-console-v1"}'::jsonb)
      RETURNING * INTO v_principal;
    INSERT INTO public.account_links(principal_id,realm,provider,provider_subject)
      VALUES(v_principal.id,'admin','users_custom',v_actor::text);
  ELSE
    SELECT * INTO v_principal FROM public.principals WHERE realm='admin' AND legacy_user_id=v_actor AND deleted_at IS NULL FOR UPDATE;
    IF v_principal.status<>'active' OR lower(v_principal.email) IS DISTINCT FROM v_identity->>'email' THEN
      RETURN jsonb_build_object('accepted',false,'code','CONSOLE_ACCESS_REVOKED');
    END IF;
  END IF;
  INSERT INTO public.sessions_v2(id,principal_id,realm,sid,status,issued_at,absolute_expires_at,metadata)
    VALUES(p_session_id,v_principal.id,'admin',p_session_id::text,'active',p_issued_at,p_expires_at,
      jsonb_build_object('protocol','platform-console-v1','cookie_sha256',p_cookie_sha256,'mfa_verified_at',p_mfa_verified_at));
  IF p_previous_session_id IS NOT NULL THEN
    UPDATE public.sessions_v2 SET status='revoked',revoked_at=clock_timestamp(),revoke_reason='mfa_rotation' WHERE id=p_previous_session_id;
  END IF;
  INSERT INTO public.audit_logs(actor_id,actor_type,actor_email,action,resource_type,resource_id,metadata)
    VALUES(v_actor,CASE WHEN (v_identity->>'is_super_admin')::boolean THEN 'super_admin' ELSE 'employee' END,
      v_identity->>'email','platform_console_session.registered','platform_console_session',p_session_id,
      jsonb_build_object('mfa_verified',p_mfa_verified_at IS NOT NULL,'previous_session_id',p_previous_session_id));
  RETURN public.console_session_state_v1(p_session_id,p_cookie_sha256);
END

BEGIN
  IF TG_TABLE_NAME='employees' THEN
    IF OLD.store_id IS NOT NULL THEN RETURN OLD; END IF;
  END IF;
  UPDATE public.sessions_v2 s SET status='revoked',revoked_at=clock_timestamp(),revoke_reason='membership_changed'
    FROM public.principals p WHERE p.id=s.principal_id AND p.realm='admin' AND s.realm='admin' AND s.site_id IS NULL
      AND s.status='active' AND s.metadata->>'protocol'='platform-console-v1'
      AND ((OLD.user_id IS NOT NULL AND p.legacy_user_id=OLD.user_id) OR lower(p.email)=lower(OLD.email));
  RETURN OLD;
END

DECLARE v_state jsonb; v_employee public.employees%ROWTYPE; v_count integer; v_input jsonb;
BEGIN
  v_state:=public.console_session_state_v1(p_session_id,p_cookie_sha256);
  IF NOT coalesce((v_state->>'accepted')::boolean,false) THEN RETURN v_state; END IF;
  -- Match the existing sensitive-action step-up window (security-controls.ts).
  IF NOT coalesce((v_state->>'mfa_verified')::boolean,false) OR (p_step_up AND
    (v_state->>'mfa_verified_at')::timestamptz<clock_timestamp()-interval '10 minutes') THEN
    RETURN jsonb_build_object('accepted',false,'code','STEP_UP_REQUIRED');
  END IF;
  SELECT count(*) INTO v_count FROM public.employees e WHERE e.user_id=(v_state->>'actor_id')::uuid
    AND e.store_id IS NULL AND e.status='active' AND e.is_active=true AND e.deleted_at IS NULL;
  IF v_count>1 THEN RETURN jsonb_build_object('accepted',false,'code','CONSOLE_MEMBERSHIP_AMBIGUOUS'); END IF;
  SELECT * INTO v_employee FROM public.employees e WHERE e.user_id=(v_state->>'actor_id')::uuid
    AND e.store_id IS NULL AND e.status='active' AND e.is_active=true AND e.deleted_at IS NULL;
  v_input:=jsonb_build_object('role',v_employee.role,'inlinePermissions',v_employee.permissions,
    'employeeId',v_employee.id,'isSuperAdmin',(v_state->>'is_super_admin')::boolean,
    'rolePermissionRows',coalesce((SELECT jsonb_agg(jsonb_build_object('permission',p.permission) ORDER BY p.id)
      FROM public.employee_permissions p WHERE p.role=v_employee.role),'[]'::jsonb),
    'employeeRolePermissions',coalesce((SELECT r.permissions FROM public.employee_roles r WHERE r.id=v_employee.role_id),'[]'::jsonb),
    'breakGlassGrants',coalesce((SELECT jsonb_agg(jsonb_build_object('id',g.id,'scope',g.scope,'expires_at',g.expires_at,
      'revoked_at',g.revoked_at,'deleted_at',g.deleted_at) ORDER BY g.id) FROM public.break_glass_grants g
      WHERE g.employee_id=v_employee.id AND g.expires_at>clock_timestamp() AND g.revoked_at IS NULL AND g.deleted_at IS NULL),'[]'::jsonb));
  RETURN jsonb_build_object('accepted',true,'session',v_state,'input',v_input,
    'evidence_hash',encode(sha256(convert_to(v_input::text,'UTF8')),'hex'));
END

BEGIN
  IF TG_OP='DELETE' THEN
    IF OLD.protocol_version=1 THEN RAISE EXCEPTION 'session-bound approvals are retained records'; END IF;
    RETURN OLD;
  END IF;
  IF TG_OP='UPDATE' AND OLD.protocol_version IS NULL AND NEW.protocol_version=1 THEN
    RAISE EXCEPTION 'legacy approvals require a new session-bound request';
  END IF;
  IF TG_OP='UPDATE' AND OLD.protocol_version=1 THEN
    IF ROW(NEW.id,NEW.protocol_version,NEW.site_id,NEW.action,NEW.resource_type,NEW.resource_id,NEW.maker_actor_id,
      NEW.requester_session_id,NEW.request_key,NEW.payload,NEW.payload_hash,NEW.reason,NEW.created_at,NEW.deleted_at,NEW.deleted_by)
      IS DISTINCT FROM ROW(OLD.id,OLD.protocol_version,OLD.site_id,OLD.action,OLD.resource_type,OLD.resource_id,OLD.maker_actor_id,
      OLD.requester_session_id,OLD.request_key,OLD.payload,OLD.payload_hash,OLD.reason,OLD.created_at,OLD.deleted_at,OLD.deleted_by) THEN
      RAISE EXCEPTION 'session-bound approval intent is immutable';
    END IF;
    IF NEW.expires_at IS DISTINCT FROM OLD.expires_at AND NOT (OLD.status='pending' AND NEW.status='approved'
      AND NEW.expires_at<=OLD.expires_at AND NEW.expires_at>clock_timestamp()) THEN
      RAISE EXCEPTION 'approval expiry can only shorten on independent consent';
    END IF;
    IF OLD.consumed_at IS NOT NULL AND (to_jsonb(NEW)-'updated_at') IS DISTINCT FROM (to_jsonb(OLD)-'updated_at') THEN
      RAISE EXCEPTION 'consumed approval receipt is immutable';
    END IF;
    IF OLD.status<>'pending' AND ROW(NEW.status,NEW.checker_actor_id,NEW.approver_session_id,NEW.approved_at)
      IS DISTINCT FROM ROW(OLD.status,OLD.checker_actor_id,OLD.approver_session_id,OLD.approved_at) THEN
      RAISE EXCEPTION 'approval decision is immutable';
    END IF;
  END IF;
  IF NEW.protocol_version=1 THEN
    IF TG_OP='INSERT' AND (NEW.status<>'pending' OR NEW.checker_actor_id IS NOT NULL OR NEW.approver_session_id IS NOT NULL
      OR NEW.approved_at IS NOT NULL OR NEW.consumed_at IS NOT NULL OR NEW.result IS NOT NULL) THEN
      RAISE EXCEPTION 'session-bound approvals must begin pending';
    END IF;
    IF NEW.payload_hash IS DISTINCT FROM public.console_approval_payload_hash_v1(NEW.action,NEW.site_id,NEW.resource_type,NEW.resource_id,NEW.payload) THEN
      RAISE EXCEPTION 'approval payload fingerprint mismatch';
    END IF;
  END IF;
  RETURN NEW;
END

DECLARE v_permission jsonb; v_state jsonb; v_approval public.sensitive_action_approvals%ROWTYPE;
  v_site public.sites%ROWTYPE; v_payload jsonb; v_hash text;
BEGIN
  v_permission:=public.console_permission_snapshot_v1(p_session_id,p_cookie_sha256,true);
  IF NOT coalesce((v_permission->>'accepted')::boolean,false) THEN RETURN v_permission; END IF;
  IF v_permission->>'evidence_hash' IS DISTINCT FROM p_permission_hash THEN
    RETURN jsonb_build_object('accepted',false,'code','PERMISSION_CHANGED');
  END IF;
  v_state:=v_permission->'session';
  IF p_action NOT IN ('merchant.suspend','merchant.restore') OR p_action IS NULL OR p_resource_id IS NULL
    OR p_request_key IS NULL OR p_reason IS NULL OR length(btrim(p_reason))<8 OR length(btrim(p_reason))>1000 THEN
    RETURN jsonb_build_object('accepted',false,'code','APPROVAL_INTENT_INVALID');
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('letbuyy:approval-request:'||(v_state->>'actor_id')||':'||p_request_key::text,0));
  SELECT * INTO v_approval FROM public.sensitive_action_approvals a WHERE a.protocol_version=1
    AND a.maker_actor_id=(v_state->>'actor_id')::uuid AND a.action=p_action AND a.resource_type='site'
    AND a.resource_id=p_resource_id::text AND a.request_key=p_request_key;
  IF FOUND THEN
    IF v_approval.requester_session_id<>p_session_id OR v_approval.reason<>btrim(p_reason) THEN
      RETURN jsonb_build_object('accepted',false,'code','IDEMPOTENCY_CONFLICT');
    END IF;
    RETURN jsonb_build_object('accepted',true,'approval',public.console_approval_view_v1(v_approval.id),'replayed',true);
  END IF;
  SELECT * INTO v_site FROM public.sites WHERE id=p_resource_id AND deleted_at IS NULL FOR SHARE;
  IF NOT FOUND THEN RETURN jsonb_build_object('accepted',false,'code','APPROVAL_TARGET_NOT_FOUND'); END IF;
  IF v_site.status IS DISTINCT FROM (CASE WHEN p_action='merchant.suspend' THEN 'published' ELSE 'suspended' END) THEN
    RETURN jsonb_build_object('accepted',false,'code','APPROVAL_TARGET_STATE_CHANGED');
  END IF;
  v_payload:=jsonb_build_object('action',CASE WHEN p_action='merchant.suspend' THEN 'suspend' ELSE 'restore' END,
    'reason',btrim(p_reason),'expected_status',v_site.status,'expected_updated_at',v_site.updated_at);
  v_hash:=public.console_approval_payload_hash_v1(p_action,v_site.id,'site',v_site.id::text,v_payload);
  INSERT INTO public.sensitive_action_approvals(site_id,action,resource_type,resource_id,maker_actor_id,status,reason,
    protocol_version,requester_session_id,request_key,payload,payload_hash,expires_at,created_by)
    VALUES(v_site.id,p_action,'site',v_site.id::text,(v_state->>'actor_id')::uuid,'pending',btrim(p_reason),
      1,p_session_id,p_request_key,v_payload,v_hash,least(clock_timestamp()+interval '10 minutes',(v_state->>'expires_at')::timestamptz,
        (v_state->>'mfa_verified_at')::timestamptz+interval '10 minutes'),
      (v_state->>'actor_id')::uuid) RETURNING * INTO v_approval;
  INSERT INTO public.audit_logs(actor_id,actor_type,actor_email,action,resource_type,resource_id,metadata)
    VALUES(v_approval.maker_actor_id,'employee',v_state->>'email','sensitive_action.requested','sensitive_action_approval',v_approval.id,
      jsonb_build_object('action',p_action,'site_id',v_site.id,'payload_hash',v_hash,'requester_session_id',p_session_id));
  UPDATE public.break_glass_grants SET used_at=coalesce(used_at,clock_timestamp())
    WHERE id IN (SELECT (g->>'id')::uuid FROM jsonb_array_elements(v_permission->'input'->'breakGlassGrants') g);
  RETURN jsonb_build_object('accepted',true,'approval',public.console_approval_view_v1(v_approval.id),'replayed',false);
END

DECLARE v_approval public.sensitive_action_approvals%ROWTYPE; v_permission jsonb; v_state jsonb; v_maker jsonb; v_status text;
BEGIN
  SELECT * INTO v_approval FROM public.sensitive_action_approvals WHERE id=p_id AND protocol_version=1 FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('accepted',false,'code','APPROVAL_NOT_FOUND'); END IF;
  PERFORM id FROM public.sessions_v2 WHERE id=ANY(ARRAY[p_session_id,v_approval.requester_session_id]) ORDER BY id FOR UPDATE;
  v_permission:=public.console_permission_snapshot_v1(p_session_id,p_cookie_sha256,true);
  IF NOT coalesce((v_permission->>'accepted')::boolean,false) THEN RETURN v_permission; END IF;
  v_state:=v_permission->'session';
  IF p_decision NOT IN ('approve','reject','cancel') OR p_decision IS NULL THEN
    RETURN jsonb_build_object('accepted',false,'code','APPROVAL_INTENT_INVALID');
  END IF;
  IF (p_decision='cancel' AND ((v_state->>'actor_id')::uuid<>v_approval.maker_actor_id OR p_session_id<>v_approval.requester_session_id))
    OR (p_decision<>'cancel' AND ((v_state->>'actor_id')::uuid=v_approval.maker_actor_id
      OR NOT coalesce((v_state->>'is_super_admin')::boolean,false))) THEN
    RETURN jsonb_build_object('accepted',false,'code','INDEPENDENT_SUPER_ADMIN_REQUIRED');
  END IF;
  IF p_decision<>'cancel' AND v_approval.action='operator.mfa.reset'
    AND v_approval.resource_id=v_state->>'actor_id' THEN RETURN jsonb_build_object('accepted',false,'code','INDEPENDENT_SUPER_ADMIN_REQUIRED');END IF;
  IF p_payload_hash IS DISTINCT FROM v_approval.payload_hash OR v_approval.payload_hash IS DISTINCT FROM
    public.console_approval_payload_hash_v1(v_approval.action,v_approval.site_id,v_approval.resource_type,v_approval.resource_id,v_approval.payload) THEN
    RETURN jsonb_build_object('accepted',false,'code','APPROVAL_PAYLOAD_MISMATCH');
  END IF;
  v_maker:=public.console_session_state_v1(v_approval.requester_session_id,
    (SELECT metadata->>'cookie_sha256' FROM public.sessions_v2 WHERE id=v_approval.requester_session_id));
  IF NOT coalesce((v_maker->>'accepted')::boolean,false) OR v_approval.expires_at<=clock_timestamp() THEN
    RETURN jsonb_build_object('accepted',false,'code','APPROVAL_EXPIRED_OR_REVOKED');
  END IF;
  v_status:=CASE p_decision WHEN 'approve' THEN 'approved' WHEN 'reject' THEN 'rejected' ELSE 'cancelled' END;
  IF v_approval.status<>'pending' THEN
    IF v_approval.status=v_status AND ((p_decision='cancel' AND v_approval.maker_actor_id=(v_state->>'actor_id')::uuid)
      OR (v_approval.checker_actor_id=(v_state->>'actor_id')::uuid AND v_approval.approver_session_id=p_session_id)) THEN
      RETURN jsonb_build_object('accepted',true,'approval',public.console_approval_view_v1(p_id),'replayed',true);
    END IF;
    RETURN jsonb_build_object('accepted',false,'code','APPROVAL_ALREADY_DECIDED');
  END IF;
  UPDATE public.sensitive_action_approvals SET status=v_status,
    expires_at=CASE WHEN p_decision='approve' THEN least(v_approval.expires_at,(v_state->>'expires_at')::timestamptz,
      (v_state->>'mfa_verified_at')::timestamptz+interval '10 minutes') ELSE v_approval.expires_at END,
    checker_actor_id=CASE WHEN p_decision='cancel' THEN NULL ELSE (v_state->>'actor_id')::uuid END,
    approver_session_id=CASE WHEN p_decision='cancel' THEN NULL ELSE p_session_id END,
    approved_at=CASE WHEN p_decision='approve' THEN clock_timestamp() ELSE NULL END,updated_by=(v_state->>'actor_id')::uuid WHERE id=p_id;
  INSERT INTO public.audit_logs(actor_id,actor_type,actor_email,action,resource_type,resource_id,metadata)
    VALUES((v_state->>'actor_id')::uuid,CASE WHEN (v_state->>'is_super_admin')::boolean THEN 'super_admin' ELSE 'employee' END,
      v_state->>'email','sensitive_action.'||v_status,'sensitive_action_approval',p_id,
      jsonb_build_object('action',v_approval.action,'payload_hash',v_approval.payload_hash,'approver_session_id',p_session_id));
  RETURN jsonb_build_object('accepted',true,'approval',public.console_approval_view_v1(p_id),'replayed',false);
END

DECLARE v_approval public.sensitive_action_approvals%ROWTYPE; v_permission jsonb; v_state jsonb; v_checker jsonb;
  v_site public.sites%ROWTYPE; v_next text; v_result jsonb;
BEGIN
  SELECT * INTO v_approval FROM public.sensitive_action_approvals WHERE id=p_id AND protocol_version=1 FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('accepted',false,'code','APPROVAL_NOT_FOUND'); END IF;
  PERFORM id FROM public.sessions_v2 WHERE id=ANY(ARRAY[p_session_id,v_approval.approver_session_id]) ORDER BY id FOR UPDATE;
  v_permission:=public.console_permission_snapshot_v1(p_session_id,p_cookie_sha256,true);
  IF NOT coalesce((v_permission->>'accepted')::boolean,false) THEN RETURN v_permission; END IF;
  IF v_permission->>'evidence_hash' IS DISTINCT FROM p_permission_hash THEN
    RETURN jsonb_build_object('accepted',false,'code','PERMISSION_CHANGED');
  END IF;
  v_state:=v_permission->'session';
  IF v_approval.maker_actor_id<>(v_state->>'actor_id')::uuid OR v_approval.requester_session_id<>p_session_id THEN
    RETURN jsonb_build_object('accepted',false,'code','APPROVAL_REQUESTER_MISMATCH');
  END IF;
  IF v_approval.site_id IS DISTINCT FROM p_site_id OR v_approval.resource_type<>'site' OR v_approval.resource_id<>p_site_id::text
    OR p_action NOT IN ('suspend','restore') OR p_action IS NULL OR v_approval.action<>'merchant.'||p_action
    OR v_approval.payload->>'action' IS DISTINCT FROM p_action OR v_approval.reason IS DISTINCT FROM btrim(p_reason)
    OR v_approval.payload_hash IS DISTINCT FROM public.console_approval_payload_hash_v1(v_approval.action,v_approval.site_id,
      v_approval.resource_type,v_approval.resource_id,v_approval.payload) THEN
    RETURN jsonb_build_object('accepted',false,'code','APPROVAL_PAYLOAD_MISMATCH');
  END IF;
  IF v_approval.status<>'approved' OR v_approval.approver_session_id IS NULL OR v_approval.checker_actor_id=v_approval.maker_actor_id THEN
    RETURN jsonb_build_object('accepted',false,'code','INDEPENDENT_APPROVAL_REQUIRED');
  END IF;
  v_checker:=public.console_session_state_v1(v_approval.approver_session_id,
    (SELECT metadata->>'cookie_sha256' FROM public.sessions_v2 WHERE id=v_approval.approver_session_id));
  IF NOT coalesce((v_checker->>'accepted')::boolean,false) OR NOT coalesce((v_checker->>'is_super_admin')::boolean,false)
    OR (v_checker->>'actor_id')::uuid IS DISTINCT FROM v_approval.checker_actor_id THEN
    RETURN jsonb_build_object('accepted',false,'code','APPROVAL_EXPIRED_OR_REVOKED');
  END IF;
  IF v_approval.consumed_at IS NOT NULL THEN
    RETURN jsonb_build_object('accepted',true,'result',v_approval.result||'{"replayed":true}'::jsonb);
  END IF;
  SELECT * INTO v_site FROM public.sites WHERE id=p_site_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('accepted',false,'code','APPROVAL_TARGET_NOT_FOUND'); END IF;
  IF v_approval.expires_at<=clock_timestamp() THEN
    RETURN jsonb_build_object('accepted',false,'code','APPROVAL_EXPIRED_OR_REVOKED');
  END IF;
  IF v_site.status IS DISTINCT FROM v_approval.payload->>'expected_status'
    OR v_site.updated_at IS DISTINCT FROM (v_approval.payload->>'expected_updated_at')::timestamptz THEN
    RETURN jsonb_build_object('accepted',false,'code','APPROVAL_TARGET_STATE_CHANGED');
  END IF;
  v_next:=CASE WHEN p_action='suspend' THEN 'suspended' ELSE 'published' END;
  UPDATE public.sites SET status=v_next,published=(v_next='published'),updated_by=v_approval.maker_actor_id,updated_at=clock_timestamp() WHERE id=p_site_id;
  SELECT jsonb_build_object('id',id,'name',name,'store_name',store_name,'subdomain',subdomain,'custom_domain',custom_domain,
    'status',status,'published',published,'updated_at',updated_at) INTO v_result FROM public.sites WHERE id=p_site_id;
  v_result:=jsonb_build_object('site',v_result,'approval_id',p_id,'publication_protocol','site-publication-v1','replayed',false);
  INSERT INTO public.audit_logs(actor_id,actor_type,actor_email,action,resource_type,resource_id,metadata)
    VALUES(v_approval.maker_actor_id,CASE WHEN (v_state->>'is_super_admin')::boolean THEN 'super_admin' ELSE 'employee' END,
      v_state->>'email',v_approval.action,'site',p_site_id,jsonb_build_object('reason',v_approval.reason,'old_status',v_site.status,
        'new_status',v_next,'approval_id',p_id,'secondary_approver_id',v_approval.checker_actor_id,'payload_hash',v_approval.payload_hash));
  UPDATE public.sensitive_action_approvals SET consumed_at=clock_timestamp(),result=v_result,updated_by=v_approval.maker_actor_id WHERE id=p_id;
  UPDATE public.break_glass_grants SET used_at=coalesce(used_at,clock_timestamp())
    WHERE id IN (SELECT (g->>'id')::uuid FROM jsonb_array_elements(v_permission->'input'->'breakGlassGrants') g);
  RETURN jsonb_build_object('accepted',true,'result',v_result);
END

DECLARE v_permission jsonb; v_state jsonb; v_items jsonb; v_total bigint;
BEGIN
  v_permission:=public.console_permission_snapshot_v1(p_session_id,p_cookie_sha256,false);
  IF NOT coalesce((v_permission->>'accepted')::boolean,false) THEN RETURN v_permission; END IF;
  IF p_page IS NULL OR p_limit IS NULL OR p_page<1 OR p_page>10000 OR p_limit<1 OR p_limit>100 THEN
    RETURN jsonb_build_object('accepted',false,'code','APPROVAL_QUERY_INVALID');
  END IF;
  v_state:=v_permission->'session';
  SELECT count(*) INTO v_total FROM public.sensitive_action_approvals a WHERE a.protocol_version=1 AND (p_id IS NULL OR a.id=p_id)
    AND (a.maker_actor_id=(v_state->>'actor_id')::uuid OR a.checker_actor_id=(v_state->>'actor_id')::uuid OR (v_state->>'is_super_admin')::boolean);
  SELECT coalesce(jsonb_agg(public.console_approval_view_v1(a.id) ORDER BY a.created_at DESC,a.id DESC),'[]'::jsonb) INTO v_items FROM (
    SELECT a.id,a.created_at FROM public.sensitive_action_approvals a WHERE a.protocol_version=1 AND (p_id IS NULL OR a.id=p_id)
      AND (a.maker_actor_id=(v_state->>'actor_id')::uuid OR a.checker_actor_id=(v_state->>'actor_id')::uuid OR (v_state->>'is_super_admin')::boolean)
      ORDER BY a.created_at DESC,a.id DESC LIMIT p_limit OFFSET ((p_page-1)*p_limit)) a;
  RETURN jsonb_build_object('accepted',true,'items',v_items,'total',v_total,'page',p_page,'limit',p_limit,'has_next',p_page::bigint*p_limit<v_total);
END

DECLARE v_permission jsonb; v_state jsonb; v_approval public.sensitive_action_approvals%ROWTYPE;
 v_row public.money_ledger_site_reconciliations%ROWTYPE; v_payload jsonb; v_details jsonb; v_ref uuid;
BEGIN
  v_permission:=public.console_permission_snapshot_v1(p_session_id,p_cookie_sha256,true);
  IF NOT coalesce((v_permission->>'accepted')::boolean,false) THEN RETURN v_permission; END IF;
  IF v_permission->>'evidence_hash' IS DISTINCT FROM p_permission_hash THEN
    RETURN jsonb_build_object('accepted',false,'code','PERMISSION_CHANGED');
  END IF;
  v_state:=v_permission->'session';
  IF p_site_id IS NULL OR p_request_key IS NULL OR p_reason IS NULL OR length(btrim(p_reason))<8 OR length(btrim(p_reason))>1000
    OR p_details IS NULL OR jsonb_typeof(p_details)<>'object'
    OR (p_details-'resolution'-'provider_reference'-'suspense_ledger_transaction_id')<>'{}'::jsonb
    OR coalesce(p_details->>'resolution','') NOT IN ('acknowledge_suspense','provider_explained','request_recheck')
    OR jsonb_typeof(p_details->'provider_reference') NOT IN ('string','null')
    OR length(coalesce(p_details->>'provider_reference',''))>160
    OR (p_details->>'suspense_ledger_transaction_id' IS NOT NULL
      AND (p_details->>'suspense_ledger_transaction_id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$') THEN
    RETURN jsonb_build_object('accepted',false,'code','APPROVAL_INTENT_INVALID');
  END IF;
  v_ref:=(p_details->>'suspense_ledger_transaction_id')::uuid;
  v_details:=jsonb_build_object('resolution',p_details->>'resolution','provider_reference',nullif(btrim(p_details->>'provider_reference'),''),
    'suspense_ledger_transaction_id',v_ref);
  PERFORM pg_advisory_xact_lock(hashtextextended('letbuyy:approval-request:'||(v_state->>'actor_id')||':'||p_request_key::text,0));
  SELECT * INTO v_approval FROM public.sensitive_action_approvals a WHERE a.protocol_version=1
    AND a.maker_actor_id=(v_state->>'actor_id')::uuid AND a.action='money.reconciliation.resolve'
    AND a.resource_type='money_ledger_site_reconciliation' AND a.resource_id=p_site_id::text AND a.request_key=p_request_key;
  IF FOUND THEN
    IF v_approval.requester_session_id<>p_session_id OR v_approval.reason<>btrim(p_reason)
      OR v_approval.payload->'details' IS DISTINCT FROM v_details THEN
      RETURN jsonb_build_object('accepted',false,'code','IDEMPOTENCY_CONFLICT');
    END IF;
    RETURN jsonb_build_object('accepted',true,'approval',public.console_approval_view_v1(v_approval.id),'replayed',true);
  END IF;
  PERFORM id FROM public.sites WHERE id=p_site_id AND deleted_at IS NULL FOR SHARE;
  IF NOT FOUND THEN RETURN jsonb_build_object('accepted',false,'code','APPROVAL_TARGET_NOT_FOUND'); END IF;
  SELECT * INTO v_row FROM public.money_ledger_site_reconciliations WHERE site_id=p_site_id AND deleted_at IS NULL FOR SHARE;
  IF NOT FOUND THEN RETURN jsonb_build_object('accepted',false,'code','APPROVAL_TARGET_NOT_FOUND'); END IF;
  IF v_row.status<>'mismatch' OR v_row.variance_minor=0 THEN
    RETURN jsonb_build_object('accepted',false,'code','MONEY_RECONCILIATION_ALREADY_VERIFIED');
  END IF;
  IF v_ref IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ledger_transactions t WHERE t.id=v_ref AND t.site_id=p_site_id AND t.deleted_at IS NULL) THEN
    RETURN jsonb_build_object('accepted',false,'code','APPROVAL_EVIDENCE_MISMATCH');
  END IF;
  v_payload:=jsonb_build_object('details',v_details,'reason',btrim(p_reason),'expected_status',v_row.status,
    'expected_updated_at',v_row.updated_at,'wallet_available_minor',v_row.wallet_available_minor,
    'ledger_merchant_payable_minor',v_row.ledger_merchant_payable_minor,'variance_minor',v_row.variance_minor,
    'expected_verified_at',v_row.verified_at);
  INSERT INTO public.sensitive_action_approvals(site_id,action,resource_type,resource_id,maker_actor_id,status,reason,
    protocol_version,requester_session_id,request_key,payload,payload_hash,expires_at,created_by)
  VALUES(p_site_id,'money.reconciliation.resolve','money_ledger_site_reconciliation',p_site_id::text,(v_state->>'actor_id')::uuid,'pending',btrim(p_reason),
    1,p_session_id,p_request_key,v_payload,public.console_approval_payload_hash_v1('money.reconciliation.resolve',p_site_id,'money_ledger_site_reconciliation',p_site_id::text,v_payload),
    least(clock_timestamp()+interval '10 minutes',(v_state->>'expires_at')::timestamptz,(v_state->>'mfa_verified_at')::timestamptz+interval '10 minutes'),
    (v_state->>'actor_id')::uuid) RETURNING * INTO v_approval;
  INSERT INTO public.audit_logs(actor_id,actor_type,actor_email,action,resource_type,resource_id,metadata)
  VALUES(v_approval.maker_actor_id,'employee',v_state->>'email','sensitive_action.requested','sensitive_action_approval',v_approval.id,
    jsonb_build_object('action',v_approval.action,'site_id',p_site_id,'payload_hash',v_approval.payload_hash,'requester_session_id',p_session_id));
  UPDATE public.break_glass_grants SET used_at=coalesce(used_at,clock_timestamp())
    WHERE id IN (SELECT (g->>'id')::uuid FROM jsonb_array_elements(v_permission->'input'->'breakGlassGrants') g);
  RETURN jsonb_build_object('accepted',true,'approval',public.console_approval_view_v1(v_approval.id),'replayed',false);
END

DECLARE v_approval public.sensitive_action_approvals%ROWTYPE; v_permission jsonb; v_state jsonb; v_checker jsonb;
 v_row public.money_ledger_site_reconciliations%ROWTYPE; v_ref uuid; v_resolution jsonb; v_result jsonb; v_action text;
BEGIN
