  END IF;
  IF v_approval.site_id IS DISTINCT FROM p_site_id OR v_approval.resource_id<>p_site_id::text
    OR v_approval.action<>'money.reconciliation.resolve' OR v_approval.resource_type<>'money_ledger_site_reconciliation'
    OR v_approval.reason IS DISTINCT FROM btrim(p_reason) OR v_approval.payload->'details' IS DISTINCT FROM p_details
    OR v_approval.payload_hash IS DISTINCT FROM public.console_approval_payload_hash_v1(v_approval.action,v_approval.site_id,
      v_approval.resource_type,v_approval.resource_id,v_approval.payload) THEN
    RETURN jsonb_build_object('accepted',false,'code','APPROVAL_PAYLOAD_MISMATCH');
  END IF;
  IF v_approval.status<>'approved' OR v_approval.approver_session_id IS NULL OR v_approval.checker_actor_id=v_approval.maker_actor_id THEN
    RETURN jsonb_build_object('accepted',false,'code','INDEPENDENT_APPROVAL_REQUIRED');
  END IF;
  v_checker:=public.console_session_state_v1(v_approval.approver_session_id,
    (SELECT metadata->>'cookie_sha256' FROM public.sessions_v2 WHERE id=v_approval.approver_session_id));
  IF NOT coalesce((v_checker->>'accepted')::boolean,false) OR NOT coalesce((v_checker->>'is_super_admin')::boolean,false)
    OR (v_checker->>'actor_id')::uuid IS DISTINCT FROM v_approval.checker_actor_id THEN
    RETURN jsonb_build_object('accepted',false,'code','APPROVAL_EXPIRED_OR_REVOKED');
  END IF;
  IF v_approval.consumed_at IS NOT NULL THEN RETURN jsonb_build_object('accepted',true,'result',v_approval.result||'{"replayed":true}'::jsonb); END IF;
  PERFORM id FROM public.sites WHERE id=p_site_id AND deleted_at IS NULL FOR SHARE;
  IF NOT FOUND THEN RETURN jsonb_build_object('accepted',false,'code','APPROVAL_TARGET_NOT_FOUND'); END IF;
  SELECT * INTO v_row FROM public.money_ledger_site_reconciliations WHERE site_id=p_site_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('accepted',false,'code','APPROVAL_TARGET_NOT_FOUND'); END IF;
  IF v_approval.expires_at<=clock_timestamp() THEN RETURN jsonb_build_object('accepted',false,'code','APPROVAL_EXPIRED_OR_REVOKED'); END IF;
  IF v_row.status IS DISTINCT FROM v_approval.payload->>'expected_status'
    OR v_row.updated_at IS DISTINCT FROM (v_approval.payload->>'expected_updated_at')::timestamptz
    OR v_row.wallet_available_minor IS DISTINCT FROM (v_approval.payload->>'wallet_available_minor')::bigint
    OR v_row.ledger_merchant_payable_minor IS DISTINCT FROM (v_approval.payload->>'ledger_merchant_payable_minor')::bigint
    OR v_row.variance_minor IS DISTINCT FROM (v_approval.payload->>'variance_minor')::bigint
    OR v_row.verified_at IS DISTINCT FROM (v_approval.payload->>'expected_verified_at')::timestamptz
    OR v_row.status<>'mismatch' OR v_row.variance_minor=0 THEN
    RETURN jsonb_build_object('accepted',false,'code','APPROVAL_TARGET_STATE_CHANGED');
  END IF;
  v_ref:=(p_details->>'suspense_ledger_transaction_id')::uuid;
  IF v_ref IS NOT NULL THEN
    PERFORM id FROM public.ledger_transactions WHERE id=v_ref AND site_id=p_site_id AND deleted_at IS NULL FOR SHARE;
    IF NOT FOUND THEN RETURN jsonb_build_object('accepted',false,'code','APPROVAL_EVIDENCE_MISMATCH'); END IF;
  END IF;
  v_resolution:=p_details||jsonb_build_object('reason',v_approval.reason,'actor_id',v_approval.maker_actor_id,'actor_email',v_state->>'email',
    'secondary_approver_id',v_approval.checker_actor_id,'approval_id',p_id,'variance_minor',v_row.variance_minor,
    'resolved_at',clock_timestamp(),'source','admin-web');
  IF p_details->>'resolution'='request_recheck' THEN
    PERFORM public.refresh_money_ledger_site_reconciliation(p_site_id);
  END IF;
  UPDATE public.money_ledger_site_reconciliations SET metadata=metadata||jsonb_build_object('operator_resolution',v_resolution),
    updated_by=v_approval.maker_actor_id,updated_at=clock_timestamp() WHERE site_id=p_site_id;
  SELECT to_jsonb(r) INTO v_result FROM public.money_ledger_site_reconciliations r WHERE site_id=p_site_id;
  v_result:=jsonb_build_object('reconciliation',v_result,'resolution',v_resolution,'approval_id',p_id,'replayed',false);
  v_action:=CASE WHEN p_details->>'resolution'='request_recheck' THEN 'money_ledger.reconciliation.recheck_requested' ELSE 'money_ledger.breaks.resolve' END;
  INSERT INTO public.audit_logs(actor_id,actor_type,actor_email,action,resource_type,resource_id,metadata)
  VALUES(v_approval.maker_actor_id,CASE WHEN (v_state->>'is_super_admin')::boolean THEN 'super_admin' ELSE 'employee' END,v_state->>'email',
    v_action,'money_ledger_site_reconciliation',p_site_id,jsonb_build_object('reason',v_approval.reason,'resolution',v_resolution,
      'status_before',v_row.status,'variance_before_minor',v_row.variance_minor,'payload_hash',v_approval.payload_hash));
  UPDATE public.sensitive_action_approvals SET consumed_at=clock_timestamp(),result=v_result,updated_by=v_approval.maker_actor_id WHERE id=p_id;
  UPDATE public.break_glass_grants SET used_at=coalesce(used_at,clock_timestamp())
    WHERE id IN (SELECT (g->>'id')::uuid FROM jsonb_array_elements(v_permission->'input'->'breakGlassGrants') g);
  RETURN jsonb_build_object('accepted',true,'result',v_result);
END

BEGIN
 NEW.status_revision:=CASE WHEN TG_OP='INSERT' THEN 0 ELSE OLD.status_revision END;
 IF NEW.status='suspended' THEN NEW.published:=false; END IF;
 RETURN NEW;
END

BEGIN
 IF (CASE WHEN TG_OP='DELETE' THEN true ELSE NEW.status IS DISTINCT FROM 'suspended' END) AND EXISTS(
   SELECT 1 FROM public.ts_takedowns t WHERE t.site_id=OLD.id AND t.action_type='suspend_site' AND t.status='active' AND t.deleted_at IS NULL) THEN
   RAISE EXCEPTION 'TS_ACTIVE_SITE_RESTRICTION' USING ERRCODE='23514';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 NEW.status_revision:=OLD.status_revision+1;
 RETURN NEW;
END

BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'trust enforcement records are retained'; END IF;
 IF OLD.enforcement_key IS NOT NULL THEN
  IF ROW(NEW.case_id,NEW.site_id,NEW.subject_type,NEW.subject_id,NEW.action_type,NEW.reason,NEW.enforced_by,NEW.enforced_at,
   NEW.enforcement_session_id,NEW.enforcement_key,NEW.enforcement_payload_hash,NEW.applied_site_revision,
   NEW.restoration_root_id,NEW.restoration_baseline_status,NEW.restoration_baseline_published,NEW.created_at,NEW.created_by,NEW.deleted_at,NEW.deleted_by)
   IS DISTINCT FROM ROW(OLD.case_id,OLD.site_id,OLD.subject_type,OLD.subject_id,OLD.action_type,OLD.reason,OLD.enforced_by,OLD.enforced_at,
   OLD.enforcement_session_id,OLD.enforcement_key,OLD.enforcement_payload_hash,OLD.applied_site_revision,
   OLD.restoration_root_id,OLD.restoration_baseline_status,OLD.restoration_baseline_published,OLD.created_at,OLD.created_by,OLD.deleted_at,OLD.deleted_by) THEN
    RAISE EXCEPTION 'trust enforcement binding is immutable';
  END IF;
  IF OLD.enforcement_result IS NOT NULL AND NEW.enforcement_result IS DISTINCT FROM OLD.enforcement_result THEN
   RAISE EXCEPTION 'trust enforcement receipt is immutable';
  END IF;
  IF OLD.status='reversed' AND ROW(NEW.status,NEW.reversed_by,NEW.reversed_at) IS DISTINCT FROM ROW(OLD.status,OLD.reversed_by,OLD.reversed_at) THEN
   RAISE EXCEPTION 'trust enforcement reversal is immutable';
  END IF;
 END IF;
 RETURN NEW;
END

BEGIN
 IF TG_OP='INSERT' THEN
  PERFORM id FROM public.ts_cases WHERE id=NEW.case_id FOR UPDATE;
 ELSIF TG_OP='DELETE' THEN
  PERFORM id FROM public.ts_cases WHERE id=OLD.case_id FOR UPDATE;
 ELSE
  PERFORM id FROM public.ts_cases WHERE id=ANY(ARRAY[OLD.case_id,NEW.case_id]) ORDER BY id FOR UPDATE;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END

DECLARE v_case public.ts_cases%ROWTYPE; v_site public.sites%ROWTYPE; v_takedowns jsonb; v_others jsonb; v_roots jsonb;v_sources jsonb;
BEGIN
 SELECT * INTO v_case FROM public.ts_cases WHERE id=p_case_id AND deleted_at IS NULL;
 IF NOT FOUND THEN RETURN jsonb_build_object('accepted',false,'code','APPROVAL_TARGET_NOT_FOUND'); END IF;
 IF v_case.status NOT IN ('actioned','appealed') THEN RETURN jsonb_build_object('accepted',false,'code','APPROVAL_TARGET_STATE_CHANGED'); END IF;
 -- Policy edits serialize with the reviewed context until this transaction
 -- completes, just as child evidence/appeal/event writers lock the case.
 PERFORM id FROM public.ts_policies WHERE id=v_case.policy_id FOR SHARE;
 SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY t.id),'[]'::jsonb) INTO v_takedowns FROM (
  SELECT * FROM public.ts_takedowns WHERE case_id=p_case_id AND status='active' AND deleted_at IS NULL ORDER BY id LIMIT 101) t;
 IF jsonb_array_length(v_takedowns)=0 THEN RETURN jsonb_build_object('accepted',false,'code','APPROVAL_NO_ACTIVE_RESTRICTION'); END IF;
 IF jsonb_array_length(v_takedowns)>100 THEN RETURN jsonb_build_object('accepted',false,'code','APPROVAL_CONTEXT_TOO_LARGE'); END IF;
 -- Other action families retain their accepted/frozen/provider owner gates.
 -- Never label an unimplemented payout/app/theme restoration successful.
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(v_takedowns) t WHERE t->>'action_type'<>'suspend_site') THEN
  RETURN jsonb_build_object('accepted',false,'code','APPROVAL_RESTORATION_SCOPE_UNAVAILABLE');
 END IF;
 IF v_case.site_id IS NULL OR EXISTS(SELECT 1 FROM jsonb_array_elements(v_takedowns) t
   WHERE t->>'site_id' IS DISTINCT FROM v_case.site_id::text OR t->>'subject_type' IS DISTINCT FROM v_case.subject_type
    OR t->>'subject_id' IS DISTINCT FROM v_case.subject_id) THEN
  RETURN jsonb_build_object('accepted',false,'code','APPROVAL_TARGET_SCOPE_MISMATCH');
 END IF;
 SELECT * INTO v_site FROM public.sites WHERE id=v_case.site_id AND deleted_at IS NULL;
 IF NOT FOUND THEN RETURN jsonb_build_object('accepted',false,'code','APPROVAL_TARGET_NOT_FOUND'); END IF;
 IF v_site.status<>'suspended' THEN RETURN jsonb_build_object('accepted',false,'code','APPROVAL_TARGET_STATE_CHANGED'); END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY t.id),'[]'::jsonb) INTO v_others FROM(
  SELECT * FROM public.ts_takedowns WHERE site_id=v_case.site_id AND case_id<>p_case_id AND action_type='suspend_site'
   AND status='active' AND deleted_at IS NULL ORDER BY id LIMIT 101) t;
 IF jsonb_array_length(v_others)>100 THEN RETURN jsonb_build_object('accepted',false,'code','APPROVAL_CONTEXT_TOO_LARGE'); END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY t.id),'[]'::jsonb) INTO v_roots FROM public.ts_takedowns t
  WHERE t.id IN(SELECT (a->>'restoration_root_id')::uuid FROM jsonb_array_elements(v_takedowns) a);
 SELECT jsonb_build_object(
  'evidence',(SELECT jsonb_build_object('count',count(*),'sha256',encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(e) ORDER BY e.id)::text,'[]'),'UTF8')),'hex')) FROM public.ts_evidence e WHERE e.case_id=p_case_id AND e.deleted_at IS NULL),
  'appeals',(SELECT jsonb_build_object('count',count(*),'sha256',encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.id)::text,'[]'),'UTF8')),'hex')) FROM public.ts_appeals a WHERE a.case_id=p_case_id AND a.deleted_at IS NULL),
  'events',(SELECT jsonb_build_object('count',count(*),'sha256',encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(e) ORDER BY e.id)::text,'[]'),'UTF8')),'hex')) FROM public.ts_case_events e WHERE e.case_id=p_case_id AND e.deleted_at IS NULL),
  'policy',(SELECT encode(sha256(convert_to(to_jsonb(p)::text,'UTF8')),'hex') FROM public.ts_policies p WHERE p.id=v_case.policy_id)
 ) INTO v_sources;
 RETURN jsonb_build_object('accepted',true,'context',jsonb_build_object('case',to_jsonb(v_case),'takedowns',v_takedowns,
  'site',jsonb_build_object('id',v_site.id,'status',v_site.status,'status_revision',v_site.status_revision,'published',v_site.published,'legacy_updated_by',CASE WHEN v_site.status_revision=0 THEN v_site.updated_by ELSE NULL END),
  'other_active_takedowns',v_others,'roots',v_roots,'review_sources',v_sources));
END

DECLARE v_permission jsonb; v_state jsonb; v_a public.sensitive_action_approvals%ROWTYPE; v_context jsonb; v_payload jsonb; v_site uuid;
BEGIN
 v_permission:=public.console_permission_snapshot_v1(p_session_id,p_cookie_sha256,true);
 IF NOT coalesce((v_permission->>'accepted')::boolean,false) THEN RETURN v_permission; END IF;
 IF v_permission->>'evidence_hash' IS DISTINCT FROM p_permission_hash THEN RETURN jsonb_build_object('accepted',false,'code','PERMISSION_CHANGED'); END IF;
 v_state:=v_permission->'session';
 IF p_case_id IS NULL OR p_request_key IS NULL OR p_reason IS NULL OR length(btrim(p_reason))<8 OR length(btrim(p_reason))>1000
  OR p_note_metadata IS NULL OR jsonb_typeof(p_note_metadata)<>'object' OR octet_length(p_note_metadata::text)>4096 THEN
  RETURN jsonb_build_object('accepted',false,'code','APPROVAL_INTENT_INVALID');
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('letbuyy:approval-request:'||(v_state->>'actor_id')||':'||p_request_key::text,0));
 SELECT * INTO v_a FROM public.sensitive_action_approvals WHERE protocol_version=1 AND action='ts.reinstate' AND resource_type='ts_case'
  AND resource_id=p_case_id::text AND maker_actor_id=(v_state->>'actor_id')::uuid AND request_key=p_request_key;
 IF FOUND THEN
  IF v_a.requester_session_id<>p_session_id OR v_a.reason<>btrim(p_reason) OR v_a.payload->'note_metadata' IS DISTINCT FROM p_note_metadata THEN
   RETURN jsonb_build_object('accepted',false,'code','IDEMPOTENCY_CONFLICT');
  END IF;
  RETURN jsonb_build_object('accepted',true,'approval',public.console_approval_view_v1(v_a.id),'replayed',true);
 END IF;
 SELECT site_id INTO v_site FROM public.ts_cases WHERE id=p_case_id AND deleted_at IS NULL FOR SHARE;
 IF NOT FOUND THEN RETURN jsonb_build_object('accepted',false,'code','APPROVAL_TARGET_NOT_FOUND'); END IF;
 PERFORM id FROM public.sites WHERE id=v_site FOR SHARE;
 v_context:=public.console_trust_reinstatement_context_v1(p_case_id);
 IF NOT coalesce((v_context->>'accepted')::boolean,false) THEN RETURN v_context; END IF;
 v_payload:=jsonb_build_object('context',v_context->'context','reason',btrim(p_reason),'note_metadata',p_note_metadata);
 INSERT INTO public.sensitive_action_approvals(site_id,action,resource_type,resource_id,maker_actor_id,status,reason,protocol_version,
  requester_session_id,request_key,payload,payload_hash,expires_at,created_by)
 VALUES(v_site,'ts.reinstate','ts_case',p_case_id::text,(v_state->>'actor_id')::uuid,'pending',btrim(p_reason),1,p_session_id,p_request_key,v_payload,
  public.console_approval_payload_hash_v1('ts.reinstate',v_site,'ts_case',p_case_id::text,v_payload),
  least(clock_timestamp()+interval '10 minutes',(v_state->>'expires_at')::timestamptz,(v_state->>'mfa_verified_at')::timestamptz+interval '10 minutes'),
  (v_state->>'actor_id')::uuid) RETURNING * INTO v_a;
 INSERT INTO public.audit_logs(actor_id,actor_type,actor_email,action,resource_type,resource_id,metadata)
 VALUES(v_a.maker_actor_id,CASE WHEN(v_state->>'is_super_admin')::boolean THEN 'super_admin' ELSE 'employee' END,v_state->>'email','sensitive_action.requested','sensitive_action_approval',v_a.id,
  jsonb_build_object('action',v_a.action,'case_id',p_case_id,'payload_hash',v_a.payload_hash,'requester_session_id',p_session_id));
 UPDATE public.break_glass_grants SET used_at=coalesce(used_at,clock_timestamp())
  WHERE id IN(SELECT(g->>'id')::uuid FROM jsonb_array_elements(v_permission->'input'->'breakGlassGrants')g);
 RETURN jsonb_build_object('accepted',true,'approval',public.console_approval_view_v1(v_a.id),'replayed',false);
END

DECLARE v_a public.sensitive_action_approvals%ROWTYPE; v_permission jsonb; v_state jsonb; v_checker jsonb; v_context jsonb;
 v_case public.ts_cases%ROWTYPE; v_site public.sites%ROWTYPE; v_last public.ts_takedowns%ROWTYPE; v_baseline text;
 v_next text; v_published boolean; v_outcome text; v_result jsonb; v_ids jsonb;
BEGIN
 SELECT * INTO v_a FROM public.sensitive_action_approvals WHERE id=p_id AND protocol_version=1 FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('accepted',false,'code','APPROVAL_NOT_FOUND'); END IF;
 PERFORM id FROM public.sessions_v2 WHERE id=ANY(ARRAY[p_session_id,v_a.approver_session_id]) ORDER BY id FOR UPDATE;
 v_permission:=public.console_permission_snapshot_v1(p_session_id,p_cookie_sha256,true);
 IF NOT coalesce((v_permission->>'accepted')::boolean,false) THEN RETURN v_permission; END IF;
 IF v_permission->>'evidence_hash' IS DISTINCT FROM p_permission_hash THEN RETURN jsonb_build_object('accepted',false,'code','PERMISSION_CHANGED'); END IF;
 v_state:=v_permission->'session';
 IF v_a.maker_actor_id<>(v_state->>'actor_id')::uuid OR v_a.requester_session_id<>p_session_id THEN
  RETURN jsonb_build_object('accepted',false,'code','APPROVAL_REQUESTER_MISMATCH');
 END IF;
 IF v_a.action<>'ts.reinstate' OR v_a.resource_type<>'ts_case' OR v_a.resource_id IS DISTINCT FROM p_case_id::text
  OR v_a.reason IS DISTINCT FROM btrim(p_reason) OR v_a.payload->'note_metadata' IS DISTINCT FROM p_note_metadata
  OR v_a.payload_hash IS DISTINCT FROM public.console_approval_payload_hash_v1(v_a.action,v_a.site_id,v_a.resource_type,v_a.resource_id,v_a.payload) THEN
  RETURN jsonb_build_object('accepted',false,'code','APPROVAL_PAYLOAD_MISMATCH');
 END IF;
 IF v_a.status<>'approved' OR v_a.approver_session_id IS NULL OR v_a.checker_actor_id=v_a.maker_actor_id THEN
  RETURN jsonb_build_object('accepted',false,'code','INDEPENDENT_APPROVAL_REQUIRED');
 END IF;
 v_checker:=public.console_session_state_v1(v_a.approver_session_id,(SELECT metadata->>'cookie_sha256' FROM public.sessions_v2 WHERE id=v_a.approver_session_id));
 IF NOT coalesce((v_checker->>'accepted')::boolean,false) OR NOT coalesce((v_checker->>'is_super_admin')::boolean,false)
  OR (v_checker->>'actor_id')::uuid IS DISTINCT FROM v_a.checker_actor_id THEN
  RETURN jsonb_build_object('accepted',false,'code','APPROVAL_EXPIRED_OR_REVOKED');
 END IF;
 IF v_a.consumed_at IS NOT NULL THEN RETURN jsonb_build_object('accepted',true,'result',v_a.result||'{"replayed":true}'::jsonb); END IF;
 IF v_a.expires_at<=clock_timestamp() THEN RETURN jsonb_build_object('accepted',false,'code','APPROVAL_EXPIRED_OR_REVOKED'); END IF;
 SELECT * INTO v_case FROM public.ts_cases WHERE id=p_case_id AND deleted_at IS NULL FOR UPDATE;
 IF NOT FOUND OR v_case.site_id IS DISTINCT FROM v_a.site_id THEN RETURN jsonb_build_object('accepted',false,'code','APPROVAL_TARGET_SCOPE_MISMATCH'); END IF;
 SELECT * INTO v_site FROM public.sites WHERE id=v_case.site_id AND deleted_at IS NULL FOR UPDATE;
 v_context:=public.console_trust_reinstatement_context_v1(p_case_id);
 IF NOT coalesce((v_context->>'accepted')::boolean,false) THEN RETURN v_context; END IF;
 IF v_context->'context' IS DISTINCT FROM v_a.payload->'context' THEN RETURN jsonb_build_object('accepted',false,'code','APPROVAL_TARGET_STATE_CHANGED'); END IF;
 v_next:='suspended';v_published:=false;v_outcome:='independent_site_status_retained';
 IF jsonb_array_length(v_context->'context'->'other_active_takedowns')>0 THEN
  v_outcome:='other_safety_restriction_retained';
 ELSE
  SELECT * INTO v_last FROM public.ts_takedowns WHERE case_id=p_case_id AND status='active' AND deleted_at IS NULL
   ORDER BY applied_site_revision DESC NULLS LAST,enforced_at DESC,id DESC LIMIT 1;
  IF v_last.enforcement_key IS NOT NULL AND v_last.applied_site_revision=v_site.status_revision THEN
   v_baseline:=v_last.restoration_baseline_status;v_published:=v_last.restoration_baseline_published;
  ELSIF v_site.status_revision=0 AND v_site.updated_by=v_last.enforced_by AND NOT EXISTS(
   SELECT 1 FROM public.ts_takedowns t WHERE t.case_id=p_case_id AND t.status='active' AND t.deleted_at IS NULL
    AND (t.enforced_by IS DISTINCT FROM v_site.updated_by OR t.metadata->>'previous_site_status' IS DISTINCT FROM v_last.metadata->>'previous_site_status')) THEN
   v_baseline:=v_last.metadata->>'previous_site_status';v_published:=coalesce((v_last.metadata->>'previous_published')::boolean,false);
  END IF;
  IF v_baseline IN('published','draft','suspended') THEN
   v_next:=v_baseline;v_outcome:=CASE WHEN v_next='suspended' THEN 'preexisting_suspension_retained' ELSE 'owned_site_status_restored' END;
  END IF;
 END IF;
 SELECT jsonb_agg(t->'id' ORDER BY t->>'id') INTO v_ids FROM jsonb_array_elements(v_context->'context'->'takedowns')t;
 -- Reverse only this reviewed case's hold, then let the global site guard check
 -- every remaining active hold before a publication change can commit.
 UPDATE public.ts_takedowns SET status='reversed',reversed_by=v_a.maker_actor_id,reversed_at=clock_timestamp(),updated_by=v_a.maker_actor_id
  WHERE case_id=p_case_id AND status='active' AND deleted_at IS NULL;
 IF v_next IS DISTINCT FROM v_site.status OR (v_next='suspended' AND v_site.published IS DISTINCT FROM false) THEN
  UPDATE public.sites SET status=v_next,published=CASE WHEN v_next='suspended' THEN false ELSE v_published END,updated_by=v_a.maker_actor_id WHERE id=v_site.id;
 END IF;
 UPDATE public.ts_cases SET status='reinstated',closed_at=clock_timestamp(),updated_by=v_a.maker_actor_id,
  metadata=metadata||jsonb_build_object('reinstatement',jsonb_build_object('approval_id',p_id,'note_metadata',p_note_metadata,
   'site_restoration_outcome',v_outcome,'independent_approver_id',v_a.checker_actor_id)) WHERE id=p_case_id;
 SELECT jsonb_build_object('case',to_jsonb(c),'site',jsonb_build_object('id',s.id,'status',s.status,'status_revision',s.status_revision,'published',s.published),
  'site_restoration_outcome',v_outcome,'reversed_takedowns',v_ids,'approval_id',p_id,'replayed',false) INTO v_result
  FROM public.ts_cases c JOIN public.sites s ON s.id=c.site_id WHERE c.id=p_case_id;
 INSERT INTO public.ts_case_events(case_id,event_type,actor_type,actor_id,reason,metadata,created_by)
 VALUES(p_case_id,'reinstated',CASE WHEN(v_state->>'is_super_admin')::boolean THEN 'super_admin' ELSE 'employee' END,
  v_a.maker_actor_id,v_a.reason,v_result,v_a.maker_actor_id);
 INSERT INTO public.audit_logs(actor_id,actor_type,actor_email,action,resource_type,resource_id,metadata)
 VALUES(v_a.maker_actor_id,CASE WHEN(v_state->>'is_super_admin')::boolean THEN 'super_admin' ELSE 'employee' END,v_state->>'email',
  'trust_safety.case.reinstate','ts_case',p_case_id,jsonb_build_object('reason',v_a.reason,'approval_id',p_id,'payload_hash',v_a.payload_hash,'result',v_result));
 UPDATE public.sensitive_action_approvals SET consumed_at=clock_timestamp(),result=v_result,updated_by=v_a.maker_actor_id WHERE id=p_id;
 UPDATE public.break_glass_grants SET used_at=coalesce(used_at,clock_timestamp())
  WHERE id IN(SELECT(g->>'id')::uuid FROM jsonb_array_elements(v_permission->'input'->'breakGlassGrants')g);
 RETURN jsonb_build_object('accepted',true,'result',v_result);
END

DECLARE v_permission jsonb; v_state jsonb; v_case public.ts_cases%ROWTYPE; v_site public.sites%ROWTYPE;
 v_old public.ts_takedowns%ROWTYPE; v_td public.ts_takedowns%ROWTYPE; v_prior public.ts_takedowns%ROWTYPE;
 v_id uuid:=gen_random_uuid();v_hash text;v_root uuid;v_baseline text;v_published boolean;v_result jsonb;v_revision bigint;v_delivery text;
BEGIN
 v_permission:=public.console_permission_snapshot_v1(p_session_id,p_cookie_sha256,true);
 IF NOT coalesce((v_permission->>'accepted')::boolean,false) THEN RETURN v_permission; END IF;
 IF v_permission->>'evidence_hash' IS DISTINCT FROM p_permission_hash THEN RETURN jsonb_build_object('accepted',false,'code','PERMISSION_CHANGED'); END IF;
 v_state:=v_permission->'session';
 IF p_request_key IS NULL OR p_case_id IS NULL OR p_reason IS NULL OR length(btrim(p_reason))<8 OR length(btrim(p_reason))>1000
  OR p_note_metadata IS NULL OR jsonb_typeof(p_note_metadata)<>'object' OR octet_length(p_note_metadata::text)>4096 THEN
  RETURN jsonb_build_object('accepted',false,'code','APPROVAL_INTENT_INVALID');
 END IF;
 IF p_action IS DISTINCT FROM 'suspend_site' THEN RETURN jsonb_build_object('accepted',false,'code','APPROVAL_RESTORATION_SCOPE_UNAVAILABLE'); END IF;
 v_delivery:=CASE WHEN coalesce(p_notify_subject,false) THEN 'pending_approved_delivery' ELSE 'not_requested' END;
 v_hash:=encode(sha256(convert_to(jsonb_build_object('case_id',p_case_id,'action',p_action,'reason',btrim(p_reason),
  'notes',p_note_metadata,'notification_requested',coalesce(p_notify_subject,false))::text,'UTF8')),'hex');
 PERFORM pg_advisory_xact_lock(hashtextextended('letbuyy:ts-enforce:'||(v_state->>'actor_id')||':'||p_request_key::text,0));
 SELECT * INTO v_old FROM public.ts_takedowns WHERE case_id=p_case_id AND enforced_by=(v_state->>'actor_id')::uuid AND enforcement_key=p_request_key;
 IF FOUND THEN
  IF v_old.enforcement_session_id<>p_session_id OR v_old.enforcement_payload_hash<>v_hash THEN
   RETURN jsonb_build_object('accepted',false,'code','IDEMPOTENCY_CONFLICT');
  END IF;
  IF v_old.enforcement_result IS NULL THEN RAISE EXCEPTION 'retained enforcement receipt is unavailable'; END IF;
  RETURN jsonb_build_object('accepted',true,'result',v_old.enforcement_result||'{"replayed":true}'::jsonb);
 END IF;
 SELECT * INTO v_case FROM public.ts_cases WHERE id=p_case_id AND deleted_at IS NULL FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('accepted',false,'code','APPROVAL_TARGET_NOT_FOUND'); END IF;
 IF v_case.site_id IS NULL OR v_case.status NOT IN('open','under_review','actioned','appealed') THEN
  RETURN jsonb_build_object('accepted',false,'code','APPROVAL_TARGET_STATE_CHANGED');
 END IF;
 IF v_case.subject_type<>'site' OR v_case.subject_id IS DISTINCT FROM v_case.site_id::text THEN
  RETURN jsonb_build_object('accepted',false,'code','APPROVAL_TARGET_SCOPE_MISMATCH');
 END IF;
 SELECT * INTO v_site FROM public.sites WHERE id=v_case.site_id AND deleted_at IS NULL FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('accepted',false,'code','APPROVAL_TARGET_NOT_FOUND'); END IF;
 v_baseline:=v_site.status;v_published:=coalesce(v_site.published,false);v_root:=v_id;
 IF v_site.status='suspended' THEN
  SELECT * INTO v_prior FROM public.ts_takedowns WHERE site_id=v_site.id AND action_type='suspend_site' AND status='active' AND deleted_at IS NULL
   AND enforcement_key IS NOT NULL ORDER BY applied_site_revision DESC,id DESC LIMIT 1;
  IF FOUND AND v_prior.applied_site_revision=v_site.status_revision THEN
   v_baseline:=v_prior.restoration_baseline_status;v_published:=v_prior.restoration_baseline_published;v_root:=v_prior.restoration_root_id;
  END IF;
 END IF;
 UPDATE public.sites SET status='suspended',updated_by=(v_state->>'actor_id')::uuid WHERE id=v_site.id RETURNING status_revision INTO v_revision;
 INSERT INTO public.ts_takedowns(id,case_id,site_id,subject_type,subject_id,action_type,status,reason,enforced_by,metadata,created_by,
  enforcement_session_id,enforcement_key,enforcement_payload_hash,applied_site_revision,restoration_root_id,restoration_baseline_status,restoration_baseline_published)
 VALUES(v_id,p_case_id,v_site.id,v_case.subject_type,v_case.subject_id,'suspend_site','active',btrim(p_reason),(v_state->>'actor_id')::uuid,
  jsonb_build_object('previous_site_status',v_site.status,'previous_published',v_site.published,'notes',p_note_metadata,'notification_status',v_delivery),
  (v_state->>'actor_id')::uuid,p_session_id,p_request_key,v_hash,v_revision,v_root,v_baseline,v_published) RETURNING * INTO v_td;
 UPDATE public.ts_cases SET status='actioned',enforcement_action='suspend_site',enforced_by=(v_state->>'actor_id')::uuid,
  decision='violation',decision_reason=btrim(p_reason),updated_by=(v_state->>'actor_id')::uuid WHERE id=p_case_id RETURNING * INTO v_case;
 v_result:=jsonb_build_object('case',to_jsonb(v_case),'takedown',to_jsonb(v_td),'site',jsonb_build_object('id',v_site.id,'status','suspended','status_revision',v_revision,'published',false),
  'notification_status',v_delivery,'replayed',false);
 INSERT INTO public.ts_case_events(case_id,event_type,actor_type,actor_id,reason,metadata,created_by)
 VALUES(p_case_id,'enforcement_applied',CASE WHEN(v_state->>'is_super_admin')::boolean THEN 'super_admin' ELSE 'employee' END,
  (v_state->>'actor_id')::uuid,btrim(p_reason),jsonb_build_object('action','suspend_site','takedown_id',v_id,'notification_status',v_delivery),(v_state->>'actor_id')::uuid);
 INSERT INTO public.audit_logs(actor_id,actor_type,actor_email,action,resource_type,resource_id,metadata)
 VALUES((v_state->>'actor_id')::uuid,CASE WHEN(v_state->>'is_super_admin')::boolean THEN 'super_admin' ELSE 'employee' END,
  v_state->>'email','trust_safety.case.enforce','ts_case',p_case_id,jsonb_build_object('reason',btrim(p_reason),'result',v_result,'request_key',p_request_key));
 UPDATE public.ts_takedowns SET enforcement_result=v_result WHERE id=v_id;
 UPDATE public.break_glass_grants SET used_at=coalesce(used_at,clock_timestamp())
  WHERE id IN(SELECT(g->>'id')::uuid FROM jsonb_array_elements(v_permission->'input'->'breakGlassGrants')g);
 RETURN jsonb_build_object('accepted',true,'result',v_result);
END

DECLARE v_site public.sites; v_slug text; v_plan jsonb; v_source jsonb;
BEGIN
 SELECT * INTO v_site FROM public.sites WHERE id=p_store_id AND deleted_at IS NULL
  AND(custom_user_id=p_actor_id OR user_id=p_actor_id)
  AND(p_bound_site_id IS NULL OR id=p_bound_site_id)
  AND EXISTS(SELECT 1 FROM public.users_custom WHERE id=p_actor_id);
 IF NOT FOUND THEN RETURN NULL; END IF;
 SELECT plan INTO v_slug FROM public.subscriptions WHERE store_id=p_store_id
  AND status IN('active','past_due','failed') ORDER BY created_at DESC,id DESC LIMIT 1;
 v_slug:=coalesce(nullif(v_slug,''),'free');
 SELECT to_jsonb(p) INTO v_plan FROM public.plans p WHERE site_type=v_site.site_type AND slug=v_slug AND is_active=true;
 v_source:=jsonb_build_object('site_type',v_site.site_type,'slug',v_slug,'plan',v_plan);
 RETURN v_source||jsonb_build_object('source_hash',encode(sha256(convert_to(v_source::text,'UTF8')),'hex'));
END

DECLARE v_actor public.users_custom; v_site public.sites; v_employee public.employees;
 v_before jsonb; v_response jsonb; v_scope text; v_hash text; v_receipt public.idempotency_keys;
 v_policy jsonb; v_used integer; v_staff_id uuid; v_constraint text; v_status integer; v_action text;
BEGIN
 IF p_operation NOT IN('create','update','remove') OR p_operation IS NULL OR p_key IS NULL OR length(p_key) NOT BETWEEN 8 AND 200 THEN
  RETURN jsonb_build_object('error','VALIDATION','status',400); END IF;
 -- Serialize the last available seat and all lifecycle changes for this store.
 -- A replay is still authorized against current ownership before exposing its receipt.
 SELECT * INTO v_site FROM public.sites WHERE id=p_store_id AND deleted_at IS NULL FOR UPDATE;
 SELECT * INTO v_actor FROM public.users_custom WHERE id=p_actor_id;
 IF v_site.id IS NULL OR v_actor.id IS NULL OR NOT(coalesce(v_site.custom_user_id=p_actor_id,false) OR coalesce(v_site.user_id=p_actor_id,false))
  OR(p_bound_site_id IS NOT NULL AND p_bound_site_id<>p_store_id) THEN
  RETURN jsonb_build_object('error','FORBIDDEN','status',403); END IF;
 v_scope:='merchant-staff-v1:'||p_actor_id::text||':'||p_operation;
 v_hash:=encode(sha256(convert_to(jsonb_build_object('actor',p_actor_id,'store',p_store_id,'operation',p_operation,
  'intent',p_intent,'employee',p_employee_id,'expected_updated_at',p_expected_updated_at)::text,'UTF8')),'hex');
 SELECT * INTO v_receipt FROM public.idempotency_keys WHERE site_id=p_store_id AND scope=v_scope AND key=p_key FOR UPDATE;
 IF FOUND THEN
  IF v_receipt.request_hash<>v_hash THEN RETURN jsonb_build_object('error','IDEMPOTENCY_CONFLICT','status',409); END IF;
  IF v_receipt.status<>'completed' OR v_receipt.response_body IS NULL OR v_receipt.deleted_at IS NOT NULL THEN
   RETURN jsonb_build_object('error','STAFF_STATE_UNAVAILABLE','status',503); END IF;
  RETURN jsonb_build_object('data',v_receipt.response_body,'status',v_receipt.status_code,'replayed',true);
 END IF;
 IF p_operation IN('create','update') THEN
  IF p_intent IS NULL OR jsonb_typeof(p_intent)<>'object' OR(p_operation='create' AND NOT(p_intent ? 'role'))
   OR(p_intent ? 'role' AND (p_intent->>'role' IS NULL OR p_intent->>'role' NOT IN('manager','editor','fulfillment','marketing','support','viewer','staff')))
   OR NOT(p_intent ? 'permissions') OR jsonb_typeof(p_intent->'permissions') IS DISTINCT FROM 'object'
   OR (p_intent->'permissions')-'granted'<>'{}'::jsonb OR jsonb_typeof(p_intent->'permissions'->'granted') IS DISTINCT FROM 'array' THEN
   RETURN jsonb_build_object('error','VALIDATION','status',400); END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_intent->'permissions'->'granted') g WHERE jsonb_typeof(g)<>'string'
   OR g#>>'{}' NOT IN('products:read','products:write','orders:read','orders:write','customers:read','customers:write',
    'content:write','marketing:write','shipping:write','returns:write','reports:read','settings:write')) THEN
   RETURN jsonb_build_object('error','VALIDATION','status',400); END IF;
 END IF;
 IF p_operation='create' THEN
  IF nullif(p_intent->>'email','') IS NULL OR p_intent->>'email'<>lower(trim(p_intent->>'email')) THEN
   RETURN jsonb_build_object('error','VALIDATION','status',400); END IF;
  v_policy:=public.merchant_staff_policy_snapshot_v1(p_actor_id,p_store_id,p_bound_site_id);
  IF p_policy_hash IS NULL OR v_policy->>'source_hash' IS DISTINCT FROM p_policy_hash OR p_seat_limit<0 THEN
   RETURN jsonb_build_object('error','STAFF_POLICY_CHANGED','status',409); END IF;
  SELECT count(*) INTO v_used FROM public.employees WHERE store_id=p_store_id AND status<>'removed' AND deleted_at IS NULL;
  IF p_seat_limit IS NOT NULL AND v_used>=p_seat_limit THEN
   RETURN jsonb_build_object('error','STAFF_LIMIT_REACHED','status',409,'staff_limit',p_seat_limit,'staff_used',v_used); END IF;
  SELECT id INTO v_staff_id FROM public.users_custom WHERE email=p_intent->>'email' AND email_verified=true;
  IF v_staff_id IS NULL THEN RETURN jsonb_build_object('error','STAFF_ACCOUNT_VERIFICATION_REQUIRED','status',409); END IF;
  INSERT INTO public.employees(store_id,email,full_name,role,permissions,created_by,user_id,status,is_active)
   VALUES(p_store_id,p_intent->>'email',p_intent->>'full_name',p_intent->>'role',p_intent->'permissions',p_actor_id,v_staff_id,
    CASE WHEN v_staff_id IS NULL THEN 'invited' ELSE 'active' END,true) RETURNING * INTO v_employee;
  v_status:=201; v_action:='employee.created';
 ELSE
  SELECT * INTO v_employee FROM public.employees WHERE id=p_employee_id AND store_id=p_store_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('error','FORBIDDEN','status',403); END IF;
  IF p_expected_updated_at IS NULL THEN RETURN jsonb_build_object('error','STAFF_VERSION_REQUIRED','status',400); END IF;
  IF v_employee.updated_at IS DISTINCT FROM p_expected_updated_at OR v_employee.deleted_at IS NOT NULL OR v_employee.status='removed' THEN
   RETURN jsonb_build_object('error','STAFF_VERSION_CONFLICT','status',409); END IF;
  v_before:=to_jsonb(v_employee);
  IF p_operation='update' THEN
   UPDATE public.employees SET role=coalesce(p_intent->>'role',role),permissions=p_intent->'permissions',updated_at=clock_timestamp()
    WHERE id=p_employee_id AND store_id=p_store_id RETURNING * INTO v_employee;
   v_action:='employee.updated';
  ELSE
   UPDATE public.employees SET status='removed',is_active=false,deleted_at=clock_timestamp(),updated_at=clock_timestamp()
    WHERE id=p_employee_id AND store_id=p_store_id RETURNING * INTO v_employee;
   v_action:='employee.removed';
  END IF;
  v_status:=200;
 END IF;
 v_response:=CASE WHEN p_operation='remove' THEN jsonb_build_object('deleted',true) ELSE to_jsonb(v_employee) END;
 INSERT INTO public.audit_logs(actor_id,actor_type,actor_email,action,resource_type,resource_id,old_values,new_values,metadata)
 VALUES(p_actor_id,'user',v_actor.email,v_action,'employee',v_employee.id,v_before,to_jsonb(v_employee),
  jsonb_build_object('store_id',p_store_id,'request_id',p_request_id));
 INSERT INTO public.idempotency_keys(site_id,key,scope,request_hash,response_hash,response_body,status,status_code,resource_type,resource_id,request_id,expires_at)
 VALUES(p_store_id,p_key,v_scope,v_hash,encode(sha256(convert_to(v_response::text,'UTF8')),'hex'),v_response,'completed',v_status,'employee',v_employee.id,p_request_id,now()+interval '24 hours');
 RETURN jsonb_build_object('data',v_response,'status',v_status,'replayed',false);
EXCEPTION WHEN unique_violation THEN
 GET STACKED DIAGNOSTICS v_constraint=CONSTRAINT_NAME;
 IF v_constraint='employees_email_key' THEN
  RETURN jsonb_build_object('error','EMPLOYEE_ALREADY_EXISTS','status',409);
 END IF;
 RAISE;
END

BEGIN
 IF OLD.store_id IS NULL AND NEW.store_id IS NOT NULL THEN RAISE EXCEPTION 'Legacy platform invitation cannot become a merchant invitation'; END IF;
 IF OLD.store_id IS NOT NULL THEN
  IF ROW(NEW.store_id,NEW.employee_id,NEW.email,NEW.role,NEW.token,NEW.invited_by,NEW.expires_at,NEW.member_updated_at,
    NEW.permissions_snapshot,NEW.store_name_snapshot,NEW.accept_origin,NEW.sender_snapshot)
    IS DISTINCT FROM ROW(OLD.store_id,OLD.employee_id,OLD.email,OLD.role,OLD.token,OLD.invited_by,OLD.expires_at,OLD.member_updated_at,
    OLD.permissions_snapshot,OLD.store_name_snapshot,OLD.accept_origin,OLD.sender_snapshot) THEN
   RAISE EXCEPTION 'Merchant invitation intent is immutable; reissue through the canonical owner'; END IF;
  IF OLD.accepted_at IS NOT NULL AND ROW(NEW.accepted_at,NEW.accepted_by) IS DISTINCT FROM ROW(OLD.accepted_at,OLD.accepted_by) THEN
   RAISE EXCEPTION 'Accepted merchant invitation cannot be rewritten'; END IF;
  IF OLD.revoked_at IS NOT NULL AND NEW.revoked_at IS DISTINCT FROM OLD.revoked_at THEN RAISE EXCEPTION 'Revoked merchant invitation cannot be reopened'; END IF;
 END IF;
 RETURN NEW;
END

DECLARE v_site public.sites;v_actor public.users_custom;v_employee public.employees;v_before jsonb;v_policy jsonb;
 v_receipt public.idempotency_keys;v_hash text;v_scope text;v_used integer;v_invite public.employee_invites;v_response jsonb;v_constraint text;
BEGIN
 SELECT * INTO v_site FROM public.sites WHERE id=p_store_id AND deleted_at IS NULL FOR UPDATE;
 SELECT * INTO v_actor FROM public.users_custom WHERE id=p_actor_id;
 IF v_site.id IS NULL OR v_actor.id IS NULL OR NOT(coalesce(v_site.custom_user_id=p_actor_id,false) OR coalesce(v_site.user_id=p_actor_id,false))
  OR(p_bound_site_id IS NOT NULL AND p_bound_site_id<>p_store_id) THEN RETURN jsonb_build_object('error','FORBIDDEN','status',403); END IF;
 IF p_key IS NULL OR length(p_key) NOT BETWEEN 8 AND 200 OR p_intent IS NULL OR jsonb_typeof(p_intent)<>'object' THEN
  RETURN jsonb_build_object('error','VALIDATION','status',400); END IF;
 v_scope:='merchant-staff-invite-v1:'||p_actor_id::text||':issue';
 v_hash:=encode(sha256(convert_to(jsonb_build_object('actor',p_actor_id,'store',p_store_id,'intent',p_intent,
  'employee',p_employee_id,'expected',p_expected_updated_at)::text,'UTF8')),'hex');
 SELECT * INTO v_receipt FROM public.idempotency_keys WHERE site_id=p_store_id AND scope=v_scope AND key=p_key FOR UPDATE;
 IF FOUND THEN
  IF v_receipt.request_hash<>v_hash THEN RETURN jsonb_build_object('error','IDEMPOTENCY_CONFLICT','status',409); END IF;
  IF v_receipt.status<>'completed' OR v_receipt.response_body IS NULL OR v_receipt.deleted_at IS NOT NULL THEN
   RETURN jsonb_build_object('error','STAFF_STATE_UNAVAILABLE','status',503); END IF;
  RETURN jsonb_build_object('data',v_receipt.response_body,'status',201,'replayed',true);
 END IF;
 IF p_invite_id IS NULL OR p_token_hash IS NULL OR p_token_hash !~ '^[a-f0-9]{64}$'
  OR p_expires_at IS NULL OR p_expires_at<=clock_timestamp() OR p_expires_at>clock_timestamp()+interval '24 hours 5 minutes'
  OR nullif(p_accept_origin,'') IS NULL OR nullif(p_sender,'') IS NULL
  OR p_intent->>'role' IS NULL OR p_intent->>'role' NOT IN('manager','editor','fulfillment','marketing','support','viewer','staff')
  OR jsonb_typeof(p_intent->'permissions') IS DISTINCT FROM 'object' OR(p_intent->'permissions')-'granted'<>'{}'::jsonb
  OR jsonb_typeof(p_intent->'permissions'->'granted') IS DISTINCT FROM 'array'
  OR nullif(p_intent->>'email','') IS NULL OR p_intent->>'email'<>lower(trim(p_intent->>'email')) THEN
  RETURN jsonb_build_object('error','VALIDATION','status',400); END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_intent->'permissions'->'granted') g WHERE jsonb_typeof(g)<>'string'
  OR g#>>'{}' NOT IN('products:read','products:write','orders:read','orders:write','customers:read','customers:write',
   'content:write','marketing:write','shipping:write','returns:write','reports:read','settings:write')) THEN
  RETURN jsonb_build_object('error','VALIDATION','status',400); END IF;
 IF p_employee_id IS NULL THEN
  v_policy:=public.merchant_staff_policy_snapshot_v1(p_actor_id,p_store_id,p_bound_site_id);
  IF p_policy_hash IS NULL OR v_policy->>'source_hash' IS DISTINCT FROM p_policy_hash OR p_seat_limit<0 THEN
   RETURN jsonb_build_object('error','STAFF_POLICY_CHANGED','status',409); END IF;
  SELECT count(*) INTO v_used FROM public.employees WHERE store_id=p_store_id AND status<>'removed' AND deleted_at IS NULL;
  IF p_seat_limit IS NOT NULL AND v_used>=p_seat_limit THEN RETURN jsonb_build_object('error','STAFF_LIMIT_REACHED','status',409); END IF;
  INSERT INTO public.employees(store_id,email,full_name,role,permissions,created_by,status,is_active)
   VALUES(p_store_id,p_intent->>'email',p_intent->>'full_name',p_intent->>'role',p_intent->'permissions',p_actor_id,'invited',true) RETURNING * INTO v_employee;
 ELSE
  SELECT * INTO v_employee FROM public.employees WHERE id=p_employee_id AND store_id=p_store_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('error','FORBIDDEN','status',403); END IF;
  IF p_expected_updated_at IS NULL OR v_employee.updated_at IS DISTINCT FROM p_expected_updated_at
   OR v_employee.email IS DISTINCT FROM p_intent->>'email' OR v_employee.status<>'invited' OR v_employee.user_id IS NOT NULL
   OR v_employee.deleted_at IS NOT NULL OR v_employee.is_active IS DISTINCT FROM true THEN
   RETURN jsonb_build_object('error','STAFF_VERSION_CONFLICT','status',409); END IF;
  v_before:=to_jsonb(v_employee);
  UPDATE public.employee_invites SET revoked_at=clock_timestamp() WHERE store_id=p_store_id AND employee_id=p_employee_id AND accepted_at IS NULL AND revoked_at IS NULL;
  UPDATE public.employees SET full_name=p_intent->>'full_name',role=p_intent->>'role',permissions=p_intent->'permissions',updated_at=clock_timestamp()
   WHERE id=p_employee_id AND store_id=p_store_id RETURNING * INTO v_employee;
 END IF;
 INSERT INTO public.employee_invites(id,store_id,employee_id,email,role,token,invited_by,expires_at,member_updated_at,permissions_snapshot,
  store_name_snapshot,accept_origin,sender_snapshot)
 VALUES(p_invite_id,p_store_id,v_employee.id,v_employee.email,v_employee.role,p_token_hash,p_actor_id,p_expires_at,v_employee.updated_at,v_employee.permissions,
  coalesce(v_site.name,v_site.store_name,'your store'),p_accept_origin,p_sender) RETURNING * INTO v_invite;
 INSERT INTO public.platform_queue_jobs(site_id,event_id,queue_name,job_type,payload,idempotency_key,request_id,max_attempts,created_by,updated_by)
 VALUES(p_store_id,p_invite_id,'notification-jobs','email.employee_invite',jsonb_build_object('invitation_id',p_invite_id),
  'staff-invite-email:'||p_invite_id::text,p_request_id,10,p_actor_id,p_actor_id);
 INSERT INTO public.audit_logs(actor_id,actor_type,actor_email,action,resource_type,resource_id,old_values,new_values,metadata)
 VALUES(p_actor_id,'user',v_actor.email,'employee.invited','employee',v_employee.id,v_before,to_jsonb(v_employee),jsonb_build_object('store_id',p_store_id,'invitation_id',p_invite_id,'request_id',p_request_id));
 v_response:=jsonb_build_object('employee',to_jsonb(v_employee),'invitation',jsonb_build_object('id',p_invite_id,'store_id',p_store_id,
  'expires_at',p_expires_at,'accept_origin',p_accept_origin,'token_hash',p_token_hash,'delivery_status','queued','status','pending'));
 INSERT INTO public.idempotency_keys(site_id,key,scope,request_hash,response_hash,response_body,status,status_code,resource_type,resource_id,request_id,expires_at)
 VALUES(p_store_id,p_key,v_scope,v_hash,encode(sha256(convert_to(v_response::text,'UTF8')),'hex'),v_response,'completed',201,'employee_invite',p_invite_id,p_request_id,now()+interval '24 hours');
 RETURN jsonb_build_object('data',v_response,'status',201,'replayed',false);
EXCEPTION WHEN unique_violation THEN
 GET STACKED DIAGNOSTICS v_constraint=CONSTRAINT_NAME;
 IF v_constraint='employees_email_key' THEN RETURN jsonb_build_object('error','EMPLOYEE_ALREADY_EXISTS','status',409); END IF;
 RAISE;
END

DECLARE v_invite public.employee_invites;v_site public.sites;v_actor public.users_custom;v_employee public.employees;
 v_receipt public.idempotency_keys;v_hash text;v_scope text;v_before jsonb;v_response jsonb;
BEGIN
 SELECT * INTO v_invite FROM public.employee_invites WHERE id=p_invite_id AND store_id IS NOT NULL;
 IF NOT FOUND THEN RETURN jsonb_build_object('error','STAFF_INVITATION_UNAVAILABLE','status',403); END IF;
 SELECT * INTO v_site FROM public.sites WHERE id=v_invite.store_id AND deleted_at IS NULL FOR UPDATE;
 SELECT * INTO v_invite FROM public.employee_invites WHERE id=p_invite_id FOR UPDATE;
 SELECT * INTO v_actor FROM public.users_custom WHERE id=p_actor_id;
 SELECT * INTO v_employee FROM public.employees WHERE id=v_invite.employee_id AND store_id=v_invite.store_id FOR UPDATE;
 IF v_actor.id IS NULL OR v_actor.email_verified IS DISTINCT FROM true OR v_actor.email IS DISTINCT FROM v_invite.email
  OR v_site.id IS NULL OR NOT(coalesce(v_site.custom_user_id=v_invite.invited_by,false) OR coalesce(v_site.user_id=v_invite.invited_by,false))
  OR v_invite.token IS DISTINCT FROM p_token_hash OR v_invite.revoked_at IS NOT NULL OR v_invite.expires_at<=clock_timestamp()
  OR(p_bound_site_id IS NOT NULL AND p_bound_site_id<>v_invite.store_id)
  OR v_employee.id IS NULL OR v_employee.deleted_at IS NOT NULL OR v_employee.is_active IS DISTINCT FROM true THEN
  RETURN jsonb_build_object('error','STAFF_INVITATION_UNAVAILABLE','status',403); END IF;
 IF p_key IS NULL OR length(p_key) NOT BETWEEN 8 AND 200 THEN RETURN jsonb_build_object('error','VALIDATION','status',400); END IF;
 v_scope:='merchant-staff-invite-v1:'||p_actor_id::text||':accept';
 v_hash:=encode(sha256(convert_to(jsonb_build_object('actor',p_actor_id,'store',v_invite.store_id,'invite',p_invite_id,'token_hash',p_token_hash)::text,'UTF8')),'hex');
 SELECT * INTO v_receipt FROM public.idempotency_keys WHERE site_id=v_invite.store_id AND scope=v_scope AND key=p_key FOR UPDATE;
 IF FOUND THEN
  IF v_receipt.request_hash<>v_hash THEN RETURN jsonb_build_object('error','IDEMPOTENCY_CONFLICT','status',409); END IF;
  IF v_employee.status<>'active' OR v_employee.user_id IS DISTINCT FROM p_actor_id THEN RETURN jsonb_build_object('error','STAFF_INVITATION_UNAVAILABLE','status',403); END IF;
  IF v_receipt.status<>'completed' OR v_receipt.response_body IS NULL OR v_receipt.deleted_at IS NOT NULL THEN RETURN jsonb_build_object('error','STAFF_STATE_UNAVAILABLE','status',503); END IF;
  RETURN jsonb_build_object('data',v_receipt.response_body,'status',200,'replayed',true);
 END IF;
 IF v_invite.accepted_at IS NULL THEN
  IF v_employee.status<>'invited' OR v_employee.user_id IS NOT NULL OR v_employee.updated_at IS DISTINCT FROM v_invite.member_updated_at
   OR v_employee.role IS DISTINCT FROM v_invite.role OR v_employee.permissions IS DISTINCT FROM v_invite.permissions_snapshot THEN
   RETURN jsonb_build_object('error','STAFF_VERSION_CONFLICT','status',409); END IF;
  v_before:=to_jsonb(v_employee);
  UPDATE public.employees SET user_id=p_actor_id,status='active',updated_at=clock_timestamp()
   WHERE id=v_employee.id AND store_id=v_invite.store_id RETURNING * INTO v_employee;
  UPDATE public.employee_invites SET accepted_at=clock_timestamp(),accepted_by=p_actor_id WHERE id=p_invite_id;
  INSERT INTO public.audit_logs(actor_id,actor_type,actor_email,action,resource_type,resource_id,old_values,new_values,metadata)
  VALUES(p_actor_id,'user',v_actor.email,'employee.invite.accepted','employee',v_employee.id,v_before,to_jsonb(v_employee),
   jsonb_build_object('store_id',v_invite.store_id,'invitation_id',p_invite_id,'request_id',p_request_id));
 ELSIF v_invite.accepted_by IS DISTINCT FROM p_actor_id OR v_employee.user_id IS DISTINCT FROM p_actor_id OR v_employee.status<>'active' THEN
  RETURN jsonb_build_object('error','STAFF_INVITATION_UNAVAILABLE','status',403);
 END IF;
 v_response:=jsonb_build_object('employee',to_jsonb(v_employee),'store_handle',v_site.subdomain,'accepted',true);
 INSERT INTO public.idempotency_keys(site_id,key,scope,request_hash,response_hash,response_body,status,status_code,resource_type,resource_id,request_id,expires_at)
 VALUES(v_invite.store_id,p_key,v_scope,v_hash,encode(sha256(convert_to(v_response::text,'UTF8')),'hex'),v_response,'completed',200,'employee_invite',p_invite_id,p_request_id,now()+interval '24 hours');
 RETURN jsonb_build_object('data',v_response,'status',200,'replayed',false);
END

DECLARE r record;v_count integer:=0;
BEGIN
 FOR r IN SELECT id,locked_by FROM public.platform_queue_jobs
  WHERE queue_name='notification-jobs' AND job_type='email.employee_invite' AND status='running'
   AND deleted_at IS NULL AND locked_by IS NOT NULL AND locked_at<clock_timestamp()-interval '120 seconds'
  ORDER BY locked_at,id LIMIT least(greatest(coalesce(p_limit,25),1),100) FOR UPDATE SKIP LOCKED LOOP
  PERFORM public.fail_platform_queue_job(r.id,r.locked_by,'Staff invitation worker lease expired',30,
   jsonb_build_object('consumer_runtime','services/queue-workers','lease_recovered',true));
  v_count:=v_count+1;
 END LOOP;
 RETURN v_count;
END

DECLARE v_permission jsonb;v_state jsonb;v_overview jsonb;v_since timestamptz:=clock_timestamp()-interval '30 days';
BEGIN
 IF p_kind IS NULL OR p_kind NOT IN('summary','analytics') THEN
  RETURN jsonb_build_object('accepted',false,'code','CONSOLE_OVERVIEW_QUERY_INVALID');
 END IF;
 v_permission:=public.console_permission_snapshot_v1(p_session_id,p_cookie_sha256,false);
 IF NOT coalesce((v_permission->>'accepted')::boolean,false) THEN RETURN v_permission; END IF;
 IF p_permission_hash IS NULL OR v_permission->>'evidence_hash' IS DISTINCT FROM p_permission_hash THEN
  RETURN jsonb_build_object('accepted',false,'code','PERMISSION_CHANGED');
 END IF;
 v_state:=v_permission->'session';
 -- The Gateway requires exec:view through the canonical resolver, then supplies
 -- this snapshot witness. Recheck under the existing session lock before reads.
 IF p_kind='summary' THEN
  SELECT jsonb_build_object(
   'total_users',(SELECT count(*) FROM public.users_custom),
   'total_stores',(SELECT count(*) FROM public.sites),
   'active_stores',(SELECT count(*) FROM public.sites WHERE status='published'),
   'total_subscriptions',(SELECT count(*) FROM public.subscriptions),
   'active_subscriptions',(SELECT count(*) FROM public.subscriptions WHERE status='active'),
   'total_employees',(SELECT count(*) FROM public.employees WHERE store_id IS NULL AND deleted_at IS NULL),
   'total_audit_logs',(SELECT count(*) FROM public.audit_logs),
   'monthly_revenue_paise',(SELECT coalesce(sum(amount_paid),0) FROM public.subscriptions WHERE status='active')) INTO v_overview;
 ELSE
  WITH counts AS(SELECT
   (SELECT count(*) FROM public.users_custom WHERE created_at>=v_since) AS users,
   (SELECT count(*) FROM public.sites WHERE created_at>=v_since) AS stores,
   (SELECT count(*) FROM public.subscriptions WHERE created_at>=v_since) AS subscriptions,
   (SELECT count(*) FROM public.audit_logs WHERE created_at>=v_since) AS audits)
  SELECT jsonb_build_object('period_days',30,'new_signups',users,'stores_created',stores,
   'subscriptions_created',subscriptions,'audit_events',audits,
   'signup_to_store_conversion_percent',CASE WHEN users>0 THEN round(stores::numeric/users*100,1) ELSE 0 END)
   INTO v_overview FROM counts;
 END IF;
 INSERT INTO public.audit_logs(actor_id,actor_type,actor_email,action,resource_type,resource_id,metadata)
 VALUES((v_state->>'actor_id')::uuid,'employee',v_state->>'email','console.'||p_kind||'.read','platform_overview',NULL,
  jsonb_build_object('permission_scope','exec:view','session_id',p_session_id,'aggregate_only',true));
 RETURN jsonb_build_object('accepted',true,'overview',v_overview);
END

DECLARE s public.sites%ROWTYPE;plan public.plans%ROWTYPE;existing public.subscriptions%ROWTYPE;created public.subscriptions%ROWTYPE;
 actor uuid;site uuid;plan_id uuid;gateway text;payment text;period text;amount bigint;tax bigint;total bigint;
 charge public.billing_history%ROWTYPE;source_ref text;free_id uuid;is_free boolean;tax_source uuid;invoice_id uuid;
 started timestamptz;finished timestamptz;promo timestamptz;constraint_name text;evidence jsonb;selected_tax jsonb;historical_cycle boolean:=false;consume_quote boolean:=true;
BEGIN
 IF p_input IS NULL OR jsonb_typeof(p_input)<>'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_input) k
  WHERE k NOT IN('user_id','store_id','plan_id','plan_slug','plan_name','billing_period','amount_paid','payment_gateway',
   'external_subscription_id','razorpay_order_id','razorpay_payment_id','period_start','period_end','promo_ends_at',
   'products_limit','invoice_number','invoice_description','tax_amount','total_amount',
   'subscription_checkout_id','subscription_checkout_key','subscription_checkout_request','subscription_tax_source_id','provider_invoice_evidence')) THEN
  RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_CONTEXT_INVALID');
 END IF;
 actor:=(p_input->>'user_id')::uuid;site:=(p_input->>'store_id')::uuid;plan_id:=(p_input->>'plan_id')::uuid;
 gateway:=p_input->>'payment_gateway';payment:=nullif(btrim(p_input->>'razorpay_payment_id'),'');period:=p_input->>'billing_period';
 amount:=(p_input->>'amount_paid')::bigint;tax:=(p_input->>'tax_amount')::bigint;total:=(p_input->>'total_amount')::bigint;
 -- 347: explicit retained free checkout context; the existing paid ABI remains intact.
 free_id:=nullif(p_input->>'subscription_checkout_id','')::uuid;is_free:=free_id IS NOT NULL;
 IF amount=0 AND NOT is_free THEN RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_CONTEXT_INVALID');END IF;
 started:=(p_input->>'period_start')::timestamptz;finished:=(p_input->>'period_end')::timestamptz;promo:=(p_input->>'promo_ends_at')::timestamptz;
 evidence:=p_input->'provider_invoice_evidence';
 IF actor IS NULL OR site IS NULL OR plan_id IS NULL OR period IS NULL OR period NOT IN('monthly','yearly')
  OR amount IS NULL OR amount<0 OR amount>2147483647 OR tax IS NULL OR tax<0 OR total IS NULL OR total<>amount OR tax>amount OR total>2147483647
  OR started IS NULL OR finished IS NULL OR finished<=started
  OR (gateway IS NOT NULL AND gateway NOT IN('razorpay','stripe')) OR (amount>0 AND gateway IS NULL)
  OR (gateway='razorpay' AND amount>0 AND payment IS NULL) OR (payment IS NOT NULL AND gateway IS DISTINCT FROM 'razorpay')
  OR coalesce(length(payment),0)>200 OR nullif(btrim(p_input->>'invoice_number'),'') IS NULL
  OR nullif(btrim(p_input->>'invoice_description'),'') IS NULL OR NOT(p_input?'products_limit') THEN
  RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_CONTEXT_INVALID');
 END IF;
 IF (p_input ?| ARRAY['subscription_checkout_id','subscription_checkout_key','subscription_checkout_request']) AND NOT is_free
  OR (is_free AND (amount<>0 OR tax<>0 OR total<>0 OR gateway IS NOT NULL OR payment IS NOT NULL
   OR p_input->>'razorpay_order_id' IS NOT NULL OR promo IS NOT NULL)) THEN
  RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_CONTEXT_INVALID'); END IF;
 IF evidence IS NOT NULL AND (
  jsonb_typeof(evidence) IS DISTINCT FROM 'object'
  OR EXISTS(SELECT 1 FROM jsonb_object_keys(evidence) k WHERE k NOT IN('phase','invoice_id','payment_id','order_id','subscription_reference','period_start','period_end','gross_minor'))
  OR evidence->>'phase' IS NULL OR evidence->>'phase' NOT IN('initial_with_upfront','base_cycle')
  OR NOT coalesce((evidence->>'invoice_id')~'^inv_[A-Za-z0-9]{1,116}$',false)
  OR NOT coalesce((evidence->>'payment_id')~'^pay_[A-Za-z0-9]{1,116}$',false)
  OR NOT coalesce((evidence->>'order_id')~'^order_[A-Za-z0-9]{1,114}$',false)
  OR NOT coalesce((evidence->>'subscription_reference')~'^sub_[A-Za-z0-9]{1,116}$',false)
  OR gateway IS DISTINCT FROM 'razorpay' OR evidence->>'payment_id' IS DISTINCT FROM payment
  OR evidence->>'subscription_reference' IS DISTINCT FROM p_input->>'external_subscription_id'
  OR jsonb_typeof(evidence->'gross_minor') IS DISTINCT FROM 'number' OR evidence->>'gross_minor' IS DISTINCT FROM amount::text
  OR (evidence->>'period_start')::timestamptz IS DISTINCT FROM started OR (evidence->>'period_end')::timestamptz IS DISTINCT FROM finished
  OR (p_input->>'razorpay_order_id' IS NOT NULL AND evidence->>'order_id' IS DISTINCT FROM p_input->>'razorpay_order_id')) THEN
  RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_CHECKOUT_CONFLICT');END IF;
 -- Global payment lock first, then the exact store. Different payments at the
 -- same store also serialize old-entitlement retirement with the new receipt.
 IF payment IS NOT NULL THEN PERFORM pg_advisory_xact_lock(hashtextextended('letbuyy:subscription:razorpay:'||payment,0));END IF;
 IF evidence IS NOT NULL THEN PERFORM pg_advisory_xact_lock(hashtextextended('letbuyy:subscription:invoice:'||(evidence->>'invoice_id'),0));END IF;
 SELECT * INTO s FROM public.sites WHERE id=site AND deleted_at IS NULL FOR UPDATE;
 IF NOT FOUND OR NOT coalesce(actor=s.custom_user_id OR actor=s.user_id,false) OR NOT EXISTS(SELECT 1 FROM public.users_custom WHERE id=actor) THEN
  RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_OWNER_REQUIRED');
 END IF;
 -- The table admission lock is already held by the store SELECT above. A
 -- call compiled before rollback may have waited on that lock; verify the
 -- currently bound function's own SET attribute, not the caller/session GUC.
 -- Read the live catalog binding even for a cached frame; admit exact supported versions only.
 IF is_free AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_proc current_binding
  WHERE current_binding.oid='public.activate_merchant_subscription_v1(jsonb)'::pg_catalog.regprocedure
   AND current_binding.proconfig && ARRAY['application_name=activate_merchant_subscription_v1:347','application_name=activate_merchant_subscription_v1:347:360']::text[]) THEN
  RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_CONTEXT_INVALID'); END IF;
 IF is_free THEN
  SELECT * INTO charge FROM public.billing_history WHERE id=free_id FOR UPDATE;
  IF NOT FOUND OR charge.deleted_at IS NOT NULL OR charge.site_id IS DISTINCT FROM site OR charge.store_id IS DISTINCT FROM site
   OR charge.user_id IS DISTINCT FROM actor OR charge.amount IS DISTINCT FROM 0 OR charge.currency IS DISTINCT FROM 'INR'
   OR charge.payment_gateway IS NOT NULL OR charge.provider_payment_reference IS NOT NULL
   OR charge.subscription_checkout->>'mode' IS DISTINCT FROM 'free_activation'
   OR charge.subscription_checkout->>'amount_minor' IS DISTINCT FROM '0'
   OR charge.subscription_checkout_reference IS DISTINCT FROM 'free_checkout:'||charge.id
   OR charge.subscription_checkout_reference IS DISTINCT FROM p_input->>'external_subscription_id'
   OR charge.subscription_checkout_key IS DISTINCT FROM p_input->>'subscription_checkout_key'
   OR charge.subscription_checkout_request IS DISTINCT FROM p_input->'subscription_checkout_request'
   OR charge.subscription_checkout_request->>'plan_slug' IS DISTINCT FROM p_input->>'plan_slug'
   OR charge.subscription_checkout_request->>'site_type' IS DISTINCT FROM s.site_type
   OR charge.subscription_checkout_request->>'billing_period' IS DISTINCT FROM period
   OR charge.subscription_checkout->'plan'->>'id' IS DISTINCT FROM plan_id::text
   OR charge.subscription_checkout->'plan'->>'slug' IS DISTINCT FROM p_input->>'plan_slug'
   OR charge.subscription_checkout->'plan'->>'name' IS DISTINCT FROM p_input->>'plan_name'
   OR charge.subscription_checkout->'plan'->'products_limit' IS DISTINCT FROM p_input->'products_limit'
   OR charge.billing_period IS DISTINCT FROM period THEN
   RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_CHECKOUT_CONFLICT'); END IF;
  IF charge.subscription_id IS NOT NULL THEN
   SELECT * INTO existing FROM public.subscriptions WHERE id=charge.subscription_id;
   IF NOT FOUND OR existing.deleted_at IS NOT NULL OR charge.payment_status IS DISTINCT FROM 'paid'
    OR existing.user_id IS DISTINCT FROM actor OR existing.store_id IS DISTINCT FROM site OR existing.site_id IS DISTINCT FROM site
    OR existing.plan_id IS DISTINCT FROM plan_id OR existing.plan IS DISTINCT FROM p_input->>'plan_slug'
    OR existing.billing_period IS DISTINCT FROM period OR existing.amount_paid IS DISTINCT FROM 0 OR existing.currency IS DISTINCT FROM 'INR'
    OR existing.payment_gateway IS NOT NULL OR existing.razorpay_payment_id IS NOT NULL OR existing.razorpay_order_id IS NOT NULL
    OR existing.external_subscription_id IS DISTINCT FROM charge.subscription_checkout_reference
    OR existing.current_period_start IS DISTINCT FROM charge.period_start OR existing.current_period_end IS DISTINCT FROM charge.period_end THEN
    RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_CHECKOUT_CONFLICT'); END IF;
   -- A completed intent may have been superseded. Read it; never reactivate it.
   RETURN jsonb_build_object('accepted',true,'subscription',to_jsonb(existing),'replayed',true);
  END IF;
  IF charge.payment_status IS DISTINCT FROM 'pending' THEN
   RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_CHECKOUT_CONFLICT'); END IF;
 END IF;
 IF payment IS NOT NULL THEN
  SELECT * INTO existing FROM public.subscriptions WHERE razorpay_payment_id=payment;
  IF FOUND THEN
   IF existing.deleted_at IS NOT NULL OR existing.store_id IS DISTINCT FROM site OR existing.site_id IS DISTINCT FROM site OR existing.user_id IS DISTINCT FROM actor
    OR (existing.plan_id IS NOT NULL AND existing.plan_id IS DISTINCT FROM plan_id) OR existing.plan IS DISTINCT FROM p_input->>'plan_slug'
    OR existing.billing_period IS DISTINCT FROM period OR existing.amount_paid IS DISTINCT FROM amount
    OR existing.currency IS DISTINCT FROM 'INR'
    OR (existing.subscription_tax_snapshot IS NOT NULL AND (
      existing.razorpay_order_id IS DISTINCT FROM nullif(p_input->>'razorpay_order_id','')
      OR existing.external_subscription_id IS DISTINCT FROM nullif(p_input->>'external_subscription_id','')
      OR (existing.subscription_tax_snapshot->>'tax_minor')::bigint IS DISTINCT FROM tax
      OR nullif(p_input->>'subscription_tax_source_id','')::uuid IS DISTINCT FROM
        (SELECT b.subscription_tax_source_id FROM public.billing_history b WHERE b.id=existing.subscription_tax_source_id)))
    OR (existing.razorpay_order_id IS NOT NULL AND existing.razorpay_order_id IS DISTINCT FROM p_input->>'razorpay_order_id')
    OR (existing.external_subscription_id IS NOT NULL AND existing.external_subscription_id IS DISTINCT FROM p_input->>'external_subscription_id') THEN
    RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_PAYMENT_CONFLICT');
   END IF;
   IF existing.subscription_tax_snapshot IS NOT NULL AND left(existing.external_subscription_id,4)='sub_' AND evidence IS NULL THEN
    RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_TAX_REVIEW_REQUIRED');END IF;
   IF evidence IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.billing_history b JOIN public.merchant_billing_invoices i ON i.billing_history_id=b.id
    WHERE b.id=existing.subscription_tax_source_id AND b.subscription_id=existing.id AND b.provider_payment_reference=payment
     AND i.metadata->'provider_invoice'=evidence AND b.period_start=started AND b.period_end=finished) THEN
    RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_PAYMENT_CONFLICT');END IF;
   RETURN jsonb_build_object('accepted',true,'subscription',to_jsonb(existing),'replayed',true);
  END IF;
  IF EXISTS(SELECT 1 FROM public.billing_history WHERE provider_payment_reference=payment)
   OR EXISTS(SELECT 1 FROM public.payment_transactions t WHERE t.gateway='razorpay' AND t.provider_payment_id=payment) THEN
   RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_PAYMENT_CONFLICT');
  END IF;
 END IF;
 IF amount>0 THEN
  tax_source:=nullif(p_input->>'subscription_tax_source_id','')::uuid;
  IF tax_source IS NULL THEN RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_TAX_REVIEW_REQUIRED');END IF;
  SELECT * INTO charge FROM public.billing_history WHERE id=tax_source FOR UPDATE;
  IF NOT FOUND OR charge.deleted_at IS NOT NULL OR charge.site_id IS DISTINCT FROM site OR charge.store_id IS DISTINCT FROM site OR charge.user_id IS DISTINCT FROM actor
   OR charge.currency IS DISTINCT FROM 'INR' OR charge.payment_gateway IS DISTINCT FROM gateway
   OR charge.subscription_checkout->'plan'->>'id' IS DISTINCT FROM plan_id::text
   OR charge.subscription_checkout->'plan'->>'slug' IS DISTINCT FROM p_input->>'plan_slug' OR charge.billing_period IS DISTINCT FROM period
   OR charge.subscription_checkout->'plan'->'products_limit' IS DISTINCT FROM p_input->'products_limit'
   OR charge.subscription_checkout_reference IS DISTINCT FROM coalesce(nullif(p_input->>'external_subscription_id',''),nullif(p_input->>'razorpay_order_id',''))
   OR charge.payment_status NOT IN('pending','paid') OR (charge.payment_status='paid' AND charge.subscription_checkout->>'mode'<>'razorpay_subscription') THEN
   RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_CHECKOUT_CONFLICT');END IF;
  IF charge.subscription_checkout->>'mode'='razorpay_subscription' AND evidence IS NULL THEN
   RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_TAX_REVIEW_REQUIRED');END IF;
  selected_tax:=charge.subscription_tax_snapshot;
  IF evidence IS NOT NULL THEN
   IF charge.subscription_checkout->>'mode' IS DISTINCT FROM 'razorpay_subscription' THEN RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_CHECKOUT_CONFLICT');END IF;
   IF evidence->>'phase'='base_cycle' THEN
    selected_tax:=charge.subscription_checkout->'recurring_tax_snapshot';
    consume_quote:=charge.amount=amount;
   ELSIF coalesce((charge.subscription_checkout->'charge_schedule'->>'upfront_gross_minor')::bigint,0)<=0 THEN
    RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_CHECKOUT_CONFLICT');END IF;
   IF EXISTS(SELECT 1 FROM public.merchant_billing_invoices i WHERE i.metadata->'provider_invoice'->>'invoice_id'=evidence->>'invoice_id')
    OR EXISTS(SELECT 1 FROM public.merchant_billing_invoices i WHERE i.metadata->'provider_invoice'->>'subscription_reference'=evidence->>'subscription_reference'
      AND (i.metadata->'provider_invoice'->>'period_start')::timestamptz=started AND (i.metadata->'provider_invoice'->>'period_end')::timestamptz=finished) THEN
    RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_PAYMENT_CONFLICT');END IF;
   IF evidence->>'phase'='initial_with_upfront' AND charge.payment_status<>'pending' THEN RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_PAYMENT_CONFLICT');END IF;
   historical_cycle:=EXISTS(SELECT 1 FROM public.subscriptions x WHERE x.store_id=site AND x.deleted_at IS NULL
     AND x.subscription_tax_snapshot IS NOT NULL AND x.current_period_start>started);
  END IF;
  IF NOT public.valid_subscription_tax_snapshot_360(selected_tax) OR (selected_tax->>'gross_minor')::bigint IS DISTINCT FROM amount
   OR (selected_tax->>'tax_minor')::bigint IS DISTINCT FROM tax OR amount IS DISTINCT FROM total
   OR selected_tax->'source'->>'actor_id' IS DISTINCT FROM actor::text OR selected_tax->'source'->>'site_id' IS DISTINCT FROM site::text THEN
   RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_CHECKOUT_CONFLICT');END IF;
 END IF;
 IF evidence IS NOT NULL THEN
  -- The quote was admitted against the active catalog before provider create.
  -- A later rename/inactivation cannot reinterpret an already consented cycle.
  plan:=jsonb_populate_record(NULL::public.plans,charge.subscription_checkout->'plan');
 ELSE
  SELECT * INTO plan FROM public.plans WHERE id=plan_id AND site_type=s.site_type AND slug=p_input->>'plan_slug' AND is_active=true FOR SHARE;
  IF NOT FOUND THEN RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_PLAN_CHANGED');END IF;
 END IF;
 INSERT INTO public.subscriptions(user_id,store_id,site_id,plan,plan_id,status,billing_period,current_period_start,current_period_end,promo_ends_at,
  payment_gateway,external_subscription_id,razorpay_order_id,razorpay_payment_id,amount_paid,currency,products_limit,stores_limit,idempotency_key,subscription_tax_snapshot,subscription_tax_source_id)
 VALUES(actor,site,site,plan.slug,plan.id,CASE WHEN historical_cycle THEN 'cancelled' ELSE 'active' END,period,started,finished,promo,gateway,p_input->>'external_subscription_id',
  p_input->>'razorpay_order_id',payment,amount,'INR',(p_input->>'products_limit')::integer,1,
  CASE WHEN is_free THEN 'free_checkout:'||free_id WHEN payment IS NOT NULL THEN 'razorpay_payment:'||payment ELSE NULL END,CASE WHEN amount>0 THEN selected_tax ELSE NULL END,CASE WHEN amount>0 THEN charge.id ELSE NULL END) RETURNING * INTO created;
 IF NOT historical_cycle THEN
  UPDATE public.subscriptions SET status='cancelled',cancelled_at=started WHERE store_id=site AND status='active' AND id<>created.id;
  UPDATE public.sites SET trial_status=CASE WHEN amount>0 THEN 'paid' ELSE 'active' END,updated_at=started WHERE id=site;
 END IF;
 IF charge.id IS NOT NULL AND charge.payment_status='pending' AND consume_quote THEN
  UPDATE public.billing_history SET subscription_id=created.id,invoice_number=p_input->>'invoice_number',
   description=p_input->>'invoice_description',tax_amount=tax,total_amount=total,payment_id=CASE WHEN is_free THEN charge.subscription_checkout_reference ELSE payment END,
   provider_payment_reference=payment,payment_status='paid',period_start=started,period_end=finished,updated_at=now()
   WHERE id=charge.id;
  invoice_id:=charge.id;
 ELSE
 INSERT INTO public.billing_history(user_id,store_id,site_id,subscription_id,invoice_number,description,amount,currency,tax_amount,total_amount,
  payment_gateway,payment_id,provider_payment_reference,payment_status,billing_period,period_start,period_end,subscription_tax_snapshot,subscription_tax_source_id)
 VALUES(actor,site,site,created.id,p_input->>'invoice_number',p_input->>'invoice_description',amount,'INR',tax,total,gateway,
  coalesce(payment,p_input->>'external_subscription_id',p_input->>'razorpay_order_id'),payment,'paid',period,started,finished,CASE WHEN amount>0 THEN selected_tax ELSE NULL END,CASE WHEN amount>0 THEN charge.id ELSE NULL END) RETURNING id INTO invoice_id;
 END IF;
 IF amount>0 THEN
  UPDATE public.subscriptions SET subscription_tax_source_id=invoice_id WHERE id=created.id;
  PERFORM public.issue_subscription_tax_invoice_360(invoice_id,evidence);
 END IF;
 INSERT INTO public.audit_logs(actor_id,actor_type,action,resource_type,resource_id,metadata)
 VALUES(actor,'user','merchant_subscription.activated','subscription',created.id,jsonb_build_object('site_id',site,'provider',gateway,'payment_reference',payment)
  ||CASE WHEN amount>0 THEN jsonb_build_object('subscription_tax_source_id',invoice_id,'subscription_tax_policy','D-SUB-TAX-INCLUSIVE-V1') ELSE '{}'::jsonb END
  ||CASE WHEN is_free THEN jsonb_build_object('checkout_receipt_id',charge.id,'request_hash',encode(sha256(convert_to(charge.subscription_checkout_request::text,'UTF8')),'hex')) ELSE '{}'::jsonb END);
 IF is_free THEN
  UPDATE public.idempotency_keys SET status='completed',locked_until=NULL,status_code=201,
   response_body=jsonb_build_object('billing_history_id',charge.id,'subscription_id',created.id)
   WHERE site_id=site AND scope='subscription.checkout:'||actor AND key=charge.subscription_checkout_key
    AND resource_id=charge.id AND request_hash=encode(sha256(convert_to(charge.subscription_checkout_request::text,'UTF8')),'hex');
  IF NOT FOUND THEN RAISE EXCEPTION 'free subscription checkout completion source unavailable'; END IF;
 END IF;
 RETURN jsonb_build_object('accepted',true,'subscription',to_jsonb(created),'replayed',false);
EXCEPTION WHEN unique_violation THEN
 GET STACKED DIAGNOSTICS constraint_name=CONSTRAINT_NAME;
 IF constraint_name IN('subscriptions_razorpay_payment_global_uidx','billing_history_provider_payment_reference_uidx','merchant_billing_provider_invoice_360_uidx') THEN
  RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_PAYMENT_CONFLICT');
 END IF;
 RAISE;
END

BEGIN
 IF current_user<>'service_role' AND current_user<>(SELECT pg_get_userbyid(relowner) FROM pg_class WHERE oid=TG_RELID) THEN
  RAISE EXCEPTION 'subscription receipt mutation requires the canonical backend' USING ERRCODE='42501';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END

DECLARE s public.sites%ROWTYPE;c public.billing_history%ROWTYPE;
BEGIN
 SELECT * INTO s FROM public.sites WHERE id=p_site AND deleted_at IS NULL FOR SHARE;
 IF NOT FOUND OR NOT coalesce(p_actor=s.custom_user_id OR p_actor=s.user_id,false) THEN
  RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_OWNER_REQUIRED'); END IF;
 SELECT * INTO c FROM public.billing_history WHERE id=p_charge AND site_id=p_site AND user_id=p_actor AND deleted_at IS NULL FOR UPDATE;
 IF NOT FOUND OR c.subscription_checkout IS NULL OR c.subscription_checkout->>'mode'='free_activation' OR nullif(btrim(p_reference),'') IS NULL OR length(p_reference)>200
  OR (c.subscription_checkout_reference IS NOT NULL AND c.subscription_checkout_reference<>p_reference) THEN
  RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_CHECKOUT_CONFLICT'); END IF;
 UPDATE public.billing_history SET subscription_checkout_reference=p_reference,
  subscription_checkout=subscription_checkout||jsonb_build_object('short_url',p_short_url),updated_at=now() WHERE id=c.id RETURNING * INTO c;
 UPDATE public.idempotency_keys SET status='completed',locked_until=NULL,status_code=200,response_body=jsonb_build_object('billing_history_id',c.id)
  WHERE site_id=p_site AND scope='subscription.checkout:'||p_actor AND key=c.subscription_checkout_key AND resource_id=c.id;
 RETURN jsonb_build_object('accepted',true,'charge',to_jsonb(c));
END

DECLARE s public.sites%ROWTYPE;c public.billing_history%ROWTYPE;retained public.subscriptions%ROWTYPE;plan public.plans%ROWTYPE;paid public.billing_history%ROWTYPE;retained_evidence jsonb;
BEGIN
 SELECT * INTO s FROM public.sites WHERE id=p_site AND deleted_at IS NULL;
 IF NOT FOUND OR NOT coalesce(p_actor=s.custom_user_id OR p_actor=s.user_id,false) THEN
  RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_OWNER_REQUIRED'); END IF;
 SELECT * INTO c FROM public.billing_history WHERE subscription_checkout_reference=p_reference;
 IF FOUND THEN
  IF c.subscription_checkout->>'mode'='free_activation' OR c.deleted_at IS NOT NULL OR c.site_id IS DISTINCT FROM p_site OR c.user_id IS DISTINCT FROM p_actor
   OR c.subscription_checkout->'plan'->>'slug' IS DISTINCT FROM p_plan_slug OR c.billing_period IS DISTINCT FROM p_period THEN
   RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_CHECKOUT_CONFLICT'); END IF;
  IF c.subscription_tax_snapshot IS NULL AND c.payment_status='paid' AND c.payment_id=p_payment
   AND EXISTS(SELECT 1 FROM public.subscriptions legacy WHERE legacy.id=c.subscription_id AND legacy.razorpay_payment_id=p_payment AND legacy.user_id=p_actor AND legacy.store_id=p_site AND legacy.deleted_at IS NULL) THEN
   RETURN jsonb_build_object('accepted',true,'charge',to_jsonb(c)||jsonb_build_object('legacy_completed',true));END IF;
  IF c.subscription_checkout->>'mode'='razorpay_subscription' AND c.subscription_tax_snapshot IS NOT NULL THEN
   SELECT * INTO paid FROM public.billing_history WHERE provider_payment_reference=p_payment AND payment_status='paid' AND deleted_at IS NULL
    AND subscription_tax_source_id=c.id AND site_id=p_site AND user_id=p_actor;
   IF FOUND THEN
    SELECT i.metadata->'provider_invoice' INTO retained_evidence FROM public.merchant_billing_invoices i
     WHERE i.billing_history_id=paid.id AND i.site_id=p_site AND i.subscription_id=paid.subscription_id
      AND i.metadata->>'policy_version'='D-SUB-TAX-INCLUSIVE-V1';
    IF retained_evidence IS NOT NULL THEN
     IF retained_evidence->>'payment_id' IS DISTINCT FROM p_payment OR retained_evidence->>'subscription_reference' IS DISTINCT FROM p_reference
      OR retained_evidence->>'gross_minor' IS DISTINCT FROM paid.amount::text
      OR (retained_evidence->>'period_start')::timestamptz IS DISTINCT FROM paid.period_start
      OR (retained_evidence->>'period_end')::timestamptz IS DISTINCT FROM paid.period_end THEN
      RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_TAX_REVIEW_REQUIRED');END IF;
     RETURN jsonb_build_object('accepted',true,'charge',to_jsonb(c)||jsonb_build_object('retained_invoice_evidence',retained_evidence));
    END IF;
   END IF;
  END IF;
  RETURN jsonb_build_object('accepted',true,'charge',to_jsonb(c));
 END IF;
 -- A retained paid receipt can be read back; it cannot authorize a new purchase.
 SELECT * INTO retained FROM public.subscriptions WHERE razorpay_payment_id=p_payment AND deleted_at IS NULL;
 IF FOUND AND retained.user_id=p_actor AND retained.store_id=p_site AND retained.plan=p_plan_slug AND retained.billing_period=p_period THEN
  SELECT * INTO plan FROM public.plans WHERE slug=retained.plan AND site_type=s.site_type;
  RETURN jsonb_build_object('accepted',true,'charge',jsonb_build_object('amount',retained.amount_paid,'currency','INR','legacy_completed',true,'payment_status','paid','subscription_id',retained.id,
   'subscription_checkout_reference',p_reference,'subscription_checkout',jsonb_build_object('plan',to_jsonb(plan),'mode',
    CASE WHEN p_reference LIKE 'sub_%' THEN 'razorpay_subscription' ELSE 'razorpay_order' END)));
 END IF;
 RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_CHECKOUT_CONFLICT');
END

DECLARE v_identity jsonb;v_state jsonb;v_principal public.principals%ROWTYPE;v_new public.sessions_v2%ROWTYPE;
 v_factor jsonb;v_fingerprint text;v_retired jsonb;v_guard jsonb;v_failures integer;v_last bigint;v_locked timestamptz;v_current bigint;v_result jsonb;v_reason text;
BEGIN
 IF p_factor_fingerprint IS NULL OR p_factor_fingerprint !~ '^[0-9a-f]{64}$' THEN RETURN jsonb_build_object('accepted',false,'code','CONSOLE_FACTOR_PROOF_REQUIRED');END IF;
 IF p_actor_id IS NULL OR p_session_id IS NULL OR p_session_id=p_previous_session_id OR p_mfa_verified_at IS NULL THEN
  RETURN jsonb_build_object('accepted',false,'code','CONSOLE_SESSION_INVALID');
 END IF;
 v_identity:=public.resolve_console_operator_v1(p_email,p_actor_id);
 IF NOT coalesce((v_identity->>'accepted')::boolean,false) THEN RETURN v_identity; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('letbuyy:console-actor:'||p_actor_id::text,0));
 -- Exact committed-response retry may recover its own still-live target. It
 -- cannot mint another session, revive a revoked one or change its predecessor.
 SELECT * INTO v_new FROM public.sessions_v2 WHERE id=p_session_id FOR UPDATE;
 IF FOUND THEN
  IF v_new.metadata->>'console_factor_fingerprint' IS DISTINCT FROM p_factor_fingerprint THEN RETURN jsonb_build_object('accepted',false,'code','CONSOLE_FACTOR_PROOF_REQUIRED');END IF;
  IF v_new.metadata->>'console_mfa_previous_session' IS DISTINCT FROM p_previous_session_id::text
   OR v_new.metadata->>'console_mfa_previous_digest' IS DISTINCT FROM p_previous_cookie_sha256
   OR (v_new.metadata->>'console_mfa_counter')::bigint IS DISTINCT FROM p_counter THEN
   RETURN jsonb_build_object('accepted',false,'code','CONSOLE_SESSION_INVALID');
  END IF;
  v_state:=public.console_session_state_v1(p_session_id,p_cookie_sha256);
  IF NOT coalesce((v_state->>'accepted')::boolean,false) THEN RETURN v_state; END IF;
  RETURN jsonb_build_object('accepted',true,'verified',true,'state',v_state,'replayed',true);
 END IF;
 v_state:=public.console_session_state_v1(p_previous_session_id,p_previous_cookie_sha256);
 IF NOT coalesce((v_state->>'accepted')::boolean,false) OR v_state->>'actor_id' IS DISTINCT FROM p_actor_id::text THEN
  RETURN jsonb_build_object('accepted',false,'code','CONSOLE_PREVIOUS_SESSION_REQUIRED');
 END IF;
 SELECT p.* INTO v_principal FROM public.principals p JOIN public.sessions_v2 s ON s.principal_id=p.id
  WHERE s.id=p_previous_session_id FOR UPDATE OF p;
 IF NOT FOUND THEN RETURN jsonb_build_object('accepted',false,'code','CONSOLE_SESSION_INVALID');END IF;
 v_factor:=coalesce(v_principal.metadata->'console_mfa_factor','{}'::jsonb);
 v_fingerprint:=v_factor->>'fingerprint';v_retired:=coalesce(v_factor->'retired','[]'::jsonb);
 IF jsonb_typeof(v_retired)<>'array' THEN RAISE EXCEPTION 'Invalid retained Console factor state';END IF;
 IF v_retired ? p_factor_fingerprint OR (coalesce((v_factor->>'reset_required')::boolean,false) AND v_fingerprint=p_factor_fingerprint)
  OR (v_fingerprint IS NOT NULL AND v_fingerprint<>p_factor_fingerprint AND NOT coalesce((v_factor->>'reset_required')::boolean,false)) THEN
  RETURN jsonb_build_object('accepted',true,'verified',false,'reason','reset_required');
 END IF;
 v_guard:=coalesce(v_principal.metadata->'console_mfa_guard','{}'::jsonb);
 v_failures:=coalesce((v_guard->>'failures')::integer,0);v_last:=coalesce((v_guard->>'last_counter')::bigint,-1);
 v_locked:=(v_guard->>'locked_until')::timestamptz;
 IF v_failures<0 OR v_failures>5 OR v_last< -1 THEN RAISE EXCEPTION 'Console MFA guard state is invalid';END IF;
 IF v_locked>clock_timestamp() THEN
  RETURN jsonb_build_object('accepted',true,'verified',false,'reason','locked');
 END IF;
 IF v_locked IS NOT NULL THEN v_failures:=0;v_locked:=NULL;END IF;
 v_current:=floor(extract(epoch FROM clock_timestamp())/30)::bigint;
 IF p_counter IS NULL OR p_counter<v_current-1 OR p_counter>v_current+1 OR p_counter<=v_last THEN
  v_failures:=least(v_failures+1,5);IF v_failures=5 THEN v_locked:=clock_timestamp()+interval '5 minutes';END IF;
  UPDATE public.principals SET metadata=jsonb_set(metadata,'{console_mfa_guard}',jsonb_build_object(
   'failures',v_failures,'last_counter',v_last,'locked_until',v_locked)),updated_at=clock_timestamp() WHERE id=v_principal.id;
  INSERT INTO public.audit_logs(actor_id,actor_type,actor_email,action,resource_type,resource_id,metadata)
   VALUES(p_actor_id,CASE WHEN (v_state->>'is_super_admin')::boolean THEN 'super_admin' ELSE 'employee' END,
    v_state->>'email','platform_console_mfa.failed','platform_console_session',p_previous_session_id,
    jsonb_build_object('locked',v_failures=5));
  RETURN jsonb_build_object('accepted',true,'verified',false,'reason',CASE WHEN v_failures=5 THEN 'locked' ELSE 'invalid' END);
 END IF;
 v_result:=public.transition_console_session_v1('register',p_session_id,p_cookie_sha256,p_email,p_actor_id,
  p_issued_at,p_expires_at,p_mfa_verified_at,p_previous_session_id,p_previous_cookie_sha256);
 IF NOT coalesce((v_result->>'accepted')::boolean,false) THEN RETURN v_result;END IF;
 UPDATE public.principals SET metadata=jsonb_set(metadata,'{console_mfa_guard}',jsonb_build_object(
  'failures',0,'last_counter',p_counter,'locked_until',NULL)),updated_at=clock_timestamp() WHERE id=v_principal.id;
 UPDATE public.principals SET metadata=jsonb_set(metadata,'{console_mfa_factor}',
  v_factor||jsonb_build_object('fingerprint',p_factor_fingerprint,'reset_required',false,
   'generation',coalesce((v_factor->>'generation')::integer,0),
   'retired',v_retired,'verified_at',clock_timestamp())),updated_at=clock_timestamp() WHERE id=v_principal.id;
 UPDATE public.sessions_v2 SET metadata=metadata||jsonb_build_object('console_factor_fingerprint',p_factor_fingerprint,'console_mfa_counter',p_counter,
  'console_mfa_previous_session',p_previous_session_id,'console_mfa_previous_digest',p_previous_cookie_sha256) WHERE id=p_session_id;
 INSERT INTO public.audit_logs(actor_id,actor_type,actor_email,action,resource_type,resource_id,metadata)
  VALUES(p_actor_id,CASE WHEN (v_state->>'is_super_admin')::boolean THEN 'super_admin' ELSE 'employee' END,
   v_state->>'email','platform_console_mfa.verified','platform_console_session',p_session_id,
   jsonb_build_object('previous_session_id',p_previous_session_id,'durable_replay_guard',true));
 RETURN jsonb_build_object('accepted',true,'verified',true,'state',v_result,'replayed',false);
END

DECLARE v_user public.users_custom%ROWTYPE;v_identity jsonb;v_principal public.principals%ROWTYPE;v_count integer;v_factor jsonb;
BEGIN
 SELECT * INTO v_user FROM public.users_custom WHERE id=p_actor_id AND email_verified=true;
 IF NOT FOUND THEN RETURN NULL;END IF;
 v_identity:=public.resolve_console_operator_v1(v_user.email,p_actor_id);
 IF NOT coalesce((v_identity->>'accepted')::boolean,false) THEN RETURN NULL;END IF;
 SELECT count(*) INTO v_count FROM public.principals WHERE realm='admin' AND legacy_user_id=p_actor_id AND deleted_at IS NULL;
 IF v_count>1 THEN RETURN NULL;END IF;
 SELECT * INTO v_principal FROM public.principals WHERE realm='admin' AND legacy_user_id=p_actor_id AND deleted_at IS NULL;
 IF v_count=1 AND (v_principal.status<>'active' OR lower(v_principal.email) IS DISTINCT FROM lower(v_user.email)) THEN RETURN NULL;END IF;
 v_factor:=coalesce(v_principal.metadata->'console_mfa_factor','{}'::jsonb);
 RETURN jsonb_build_object('actor_id',p_actor_id,'email',lower(v_user.email),'name',v_user.full_name,'principal_id',v_principal.id,
  'factor',jsonb_build_object('fingerprint',v_factor->'fingerprint','generation',coalesce((v_factor->>'generation')::integer,0),
   'reset_required',coalesce((v_factor->>'reset_required')::boolean,false),'retired',coalesce(v_factor->'retired','[]'::jsonb)));
END

DECLARE v_permission jsonb;v_items jsonb;
BEGIN
 v_permission:=public.console_permission_snapshot_v1(p_session_id,p_cookie_sha256,false);
 IF NOT coalesce((v_permission->>'accepted')::boolean,false) THEN RETURN v_permission;END IF;
 IF v_permission->>'evidence_hash' IS DISTINCT FROM p_permission_hash THEN RETURN jsonb_build_object('accepted',false,'code','PERMISSION_CHANGED');END IF;
 IF length(coalesce(p_query,''))>160 THEN RETURN jsonb_build_object('accepted',false,'code','APPROVAL_QUERY_INVALID');END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('actor_id',x.state->'actor_id','email',x.state->'email','name',x.state->'name',
  'reset_required',x.state->'factor'->'reset_required') ORDER BY x.email),'[]'::jsonb) INTO v_items FROM (
  SELECT u.email,public.console_mfa_reset_target_v1(u.id) state FROM public.users_custom u
   WHERE u.email_verified=true AND (p_actor_id IS NULL OR u.id=p_actor_id)
   AND (coalesce(p_query,'')='' OR position(lower(p_query) in lower(u.email))>0 OR position(lower(p_query) in lower(coalesce(u.full_name,'')))>0)
   AND (EXISTS(SELECT 1 FROM public.super_admin_allowlist a WHERE a.is_active=true AND lower(a.email)=lower(u.email) AND (a.user_id=u.id OR a.user_id IS NULL))
    OR EXISTS(SELECT 1 FROM public.employees e WHERE e.user_id=u.id AND e.store_id IS NULL AND e.status='active' AND e.is_active=true AND e.deleted_at IS NULL))
   ORDER BY u.email LIMIT 50
 ) x WHERE x.state IS NOT NULL;
 RETURN jsonb_build_object('accepted',true,'items',v_items);
END

DECLARE v_permission jsonb;v_state jsonb;v_target jsonb;v_a public.sensitive_action_approvals%ROWTYPE;v_payload jsonb;v_lock uuid;v_requester uuid;
BEGIN
 SELECT p.legacy_user_id INTO v_requester FROM public.sessions_v2 x JOIN public.principals p ON p.id=x.principal_id
  WHERE x.id=p_session_id AND x.realm='admin' AND x.metadata->>'cookie_sha256'=p_cookie_sha256;
 FOR v_lock IN SELECT DISTINCT id FROM unnest(ARRAY[v_requester,p_actor_id]) id WHERE id IS NOT NULL ORDER BY id LOOP
  PERFORM pg_advisory_xact_lock(hashtextextended('letbuyy:console-actor:'||v_lock::text,0));
 END LOOP;
 v_permission:=public.console_permission_snapshot_v1(p_session_id,p_cookie_sha256,true);
 IF NOT coalesce((v_permission->>'accepted')::boolean,false) THEN RETURN v_permission;END IF;
 IF v_permission->>'evidence_hash' IS DISTINCT FROM p_permission_hash THEN RETURN jsonb_build_object('accepted',false,'code','PERMISSION_CHANGED');END IF;
 v_state:=v_permission->'session';
 IF p_actor_id IS NULL OR p_request_key IS NULL OR p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 8 AND 1000
  OR p_configured_fingerprint IS NULL OR p_configured_fingerprint !~ '^[0-9a-f]{64}$' THEN RETURN jsonb_build_object('accepted',false,'code','APPROVAL_INTENT_INVALID');END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('letbuyy:approval-request:'||(v_state->>'actor_id')||':'||p_request_key::text,0));
 SELECT * INTO v_a FROM public.sensitive_action_approvals WHERE protocol_version=1 AND maker_actor_id=(v_state->>'actor_id')::uuid
  AND action='operator.mfa.reset' AND resource_id=p_actor_id::text AND request_key=p_request_key;
 IF FOUND THEN
  IF v_a.requester_session_id<>p_session_id OR v_a.reason<>btrim(p_reason) OR v_a.payload->>'configured_fingerprint'<>p_configured_fingerprint THEN
   RETURN jsonb_build_object('accepted',false,'code','IDEMPOTENCY_CONFLICT');END IF;
  RETURN jsonb_build_object('accepted',true,'approval',public.console_approval_view_v1(v_a.id),'replayed',true);
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('letbuyy:console-actor:'||p_actor_id::text,0));
 v_target:=public.console_mfa_reset_target_v1(p_actor_id);
 IF v_target IS NULL THEN RETURN jsonb_build_object('accepted',false,'code','APPROVAL_TARGET_NOT_FOUND');END IF;
 IF coalesce((v_target->'factor'->>'reset_required')::boolean,false) THEN RETURN jsonb_build_object('accepted',false,'code','MFA_RESET_ALREADY_REQUIRED');END IF;
 IF v_target->'factor'->>'fingerprint' IS NOT NULL AND v_target->'factor'->>'fingerprint'<>p_configured_fingerprint THEN
  RETURN jsonb_build_object('accepted',false,'code','MFA_FACTOR_CONFIGURATION_CHANGED');END IF;
 v_payload:=jsonb_build_object('target',v_target,'configured_fingerprint',p_configured_fingerprint,'reason',btrim(p_reason));
 INSERT INTO public.sensitive_action_approvals(site_id,action,resource_type,resource_id,maker_actor_id,status,reason,
  protocol_version,requester_session_id,request_key,payload,payload_hash,expires_at,created_by)
 VALUES(NULL,'operator.mfa.reset','platform_operator',p_actor_id::text,(v_state->>'actor_id')::uuid,'pending',btrim(p_reason),
  1,p_session_id,p_request_key,v_payload,public.console_approval_payload_hash_v1('operator.mfa.reset',NULL,'platform_operator',p_actor_id::text,v_payload),
  least(clock_timestamp()+interval '10 minutes',(v_state->>'expires_at')::timestamptz,(v_state->>'mfa_verified_at')::timestamptz+interval '10 minutes'),(v_state->>'actor_id')::uuid)
 RETURNING * INTO v_a;
 INSERT INTO public.audit_logs(actor_id,actor_type,actor_email,action,resource_type,resource_id,metadata)
 VALUES(v_a.maker_actor_id,'employee',v_state->>'email','sensitive_action.requested','sensitive_action_approval',v_a.id,
  jsonb_build_object('action',v_a.action,'target_actor_id',p_actor_id,'payload_hash',v_a.payload_hash,'requester_session_id',p_session_id));
 UPDATE public.break_glass_grants SET used_at=coalesce(used_at,clock_timestamp()) WHERE id IN (SELECT (g->>'id')::uuid FROM jsonb_array_elements(v_permission->'input'->'breakGlassGrants') g);
 RETURN jsonb_build_object('accepted',true,'approval',public.console_approval_view_v1(v_a.id),'replayed',false);
END

DECLARE v_a public.sensitive_action_approvals%ROWTYPE;v_permission jsonb;v_state jsonb;v_checker jsonb;v_target jsonb;
 v_principal public.principals%ROWTYPE;v_factor jsonb;v_retired jsonb;v_count integer;v_result jsonb;v_job uuid;v_lock uuid;
BEGIN
 SELECT * INTO v_a FROM public.sensitive_action_approvals WHERE id=p_id AND protocol_version=1 FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('accepted',false,'code','APPROVAL_NOT_FOUND');END IF;
 -- All participating actor locks precede session rows. Reciprocal resets and
 -- concurrent normal MFA rotation therefore share one deterministic order.
 FOR v_lock IN SELECT DISTINCT id FROM unnest(ARRAY[v_a.maker_actor_id,v_a.checker_actor_id,p_actor_id]) id WHERE id IS NOT NULL ORDER BY id LOOP
  PERFORM pg_advisory_xact_lock(hashtextextended('letbuyy:console-actor:'||v_lock::text,0));
 END LOOP;
 PERFORM id FROM public.sessions_v2 WHERE id=ANY(ARRAY[p_session_id,v_a.approver_session_id]) ORDER BY id FOR UPDATE;
 v_permission:=public.console_permission_snapshot_v1(p_session_id,p_cookie_sha256,true);
 IF NOT coalesce((v_permission->>'accepted')::boolean,false) THEN RETURN v_permission;END IF;
 IF v_permission->>'evidence_hash' IS DISTINCT FROM p_permission_hash THEN RETURN jsonb_build_object('accepted',false,'code','PERMISSION_CHANGED');END IF;
 v_state:=v_permission->'session';
 IF v_a.maker_actor_id<>(v_state->>'actor_id')::uuid OR v_a.requester_session_id<>p_session_id THEN RETURN jsonb_build_object('accepted',false,'code','APPROVAL_REQUESTER_MISMATCH');END IF;
 IF p_actor_id IS NULL OR v_a.site_id IS NOT NULL OR v_a.action<>'operator.mfa.reset' OR v_a.resource_type<>'platform_operator'
  OR v_a.resource_id<>p_actor_id::text OR v_a.reason IS DISTINCT FROM btrim(p_reason)
  OR v_a.payload_hash IS DISTINCT FROM public.console_approval_payload_hash_v1(v_a.action,NULL,v_a.resource_type,v_a.resource_id,v_a.payload) THEN
  RETURN jsonb_build_object('accepted',false,'code','APPROVAL_PAYLOAD_MISMATCH');END IF;
 IF v_a.status<>'approved' OR v_a.approver_session_id IS NULL OR v_a.checker_actor_id=v_a.maker_actor_id THEN RETURN jsonb_build_object('accepted',false,'code','INDEPENDENT_APPROVAL_REQUIRED');END IF;
 v_checker:=public.console_session_state_v1(v_a.approver_session_id,(SELECT metadata->>'cookie_sha256' FROM public.sessions_v2 WHERE id=v_a.approver_session_id));
 IF NOT coalesce((v_checker->>'accepted')::boolean,false) OR NOT coalesce((v_checker->>'is_super_admin')::boolean,false)
  OR (v_checker->>'actor_id')::uuid IS DISTINCT FROM v_a.checker_actor_id OR v_a.checker_actor_id=p_actor_id THEN
  RETURN jsonb_build_object('accepted',false,'code','APPROVAL_EXPIRED_OR_REVOKED');END IF;
 IF v_a.consumed_at IS NOT NULL THEN RETURN jsonb_build_object('accepted',true,'result',v_a.result||'{"replayed":true}'::jsonb);END IF;
 IF v_a.expires_at<=clock_timestamp() THEN RETURN jsonb_build_object('accepted',false,'code','APPROVAL_EXPIRED_OR_REVOKED');END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('letbuyy:console-actor:'||p_actor_id::text,0));
 PERFORM id FROM public.principals WHERE realm='admin' AND legacy_user_id=p_actor_id AND deleted_at IS NULL ORDER BY id FOR UPDATE;
 PERFORM x.id FROM public.sessions_v2 x JOIN public.principals p ON p.id=x.principal_id
  WHERE p.realm='admin' AND p.legacy_user_id=p_actor_id AND x.realm='admin' AND x.site_id IS NULL
   AND x.metadata->>'protocol'='platform-console-v1' ORDER BY x.id FOR UPDATE OF x;
 -- A membership/identity revocation that held a target session must finish
 -- before this fresh source read, rather than being hidden behind our write.
 v_target:=public.console_mfa_reset_target_v1(p_actor_id);
 IF v_target IS NULL THEN RETURN jsonb_build_object('accepted',false,'code','APPROVAL_TARGET_NOT_FOUND');END IF;
 IF v_target IS DISTINCT FROM v_a.payload->'target' THEN RETURN jsonb_build_object('accepted',false,'code','APPROVAL_TARGET_STATE_CHANGED');END IF;
 IF v_target->>'principal_id' IS NULL THEN
  INSERT INTO public.principals(realm,actor_type,legacy_user_id,email,status,metadata)
   VALUES('admin','platform-operator',p_actor_id,v_target->>'email','active','{"source":"platform-console-v1"}'::jsonb) RETURNING * INTO v_principal;
  INSERT INTO public.account_links(principal_id,realm,provider,provider_subject) VALUES(v_principal.id,'admin','users_custom',p_actor_id::text);
 ELSE SELECT * INTO v_principal FROM public.principals WHERE id=(v_target->>'principal_id')::uuid FOR UPDATE;END IF;
 v_factor:=coalesce(v_principal.metadata->'console_mfa_factor','{}'::jsonb);v_retired:=coalesce(v_factor->'retired','[]'::jsonb);
 IF NOT v_retired ? (v_a.payload->>'configured_fingerprint') THEN v_retired:=v_retired||jsonb_build_array(v_a.payload->>'configured_fingerprint');END IF;
 UPDATE public.principals SET metadata=jsonb_set(metadata,'{console_mfa_factor}',v_factor||jsonb_build_object(
  'fingerprint',v_a.payload->>'configured_fingerprint','reset_required',true,'generation',coalesce((v_factor->>'generation')::integer,0)+1,
  'retired',v_retired,'reset_approval_id',p_id,'reset_at',clock_timestamp())),updated_at=clock_timestamp() WHERE id=v_principal.id;
 WITH revoked AS (
  UPDATE public.sessions_v2 SET status='revoked',revoked_at=clock_timestamp(),revoke_reason='approved_mfa_reset'
   WHERE principal_id=v_principal.id AND realm='admin' AND site_id IS NULL AND status='active' AND metadata->>'protocol'='platform-console-v1' RETURNING id
 ) SELECT count(*) INTO v_count FROM revoked;
 INSERT INTO public.platform_queue_jobs(site_id,event_id,queue_name,job_type,payload,idempotency_key,created_by,updated_by)
 VALUES(NULL,p_id,'notification-jobs','email.operator_mfa_reset',jsonb_build_object('approval_id',p_id),
  'operator-mfa-reset-email:'||p_id::text,v_a.maker_actor_id,v_a.maker_actor_id) RETURNING id INTO v_job;
 v_result:=jsonb_build_object('actor_id',p_actor_id,'approval_id',p_id,'reset_required',true,'revoked_sessions',v_count,
  'notification_job_id',v_job,'notification_status','queued','replayed',false);
 INSERT INTO public.audit_logs(actor_id,actor_type,actor_email,action,resource_type,resource_id,metadata)
 VALUES(v_a.maker_actor_id,CASE WHEN (v_state->>'is_super_admin')::boolean THEN 'super_admin' ELSE 'employee' END,v_state->>'email',
  'operator.mfa.reset','platform_operator',p_actor_id,jsonb_build_object('approval_id',p_id,'reason',v_a.reason,
   'independent_approver_id',v_a.checker_actor_id,'payload_hash',v_a.payload_hash,'revoked_sessions',v_count,'notification_job_id',v_job));
 UPDATE public.sensitive_action_approvals SET consumed_at=clock_timestamp(),result=v_result,updated_by=v_a.maker_actor_id WHERE id=p_id;
 UPDATE public.break_glass_grants SET used_at=coalesce(used_at,clock_timestamp()) WHERE id IN (SELECT (g->>'id')::uuid FROM jsonb_array_elements(v_permission->'input'->'breakGlassGrants') g);
 RETURN jsonb_build_object('accepted',true,'result',v_result);
END

DECLARE v_job public.platform_queue_jobs%ROWTYPE;v_a public.sensitive_action_approvals%ROWTYPE;v_sender text;
BEGIN
 SELECT * INTO v_job FROM public.platform_queue_jobs WHERE id=p_job_id FOR UPDATE;
 IF NOT FOUND OR v_job.queue_name<>'notification-jobs' OR v_job.job_type<>'email.operator_mfa_reset' OR v_job.site_id IS NOT NULL
  OR v_job.status<>'running' OR v_job.deleted_at IS NOT NULL OR v_job.locked_by IS DISTINCT FROM p_worker_id
  OR p_worker_id IS NULL OR v_job.locked_at IS NULL OR v_job.locked_at<clock_timestamp()-interval '120 seconds' THEN
  RAISE EXCEPTION 'A current operator notification lease is required';END IF;
 SELECT * INTO v_a FROM public.sensitive_action_approvals WHERE id=v_job.event_id AND action='operator.mfa.reset'
  AND site_id IS NULL AND protocol_version=1 AND consumed_at IS NOT NULL AND result->>'notification_job_id'=p_job_id::text;
 IF NOT FOUND OR v_job.payload->>'approval_id' IS DISTINCT FROM v_a.id::text
  OR v_job.idempotency_key IS DISTINCT FROM 'operator-mfa-reset-email:'||v_a.id::text THEN RAISE EXCEPTION 'Operator notification source does not match';END IF;
 v_sender:=v_job.payload->>'notification_sender';
 IF v_sender IS NULL THEN
  v_sender:=btrim(p_sender);
  IF v_sender IS NULL OR length(v_sender) NOT BETWEEN 3 AND 320 OR v_sender ~ '[\r\n]' OR v_sender !~ '@' THEN
   RAISE EXCEPTION 'Operator notification sender is not configured';END IF;
  UPDATE public.platform_queue_jobs SET payload=payload||jsonb_build_object('notification_sender',v_sender,'notification_template_version',1) WHERE id=p_job_id;
 END IF;
 RETURN jsonb_build_object('approval_id',v_a.id,'job_id',p_job_id,'email',v_a.payload->'target'->>'email',
  'sender',v_sender,'occurred_at',v_a.consumed_at,'target_actor_id',v_a.resource_id);
END

DECLARE r record;v_count integer:=0;
BEGIN
 FOR r IN SELECT id,locked_by FROM public.platform_queue_jobs WHERE queue_name='notification-jobs' AND job_type='email.operator_mfa_reset'
  AND site_id IS NULL AND status='running' AND deleted_at IS NULL AND locked_by IS NOT NULL AND locked_at<clock_timestamp()-interval '120 seconds'
  ORDER BY locked_at,id LIMIT least(greatest(coalesce(p_limit,25),1),100) FOR UPDATE SKIP LOCKED LOOP
  PERFORM public.fail_platform_queue_job(r.id,r.locked_by,'Operator notification worker lease expired',30,
   jsonb_build_object('consumer_runtime','services/queue-workers','lease_recovered',true));v_count:=v_count+1;
 END LOOP;
 RETURN v_count;
END

DECLARE b public.buyer_accounts%ROWTYPE;t public.support_tickets%ROWTYPE;x public.step_up_challenges%ROWTYPE;v_attempts integer;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('letbuyy:buyer-export:'||p_buyer::text,0));
 SELECT * INTO b FROM public.buyer_accounts WHERE id=p_buyer FOR UPDATE;
 IF NOT FOUND OR b.status<>'active' OR b.session_epoch IS DISTINCT FROM p_epoch THEN RETURN jsonb_build_object('accepted',false,'code','BUYER_SESSION_INVALID');END IF;
 IF p_session_sha256 IS NULL OR p_session_sha256 !~ '^[0-9a-f]{64}$' OR p_request_key IS NULL THEN RETURN jsonb_build_object('accepted',false,'code','EXPORT_INTENT_INVALID');END IF;
 SELECT * INTO t FROM public.support_tickets WHERE id=p_ticket AND requester_type='customer' AND requester_user_id=p_buyer
  AND site_id IS NULL AND topic='privacy' AND metadata->>'privacy_request_type'='access' AND deleted_at IS NULL FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('accepted',false,'code','EXPORT_REQUEST_NOT_FOUND');END IF;
 IF t.status IN ('closed','resolved') AND t.metadata->>'fulfillment_outcome' IS DISTINCT FROM 'fulfilled' THEN RETURN jsonb_build_object('accepted',false,'code','EXPORT_REQUEST_CLOSED');END IF;
 SELECT * INTO x FROM public.step_up_challenges WHERE buyer_account_id=p_buyer AND action='buyer.dsr.export' AND idempotency_key=p_request_key::text FOR UPDATE;
 IF FOUND AND (x.metadata->>'support_ticket_id' IS DISTINCT FROM p_ticket::text OR x.metadata->>'session_sha256' IS DISTINCT FROM p_session_sha256
  OR (x.metadata->>'session_epoch')::integer IS DISTINCT FROM p_epoch) THEN RETURN jsonb_build_object('accepted',false,'code','EXPORT_IDEMPOTENCY_CONFLICT');END IF;
 IF x.id IS NOT NULL AND (x.status='expired' OR x.expires_at<=clock_timestamp()) THEN RETURN jsonb_build_object('accepted',false,'code','EXPORT_EXPIRED');END IF;
 SELECT coalesce(sum((metadata->>'attempts')::integer),0) INTO v_attempts FROM public.step_up_challenges
  WHERE buyer_account_id=p_buyer AND action='buyer.dsr.export' AND created_at>clock_timestamp()-interval '10 minutes';
 IF v_attempts>=5 THEN RETURN jsonb_build_object('accepted',false,'code','EXPORT_VERIFICATION_LIMIT');END IF;
 IF x.id IS NULL THEN
  INSERT INTO public.step_up_challenges(site_id,buyer_account_id,actor_id,action,idempotency_key,challenge_token_hash,expires_at,metadata)
   VALUES(NULL,p_buyer,p_buyer,'buyer.dsr.export',p_request_key::text,p_session_sha256,clock_timestamp()+interval '10 minutes',
    jsonb_build_object('support_ticket_id',p_ticket,'session_sha256',p_session_sha256,'session_epoch',p_epoch,'attempts',1,
     'password_sha256',encode(extensions.digest(coalesce(b.password_hash,''),'sha256'),'hex'))) RETURNING * INTO x;
 ELSE UPDATE public.step_up_challenges SET metadata=metadata||jsonb_build_object('attempts',coalesce((metadata->>'attempts')::integer,0)+1) WHERE id=x.id RETURNING * INTO x;END IF;
 RETURN jsonb_build_object('accepted',true,'challenge_id',x.id,'password_hash',b.password_hash);
END

BEGIN
 UPDATE public.step_up_challenges SET status='failed' WHERE id=p_id AND buyer_account_id=p_buyer AND site_id IS NULL AND action='buyer.dsr.export'
  AND metadata->>'session_sha256'=p_session_sha256 AND status IN ('issued','failed');
 RETURN jsonb_build_object('accepted',true);
END

DECLARE b public.buyer_accounts%ROWTYPE;x public.step_up_challenges%ROWTYPE;v_existing uuid;v_source jsonb;v_complete boolean;v_raw text;v_digest text;v_generated timestamptz;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('letbuyy:buyer-export:'||p_buyer::text,0));
 SELECT * INTO b FROM public.buyer_accounts WHERE id=p_buyer FOR UPDATE;
 IF NOT FOUND OR b.status<>'active' OR b.session_epoch IS DISTINCT FROM p_epoch THEN RETURN jsonb_build_object('accepted',false,'code','BUYER_SESSION_INVALID');END IF;
 SELECT * INTO x FROM public.step_up_challenges WHERE id=p_id AND buyer_account_id=p_buyer AND site_id IS NULL AND action='buyer.dsr.export' FOR UPDATE;
 IF NOT FOUND OR x.metadata->>'session_sha256' IS DISTINCT FROM p_session_sha256 OR (x.metadata->>'session_epoch')::integer IS DISTINCT FROM p_epoch
  OR p_password_hash IS NULL OR p_password_hash IS DISTINCT FROM b.password_hash
  OR x.metadata->>'password_sha256' IS DISTINCT FROM encode(extensions.digest(b.password_hash,'sha256'),'hex') THEN RETURN jsonb_build_object('accepted',false,'code','EXPORT_PROOF_CHANGED');END IF;
 IF x.status='expired' OR x.expires_at<=clock_timestamp() THEN RETURN jsonb_build_object('accepted',false,'code','EXPORT_EXPIRED');END IF;
 SELECT id INTO v_existing FROM public.customer_dsr_exports WHERE buyer_account_id=p_buyer AND buyer_request_key=x.idempotency_key::uuid AND site_id IS NULL AND deleted_at IS NULL;
 IF FOUND THEN RETURN jsonb_build_object('accepted',true,'export',public.buyer_export_metadata_v1(v_existing),'replayed',true);END IF;
 v_generated:=coalesce((x.metadata->>'source_generated_at')::timestamptz,clock_timestamp());
 -- All included sections, exact ownership joins and completeness counts share
 -- this one statement's snapshot. Named ceilings reject, never truncate success.
 WITH a AS MATERIALIZED (SELECT * FROM public.buyer_addresses WHERE buyer_account_id=p_buyer LIMIT 201),
 t AS MATERIALIZED (SELECT id,ticket_ref,topic,created_at FROM public.support_tickets WHERE requester_type='customer' AND requester_user_id=p_buyer AND deleted_at IS NULL LIMIT 501),
 m AS MATERIALIZED (SELECT z.id,z.ticket_id,z.body,z.created_at FROM public.ticket_messages z JOIN t ON t.id=z.ticket_id WHERE z.author_type='requester' AND z.deleted_at IS NULL LIMIT 10001),
 l AS MATERIALIZED (SELECT order_id FROM public.buyer_order_links WHERE buyer_account_id=p_buyer LIMIT 501),
 o AS MATERIALIZED (SELECT z.id,z.order_number,z.status,z.total,z.currency,z.created_at FROM public.orders z JOIN l ON l.order_id=z.id),
 i AS MATERIALIZED (SELECT z.id,z.order_id,z.name,z.quantity,z.price,z.total FROM public.order_items z JOIN o ON o.id=z.order_id WHERE z.deleted_at IS NULL LIMIT 10001),
 bounds AS (SELECT (SELECT count(*)<=200 FROM a) AND (SELECT count(*)<=500 FROM t) AND (SELECT count(*)<=500 FROM l)
  AND (SELECT count(*) FROM l)=(SELECT count(*) FROM o) AND (SELECT count(*)<=10000 FROM m) AND (SELECT count(*)<=10000 FROM i)
  AND NOT EXISTS(SELECT 1 FROM m GROUP BY ticket_id HAVING count(*)>500) AND NOT EXISTS(SELECT 1 FROM i GROUP BY order_id HAVING count(*)>200)
  AND coalesce((SELECT sum(octet_length(body)) FROM m),0)+coalesce((SELECT sum(octet_length(to_jsonb(a)::text)) FROM a),0)
   +coalesce((SELECT sum(octet_length(to_jsonb(o)::text)) FROM o),0)+coalesce((SELECT sum(octet_length(to_jsonb(i)::text)) FROM i),0)<4194304 AS complete)
 SELECT CASE WHEN (SELECT complete FROM bounds) THEN jsonb_build_object('contractVersion','buyer-restricted-access-v1','requestId',x.metadata->>'support_ticket_id','buyerAccountId',p_buyer,'generatedAt',v_generated,'complete',true,
  'sections',jsonb_build_object(
   'profile',jsonb_build_array(jsonb_build_object('email',b.email,'full_name',b.full_name,'phone',b.phone,'status',b.status,'created_at',b.created_at)),
   'addresses',(SELECT coalesce(jsonb_agg(jsonb_build_object('label',label,'full_name',full_name,'phone',phone,'address_line1',address_line1,'address_line2',address_line2,'city',city,'state',state,'postal_code',postal_code,'country',country,'is_default',is_default) ORDER BY id),'[]'::jsonb) FROM a),
   'authored_requests',(SELECT coalesce(jsonb_agg(jsonb_build_object('ticket_reference',ticket_ref,'topic',topic,'created_at',t.created_at,'authored_messages',
    (SELECT coalesce(jsonb_agg(body ORDER BY created_at,id),'[]'::jsonb) FROM m WHERE m.ticket_id=t.id)) ORDER BY t.created_at,t.id),'[]'::jsonb) FROM t),
   'orders',(SELECT coalesce(jsonb_agg(jsonb_build_object('order_reference',order_number,'status',status,'total',total,'currency',currency,'created_at',o.created_at,'items',
    (SELECT coalesce(jsonb_agg(jsonb_build_object('name',name,'quantity',quantity,'price',price,'total',total) ORDER BY id),'[]'::jsonb) FROM i WHERE i.order_id=o.id)) ORDER BY o.created_at,o.id),'[]'::jsonb) FROM o))) ELSE NULL END,(SELECT complete FROM bounds)
 INTO v_source,v_complete;
 v_raw:=v_source::text;
 IF NOT v_complete OR v_raw IS NULL OR octet_length(v_raw)>5242880 THEN RETURN jsonb_build_object('accepted',false,'code','EXPORT_SCOPE_LIMIT');END IF;
 v_digest:=encode(extensions.digest(v_raw,'sha256'),'hex');
 IF x.metadata ? 'source_digest' AND x.metadata->>'source_digest'<>v_digest THEN RETURN jsonb_build_object('accepted',false,'code','EXPORT_SOURCE_CHANGED');END IF;
 UPDATE public.step_up_challenges SET status='verified',verified_at=coalesce(verified_at,clock_timestamp()),
  metadata=metadata||jsonb_build_object('source_digest',v_digest,'source_generated_at',v_generated) WHERE id=x.id;
 RETURN jsonb_build_object('accepted',true,'source_json',v_raw,'source_digest',v_digest,'email',b.email,'replayed',false);
END

DECLARE b public.buyer_accounts%ROWTYPE;x public.step_up_challenges%ROWTYPE;t public.support_tickets%ROWTYPE;v_existing public.customer_dsr_exports%ROWTYPE;v_id uuid;
