DECLARE b public.buyer_accounts%ROWTYPE;e public.customer_dsr_exports%ROWTYPE;x public.step_up_challenges%ROWTYPE;t public.support_tickets%ROWTYPE;v_items jsonb;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('letbuyy:buyer-export:'||p_buyer::text,0));
 SELECT * INTO b FROM public.buyer_accounts WHERE id=p_buyer FOR UPDATE;
 IF NOT FOUND OR b.status<>'active' OR b.session_epoch IS DISTINCT FROM p_epoch THEN RETURN jsonb_build_object('accepted',false,'code','BUYER_SESSION_INVALID');END IF;
 SELECT * INTO t FROM public.support_tickets WHERE id=p_ticket AND requester_type='customer' AND requester_user_id=p_buyer AND site_id IS NULL AND topic='privacy'
  AND metadata->>'privacy_request_type'='access' AND deleted_at IS NULL FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('accepted',false,'code','EXPORT_REQUEST_NOT_FOUND');END IF;
 IF p_operation='list' THEN
  SELECT coalesce(jsonb_agg(public.buyer_export_metadata_v1(id) ORDER BY created_at DESC,id DESC),'[]'::jsonb) INTO v_items FROM
   (SELECT id,created_at FROM public.customer_dsr_exports WHERE buyer_account_id=p_buyer AND support_ticket_id=p_ticket AND site_id IS NULL AND deleted_at IS NULL ORDER BY created_at DESC,id DESC LIMIT 20) q;
  RETURN jsonb_build_object('accepted',true,'items',v_items);
 END IF;
 IF p_operation NOT IN ('inspect','consume') OR p_operation IS NULL THEN RETURN jsonb_build_object('accepted',false,'code','EXPORT_INTENT_INVALID');END IF;
 SELECT * INTO e FROM public.customer_dsr_exports WHERE id=p_export AND buyer_account_id=p_buyer AND support_ticket_id=p_ticket AND site_id IS NULL AND deleted_at IS NULL FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('accepted',false,'code','EXPORT_NOT_FOUND');END IF;
 IF e.buyer_session_epoch IS DISTINCT FROM p_epoch OR e.buyer_session_sha256 IS DISTINCT FROM p_session_sha256 THEN RETURN jsonb_build_object('accepted',false,'code','EXPORT_SESSION_MISMATCH');END IF;
 IF e.status='delivered' THEN RETURN jsonb_build_object('accepted',false,'code','EXPORT_ALREADY_RELEASED');END IF;
 IF e.status<>'ready' OR e.expires_at<=clock_timestamp() OR e.buyer_verified_at<=clock_timestamp()-interval '10 minutes' THEN RETURN jsonb_build_object('accepted',false,'code','EXPORT_EXPIRED');END IF;
 SELECT * INTO x FROM public.step_up_challenges WHERE id=e.buyer_step_up_id AND buyer_account_id=p_buyer AND action='buyer.dsr.export' AND status='verified' FOR UPDATE;
 IF NOT FOUND OR x.metadata->>'password_sha256' IS DISTINCT FROM encode(extensions.digest(coalesce(b.password_hash,''),'sha256'),'hex')
  OR x.metadata->>'source_digest' IS DISTINCT FROM e.payload_digest OR x.metadata->>'session_sha256' IS DISTINCT FROM p_session_sha256 THEN RETURN jsonb_build_object('accepted',false,'code','EXPORT_PROOF_CHANGED');END IF;
 IF p_operation='inspect' THEN RETURN jsonb_build_object('accepted',true,'export',public.buyer_export_metadata_v1(e.id),'encrypted_payload',e.encrypted_payload,'payload_digest',e.payload_digest);END IF;
 IF p_digest IS DISTINCT FROM e.payload_digest THEN RETURN jsonb_build_object('accepted',false,'code','EXPORT_SOURCE_CHANGED');END IF;
 UPDATE public.customer_dsr_exports SET status='delivered',released_at=clock_timestamp(),updated_by=p_buyer WHERE id=e.id;
 UPDATE public.support_tickets SET status='resolved',resolved_at=clock_timestamp(),metadata=metadata||jsonb_build_object('fulfillment_outcome','fulfilled','export_id',e.id,'fulfillment_kind','restricted_access_export_released') WHERE id=t.id;
 INSERT INTO public.audit_logs(actor_id,actor_type,action,resource_type,resource_id,metadata)
 VALUES(p_buyer,'buyer','buyer.privacy.export_released','customer_dsr_exports',e.id,jsonb_build_object('request_id',t.id,'payload_digest',e.payload_digest,'delivery_confirmation','server_release_only'));
 RETURN jsonb_build_object('accepted',true,'export',public.buyer_export_metadata_v1(e.id));
END

DECLARE v_identity jsonb; v_state jsonb; v_consumed public.console_magic_link_consumptions%ROWTYPE;
BEGIN
 IF p_magic_jti IS NULL OR p_actor_id IS NULL OR p_email IS NULL OR p_email<>lower(trim(p_email))
  OR p_magic_issued_at IS NULL OR p_magic_expires_at IS NULL OR p_magic_expires_at<=clock_timestamp()
  OR p_magic_issued_at>clock_timestamp()+interval '30 seconds'
  OR p_magic_expires_at<=p_magic_issued_at OR p_magic_expires_at>p_magic_issued_at+interval '15 minutes'
  OR p_session_id IS NULL OR p_cookie_sha256 IS NULL OR p_cookie_sha256 !~ '^[0-9a-f]{64}$'
  OR p_issued_at IS NULL OR p_issued_at<clock_timestamp()-interval '60 seconds'
  OR p_issued_at>clock_timestamp()+interval '30 seconds' OR p_expires_at IS NULL
  OR p_expires_at<=clock_timestamp() OR p_expires_at<=p_issued_at OR p_expires_at>p_issued_at+interval '8 hours' THEN
  RETURN jsonb_build_object('accepted',false,'code','CONSOLE_MAGIC_INVALID');
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('letbuyy:console-actor:'||p_actor_id::text,0));
 v_identity:=public.resolve_console_operator_v1(p_email,p_actor_id);
 IF NOT coalesce((v_identity->>'accepted')::boolean,false) THEN RETURN v_identity; END IF;
 SELECT * INTO v_consumed FROM public.console_magic_link_consumptions WHERE jti=p_magic_jti::text FOR UPDATE;
 IF FOUND THEN
  -- Only an exact prepared exchange may recover a committed lost response.
  -- A different signed candidate cannot redeem the same magic proof twice.
  IF v_consumed.email=p_email AND v_consumed.exchange_session_id=p_session_id
   AND v_consumed.expires_at=p_magic_expires_at THEN
   RETURN public.console_session_state_v1(p_session_id,p_cookie_sha256);
  END IF;
  RETURN jsonb_build_object('accepted',false,'code','CONSOLE_MAGIC_REPLAYED');
 END IF;
 BEGIN
  INSERT INTO public.console_magic_link_consumptions(jti,email,expires_at,exchange_session_id)
   VALUES(p_magic_jti::text,p_email,p_magic_expires_at,p_session_id);
  v_state:=public.transition_console_session_v1('register',p_session_id,p_cookie_sha256,p_email,p_actor_id,p_issued_at,p_expires_at,NULL,NULL,NULL);
  IF NOT coalesce((v_state->>'accepted')::boolean,false) THEN
   RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='CONSOLE_EXCHANGE_REFUSED';
  END IF;
 EXCEPTION WHEN unique_violation THEN
  RETURN jsonb_build_object('accepted',false,'code','CONSOLE_MAGIC_REPLAYED');
 WHEN SQLSTATE 'P0001' THEN
  IF SQLERRM<>'CONSOLE_EXCHANGE_REFUSED' THEN RAISE; END IF;
  RETURN coalesce(v_state,jsonb_build_object('accepted',false,'code','CONSOLE_MAGIC_INVALID'));
 END;
 RETURN v_state;
END

DECLARE v_site public.sites;v_program public.loyalty_programs;v_result jsonb;
BEGIN
 IF nullif(current_setting('app.site_id',true),'') IS NULL
   OR nullif(current_setting('app.site_id',true),'')::uuid IS DISTINCT FROM p_site_id THEN
  RAISE EXCEPTION 'tenant context does not match the requested site' USING ERRCODE='42501'; END IF;
 SELECT * INTO v_site FROM public.sites WHERE id=p_site_id AND deleted_at IS NULL FOR SHARE;
 IF v_site.id IS NULL OR NOT EXISTS(SELECT 1 FROM public.users_custom WHERE id=p_actor_id)
  OR NOT(coalesce(v_site.custom_user_id=p_actor_id,false) OR coalesce(v_site.user_id=p_actor_id,false)) THEN
  RAISE EXCEPTION 'loyalty programme owner is required' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended(p_site_id::text || ':loyalty.program', 3));
 SELECT * INTO v_program FROM public.loyalty_programs WHERE site_id=p_site_id;
 SELECT jsonb_build_object('store_id',p_site_id,'enrolled',v_program.site_id IS NOT NULL,
  'program',CASE WHEN v_program.site_id IS NULL THEN NULL ELSE to_jsonb(v_program)||jsonb_build_object('point_value_minor',v_program.point_value_minor::text) END,
  'outstanding_points',public.loyalty_outstanding_points(p_site_id)::text,
  'valuation_policy','block_decrease_while_outstanding',
  'value_decrease_allowed',NOT EXISTS(SELECT 1 FROM public.loyalty_accounts a WHERE a.site_id=p_site_id AND public.loyalty_balance(a.id)>0)) INTO v_result;
 RETURN v_result;
END

DECLARE v_actor public.users_custom;v_site public.sites;v_program public.loyalty_programs;
 v_scope text;v_hash text;v_receipt public.idempotency_keys;v_result jsonb;
BEGIN
 IF nullif(current_setting('app.site_id',true),'') IS NULL
   OR nullif(current_setting('app.site_id',true),'')::uuid IS DISTINCT FROM p_site_id THEN
  RAISE EXCEPTION 'tenant context does not match the requested site' USING ERRCODE='42501'; END IF;
 -- Authorize every attempt, including a receipt replay, against the current owner.
 SELECT * INTO v_site FROM public.sites WHERE id=p_site_id AND deleted_at IS NULL FOR SHARE;
 SELECT * INTO v_actor FROM public.users_custom WHERE id=p_actor_id FOR SHARE;
 IF v_site.id IS NULL OR v_actor.id IS NULL OR NOT(coalesce(v_site.custom_user_id=p_actor_id,false) OR coalesce(v_site.user_id=p_actor_id,false)) THEN
  RAISE EXCEPTION 'loyalty programme owner is required' USING ERRCODE='42501'; END IF;
 IF p_key IS NULL OR length(p_key) NOT BETWEEN 8 AND 200 OR p_key<>btrim(p_key) OR p_key ~ '[[:cntrl:]]'
  OR p_intent IS NULL OR jsonb_typeof(p_intent)<>'object' OR p_intent='{}'::jsonb
  OR p_intent-ARRAY['is_active','earn_rate_bps','redeem_cap_bps','point_value_minor']<>'{}'::jsonb
  OR(p_intent ? 'is_active' AND jsonb_typeof(p_intent->'is_active') IS DISTINCT FROM 'boolean')
  OR(p_intent ? 'earn_rate_bps' AND (p_intent->>'earn_rate_bps' IS NULL OR p_intent->>'earn_rate_bps' !~ '^(0|[1-9][0-9]{0,4})$' OR (p_intent->>'earn_rate_bps')::numeric>10000))
  OR(p_intent ? 'redeem_cap_bps' AND (p_intent->>'redeem_cap_bps' IS NULL OR p_intent->>'redeem_cap_bps' !~ '^(0|[1-9][0-9]{0,4})$' OR (p_intent->>'redeem_cap_bps')::numeric>10000))
  OR(p_intent ? 'point_value_minor' AND (p_intent->>'point_value_minor' IS NULL OR p_intent->>'point_value_minor' !~ '^[1-9][0-9]{0,18}$' OR (p_intent->>'point_value_minor')::numeric>9223372036854775807)) THEN
  RETURN jsonb_build_object('error','VALIDATION','status',400); END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_site_id::text || ':loyalty.program', 3));
 v_scope:='merchant-loyalty-program-v1:'||p_actor_id::text;
 v_hash:=encode(sha256(convert_to(jsonb_build_object('actor',p_actor_id,'store',p_site_id,'intent',p_intent,'expected_updated_at',p_expected_updated_at)::text,'UTF8')),'hex');
 SELECT * INTO v_receipt FROM public.idempotency_keys WHERE site_id=p_site_id AND scope=v_scope AND key=p_key FOR UPDATE;
 IF FOUND THEN
  IF v_receipt.request_hash IS DISTINCT FROM v_hash THEN RETURN jsonb_build_object('error','IDEMPOTENCY_CONFLICT','status',409); END IF;
  IF v_receipt.status<>'completed' OR v_receipt.response_body IS NULL OR v_receipt.deleted_at IS NOT NULL THEN
   RETURN jsonb_build_object('error','LOYALTY_STATE_UNAVAILABLE','status',503); END IF;
  RETURN jsonb_build_object('data',v_receipt.response_body,'status',200,'replayed',true);
 END IF;
 SELECT * INTO v_program FROM public.loyalty_programs WHERE site_id=p_site_id FOR UPDATE;
 IF v_program.updated_at IS DISTINCT FROM p_expected_updated_at THEN
  RETURN jsonb_build_object('error','LOYALTY_VERSION_CONFLICT','status',409); END IF;
 v_result:=public.set_loyalty_program(p_site_id,(p_intent->>'is_active')::boolean,
  (p_intent->>'earn_rate_bps')::integer,(p_intent->>'redeem_cap_bps')::integer,(p_intent->>'point_value_minor')::bigint,
  p_actor_id,'user',v_actor.email,p_request_id);
 -- Decimal strings preserve all bigint digits before a JS JSON decoder sees them.
 v_result:=v_result||jsonb_build_object('point_value_minor',v_result->>'point_value_minor',
  'outstanding_points',v_result->>'outstanding_points','liability_delta_minor',v_result->>'liability_delta_minor',
  'valuation_policy','block_decrease_while_outstanding',
  'value_decrease_allowed',NOT EXISTS(SELECT 1 FROM public.loyalty_accounts a WHERE a.site_id=p_site_id AND public.loyalty_balance(a.id)>0));
 INSERT INTO public.idempotency_keys(site_id,key,scope,request_hash,response_hash,response_body,status,status_code,resource_type,resource_id,request_id,expires_at)
 VALUES(p_site_id,p_key,v_scope,v_hash,encode(sha256(convert_to(v_result::text,'UTF8')),'hex'),v_result,'completed',200,'loyalty_program',p_site_id,p_request_id,now()+interval '24 hours');
 RETURN jsonb_build_object('data',v_result,'status',200,'replayed',false);
END

DECLARE j public.platform_queue_jobs;r public.loyalty_ledger_entries;v_result jsonb;
BEGIN
 SELECT * INTO j FROM public.platform_queue_jobs WHERE id=p_job_id AND deleted_at IS NULL FOR UPDATE;
 IF j.id IS NULL OR j.status<>'running' OR j.locked_by IS DISTINCT FROM p_worker_id OR nullif(trim(p_worker_id),'') IS NULL
  OR j.locked_at IS NULL OR j.locked_at<=clock_timestamp()-interval '120 seconds' THEN
  RAISE EXCEPTION 'loyalty recovery requires the current worker lease' USING ERRCODE='42501'; END IF;
 IF j.queue_name<>'loyalty-refunds' OR j.job_type<>'loyalty.restore_redeemed' OR j.site_id IS NULL OR j.schema_version<>1
  OR j.idempotency_key IS DISTINCT FROM 'loyalty.refund_restore:'||j.event_id::text THEN
  RAISE EXCEPTION 'loyalty recovery source mismatch' USING ERRCODE='22023'; END IF;
 IF nullif(current_setting('app.site_id',true),'') IS NOT NULL
  AND nullif(current_setting('app.site_id',true),'')::uuid<>j.site_id THEN
  RAISE EXCEPTION 'loyalty recovery tenant context mismatch' USING ERRCODE='42501'; END IF;
 PERFORM set_config('app.site_id',j.site_id::text,true);
 SELECT e.* INTO r FROM public.loyalty_ledger_entries e
  JOIN public.orders o ON o.id=e.order_id AND o.store_id=e.site_id AND public.loyalty_order_reversal_eligible_v1(e.site_id,e.order_id)
  JOIN public.loyalty_accounts a ON a.id=e.loyalty_account_id AND a.site_id=e.site_id
  WHERE e.id=j.event_id AND e.site_id=j.site_id AND e.entry_type='redeemed';
 IF r.id IS NULL OR j.payload IS DISTINCT FROM jsonb_build_object('redeemed_entry_id',r.id,'order_id',r.order_id) THEN
  RAISE EXCEPTION 'loyalty recovery source mismatch' USING ERRCODE='22023'; END IF;
 v_result:=public.restore_loyalty_on_refund(j.site_id,r.order_id,NULL,j.request_id);
 IF NOT EXISTS(SELECT 1 FROM public.loyalty_ledger_entries c WHERE c.site_id=r.site_id
  AND c.idempotency_key='loyalty.refund_credit:'||r.order_id::text||':'||r.id::text
  AND c.entry_type='refund_credit' AND c.order_id=r.order_id AND c.loyalty_account_id=r.loyalty_account_id AND c.points=r.points
  AND c.metadata=jsonb_build_object('redeemed_entry_id',r.id,'points',r.points,
   'point_value_minor_at_redemption',r.metadata->>'point_value_minor','value_minor_at_redemption',r.metadata->>'value_minor')) THEN
  RAISE EXCEPTION 'loyalty recovery credit could not be verified'; END IF;
 RETURN v_result||jsonb_build_object('processed',true,'job_id',j.id,'site_id',j.site_id,'redeemed_entry_id',r.id,'order_id',r.order_id);
END

DECLARE r record;v_count integer:=0;
BEGIN
 FOR r IN SELECT id,locked_by FROM public.platform_queue_jobs
  WHERE queue_name='loyalty-refunds' AND status='running' AND deleted_at IS NULL AND locked_by IS NOT NULL
   AND locked_at<clock_timestamp()-interval '120 seconds'
  ORDER BY locked_at,id LIMIT least(greatest(coalesce(p_limit,25),1),100) FOR UPDATE SKIP LOCKED LOOP
  PERFORM public.fail_platform_queue_job(r.id,r.locked_by,'Loyalty refund worker lease expired',30,
   jsonb_build_object('consumer_runtime','services/queue-workers','lease_recovered',true));
  v_count:=v_count+1;
 END LOOP;
 RETURN v_count;
END

DECLARE v_site public.sites;v_order public.orders;v_return public.returns;v_refund public.refunds;
 v_receipt public.idempotency_keys;v_scope text;v_key text;v_hash text;v_refund_id uuid;v_count integer;v_data jsonb;v_source_replayed boolean;
BEGIN
 IF nullif(current_setting('app.site_id',true),'') IS NOT NULL
  AND nullif(current_setting('app.site_id',true),'')::uuid IS DISTINCT FROM p_site_id THEN
  RAISE EXCEPTION 'refund tenant context mismatch' USING ERRCODE='42501'; END IF;
 IF p_intent IS NULL OR jsonb_typeof(p_intent)IS DISTINCT FROM 'object' THEN RETURN jsonb_build_object('status',400,'error','VALIDATION'); END IF;
 IF p_site_id IS NULL OR p_order_id IS NULL OR p_actor_id IS NULL
  OR p_intent-ARRAY['idempotency_key','refund_id','provider_refund_id','provider_event_id','notes','_step_up']<>'{}'::jsonb
  OR jsonb_typeof(p_intent->'idempotency_key') IS DISTINCT FROM 'string'
  OR length(p_intent->>'idempotency_key') NOT BETWEEN 8 AND 200 OR p_intent->>'idempotency_key'<>btrim(p_intent->>'idempotency_key')
  OR (p_intent->>'idempotency_key')~'[[:cntrl:]]'
  OR(p_intent?'refund_id'AND(jsonb_typeof(p_intent->'refund_id') IS DISTINCT FROM 'string'OR p_intent->>'refund_id'!~'^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'))
  OR(p_intent?'provider_refund_id'AND(jsonb_typeof(p_intent->'provider_refund_id') IS DISTINCT FROM 'string'OR length(p_intent->>'provider_refund_id')>200))
  OR(p_intent?'provider_event_id'AND(jsonb_typeof(p_intent->'provider_event_id') IS DISTINCT FROM 'string'OR length(p_intent->>'provider_event_id')>200))
  OR(p_intent?'notes'AND(jsonb_typeof(p_intent->'notes') IS DISTINCT FROM 'string'OR length(p_intent->>'notes')>1000)) THEN
  RETURN jsonb_build_object('status',400,'error','VALIDATION'); END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('letbuyy:merchant-totp:'||p_actor_id::text,0));
 SELECT * INTO v_site FROM public.sites WHERE id=p_site_id AND deleted_at IS NULL FOR SHARE;
 IF v_site.id IS NULL OR NOT(coalesce(v_site.custom_user_id=p_actor_id,false) OR coalesce(v_site.user_id=p_actor_id,false)) THEN
  RETURN jsonb_build_object('status',403,'error','REFUND_OWNER_REQUIRED'); END IF;
 IF NOT public.verify_merchant_step_up_v1(p_site_id,p_actor_id,'refund.approve',p_intent->'_step_up')THEN RETURN jsonb_build_object('status',428,'error','STEP_UP_INVALID');END IF;
 v_scope:='owned-refund-complete-v1:'||p_order_id::text||':'||coalesce(p_return_id::text,'order')||':'||p_actor_id::text;
 v_key:=p_intent->>'idempotency_key';
 v_hash:=encode(sha256(convert_to(jsonb_build_object('site',p_site_id,'order',p_order_id,'return',p_return_id,'actor',p_actor_id,'intent',p_intent-'_step_up')::text,'UTF8')),'hex');
 PERFORM pg_advisory_xact_lock(hashtextextended(p_site_id::text||':'||v_scope||':'||v_key,4));
 SELECT * INTO v_receipt FROM public.idempotency_keys WHERE site_id=p_site_id AND scope=v_scope AND key=v_key FOR UPDATE;
 IF v_receipt.id IS NOT NULL THEN
  IF v_receipt.request_hash IS DISTINCT FROM v_hash THEN RETURN jsonb_build_object('status',409,'error','IDEMPOTENCY_CONFLICT'); END IF;
  IF v_receipt.status<>'completed'OR v_receipt.response_body IS NULL OR v_receipt.deleted_at IS NOT NULL THEN
   RETURN jsonb_build_object('status',503,'error','REFUND_RECEIPT_UNAVAILABLE'); END IF;
  v_refund_id:=v_receipt.resource_id;
 ELSIF p_intent?'refund_id' THEN v_refund_id:=(p_intent->>'refund_id')::uuid;
 ELSE
  SELECT count(*),min(id::text)::uuid INTO v_count,v_refund_id FROM public.refunds
   WHERE site_id=p_site_id AND order_id=p_order_id AND return_id=p_return_id AND deleted_at IS NULL AND status IN('pending','processing','succeeded');
  IF v_count>1 THEN RETURN jsonb_build_object('status',409,'error','REFUND_SELECTION_REQUIRED'); END IF;
 END IF;
 -- Match the canonical writer's refund -> order lock order. No supplied ID
 -- can mutate a row merely because the caller owns a different URL resource.
 SELECT * INTO v_refund FROM public.refunds WHERE id=v_refund_id AND site_id=p_site_id AND order_id=p_order_id
  AND(p_return_id IS NULL OR return_id=p_return_id)AND deleted_at IS NULL FOR UPDATE;
 IF v_refund.id IS NULL THEN RETURN jsonb_build_object('status',404,'error','REFUND_NOT_FOUND'); END IF;
 SELECT * INTO v_order FROM public.orders WHERE id=p_order_id AND store_id=p_site_id AND deleted_at IS NULL FOR UPDATE;
 IF v_order.id IS NULL THEN RETURN jsonb_build_object('status',404,'error','REFUND_NOT_FOUND'); END IF;
 IF p_return_id IS NOT NULL THEN
  SELECT * INTO v_return FROM public.returns WHERE id=p_return_id AND site_id=p_site_id AND order_id=p_order_id AND deleted_at IS NULL FOR UPDATE;
  IF v_return.id IS NULL THEN RETURN jsonb_build_object('status',404,'error','REFUND_NOT_FOUND'); END IF;
 END IF;
 PERFORM set_config('app.site_id',p_site_id::text,true);
 IF v_receipt.id IS NOT NULL THEN
  IF v_refund.status<>'succeeded' OR v_receipt.response_hash IS DISTINCT FROM encode(sha256(convert_to(v_receipt.response_body::text,'UTF8')),'hex')
   OR v_receipt.response_body->'refund'->>'id' IS DISTINCT FROM v_refund.id::text
   OR v_receipt.response_body->'refund'->>'site_id' IS DISTINCT FROM p_site_id::text
   OR v_receipt.response_body->'refund'->>'order_id' IS DISTINCT FROM p_order_id::text
   OR v_receipt.response_body->'order'->>'id' IS DISTINCT FROM p_order_id::text
   OR v_receipt.response_body->'order'->>'store_id' IS DISTINCT FROM p_site_id::text THEN
   RETURN jsonb_build_object('status',409,'error','REFUND_REVIEW_REQUIRED'); END IF;
  -- The succeeded branch verifies its one canonical posting without writing
  -- money again. A receipt never substitutes for current source integrity.
  PERFORM public.complete_order_refund(v_refund.id,p_intent->>'provider_refund_id',p_intent->>'provider_event_id',p_actor_id,p_request_id,v_key);
  RETURN jsonb_build_object('status',200,'data',v_receipt.response_body,'replayed',true,'source_replayed',true);
 END IF;
 v_source_replayed:=v_refund.status='succeeded';
 v_data:=public.complete_order_refund(v_refund_id,p_intent->>'provider_refund_id',p_intent->>'provider_event_id',p_actor_id,p_request_id,v_key);
 INSERT INTO public.idempotency_keys(site_id,key,scope,request_hash,response_hash,response_body,status,status_code,resource_type,resource_id,request_id,expires_at)
 VALUES(p_site_id,v_key,v_scope,v_hash,encode(sha256(convert_to(v_data::text,'UTF8')),'hex'),v_data,'completed',200,'refund',v_refund_id,p_request_id,now()+interval '24 hours');
 RETURN jsonb_build_object('status',200,'data',v_data,'replayed',false,'source_replayed',v_source_replayed);
END

DECLARE f public.merchant_2fa_factors%ROWTYPE;r public.merchant_totp_commands_v1%ROWTYPE;
 v_factor uuid;v_recovery text[];v_replayed boolean:=false;
BEGIN
 IF p_actor_id IS NULL OR p_command IS NULL OR p_command NOT IN ('enroll','verify','disable') OR p_key IS NULL OR char_length(p_key) NOT BETWEEN 8 AND 200 OR jsonb_typeof(p_input) IS DISTINCT FROM 'object' THEN
  RETURN jsonb_build_object('accepted',false,'code','IDEMPOTENCY_KEY_REQUIRED');END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('letbuyy:merchant-totp:'||p_actor_id::text,0));
 IF NOT EXISTS(SELECT 1 FROM public.users_custom WHERE id=p_actor_id) THEN RETURN jsonb_build_object('accepted',false,'code','TWO_FACTOR_NOT_FOUND');END IF;
 SELECT * INTO r FROM public.merchant_totp_commands_v1 WHERE actor_id=p_actor_id AND command_key=p_key FOR UPDATE;
 IF FOUND THEN
  IF r.command<>p_command OR (p_command<>'enroll' AND r.factor_id IS DISTINCT FROM nullif(p_input->>'factor_id','')::uuid) THEN
   RETURN jsonb_build_object('accepted',false,'code','IDEMPOTENCY_CONFLICT');END IF;
  v_replayed:=true;v_factor:=r.factor_id;
 ELSE v_factor:=nullif(p_input->>'factor_id','')::uuid;END IF;
 IF p_command='enroll' AND NOT v_replayed THEN
  SELECT * INTO f FROM public.merchant_2fa_factors WHERE custom_user_id=p_actor_id AND factor_type='totp' AND deleted_at IS NULL AND status<>'disabled' FOR UPDATE;
 ELSE
  SELECT * INTO f FROM public.merchant_2fa_factors WHERE id=v_factor AND custom_user_id=p_actor_id AND factor_type='totp' AND deleted_at IS NULL FOR UPDATE;
 END IF;
 IF p_command='enroll' THEN
  IF f.id IS NOT NULL AND f.status<>'pending' THEN RETURN jsonb_build_object('accepted',false,'code','TWO_FACTOR_ALREADY_ENABLED');END IF;
  IF v_replayed AND f.id IS NULL THEN RETURN jsonb_build_object('accepted',false,'code','TWO_FACTOR_STATE_CHANGED');END IF;
  IF f.id IS NULL THEN
   IF coalesce(p_input->>'secret_ciphertext','')='' OR coalesce(p_input->>'label','')='' THEN RAISE EXCEPTION 'missing encrypted enrollment input';END IF;
   INSERT INTO public.merchant_2fa_factors(custom_user_id,factor_type,status,issuer,label,secret_ciphertext,metadata,created_by,updated_by)
   VALUES(p_actor_id,'totp','pending','LetBuyy',p_input->>'label',p_input->>'secret_ciphertext','{"algorithm":"SHA1","digits":6,"period":30}',p_actor_id,p_actor_id) RETURNING * INTO f;
  END IF;
 ELSIF f.id IS NULL OR (f.status='disabled' AND NOT(v_replayed AND p_command='disable')) THEN
  RETURN jsonb_build_object('accepted',false,'code','TWO_FACTOR_NOT_FOUND');
 ELSE
  -- Verification was performed by the service against exactly this encrypted
  -- factor version. A concurrent disable/activation cannot invalidate that read
  -- and then be silently overwritten here.
  IF encode(extensions.digest(f.secret_ciphertext,'sha256'),'hex') IS DISTINCT FROM p_input->>'secret_sha256' THEN
   RETURN jsonb_build_object('accepted',false,'code','TWO_FACTOR_STATE_CHANGED');END IF;
  IF v_replayed THEN
   IF p_command='verify' AND (f.status<>'active' OR p_input->>'proof_kind' IS DISTINCT FROM 'totp' OR p_input->>'proof_verified' IS DISTINCT FROM 'true'
      OR r.created_at<clock_timestamp()-interval '10 minutes') THEN RETURN jsonb_build_object('accepted',false,'code','TWO_FACTOR_STATE_CHANGED');END IF;
   IF p_command='disable' AND f.status<>'disabled' THEN RETURN jsonb_build_object('accepted',false,'code','TWO_FACTOR_STATE_CHANGED');END IF;
  ELSIF p_command='verify' THEN
   IF f.status<>'pending' THEN RETURN jsonb_build_object('accepted',false,'code','TWO_FACTOR_ALREADY_ENABLED');END IF;
   IF p_input->>'proof_kind' IS DISTINCT FROM 'totp' OR p_input->>'proof_verified' IS DISTINCT FROM 'true' THEN RETURN jsonb_build_object('accepted',false,'code','TWO_FACTOR_CODE_INVALID');END IF;
   SELECT array_agg(h) INTO v_recovery FROM jsonb_array_elements_text(p_input->'recovery_hashes')h;
   IF coalesce(array_length(v_recovery,1),0)<>8 OR EXISTS(SELECT 1 FROM unnest(v_recovery)h WHERE h!~'^[0-9a-f]{64}$') OR coalesce(p_input->>'result_ciphertext','')='' THEN RAISE EXCEPTION 'invalid encrypted recovery receipt';END IF;
   UPDATE public.merchant_2fa_factors SET status='active',enrolled_at=coalesce(enrolled_at,clock_timestamp()),last_verified_at=clock_timestamp(),
    recovery_code_hashes=v_recovery,updated_by=p_actor_id WHERE id=f.id RETURNING * INTO f;
  ELSE
   IF f.status IS DISTINCT FROM p_input->>'expected_status' THEN RETURN jsonb_build_object('accepted',false,'code','TWO_FACTOR_STATE_CHANGED');END IF;
   IF f.status='active' AND NOT(coalesce(p_input->>'proof_kind'='totp' AND p_input->>'proof_verified'='true',false)
     OR coalesce(p_input->>'proof_kind'='recovery' AND p_input->>'recovery_hash'=ANY(f.recovery_code_hashes),false)) THEN
     RETURN jsonb_build_object('accepted',false,'code','TWO_FACTOR_CODE_INVALID');END IF;
   UPDATE public.merchant_2fa_factors SET status='disabled',disabled_at=clock_timestamp(),recovery_code_hashes='{}',updated_by=p_actor_id WHERE id=f.id RETURNING * INTO f;
  END IF;
 END IF;
 IF NOT v_replayed THEN
  INSERT INTO public.merchant_totp_commands_v1(actor_id,command_key,command,factor_id,result_ciphertext)
   VALUES(p_actor_id,p_key,p_command,f.id,CASE WHEN p_command='verify' THEN p_input->>'result_ciphertext' END) RETURNING * INTO r;
  INSERT INTO public.audit_logs(actor_id,actor_type,action,resource_type,resource_id,metadata)
   VALUES(p_actor_id,'user','merchant.totp.'||p_command,'merchant_2fa_factor',f.id,jsonb_build_object('status',f.status,'command_version',1));
 END IF;
 RETURN jsonb_build_object('accepted',true,'factor',to_jsonb(f),'result_ciphertext',r.result_ciphertext,'replayed',v_replayed);
END

DECLARE x record;n integer:=0;
BEGIN
 FOR x IN UPDATE public.idempotency_keys SET status='failed',status_code=409,response_hash=NULL,locked_until=NULL,
  response_body='{"error":{"code":"CREDENTIAL_RECEIPT_RETIRED","message":"Reload account security before retrying this operation."}}'
  WHERE scope IN ('http:POST:/2fa/totp/enroll','http:POST:/2fa/totp/verify')
   AND(response_body#>'{data,secret}'IS NOT NULL OR response_body#>'{data,otpauth_uri}'IS NOT NULL OR response_body#>'{data,recovery_codes}'IS NOT NULL)
  RETURNING id,scope
 LOOP
  INSERT INTO public.audit_logs(actor_type,action,resource_type,resource_id,metadata)
   VALUES('system','merchant.totp.legacy_receipt_retired','idempotency_key',x.id,jsonb_build_object('scope',x.scope,'credentials_removed',true));n:=n+1;
 END LOOP;
 RETURN n;
END

DECLARE s public.sites%ROWTYPE;r public.data_subject_requests%ROWTYPE;v_key text;v_hash text;v_replayed boolean:=false;
BEGIN
 IF p_key IS NULL OR char_length(p_key) NOT BETWEEN 8 AND 200 OR p_reason IS NULL OR char_length(trim(p_reason)) NOT BETWEEN 8 AND 1000 OR coalesce(p_email,'')='' THEN
  RETURN jsonb_build_object('accepted',false,'code','DSR_INTENT_INVALID');END IF;
 SELECT * INTO s FROM public.sites WHERE id=p_site AND deleted_at IS NULL FOR UPDATE;
 IF NOT FOUND OR NOT(coalesce(s.custom_user_id=p_actor,false)OR coalesce(s.user_id=p_actor,false)) THEN RETURN jsonb_build_object('accepted',false,'code','DSR_NOT_FOUND');END IF;
 v_key:='merchant-erasure-review-v1:'||p_site::text||':'||p_actor::text||':'||p_key;
 v_hash:=encode(extensions.digest(jsonb_build_object('site',p_site,'actor',p_actor,'email',lower(trim(p_email)),'reason',p_reason)::text,'sha256'),'hex');
 SELECT * INTO r FROM public.data_subject_requests WHERE source='manual' AND idempotency_key=v_key AND deleted_at IS NULL FOR UPDATE;
 IF FOUND THEN
  IF r.site_id IS DISTINCT FROM p_site OR r.actor_id IS DISTINCT FROM p_actor OR r.request_type<>'erasure' OR r.metadata->>'intake_sha256' IS DISTINCT FROM v_hash THEN
   RETURN jsonb_build_object('accepted',false,'code','IDEMPOTENCY_CONFLICT');END IF;
  v_replayed:=true;
 ELSE
  -- A pre-fix request under this same actor/site/key needs review of its actual
  -- history. Never relabel a historical partial or fulfilled erasure as pending.
  IF EXISTS(SELECT 1 FROM public.data_subject_requests WHERE source='manual'AND idempotency_key=p_key AND site_id=p_site AND actor_id=p_actor AND deleted_at IS NULL)THEN
   RETURN jsonb_build_object('accepted',false,'code','DSR_LEGACY_REVIEW_REQUIRED');END IF;
  INSERT INTO public.data_subject_requests(site_id,request_type,subject_type,subject_email,subject_display,source,status,due_at,idempotency_key,reason,metadata,actor_type,actor_id,request_id,created_by,updated_by)
   VALUES(p_site,'erasure','customer',lower(trim(p_email)),lower(trim(p_email)),'manual','open',clock_timestamp()+interval '30 days',v_key,p_reason,
    jsonb_build_object('intake_sha256',v_hash,'review_required',true,'policy_hold','D05.4-8','erasure_authorized',false),'system',p_actor,p_request_id,p_actor,p_actor) RETURNING * INTO r;
  INSERT INTO public.audit_logs(actor_id,actor_type,action,resource_type,resource_id,metadata)
   VALUES(p_actor,'user','customer.erasure.review_requested','data_subject_request',r.id,jsonb_build_object('site_id',p_site,'policy_hold','D05.4-8','erased',false));
  INSERT INTO public.outbox_events(store_id,site_id,aggregate_type,aggregate_id,event_type,payload,idempotency_key,request_id,actor_id,schema_version)
   VALUES(p_site,p_site,'customer',r.id,'customer.dsr_requested',jsonb_build_object('site_id',p_site,'customer_id',r.id,'customer_email_hash',encode(extensions.digest(lower(trim(p_email)),'sha256'),'hex'),'request_type','erasure'),
    'customer.dsr_requested:'||r.id::text,p_request_id,p_actor,1);
 END IF;
 IF r.status='fulfilled' OR r.fulfilled_at IS NOT NULL THEN RETURN jsonb_build_object('accepted',false,'code','DSR_LEGACY_REVIEW_REQUIRED');END IF;
 RETURN jsonb_build_object('accepted',true,'request_id',r.id,'status',r.status,'erased',false,'review_required',true,'policy_hold','D05.4-8','replayed',v_replayed);
END

DECLARE f public.merchant_2fa_factors%ROWTYPE;s public.sites%ROWTYPE;x public.step_up_challenges%ROWTYPE;v_hash text;v_replayed boolean:=false;
BEGIN
 IF p_actor IS NULL OR p_site IS NULL OR p_factor IS NULL OR p_action IS NULL OR p_action NOT IN('refund.approve','payout.release','customer.dsr.export','customer.dsr.erase') OR p_key IS NULL OR char_length(p_key)NOT BETWEEN 8 AND 200 THEN RETURN jsonb_build_object('accepted',false,'code','STEP_UP_INTENT_INVALID');END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('letbuyy:merchant-totp:'||p_actor::text,0));
 SELECT * INTO f FROM public.merchant_2fa_factors WHERE id=p_factor AND custom_user_id=p_actor AND factor_type='totp'AND status='active'AND deleted_at IS NULL FOR SHARE;
 IF f.id IS NULL OR encode(extensions.digest(f.secret_ciphertext,'sha256'),'hex')IS DISTINCT FROM p_factor_sha256 THEN RETURN jsonb_build_object('accepted',false,'code','STEP_UP_FACTOR_REQUIRED');END IF;
 SELECT * INTO s FROM public.sites WHERE id=p_site AND deleted_at IS NULL FOR SHARE;
 IF s.id IS NULL OR NOT(coalesce(s.custom_user_id=p_actor,false)OR coalesce(s.user_id=p_actor,false))THEN RETURN jsonb_build_object('accepted',false,'code','STEP_UP_OWNER_REQUIRED');END IF;
 v_hash:=encode(extensions.digest(jsonb_build_object('site',p_site,'actor',p_actor,'factor',p_factor,'action',p_action)::text,'sha256'),'hex');
 SELECT * INTO x FROM public.step_up_challenges WHERE site_id=p_site AND idempotency_key=p_key FOR UPDATE;
 IF FOUND THEN
  IF x.actor_id IS DISTINCT FROM p_actor OR x.action IS DISTINCT FROM p_action OR x.metadata->>'factor_id'IS DISTINCT FROM p_factor::text OR x.metadata->>'merchant_intent_sha256'IS DISTINCT FROM v_hash THEN RETURN jsonb_build_object('accepted',false,'code','IDEMPOTENCY_CONFLICT');END IF;
  IF x.metadata->>'factor_sha256'IS DISTINCT FROM p_factor_sha256 OR x.deleted_at IS NOT NULL OR x.status<>'verified'OR x.expires_at<=clock_timestamp()THEN RETURN jsonb_build_object('accepted',false,'code','STEP_UP_EXPIRED');END IF;
  IF x.merchant_result_ciphertext IS NULL THEN RETURN jsonb_build_object('accepted',false,'code','STEP_UP_LEGACY_KEY_REQUIRES_REVIEW');END IF;
  v_replayed:=true;
 ELSE
  IF jsonb_typeof(p_proof)IS DISTINCT FROM 'object'OR coalesce(p_proof->>'token_sha256','')!~'^[0-9a-f]{64}$' OR coalesce(p_proof->>'result_ciphertext','')='' OR coalesce(p_proof->>'jti','')='' OR
   nullif(p_proof->>'verified_at','')IS NULL OR nullif(p_proof->>'expires_at','')IS NULL OR
   (p_proof->>'verified_at')::timestamptz<clock_timestamp()-interval '1 minute'OR(p_proof->>'verified_at')::timestamptz>clock_timestamp()+interval '1 minute'OR
   (p_proof->>'expires_at')::timestamptz<=clock_timestamp()OR(p_proof->>'expires_at')::timestamptz>clock_timestamp()+interval '10 minutes 5 seconds'THEN RETURN jsonb_build_object('accepted',false,'code','STEP_UP_INTENT_INVALID');END IF;
  INSERT INTO public.step_up_challenges(id,site_id,actor_id,action,status,challenge_token_hash,verified_at,expires_at,idempotency_key,metadata,merchant_result_ciphertext,created_by,updated_by)
   VALUES((p_proof->>'id')::uuid,p_site,p_actor,p_action,'verified',p_proof->>'token_sha256',(p_proof->>'verified_at')::timestamptz,(p_proof->>'expires_at')::timestamptz,p_key,
    jsonb_build_object('mode','crypto','method','totp','step_up_crypto','hmac-sha256','factor_id',p_factor,'factor_sha256',p_factor_sha256,'merchant_intent_sha256',v_hash,'jti',p_proof->>'jti'),p_proof->>'result_ciphertext',p_actor,p_actor)RETURNING * INTO x;
  INSERT INTO public.audit_logs(actor_id,actor_type,action,resource_type,resource_id,metadata)
   VALUES(p_actor,'user','merchant.step_up.verified','step_up_challenge',x.id,jsonb_build_object('site_id',p_site,'action',p_action,'factor_id',p_factor,'request_id',p_proof->>'request_id'));
  INSERT INTO public.outbox_events(store_id,site_id,aggregate_type,aggregate_id,event_type,idempotency_key,actor_id,schema_version,payload,request_id,trace_id)
   VALUES(p_site,p_site,'auth',x.id,'auth.stepup','auth.stepup:'||x.id::text,p_actor,1,jsonb_build_object('site_id',p_site,'action',p_action,'status','verified','method','totp'),p_proof->>'request_id',p_proof->>'request_id');
 END IF;
 RETURN jsonb_build_object('accepted',true,'challenge',jsonb_build_object('id',x.id,'site_id',x.site_id,'action',x.action,'status',x.status,'verified_at',x.verified_at,'expires_at',x.expires_at),'result_ciphertext',x.merchant_result_ciphertext,'replayed',v_replayed);
END

DECLARE x public.step_up_challenges%ROWTYPE;f public.merchant_2fa_factors%ROWTYPE;v_verified timestamptz;v_expires timestamptz;
BEGIN
 IF p_site IS NULL OR p_actor IS NULL OR jsonb_typeof(p_evidence)IS DISTINCT FROM 'object'OR coalesce(p_evidence->>'challenge_id','')!~'^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN RETURN false;END IF;
 BEGIN
  v_verified:=nullif(p_evidence->>'verified_at','')::timestamptz;v_expires:=nullif(p_evidence->>'expires_at','')::timestamptz;
 EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN RETURN false;END;
 IF v_verified IS NULL OR v_expires IS NULL THEN RETURN false;END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('letbuyy:merchant-totp:'||p_actor::text,0));
 SELECT * INTO x FROM public.step_up_challenges WHERE id=(p_evidence->>'challenge_id')::uuid AND site_id=p_site AND actor_id=p_actor AND action=p_action AND status='verified'AND deleted_at IS NULL FOR SHARE;
 IF x.id IS NULL OR x.verified_at IS DISTINCT FROM v_verified OR x.expires_at IS DISTINCT FROM v_expires OR x.verified_at>clock_timestamp()+interval '1 minute'OR x.expires_at<=clock_timestamp()OR x.verified_at<clock_timestamp()-interval '10 minutes'OR x.merchant_result_ciphertext IS NULL OR x.challenge_token_hash IS DISTINCT FROM p_evidence->>'token_sha256' OR x.metadata->>'jti'IS DISTINCT FROM p_evidence->>'jti'OR coalesce(x.metadata->>'factor_id','')!~'^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'THEN RETURN false;END IF;
 SELECT * INTO f FROM public.merchant_2fa_factors WHERE id=(x.metadata->>'factor_id')::uuid AND custom_user_id=p_actor AND factor_type='totp'AND status='active'AND deleted_at IS NULL FOR SHARE;
 IF f.id IS NULL OR encode(extensions.digest(f.secret_ciphertext,'sha256'),'hex')IS DISTINCT FROM x.metadata->>'factor_sha256'THEN RETURN false;END IF;
 RETURN EXISTS(SELECT 1 FROM public.sites WHERE id=p_site AND deleted_at IS NULL AND(custom_user_id=p_actor OR user_id=p_actor));
END

DECLARE s public.sites%ROWTYPE;p public.payments%ROWTYPE;a public.payment_attempts%ROWTYPE;r jsonb;v_amount bigint;v_ledger public.ledger_transactions%ROWTYPE;v_ref text;
BEGIN
 IF p_actor_id IS NULL OR p_site_id IS NULL OR p_payment_id IS NULL OR(p_amount_minor IS NOT NULL AND p_amount_minor<=0)OR p_idempotency_key IS NULL OR char_length(p_idempotency_key)NOT BETWEEN 8 AND 200 OR p_idempotency_key<>btrim(p_idempotency_key)OR p_idempotency_key~'[[:cntrl:]]'THEN RETURN jsonb_build_object('accepted',false,'status',400,'code','REFUND_INTENT_INVALID');END IF;
 IF nullif(current_setting('app.site_id',true),'')IS NOT NULL AND nullif(current_setting('app.site_id',true),'')::uuid IS DISTINCT FROM p_site_id THEN RETURN jsonb_build_object('accepted',false,'status',403,'code','MONEY_TENANT_MISMATCH');END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('letbuyy:merchant-totp:'||p_actor_id::text,0));
 SELECT * INTO s FROM public.sites WHERE id=p_site_id AND deleted_at IS NULL FOR SHARE;
 IF s.id IS NULL OR NOT(coalesce(s.custom_user_id=p_actor_id,false)OR coalesce(s.user_id=p_actor_id,false))THEN RETURN jsonb_build_object('accepted',false,'status',403,'code','MONEY_OWNER_REQUIRED');END IF;
 IF NOT public.verify_merchant_step_up_v1(p_site_id,p_actor_id,'refund.approve',p_step_up)THEN RETURN jsonb_build_object('accepted',false,'status',428,'code','STEP_UP_INVALID');END IF;
 SELECT * INTO p FROM public.payments WHERE id=p_payment_id AND site_id=p_site_id AND deleted_at IS NULL FOR UPDATE;
 IF p.id IS NULL THEN RETURN jsonb_build_object('accepted',false,'status',404,'code','PAYMENT_NOT_FOUND');END IF;
 SELECT * INTO a FROM public.payment_attempts WHERE payment_id=p_payment_id AND site_id=p_site_id AND attempt_type='refund'AND idempotency_key=p_idempotency_key AND deleted_at IS NULL FOR UPDATE;
 IF a.id IS NOT NULL AND a.created_by IS DISTINCT FROM p_actor_id THEN RETURN jsonb_build_object('accepted',false,'status',409,'code','REFUND_CLAIM_ACTOR_MISMATCH');END IF;
 v_amount:=coalesce(p_amount_minor,CASE WHEN a.id IS NOT NULL THEN round(a.amount*100)::bigint ELSE p.amount_minor-coalesce(p.refunded_amount_minor,0)END);
 IF v_amount IS NULL OR v_amount<=0 OR v_amount>p.amount_minor THEN RETURN jsonb_build_object('accepted',false,'status',409,'code','REFUND_AMOUNT_INVALID');END IF;
 IF a.id IS NULL AND p_metadata->>'_requires_existing_claim'='true'THEN RETURN jsonb_build_object('accepted',false,'status',409,'code','REFUND_REVIEW_REQUIRED');END IF;
 IF a.id IS NOT NULL THEN
  IF round(a.amount*100)::bigint IS DISTINCT FROM v_amount OR a.currency IS DISTINCT FROM p.currency THEN RETURN jsonb_build_object('accepted',false,'status',409,'code','REFUND_AMOUNT_CONFLICT');END IF;
  IF nullif(p_metadata->>'provider_refund_id','')IS NOT NULL AND nullif(a.metadata->>'provider_refund_id','')IS NOT NULL AND p_metadata->>'provider_refund_id'IS DISTINCT FROM a.metadata->>'provider_refund_id'THEN RETURN jsonb_build_object('accepted',false,'status',409,'code','REFUND_REFERENCE_MISMATCH');END IF;
  IF a.status='succeeded'THEN
   v_ref:=nullif(a.metadata->>'provider_refund_id','');
   IF v_ref IS NULL OR coalesce(a.metadata->>'canonical_ledger_transaction_id','')!~'^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'OR p.status NOT IN('captured','refunded')OR p.currency<>'INR'OR coalesce(p.refunded_amount_minor,0)<v_amount OR p.refunded_amount_minor>p.amount_minor THEN RETURN jsonb_build_object('accepted',false,'status',409,'code','REFUND_REVIEW_REQUIRED');END IF;
   SELECT * INTO v_ledger FROM public.ledger_transactions WHERE id=(a.metadata->>'canonical_ledger_transaction_id')::uuid AND site_id=p_site_id AND source_type='refund'AND source_id=v_ref AND currency='INR';
   IF v_ledger.id IS NULL OR(SELECT count(*)FROM public.ledger_transactions WHERE site_id=p_site_id AND source_type='refund'AND source_id=v_ref)<>1 OR
    (SELECT coalesce(sum(amount_minor),0)FROM public.ledger_entries WHERE transaction_id=v_ledger.id AND side='debit')<>v_amount OR
    (SELECT coalesce(sum(amount_minor),0)FROM public.ledger_entries WHERE transaction_id=v_ledger.id AND side='credit')<>v_amount THEN RETURN jsonb_build_object('accepted',false,'status',409,'code','REFUND_REVIEW_REQUIRED');END IF;
   RETURN jsonb_build_object('accepted',true,'reservation',jsonb_build_object('attempt_id',a.id,'status',a.status,'created',false,'amount_minor',v_amount,'provider_refund_id',v_ref),
    'completed',jsonb_build_object('payment',to_jsonb(p),'fully_refunded',p.status='refunded','ledger_transaction_id',v_ledger.id),'source_replayed',true);
  END IF;
 END IF;
 IF p.status<>'captured'THEN RETURN jsonb_build_object('accepted',false,'status',409,'code','PAYMENT_NOT_REFUNDABLE');END IF;
 r:=public.reserve_payment_refund_attempt(p_payment_id,v_amount,p_idempotency_key,p_request_id,p_actor_id,
  (coalesce(p_metadata,'{}'::jsonb)-ARRAY['step_up_token','step_up_verified_at','_requires_existing_claim'])||p_step_up);
 IF(r->>'created')::boolean THEN
  INSERT INTO public.audit_logs(actor_id,actor_type,action,resource_type,resource_id,metadata)
   VALUES(p_actor_id,'user','merchant.payment_refund.authorized','payment_attempt',(r->>'attempt_id')::uuid,
    jsonb_build_object('site_id',p_site_id,'payment_id',p_payment_id,'amount_minor',v_amount,'challenge_id',p_step_up->>'challenge_id','request_id',p_request_id));
 END IF;
 RETURN jsonb_build_object('accepted',true,'reservation',r,'payment',to_jsonb(p));
END

DECLARE s public.sites%ROWTYPE;v_before public.payout_statements%ROWTYPE;v_after public.payout_statements%ROWTYPE;
BEGIN
 IF p_site_id IS NULL OR p_statement_id IS NULL OR p_actor_id IS NULL OR p_idempotency_key IS NULL OR char_length(p_idempotency_key)NOT BETWEEN 8 AND 200 OR p_idempotency_key<>btrim(p_idempotency_key)OR p_idempotency_key~'[[:cntrl:]]'THEN RETURN jsonb_build_object('accepted',false,'status',400,'code','PAYOUT_INTENT_INVALID');END IF;
 IF nullif(current_setting('app.site_id',true),'')IS NOT NULL AND nullif(current_setting('app.site_id',true),'')::uuid IS DISTINCT FROM p_site_id THEN RETURN jsonb_build_object('accepted',false,'status',403,'code','MONEY_TENANT_MISMATCH');END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('letbuyy:merchant-totp:'||p_actor_id::text,0));
 SELECT * INTO s FROM public.sites WHERE id=p_site_id AND deleted_at IS NULL FOR SHARE;
 IF s.id IS NULL OR NOT(coalesce(s.custom_user_id=p_actor_id,false)OR coalesce(s.user_id=p_actor_id,false))THEN RETURN jsonb_build_object('accepted',false,'status',403,'code','MONEY_OWNER_REQUIRED');END IF;
 IF NOT public.verify_merchant_step_up_v1(p_site_id,p_actor_id,'payout.release',p_step_up)THEN RETURN jsonb_build_object('accepted',false,'status',428,'code','STEP_UP_INVALID');END IF;
 -- Preserve the canonical site advisory -> statement lock order.
 PERFORM pg_advisory_xact_lock(hashtextextended('payout-release:'||p_site_id::text,0));
 SELECT * INTO v_before FROM public.payout_statements WHERE id=p_statement_id AND site_id=p_site_id AND deleted_at IS NULL FOR UPDATE;
 IF v_before.id IS NULL THEN RETURN jsonb_build_object('accepted',false,'status',404,'code','PAYOUT_NOT_FOUND');END IF;
 IF v_before.status='processing'AND v_before.release_claimed_by IS DISTINCT FROM p_actor_id THEN RETURN jsonb_build_object('accepted',false,'status',409,'code','PAYOUT_CLAIM_ACTOR_MISMATCH');END IF;
 SELECT * INTO v_after FROM public.claim_payout_statement_release(p_site_id,p_statement_id,p_idempotency_key,p_actor_id);
 IF v_after.id IS NULL OR v_after.status NOT IN('processing','released')THEN RAISE EXCEPTION 'payout claim requires review before provider contact';END IF;
 IF v_before.status='pending'AND v_after.status='processing'THEN
  UPDATE public.payout_statements SET metadata=coalesce(metadata,'{}'::jsonb)||p_step_up WHERE id=p_statement_id AND site_id=p_site_id RETURNING * INTO v_after;
  INSERT INTO public.audit_logs(actor_id,actor_type,action,resource_type,resource_id,metadata)
   VALUES(p_actor_id,'user','merchant.payout_release.authorized','payout_statement',p_statement_id,
    jsonb_build_object('site_id',p_site_id,'amount_minor',v_after.net_amount_minor_bigint,'challenge_id',p_step_up->>'challenge_id','request_id',p_request_id));
 END IF;
 RETURN jsonb_build_object('accepted',true,'statement',to_jsonb(v_after));
END

DECLARE s public.sites;
BEGIN
 -- Staff lifecycle also takes this site lock. Revocation and receipt replay
 -- therefore cannot race an authorization snapshot on another connection.
 SELECT * INTO s FROM public.sites WHERE id=p_site AND deleted_at IS NULL FOR UPDATE;
 IF s.id IS NULL OR p_actor IS NULL OR(p_bound_site IS NOT NULL AND p_bound_site<>p_site)
  OR NOT EXISTS(SELECT 1 FROM public.users_custom WHERE id=p_actor) THEN
  RAISE EXCEPTION 'Theme access denied' USING ERRCODE='42501'; END IF;
 IF NOT(coalesce(s.custom_user_id=p_actor,false) OR coalesce(s.user_id=p_actor,false)) AND NOT EXISTS(
  SELECT 1 FROM public.employees e WHERE e.store_id=p_site AND e.user_id=p_actor
   AND e.status='active' AND e.is_active=true AND e.deleted_at IS NULL
   AND jsonb_typeof(e.permissions->'granted')='array'
   AND(e.permissions->'granted') ?| ARRAY['content:write','content:*','*']) THEN
  RAISE EXCEPTION 'Theme access denied' USING ERRCODE='42501'; END IF;
 RETURN s;
END

DECLARE s public.sites;t public.themes;i public.theme_instances;d public.theme_instance_drafts;e public.theme_editor_drafts;v integer;
BEGIN
 s:=public.theme_draft_actor_site_v1(p_actor_id,p_store_id,p_bound_site_id);
 SELECT * INTO t FROM public.themes WHERE slug=p_theme_slug AND is_active=true;
 IF t.id IS NULL OR(t.is_site_private AND t.owned_by_site_id IS DISTINCT FROM p_store_id) THEN
  RAISE EXCEPTION 'Theme not available' USING ERRCODE='42501'; END IF;
 SELECT * INTO i FROM public.theme_instances WHERE store_id=p_store_id AND theme_slug=p_theme_slug AND deleted_at IS NULL
  ORDER BY updated_at DESC,id DESC LIMIT 1;
 SELECT * INTO d FROM public.theme_instance_drafts WHERE theme_instance_id=i.id AND store_id=p_store_id
  AND draft_status='active' AND deleted_at IS NULL ORDER BY updated_at DESC,id DESC LIMIT 1;
 SELECT * INTO e FROM public.theme_editor_drafts WHERE store_id=p_store_id AND theme_id=p_theme_slug AND template_key=p_template_key;
 v:=greatest(coalesce(i.draft_revision,0),coalesce((SELECT max(version) FROM public.theme_editor_drafts WHERE store_id=p_store_id AND theme_id=p_theme_slug),0));
 RETURN jsonb_build_object('store',to_jsonb(s),'version',v,'theme_instance_id',i.id,
  'theme_instance_draft_id',d.id,'legacy_draft_id',CASE WHEN e.deleted_at IS NULL THEN e.id END,
  'has_draft',d.id IS NOT NULL OR(e.id IS NOT NULL AND e.deleted_at IS NULL),
  'template_config',CASE WHEN d.id IS NOT NULL THEN d.working_manifest WHEN e.deleted_at IS NULL THEN e.draft_config END,
  'saved_at',to_char(coalesce(d.auto_saved_at,e.auto_saved_at) AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
END

DECLARE s public.sites;t public.themes;i public.theme_instances;d public.theme_instance_drafts;e public.theme_editor_drafts;
 receipt public.idempotency_keys;v_hash text;v_scope text;v_current integer;v_next integer;v_now timestamptz:=now();
 v_config jsonb;v_templates jsonb;v_item record;v_response jsonb;v_release record;v_manifest jsonb;v_patch uuid;
 v_package uuid;v_package_version uuid;v_schema text;v_instance_draft uuid;
 v_input jsonb;v_order jsonb;v_existing_order jsonb;v_sections jsonb;v_ids text[];
BEGIN
 IF p_operation IS NULL OR p_operation NOT IN('save','reorder','discard','publish') OR p_base_version IS NULL OR p_base_version<0 OR p_base_version>=2147483647
  OR p_key IS NULL OR char_length(p_key) NOT BETWEEN 8 AND 200 OR p_key<>btrim(p_key) OR p_key~'[[:cntrl:]]'
  OR p_template_key IS NULL OR char_length(p_template_key) NOT BETWEEN 1 AND 120
  OR p_template_key IN('__proto__','constructor','prototype')
  OR p_template_key!~'^[a-z0-9][a-z0-9_./-]*$' OR position('..' IN p_template_key)>0 OR position('//' IN p_template_key)>0
  OR (position('.' IN p_template_key)>0 AND split_part(p_template_key,'.',2)<>''
      AND substring(p_template_key FROM position('.' IN p_template_key)+1)!~'^[a-z0-9][a-z0-9_-]*$') THEN
  RAISE EXCEPTION 'Invalid theme draft intent' USING ERRCODE='PT400'; END IF;
 s:=public.theme_draft_actor_site_v1(p_actor_id,p_store_id,p_bound_site_id);
 SELECT * INTO t FROM public.themes WHERE slug=p_theme_slug AND is_active=true;
 IF t.id IS NULL OR(t.is_site_private AND t.owned_by_site_id IS DISTINCT FROM p_store_id) THEN
  RAISE EXCEPTION 'Theme not available' USING ERRCODE='42501'; END IF;
 SELECT * INTO i FROM public.theme_instances WHERE store_id=p_store_id AND theme_slug=p_theme_slug AND deleted_at IS NULL
  ORDER BY updated_at DESC,id DESC LIMIT 1 FOR UPDATE;
 v_current:=greatest(coalesce(i.draft_revision,0),coalesce((SELECT max(version) FROM public.theme_editor_drafts WHERE store_id=p_store_id AND theme_id=p_theme_slug),0));
 v_scope:='theme-draft-v1:'||p_actor_id::text||':'||p_theme_slug;
 v_hash:=encode(sha256(convert_to(jsonb_build_object('actor',p_actor_id,'store',p_store_id,'theme',p_theme_slug,
  'template',p_template_key,'base_version',p_base_version,'operation',p_operation,'config',p_config,'publish',p_publish_options)::text,'UTF8')),'hex');
 SELECT * INTO receipt FROM public.idempotency_keys WHERE site_id=p_store_id AND scope=v_scope AND key=p_key FOR UPDATE;
 IF FOUND THEN
  IF receipt.request_hash IS DISTINCT FROM v_hash THEN RAISE EXCEPTION 'Theme intent key has different content' USING ERRCODE='PT409'; END IF;
  IF receipt.status<>'completed' OR receipt.response_body IS NULL OR receipt.deleted_at IS NOT NULL THEN
   RAISE EXCEPTION 'Theme receipt unavailable' USING ERRCODE='PT503'; END IF;
  RETURN receipt.response_body||jsonb_build_object('replayed',true,'current_version',v_current);
 END IF;
 IF v_current<>p_base_version THEN
  RAISE EXCEPTION 'Theme draft has changed in another session' USING ERRCODE='PT409',DETAIL=jsonb_build_object('current_version',v_current)::text; END IF;
 v_next:=v_current+1;
 SELECT * INTO d FROM public.theme_instance_drafts WHERE theme_instance_id=i.id AND store_id=p_store_id
  AND draft_status='active' AND deleted_at IS NULL ORDER BY updated_at DESC,id DESC LIMIT 1 FOR UPDATE;
 SELECT * INTO e FROM public.theme_editor_drafts WHERE store_id=p_store_id AND theme_id=p_theme_slug AND template_key=p_template_key FOR UPDATE;

 IF p_operation='reorder' THEN
  v_order:=p_config->'section_order';
  IF jsonb_typeof(v_order) IS DISTINCT FROM 'array' OR jsonb_array_length(v_order)>500 THEN
   RAISE EXCEPTION 'Section order required' USING ERRCODE='PT400'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(v_order) x WHERE jsonb_typeof(x)<>'string' OR length(x#>>'{}') NOT BETWEEN 1 AND 200)
   OR (SELECT count(*) FROM jsonb_array_elements(v_order))<>(SELECT count(DISTINCT x) FROM jsonb_array_elements(v_order) x) THEN
   RAISE EXCEPTION 'Distinct section IDs required' USING ERRCODE='PT400'; END IF;
  v_input:=coalesce(d.working_manifest,CASE WHEN e.deleted_at IS NULL THEN e.draft_config END,p_runtime->'initial_config');
  IF jsonb_typeof(v_input) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Theme document unavailable' USING ERRCODE='PT503'; END IF;
  v_sections:=v_input->'templates'->p_template_key->'sections';
  v_existing_order:=v_input->'templates'->p_template_key->'order';
  IF jsonb_typeof(v_sections)='object' AND jsonb_typeof(v_existing_order)='array' THEN
   SELECT array_agg(x) INTO v_ids FROM jsonb_object_keys(v_sections) x;
  ELSIF jsonb_typeof(v_input->'sections'->'template')='array' THEN
   SELECT array_agg(x->>'id'),coalesce(jsonb_agg(x->'id'),'[]') INTO v_ids,v_existing_order FROM jsonb_array_elements(v_input->'sections'->'template') x;
  ELSE RAISE EXCEPTION 'Template sections unavailable' USING ERRCODE='PT409'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(v_order) x WHERE NOT(x=ANY(coalesce(v_ids,ARRAY[]::text[])))) THEN
   RAISE EXCEPTION 'Section order changed' USING ERRCODE='PT409'; END IF;
  SELECT v_order||coalesce(jsonb_agg(x ORDER BY n) FILTER(WHERE NOT(v_order ? (x#>>'{}'))),'[]') INTO v_order
   FROM jsonb_array_elements(v_existing_order) WITH ORDINALITY a(x,n);
  IF jsonb_typeof(v_sections)='object' THEN
   v_input:=jsonb_set(v_input,ARRAY['templates',p_template_key,'order'],v_order);
  END IF;
  IF jsonb_typeof(v_input->'sections'->'template')='array' THEN
   SELECT coalesce(jsonb_agg(x ORDER BY array_position(ARRAY(SELECT jsonb_array_elements_text(v_order)),x->>'id')),'[]') INTO v_sections
    FROM jsonb_array_elements(v_input->'sections'->'template') x;
   v_input:=jsonb_set(v_input,'{sections,template}',v_sections);
  END IF;
 ELSE v_input:=p_config;
 END IF;
 IF p_operation IN('save','reorder') THEN
  IF v_input IS NULL OR jsonb_typeof(v_input)<>'object' THEN RAISE EXCEPTION 'Theme document required' USING ERRCODE='PT400'; END IF;
  v_package:=(p_runtime->>'theme_package_id')::uuid;v_package_version:=(p_runtime->>'theme_package_version_id')::uuid;
  SELECT schema_version INTO v_schema FROM public.theme_package_versions WHERE id=v_package_version AND theme_package_id=v_package;
  IF v_schema IS NULL OR NOT EXISTS(SELECT 1 FROM public.theme_packages WHERE id=v_package AND slug=p_theme_slug) THEN
   RAISE EXCEPTION 'Canonical theme runtime unavailable' USING ERRCODE='PT503'; END IF;
  IF i.id IS NULL THEN
   INSERT INTO public.theme_instances(store_id,theme_package_id,theme_package_version_id,theme_slug,installed_config,settings,created_by,updated_by,draft_revision)
    VALUES(p_store_id,v_package,v_package_version,p_theme_slug,v_input,coalesce(v_input->'themeSettings','{}'),p_actor_id,p_actor_id,v_current) RETURNING * INTO i;
  ELSIF i.theme_package_id<>v_package THEN RAISE EXCEPTION 'Theme package changed' USING ERRCODE='PT409'; END IF;
  v_templates:=coalesce(v_input->'templates','{}');
  -- Preserve every saved template while the selected template and shared settings
  -- are changed under one global instance revision.
  IF d.id IS NOT NULL THEN v_templates:=v_templates||coalesce(d.working_manifest->'templates','{}'); END IF;
  FOR v_item IN SELECT template_key,draft_config FROM public.theme_editor_drafts WHERE store_id=p_store_id AND theme_id=p_theme_slug AND deleted_at IS NULL LOOP
   IF v_item.template_key<>p_template_key AND jsonb_typeof(v_item.draft_config->'templates'->v_item.template_key)='object' THEN
    v_templates:=jsonb_set(v_templates,ARRAY[v_item.template_key],v_item.draft_config->'templates'->v_item.template_key,true); END IF;
  END LOOP;
  IF jsonb_typeof(v_input->'templates'->p_template_key)='object' THEN
   v_templates:=jsonb_set(v_templates,ARRAY[p_template_key],v_input->'templates'->p_template_key,true); END IF;
  -- Shared groups are explicit document-wide edits, not unselected pages.
  -- Reapply only supplied header/footer groups after preserving prior pages.
  IF jsonb_typeof(v_input#>'{templates,header}')='object' THEN
   v_templates:=jsonb_set(v_templates,'{header}',v_input#>'{templates,header}',true); END IF;
  IF jsonb_typeof(v_input#>'{templates,footer}')='object' THEN
   v_templates:=jsonb_set(v_templates,'{footer}',v_input#>'{templates,footer}',true); END IF;
  v_config:=v_input||jsonb_build_object('templates',v_templates);
  IF d.id IS NULL THEN
   INSERT INTO public.theme_instance_drafts(theme_instance_id,store_id,base_release_id,draft_version,working_manifest,schema_manifest_version,created_by,updated_by)
    VALUES(i.id,p_store_id,i.active_release_id,v_next,v_config,v_schema,p_actor_id,p_actor_id) RETURNING * INTO d;
  ELSE
   UPDATE public.theme_instance_drafts SET draft_version=v_next,working_manifest=v_config,schema_manifest_version=v_schema,
    auto_saved_at=v_now,updated_at=v_now,updated_by=p_actor_id WHERE id=d.id AND store_id=p_store_id RETURNING * INTO d;
  END IF;
  INSERT INTO public.theme_editor_drafts(store_id,theme_id,template_key,draft_config,version,created_by,updated_by)
   VALUES(p_store_id,p_theme_slug,p_template_key,v_config,v_next,p_actor_id,p_actor_id)
   ON CONFLICT(store_id,theme_id,template_key) DO UPDATE SET draft_config=excluded.draft_config,version=v_next,
    deleted_at=NULL,auto_saved_at=v_now,updated_at=v_now,updated_by=p_actor_id RETURNING * INTO e;
  INSERT INTO public.theme_draft_patches(draft_id,store_id,patch_sequence,patch_type,operation,path,value,previous_value,actor_id,request_id,client_revision,server_revision,metadata)
   VALUES(d.id,p_store_id,v_next,'set',jsonb_build_object('op','replace','path','/','source','theme-editor-v1'), '/',v_config,NULL,p_actor_id,p_request_id,p_base_version,v_next,
    jsonb_build_object('template_key',p_template_key,'idempotency_key',p_key)) RETURNING id INTO v_patch;
  UPDATE public.theme_instances SET draft_revision=v_next,current_draft_id=d.id,theme_package_version_id=v_package_version,
   updated_at=v_now,updated_by=p_actor_id WHERE id=i.id AND store_id=p_store_id;
  INSERT INTO public.outbox_events(store_id,site_id,aggregate_type,aggregate_id,event_type,payload,idempotency_key,request_id,actor_id,schema_version)
   VALUES(p_store_id,p_store_id,'theme_draft',e.id::text,'theme.draft.saved',jsonb_build_object('store_id',p_store_id,'theme_id',p_theme_slug,'template_key',p_template_key,
    'theme_instance_id',i.id,'theme_package_version_id',v_package_version,'theme_instance_draft_id',d.id,'draft_id',e.id,'version',v_next,'client',p_runtime->>'client'),
    'theme.draft.saved:'||i.id::text||':'||v_next,p_request_id,p_actor_id,1);
  v_response:=jsonb_build_object('saved_at',to_char(v_now AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'version',v_next,'template_key',p_template_key,'draft',jsonb_build_object('id',e.id,'version',v_next,'auto_saved_at',to_char(v_now AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')));
  IF p_operation='reorder' THEN v_response:=v_response||jsonb_build_object('section_order',v_order); END IF;
 ELSE
  IF d.id IS NULL THEN RAISE EXCEPTION 'No saved theme draft exists' USING ERRCODE='PT409'; END IF;
  v_config:=d.working_manifest;
  IF p_operation='publish' THEN
   IF p_base_version=0 OR(p_config IS NOT NULL AND p_config IS DISTINCT FROM v_config) THEN
    RAISE EXCEPTION 'Save the exact theme draft before publishing' USING ERRCODE='PT409'; END IF;
   SELECT * INTO v_release FROM public.publish_theme_release(p_store_id,p_theme_slug,v_config,e.id,p_base_version,p_actor_id,
    p_publish_options->>'publish_message',coalesce((p_publish_options->>'make_store_live')::boolean,true),p_request_id,NULL);
   UPDATE public.theme_instance_drafts SET draft_status='published',updated_at=v_now,updated_by=p_actor_id
    WHERE id=d.id AND store_id=p_store_id;
   -- Keep the existing renderer artifacts inside this transaction rather than a
   -- post-commit enrichment that can return false failure after switching release.
   v_manifest:=coalesce(p_runtime->'release_manifest','{}')||jsonb_build_object('store_id',p_store_id,'theme_id',p_theme_slug,
    'release_id',v_release.release_id,'release_version',v_release.release_version,'theme_instance_id',i.id,'theme_package_version_id',i.theme_package_version_id);
   UPDATE public.theme_releases SET release_manifest=v_manifest,asset_manifest=coalesce(p_runtime->'asset_manifest','{}'),
    settings_snapshot=coalesce(v_config->'themeSettings','{}'),template_snapshot=v_config,
    idempotency_key=p_key WHERE id=v_release.release_id AND store_id=p_store_id;
   v_response:=jsonb_build_object('version',v_next,'template_key',p_template_key,'release',jsonb_build_object('release_id',v_release.release_id,'release_version',v_release.release_version,'published_at',to_char(v_release.published_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')),'published_at',to_char(v_release.published_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
    'theme',jsonb_build_object('id',t.id,'slug',t.slug,'name',t.name),'store',(SELECT jsonb_build_object('id',x.id,'status',x.status,'theme_id',x.theme_id,
     'current_theme_release_id',x.current_theme_release_id,'storefront_release_version',x.storefront_release_version,'updated_at',to_char(x.updated_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')) FROM public.sites x WHERE id=p_store_id));
  ELSE
   UPDATE public.theme_instance_drafts SET draft_status='discarded',deleted_at=v_now,updated_at=v_now,updated_by=p_actor_id WHERE id=d.id AND store_id=p_store_id;
   v_response:=jsonb_build_object('deleted',true,'version',v_next,'template_key',p_template_key);
   INSERT INTO public.outbox_events(store_id,site_id,aggregate_type,aggregate_id,event_type,payload,idempotency_key,request_id,actor_id,schema_version)
    VALUES(p_store_id,p_store_id,'theme_draft',d.id::text,'theme.draft.discarded',jsonb_build_object('store_id',p_store_id,'theme_id',p_theme_slug,'template_key',p_template_key,
     'draft_id',d.id,'version',v_next),'theme.draft.discarded:'||i.id::text||':'||v_next,p_request_id,p_actor_id,1);
  END IF;
  INSERT INTO public.theme_draft_patches(draft_id,store_id,patch_sequence,patch_type,operation,path,value,previous_value,actor_id,request_id,client_revision,server_revision,metadata)
   VALUES(d.id,p_store_id,v_next,CASE WHEN p_operation='discard' THEN 'delete' ELSE 'set' END,
    jsonb_build_object('op',p_operation,'path','/'), '/',CASE WHEN p_operation='publish' THEN v_config ELSE NULL END,v_config,
    p_actor_id,p_request_id,p_base_version,v_next,jsonb_build_object('template_key',p_template_key,'idempotency_key',p_key,'disposition',p_operation));
  UPDATE public.theme_instance_drafts SET draft_version=v_next WHERE id=d.id AND store_id=p_store_id;
  -- End the whole canonical document; retaining revision and tombstones prevents
  -- an old editor from reviving a previously used version after discard/publish.
  UPDATE public.theme_editor_drafts SET deleted_at=v_now,version=v_next,updated_at=v_now,updated_by=p_actor_id
   WHERE store_id=p_store_id AND theme_id=p_theme_slug;
  UPDATE public.theme_instances SET draft_revision=v_next,current_draft_id=NULL,updated_at=v_now,updated_by=p_actor_id WHERE id=i.id AND store_id=p_store_id;
 END IF;
 INSERT INTO public.audit_activity_events(store_id,actor_id,actor_type,action,resource_type,resource_id,request_id,before_state,after_state,metadata)
  VALUES(p_store_id,p_actor_id,CASE WHEN s.custom_user_id=p_actor_id OR s.user_id=p_actor_id THEN 'user' ELSE 'employee' END,
   'theme.draft.'||p_operation,'theme_draft',coalesce(d.id,e.id)::text,p_request_id,jsonb_build_object('version',v_current),jsonb_build_object('version',v_next),
   jsonb_build_object('theme_id',p_theme_slug,'template_key',p_template_key,'idempotency_key',p_key));
 INSERT INTO public.idempotency_keys(site_id,key,scope,request_hash,response_hash,response_body,status,status_code,resource_type,resource_id,request_id,expires_at)
  VALUES(p_store_id,p_key,v_scope,v_hash,encode(sha256(convert_to(v_response::text,'UTF8')),'hex'),v_response,'completed',200,'theme_draft',d.id,p_request_id,'infinity');
 RETURN v_response||jsonb_build_object('replayed',false,'current_version',v_next);
END

DECLARE s public.sites;e public.employees;v jsonb;a uuid;
BEGIN
 IF p_console IS NOT NULL THEN
  v:=public.console_permission_snapshot_v1((p_console->>'session_id')::uuid,p_console->>'cookie_sha256',p_write);
  IF NOT coalesce((v->>'accepted')::boolean,false) OR v->>'evidence_hash' IS DISTINCT FROM p_console->>'permission_hash' THEN RAISE EXCEPTION 'REEL_OPERATOR_REQUIRED'; END IF;
  a:=(v->'session'->>'actor_id')::uuid;
  IF a IS NULL OR (p_write AND NOT(coalesce((v->'input'->>'isSuperAdmin')::boolean,false) OR coalesce(v->'input'->>'role' IN('operations','manager','admin'),false))) THEN RAISE EXCEPTION 'REEL_OPERATOR_REQUIRED'; END IF;
  RETURN a;
 END IF;
 IF p_actor IS NULL OR p_site IS NULL OR (nullif(current_setting('app.site_id',true),'') IS NOT NULL AND public.current_site_id() IS DISTINCT FROM p_site) THEN RAISE EXCEPTION 'REEL_MERCHANT_REQUIRED'; END IF;
 SELECT * INTO s FROM public.sites WHERE id=p_site AND deleted_at IS NULL FOR SHARE;
 IF s.id IS NULL THEN RAISE EXCEPTION 'REEL_MERCHANT_REQUIRED'; END IF;
 PERFORM 1 FROM public.users_custom WHERE id=p_actor FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'REEL_MERCHANT_REQUIRED'; END IF;
 IF s.custom_user_id=p_actor OR s.user_id=p_actor THEN RETURN p_actor; END IF;
 SELECT * INTO e FROM public.employees WHERE store_id=p_site AND user_id=p_actor AND status='active' AND is_active AND deleted_at IS NULL FOR SHARE;
 -- Same content:write matching as canonical evaluateStaffPermission: exact, content:*, or *.
 IF e.id IS NULL OR jsonb_typeof(e.permissions->'granted') IS DISTINCT FROM 'array'
  OR NOT coalesce((e.permissions->'granted') ?| ARRAY['content:write','content:*','*'],false) THEN RAISE EXCEPTION 'REEL_MERCHANT_REQUIRED'; END IF;
 RETURN p_actor;
END

DECLARE m public.reel_asset_provenance;t public.reel_asset_provenance;r public.reel_processing_receipts;
 l public.channel_listings;p public.products;s public.sites;f text;rights json;v_id uuid;
BEGIN
 SELECT * INTO l FROM public.channel_listings WHERE id=(p_selection->>'listing_id')::uuid;
 SELECT * INTO p FROM public.products WHERE id=l.product_id FOR SHARE;
 SELECT * INTO s FROM public.sites WHERE id=p_site FOR SHARE;
 SELECT * INTO l FROM public.channel_listings WHERE id=l.id FOR SHARE;
 PERFORM 1 FROM public.product_variants WHERE product_id=p.id ORDER BY id FOR SHARE;
 IF l.id IS NULL OR l.site_id IS DISTINCT FROM p_site OR p.site_id IS DISTINCT FROM p_site OR l.product_id IS DISTINCT FROM p.id
  OR l.channel IS DISTINCT FROM 'marketplace' OR l.status IS DISTINCT FROM 'approved' OR l.visibility IS DISTINCT FROM 'public' OR p.is_active IS DISTINCT FROM true OR p.deleted_at IS NOT NULL OR s.status IS DISTINCT FROM 'published' OR s.deleted_at IS NOT NULL THEN RAISE EXCEPTION 'REEL_LISTING_UNAVAILABLE'; END IF;
 f:=public.marketplace_listing_review_fingerprint(l.id);
 IF f IS NULL OR f IS DISTINCT FROM l.approved_product_fingerprint THEN RAISE EXCEPTION 'REEL_PRODUCT_REVISION_STALE'; END IF;
 v_id:=(p_selection->>'variant_id')::uuid;
 IF (v_id IS NULL AND EXISTS(SELECT 1 FROM public.product_variants WHERE product_id=p.id)) OR
  (v_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.product_variants WHERE id=v_id AND product_id=p.id)) THEN RAISE EXCEPTION 'REEL_VARIANT_MISMATCH'; END IF;
 PERFORM 1 FROM public.media_assets WHERE id IN((p_selection->>'media_asset_id')::uuid,(p_selection->>'thumbnail_asset_id')::uuid) AND site_id=p_site ORDER BY id FOR SHARE;
 SELECT a.* INTO m FROM public.reel_asset_provenance a JOIN public.media_assets x ON x.id=a.media_asset_id AND x.site_id=a.site_id
  WHERE a.media_asset_id=(p_selection->>'media_asset_id')::uuid AND a.site_id=p_site AND a.kind='video' AND a.deleted_at IS NULL AND x.deleted_at IS NULL
  AND a.custody_verified_at<=clock_timestamp() AND x.asset_type='video' AND x.public_url IS NULL AND x.checksum_sha256=a.checksum_sha256 ORDER BY a.custody_verified_at DESC,a.id LIMIT 1 FOR SHARE OF a,x;
 SELECT a.* INTO t FROM public.reel_asset_provenance a JOIN public.media_assets x ON x.id=a.media_asset_id AND x.site_id=a.site_id
  WHERE a.media_asset_id=(p_selection->>'thumbnail_asset_id')::uuid AND a.site_id=p_site AND a.kind='image' AND a.deleted_at IS NULL AND x.deleted_at IS NULL
  AND a.custody_verified_at<=clock_timestamp() AND x.asset_type='image' AND x.public_url IS NULL AND x.checksum_sha256=a.checksum_sha256 ORDER BY a.custody_verified_at DESC,a.id LIMIT 1 FOR SHARE OF a,x;
 SELECT * INTO r FROM public.reel_processing_receipts WHERE provenance_id=m.id AND site_id=p_site AND state='ready' AND deleted_at IS NULL
  AND verified_at<=clock_timestamp() AND media_version=m.asset_version AND checksum_sha256=m.checksum_sha256 AND provider_asset_id=m.provider_asset_id ORDER BY verified_at DESC,id LIMIT 1 FOR SHARE;
 IF m.id IS NULL OR t.id IS NULL OR r.id IS NULL OR m.provider_asset_id IS NULL THEN RAISE EXCEPTION 'REEL_CUSTODY_UNAVAILABLE'; END IF;
 PERFORM 1 FROM public.reel_asset_provenance a JOIN public.media_assets x ON x.id=a.media_asset_id JOIN jsonb_array_elements_text(p_selection->'rights_evidence_ids') v ON a.id=v.value::uuid ORDER BY a.id FOR SHARE OF a,x;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(p_selection->'rights_evidence_ids') v LEFT JOIN public.reel_asset_provenance a
  ON a.id=v.value::uuid AND a.site_id=p_site AND a.kind='rights' AND a.deleted_at IS NULL AND a.custody_verified_at<=clock_timestamp()
  LEFT JOIN public.media_assets x ON x.id=a.media_asset_id AND x.site_id=p_site AND x.deleted_at IS NULL AND x.public_url IS NULL AND x.checksum_sha256=a.checksum_sha256
  WHERE a.id IS NULL OR x.id IS NULL) THEN RAISE EXCEPTION 'REEL_RIGHTS_EVIDENCE_UNAVAILABLE'; END IF;
 SELECT coalesce(json_agg(json_build_object('evidence_id',a.id,'version',a.asset_version,'checksum_sha256',a.checksum_sha256) ORDER BY a.id),'[]'::json) INTO rights
 FROM public.reel_asset_provenance a JOIN jsonb_array_elements_text(p_selection->'rights_evidence_ids') v ON a.id=v.value::uuid;
 RETURN public.reel_json_compact_v1(json_build_object('schema_version',1,'site_id',p_site,
  'media',json_build_object('asset_id',m.media_asset_id,'version',m.asset_version,'checksum_sha256',m.checksum_sha256,'processing_evidence_id',r.id,'provider_asset_id',r.provider_asset_id),
  'product',json_build_object('listing_id',l.id,'product_id',p.id,'variant_id',v_id,'approved_product_fingerprint',f),
  'caption',p_selection->>'caption','thumbnail',json_build_object('asset_id',t.media_asset_id,'version',t.asset_version,'checksum_sha256',t.checksum_sha256),'rights_evidence',rights));
END

DECLARE a uuid;h text;k text;act text;rr public.commerce_reels;rev public.commerce_reel_revisions;ev public.commerce_reel_events;
 selection jsonb;canonical text;result jsonb;ins public.reel_review_inspections;reason text;
BEGIN
 IF p_reel IS NULL OR p_site IS NULL OR p_command IS NULL OR jsonb_typeof(p_command)<>'object' OR octet_length(p_command::text)>32768
  OR p_command-ARRAY['action','expected_version','idempotency_key','selection','reason']<>'{}' THEN RAISE EXCEPTION 'REEL_REQUEST_INVALID'; END IF;
 act:=p_command->>'action';k:=p_command->>'idempotency_key';reason:=p_command->>'reason';
 IF act IS NULL OR act NOT IN('save','submit','claim','reject','approve','take_down') OR k IS NULL OR length(k) NOT BETWEEN 8 AND 200
  OR k<>btrim(k) OR k~'[[:cntrl:]]' OR coalesce(p_command->>'expected_version','')!~'^[0-9]{1,9}$' THEN RAISE EXCEPTION 'REEL_REQUEST_INVALID'; END IF;
 IF (p_console IS NULL AND act NOT IN('save','submit')) OR(p_console IS NOT NULL AND act IN('save','submit')) THEN RAISE EXCEPTION 'REEL_REALM_DENIED'; END IF;
 a:=public.reel_actor_v1(p_actor,p_site,p_console,true);
 PERFORM pg_advisory_xact_lock(hashtextextended('reel:'||p_reel::text,0));
 PERFORM pg_advisory_xact_lock(hashtextextended('reel-key:'||p_site::text||a::text||k,0));
 h:=encode(sha256(convert_to(jsonb_build_object('reel',p_reel,'command',p_command)::text,'UTF8')),'hex');
 SELECT * INTO ev FROM public.commerce_reel_events WHERE site_id=p_site AND actor_id=a AND request_key=k;
 IF FOUND THEN IF ev.command_hash<>h THEN RAISE EXCEPTION 'REEL_IDEMPOTENCY_CONFLICT'; END IF;RETURN ev.result||jsonb_build_object('replayed',true);END IF;
 SELECT * INTO rr FROM public.commerce_reels WHERE id=p_reel FOR UPDATE;
 IF rr.id IS NOT NULL AND(rr.site_id<>p_site OR rr.deleted_at IS NOT NULL) THEN RAISE EXCEPTION 'REEL_NOT_FOUND'; END IF;
 IF coalesce(rr.version,0)<>(p_command->>'expected_version')::integer THEN RAISE EXCEPTION 'REEL_VERSION_CONFLICT'; END IF;
 IF act IN('save','submit') THEN
  IF rr.id IS NOT NULL AND rr.status NOT IN('draft','rejected','pending_review','approved') THEN RAISE EXCEPTION 'REEL_STATE_CONFLICT'; END IF;
  selection:=p_command->'selection';
  IF selection IS NULL OR jsonb_typeof(selection)<>'object' OR selection-ARRAY['media_asset_id','listing_id','variant_id','thumbnail_asset_id','caption','rights_evidence_ids']<>'{}'
   OR NOT(selection ?& ARRAY['media_asset_id','listing_id','variant_id','thumbnail_asset_id','caption','rights_evidence_ids'])
   OR jsonb_typeof(selection->'caption') IS DISTINCT FROM 'string' OR length(selection->>'caption')>4000
   OR jsonb_typeof(selection->'rights_evidence_ids') IS DISTINCT FROM 'array' OR jsonb_array_length(selection->'rights_evidence_ids')>20 THEN RAISE EXCEPTION 'REEL_REQUEST_INVALID'; END IF;
  IF (SELECT count(*) FROM jsonb_array_elements_text(selection->'rights_evidence_ids'))<>(SELECT count(DISTINCT value::uuid) FROM jsonb_array_elements_text(selection->'rights_evidence_ids')) THEN RAISE EXCEPTION 'REEL_REQUEST_INVALID'; END IF;
  IF selection->>'listing_id' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.channel_listings WHERE id=(selection->>'listing_id')::uuid AND site_id=p_site) THEN RAISE EXCEPTION 'REEL_LISTING_UNAVAILABLE'; END IF;
  IF EXISTS(SELECT 1 FROM unnest(ARRAY[(selection->>'media_asset_id')::uuid,(selection->>'thumbnail_asset_id')::uuid])v(id)
   WHERE v.id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.media_assets WHERE id=v.id AND site_id=p_site AND deleted_at IS NULL)) THEN RAISE EXCEPTION 'REEL_CUSTODY_UNAVAILABLE'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(selection->'rights_evidence_ids')v WHERE NOT EXISTS(SELECT 1 FROM public.reel_asset_provenance WHERE id=v.value::uuid AND site_id=p_site AND kind='rights' AND deleted_at IS NULL)) THEN RAISE EXCEPTION 'REEL_RIGHTS_EVIDENCE_UNAVAILABLE'; END IF;
  IF act='submit' THEN canonical:=public.reel_payload_v1(p_site,selection); END IF;
  IF rr.id IS NULL THEN INSERT INTO public.commerce_reels(id,site_id,created_by,updated_by) VALUES(p_reel,p_site,a,a) RETURNING * INTO rr; END IF;
  INSERT INTO public.commerce_reel_revisions(site_id,reel_id,version,selection,payload,canonical_payload,fingerprint,created_by,updated_by)
  VALUES(p_site,p_reel,rr.version+1,selection,canonical::jsonb,canonical,CASE WHEN canonical IS NULL THEN NULL ELSE encode(sha256(convert_to(canonical,'UTF8')),'hex') END,a,a) RETURNING * INTO rev;
  UPDATE public.commerce_reels SET version=version+1,current_revision_id=rev.id,status=CASE WHEN act='submit' THEN 'pending_review' ELSE 'draft' END,
   assigned_reviewer_id=NULL,updated_at=clock_timestamp(),updated_by=a WHERE id=p_reel RETURNING * INTO rr;
 ELSE
  IF rr.id IS NULL THEN RAISE EXCEPTION 'REEL_NOT_FOUND'; END IF;
  SELECT * INTO rev FROM public.commerce_reel_revisions WHERE id=rr.current_revision_id AND site_id=p_site FOR SHARE;
  IF rr.created_by=a OR rev.created_by=a OR EXISTS(SELECT 1 FROM public.sites WHERE id=p_site AND(a=custom_user_id OR a=user_id)) THEN RAISE EXCEPTION 'REEL_SELF_REVIEW_DENIED'; END IF;
  IF act='claim' THEN
   IF rr.status<>'pending_review' OR(rr.assigned_reviewer_id IS NOT NULL AND rr.assigned_reviewer_id<>a) THEN RAISE EXCEPTION 'REEL_ASSIGNMENT_REQUIRED'; END IF;
   UPDATE public.commerce_reels SET assigned_reviewer_id=a WHERE id=p_reel;
  ELSE
   IF rr.assigned_reviewer_id IS DISTINCT FROM a OR(act<>'take_down' AND rr.status<>'pending_review') THEN RAISE EXCEPTION 'REEL_ASSIGNMENT_REQUIRED'; END IF;
   IF act IN('reject','take_down') AND(length(coalesce(reason,'')) NOT BETWEEN 8 AND 1000) THEN RAISE EXCEPTION 'REEL_REASON_REQUIRED'; END IF;
   IF act='approve' THEN
    canonical:=public.reel_payload_v1(p_site,rev.selection);
    IF canonical IS DISTINCT FROM rev.canonical_payload THEN RAISE EXCEPTION 'REEL_PRODUCT_REVISION_STALE'; END IF;
    SELECT * INTO ins FROM public.reel_review_inspections WHERE site_id=p_site AND revision_id=rev.id AND reviewer_id=a
     AND processing_receipt_id=(rev.payload->'media'->>'processing_evidence_id')::uuid AND deleted_at IS NULL
     AND inspected_at<=clock_timestamp() AND expires_at>clock_timestamp() ORDER BY inspected_at DESC LIMIT 1 FOR SHARE;
    IF ins.id IS NULL THEN RAISE EXCEPTION 'REEL_INSPECTION_UNAVAILABLE'; END IF;
   END IF;
   IF act='take_down' AND rr.status<>'approved' THEN RAISE EXCEPTION 'REEL_STATE_CONFLICT'; END IF;
   UPDATE public.commerce_reels SET status=CASE act WHEN 'approve' THEN 'approved' WHEN 'reject' THEN 'rejected' ELSE 'delisted' END WHERE id=p_reel;
  END IF;
  UPDATE public.commerce_reels SET version=version+1,updated_at=clock_timestamp(),updated_by=a WHERE id=p_reel RETURNING * INTO rr;
 END IF;
 result:=jsonb_build_object('reel',to_jsonb(rr),'revision',to_jsonb(rev),'replayed',false);
 INSERT INTO public.commerce_reel_events(site_id,reel_id,revision_id,actor_id,actor_realm,action,reason,request_key,command_hash,result,created_by,updated_by)
 VALUES(p_site,p_reel,rev.id,a,CASE WHEN p_console IS NULL THEN 'merchant' ELSE 'operator' END,act,reason,k,h,result,a,a);
 INSERT INTO public.audit_logs(actor_id,actor_type,action,resource_type,resource_id,metadata)
 VALUES(a,CASE WHEN p_console IS NULL THEN 'user' ELSE 'employee' END,'reel.'||act,'commerce_reel',p_reel,jsonb_build_object('site_id',p_site,'revision_id',rev.id,'version',rr.version,'reason',reason));
 INSERT INTO public.outbox_events(store_id,site_id,aggregate_type,aggregate_id,event_type,payload,idempotency_key,actor_id)
 VALUES(p_site,p_site,'reel',p_reel::text,'reel.review.changed',jsonb_build_object('site_id',p_site,'reel_id',p_reel,'revision_id',rev.id,'action',act,'version',rr.version),
  'reel:'||encode(sha256(convert_to(p_site::text||':'||a::text||':'||k,'UTF8')),'hex'),a);
 RETURN result;
END

DECLARE a uuid;rows jsonb;rr public.commerce_reels;rev public.commerce_reel_revisions;events jsonb;refs jsonb;
BEGIN
 a:=public.reel_actor_v1(p_actor,p_site,p_console,false);
 IF p_page IS NULL OR p_page NOT BETWEEN 1 AND 10000 THEN RAISE EXCEPTION 'REEL_REQUEST_INVALID'; END IF;
 IF p_reel IS NULL THEN
  SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.updated_at DESC,x.id),'[]') INTO rows FROM
   (SELECT * FROM public.commerce_reels WHERE ((p_console IS NOT NULL AND status<>'draft') OR(p_console IS NULL AND site_id=p_site)) AND deleted_at IS NULL ORDER BY updated_at DESC,id LIMIT 21 OFFSET (p_page-1)*20)x;
  IF p_console IS NULL THEN
   SELECT jsonb_build_object('listings',coalesce((SELECT jsonb_agg(jsonb_build_object('id',l.id,'name',p.name,'variants',coalesce((SELECT jsonb_agg(jsonb_build_object('id',v.id,'title',v.title) ORDER BY v.position,v.id) FROM(SELECT id,title,position FROM public.product_variants WHERE product_id=p.id ORDER BY position,id LIMIT 100)v),'[]'::jsonb)))
    FROM(SELECT * FROM public.channel_listings WHERE site_id=p_site AND channel='marketplace' AND status='approved' AND visibility='public' ORDER BY id LIMIT 100)l JOIN public.products p ON p.id=l.product_id AND p.site_id=p_site AND p.is_active AND p.deleted_at IS NULL
    WHERE l.approved_product_fingerprint=public.marketplace_listing_review_fingerprint(l.id)),'[]'::jsonb),
    'media',coalesce((SELECT jsonb_agg(to_jsonb(v)) FROM(SELECT DISTINCT x.id,x.filename AS label FROM public.reel_asset_provenance a JOIN public.media_assets x ON x.id=a.media_asset_id AND x.site_id=a.site_id AND x.asset_type='video' AND x.public_url IS NULL AND x.deleted_at IS NULL AND x.checksum_sha256=a.checksum_sha256 WHERE a.site_id=p_site AND a.kind='video' AND a.deleted_at IS NULL AND a.custody_verified_at<=clock_timestamp() AND EXISTS(SELECT 1 FROM public.reel_processing_receipts r WHERE r.provenance_id=a.id AND r.site_id=p_site AND r.state='ready' AND r.deleted_at IS NULL AND r.verified_at<=clock_timestamp() AND r.media_version=a.asset_version AND r.checksum_sha256=a.checksum_sha256 AND r.provider_asset_id=a.provider_asset_id) ORDER BY x.id LIMIT 100)v),'[]'::jsonb),
    'thumbnails',coalesce((SELECT jsonb_agg(to_jsonb(v)) FROM(SELECT DISTINCT x.id,x.filename AS label FROM public.reel_asset_provenance a JOIN public.media_assets x ON x.id=a.media_asset_id AND x.site_id=a.site_id AND x.asset_type='image' AND x.public_url IS NULL AND x.deleted_at IS NULL AND x.checksum_sha256=a.checksum_sha256 WHERE a.site_id=p_site AND a.kind='image' AND a.deleted_at IS NULL AND a.custody_verified_at<=clock_timestamp() ORDER BY x.id LIMIT 100)v),'[]'::jsonb),
    'rights',coalesce((SELECT jsonb_agg(to_jsonb(v)) FROM(SELECT a.id,'Evidence '||a.id::text AS label FROM public.reel_asset_provenance a JOIN public.media_assets x ON x.id=a.media_asset_id AND x.site_id=a.site_id AND x.deleted_at IS NULL AND x.public_url IS NULL AND x.checksum_sha256=a.checksum_sha256 WHERE a.site_id=p_site AND a.kind='rights' AND a.deleted_at IS NULL AND a.custody_verified_at<=clock_timestamp() ORDER BY a.id LIMIT 100)v),'[]'::jsonb)) INTO refs;
  END IF;
  RETURN jsonb_build_object('items',(SELECT coalesce(jsonb_agg(value ORDER BY n),'[]') FROM jsonb_array_elements(rows) WITH ORDINALITY x(value,n) WHERE n<=20),'page',p_page,'page_size',20,'has_more',jsonb_array_length(rows)>20,'inspection_available',false,'custody_available',false,'references',refs);
 END IF;
 SELECT * INTO rr FROM public.commerce_reels WHERE id=p_reel AND ((p_console IS NOT NULL AND status<>'draft') OR(p_console IS NULL AND site_id=p_site)) AND deleted_at IS NULL;
 IF rr.id IS NULL THEN RAISE EXCEPTION 'REEL_NOT_FOUND'; END IF;
 SELECT * INTO rev FROM public.commerce_reel_revisions WHERE id=rr.current_revision_id AND site_id=rr.site_id;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',x.id,'revision_id',x.revision_id,'actor_id',x.actor_id,'actor_realm',x.actor_realm,'action',x.action,'reason',x.reason,'created_at',x.created_at) ORDER BY x.created_at DESC,x.id),'[]') INTO events
 FROM(SELECT * FROM public.commerce_reel_events WHERE reel_id=rr.id AND site_id=rr.site_id ORDER BY created_at DESC,id LIMIT 100)x;
 RETURN jsonb_build_object('reel',to_jsonb(rr),'revision',to_jsonb(rev),'events',events,'inspection_available',false,'custody_available',false);
END

BEGIN
    RAISE EXCEPTION 'product edit receipts are immutable' USING ERRCODE = '42501';
END

BEGIN
    IF TG_OP = 'UPDATE' AND (to_jsonb(NEW) - 'updated_at') IS NOT DISTINCT FROM (to_jsonb(OLD) - 'updated_at') THEN
        RETURN NEW;
    END IF;
    IF TG_OP <> 'INSERT' THEN
        UPDATE public.products SET variants=public.product_edit_snapshot_v1(OLD.product_id)->'variants',
            updated_at = clock_timestamp() WHERE id = OLD.product_id;
    END IF;
    IF TG_OP = 'INSERT' OR (TG_OP = 'UPDATE' AND NEW.product_id IS DISTINCT FROM OLD.product_id) THEN
        UPDATE public.products SET variants=public.product_edit_snapshot_v1(NEW.product_id)->'variants',
            updated_at = clock_timestamp() WHERE id = NEW.product_id;
    END IF;
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END

DECLARE s public.sites%ROWTYPE; e record; allowed boolean := false;
BEGIN
    IF current_setting('role', true) IS DISTINCT FROM 'app_tenant'
       OR p_store_id IS NULL OR p_actor_id IS NULL OR p_permission NOT IN ('products:read','products:write')
       OR nullif(current_setting('app.site_id', true), '') IS DISTINCT FROM p_store_id::text
       OR nullif(current_setting('app.actor_id', true), '') IS DISTINCT FROM p_actor_id::text THEN
        RAISE EXCEPTION 'PRODUCT_EDIT_FORBIDDEN' USING ERRCODE = '42501';
    END IF;
    PERFORM id FROM public.users_custom WHERE id = p_actor_id FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'PRODUCT_EDIT_FORBIDDEN' USING ERRCODE = '42501'; END IF;
    SELECT * INTO s FROM public.sites WHERE id = p_store_id AND deleted_at IS NULL FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'PRODUCT_EDIT_FORBIDDEN' USING ERRCODE = '42501'; END IF;
    IF coalesce(s.custom_user_id = p_actor_id, false) OR coalesce(s.user_id = p_actor_id, false) THEN RETURN; END IF;
    FOR e IN SELECT permissions FROM public.employees
        WHERE store_id = p_store_id AND user_id = p_actor_id AND status = 'active'
          AND is_active = true AND deleted_at IS NULL FOR SHARE LOOP
        IF jsonb_typeof(e.permissions->'granted') = 'array' AND (
            e.permissions->'granted' ?| ARRAY['*','products:*',p_permission]
            OR (p_permission = 'products:read' AND e.permissions->'granted' ? 'products:write')) THEN
            allowed := true;
        END IF;
    END LOOP;
    IF NOT allowed THEN RAISE EXCEPTION 'PRODUCT_EDIT_FORBIDDEN' USING ERRCODE = '42501'; END IF;
END

BEGIN
    PERFORM public.assert_product_edit_actor_v1(p_store_id, p_actor_id, 'products:read');
    PERFORM id FROM public.products WHERE id = p_product_id AND store_id = p_store_id AND deleted_at IS NULL FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'PRODUCT_EDIT_NOT_FOUND'; END IF;
    RETURN public.product_edit_snapshot_v1(p_product_id);
END

DECLARE
    p public.products%ROWTYPE; before_product jsonb; receipt public.product_edit_receipts%ROWTYPE;
    fields jsonb; item jsonb; existing public.product_variants%ROWTYPE; v_variant_id uuid;
    retained uuid[] := ARRAY[]::uuid[]; removed uuid[]; option_names text[]; option_values text[];
    gift jsonb; roles jsonb; role_name text; old_index integer; new_index integer; source_url text; match_count integer;
    idx integer := 0; options jsonb; current_options jsonb; response jsonb; request_id text := nullif(current_setting('app.request_id', true), '');
BEGIN
    -- service_role inherits app_tenant's EXECUTE grant in164. An inherited grant
    -- must not turn the administrative REST role into this tenant transaction.
    IF current_setting('role', true) IS DISTINCT FROM 'app_tenant' THEN
        RAISE EXCEPTION 'PRODUCT_EDIT_FORBIDDEN' USING ERRCODE = '42501';
    END IF;
    IF p_expected_version IS NULL OR p_expected_version <= 0 OR p_idempotency_key IS NULL
       OR p_product_id IS NULL OR jsonb_typeof(p_mutation) IS DISTINCT FROM 'object'
       OR octet_length(p_mutation::text) > 1048576
       OR jsonb_typeof(p_mutation->'fields') IS DISTINCT FROM 'object'
       OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_mutation) k WHERE k NOT IN ('fields','stock','product_options','variants')) THEN
        RAISE EXCEPTION 'PRODUCT_EDIT_INVALID';
    END IF;
    fields := p_mutation->'fields';
    IF fields = '{}'::jsonb AND NOT (p_mutation ?| ARRAY['stock','product_options','variants']) THEN
        RAISE EXCEPTION 'PRODUCT_EDIT_INVALID';
    END IF;
    -- This allowlist is the DB immutability fence for the commerce-core plan. No identity,
    -- tenant, audit, version or raw variants cache column is writable from a mutation payload.
    IF EXISTS (SELECT 1 FROM jsonb_object_keys(fields) k WHERE k NOT IN (
        'name','description','price','compare_price','cost_per_item','images','category','product_type','vendor',
        'track_inventory','sku','barcode','sell_when_oos','is_physical','weight','weight_unit','country_of_origin',
        'importer_details','hs_code','hsn_code','url_handle','seo_title','seo_description','charge_tax',
        'shipping_profile_id','is_active','is_featured','tags','metadata','display_order','status')) THEN
        RAISE EXCEPTION 'PRODUCT_EDIT_INVALID';
    END IF;
    PERFORM public.assert_product_edit_actor_v1(p_store_id, p_actor_id, 'products:write');
    PERFORM pg_advisory_xact_lock(hashtextextended('letbuyy:product-edit:' || p_idempotency_key::text, 0));
    -- Match the canonical inventory writer's level -> variant -> parent order.
    -- The decisive version comparison remains on the final locked parent row.
    PERFORM il.id FROM public.inventory_levels il WHERE il.product_id=p_product_id AND il.store_id=p_store_id ORDER BY il.id FOR UPDATE;
    PERFORM pv.id FROM public.product_variants pv JOIN public.products target_product ON target_product.id=pv.product_id
        WHERE pv.product_id=p_product_id AND target_product.store_id=p_store_id ORDER BY pv.id FOR UPDATE OF pv;
    PERFORM po.id FROM public.product_options po JOIN public.products target_product ON target_product.id=po.product_id
        WHERE po.product_id=p_product_id AND target_product.store_id=p_store_id ORDER BY po.id FOR UPDATE OF po;
    SELECT * INTO p FROM public.products WHERE id = p_product_id AND store_id = p_store_id AND deleted_at IS NULL FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'PRODUCT_EDIT_NOT_FOUND'; END IF;
    SELECT * INTO receipt FROM public.product_edit_receipts WHERE idempotency_key = p_idempotency_key;
    IF FOUND THEN
        IF receipt.operation <> 'product.update.v1' OR receipt.actor_id IS DISTINCT FROM p_actor_id
           OR receipt.store_id IS DISTINCT FROM p_store_id OR receipt.product_id IS DISTINCT FROM p_product_id
           OR receipt.expected_version IS DISTINCT FROM p_expected_version OR receipt.mutation IS DISTINCT FROM p_mutation THEN
            RAISE EXCEPTION 'PRODUCT_EDIT_KEY_CONFLICT';
        END IF;
        RETURN receipt.response;
    END IF;
    IF p.version <= 0 OR p.version IS DISTINCT FROM p_expected_version THEN RAISE EXCEPTION 'PRODUCT_EDIT_VERSION_CONFLICT'; END IF;
    -- Receipt replay returned above. Compare capability meaning only while holding
    -- the SAME decisive product lock; an unrelated no-effect resave keeps revision.
    IF fields ? 'metadata' AND (fields->'metadata') ? 'personalization' THEN
      IF NOT public.storefront_discovery_facts_valid_v1(fields->'metadata'->'personalization','personalization',false)
        OR jsonb_typeof(fields->'metadata'->'personalization') IS DISTINCT FROM 'object'
        OR jsonb_typeof(fields->'metadata'->'personalization'->'revision') IS DISTINCT FROM 'number'
        OR (fields->'metadata'->'personalization'->>'revision') !~ '^[1-9][0-9]{0,9}$'
        OR (fields->'metadata'->'personalization'->>'revision')::numeric>2147483647 THEN
        RAISE EXCEPTION 'PRODUCT_PERSONALIZATION_INVALID'; END IF;
      IF public.storefront_discovery_facts_valid_v1(p.metadata->'personalization','personalization',false) THEN
        IF (fields->'metadata'->'personalization'->>'revision')::numeric < (p.metadata->'personalization'->>'revision')::numeric THEN
          RAISE EXCEPTION 'PRODUCT_PERSONALIZATION_REVISION_DECREASED'; END IF;
        IF ((fields->'metadata'->'personalization')-'revision'::text) IS DISTINCT FROM ((p.metadata->'personalization')-'revision'::text)
          AND (fields->'metadata'->'personalization'->>'revision')::numeric <= (p.metadata->'personalization'->>'revision')::numeric THEN
          RAISE EXCEPTION 'PRODUCT_PERSONALIZATION_REVISION_REQUIRED'; END IF;
      END IF;
    END IF;
    before_product := public.product_edit_snapshot_v1(p_product_id);
    IF (fields ? 'status' OR fields ? 'is_active') AND (
        jsonb_typeof(fields->'status') IS DISTINCT FROM 'string'
        OR fields->>'status' NOT IN ('active', 'draft', 'archived')
        OR fields->'is_active' IS DISTINCT FROM to_jsonb((fields->>'status') = 'active')
    ) THEN RAISE EXCEPTION 'PRODUCT_EDIT_INVALID'; END IF;

    -- An image-only edit follows the previous URL identity while holding the
    -- product version lock. Retrying the original intent still matches its receipt.
    IF fields ? 'images' AND NOT (fields ? 'metadata') AND jsonb_typeof(p.metadata->'gifts') = 'object' THEN
        gift := p.metadata->'gifts'; roles := '{}'::jsonb;
        FOREACH role_name IN ARRAY ARRAY['openBox','closedBox'] LOOP
            IF jsonb_typeof(gift->'mediaRoles'->role_name) = 'number'
                AND (gift->'mediaRoles'->>role_name) ~ '^[0-9]+$' THEN
                old_index := (gift->'mediaRoles'->>role_name)::integer;
                IF old_index BETWEEN 0 AND 19 AND old_index < coalesce(array_length(p.images,1),0) THEN
                    source_url := p.images[old_index+1];
                    SELECT count(*), min(n-1)::integer INTO match_count,new_index
                        FROM jsonb_array_elements_text(fields->'images') WITH ORDINALITY AS images(url,n)
                        WHERE url=source_url AND nullif(btrim(url),'') IS NOT NULL;
                    IF match_count=1 AND new_index BETWEEN 0 AND 19 THEN roles := roles || jsonb_build_object(role_name,new_index); END IF;
                END IF;
            END IF;
        END LOOP;
        IF roles->'openBox' IS NOT NULL AND roles->'openBox'=roles->'closedBox' THEN roles := '{}'::jsonb; END IF;
        gift := gift-'mediaRoles';
        IF roles <> '{}'::jsonb THEN gift := gift || jsonb_build_object('mediaRoles',roles); END IF;
        IF roles='{}'::jsonb AND NOT (
            coalesce(jsonb_array_length(gift->'occasions'),0)>0 OR coalesce(jsonb_array_length(gift->'recipients'),0)>0
            OR nullif(btrim(gift->>'suitabilityNote'),'') IS NOT NULL OR coalesce(jsonb_array_length(gift->'contents'),0)>0
        ) THEN fields := fields || jsonb_build_object('metadata',p.metadata-'gifts');
        ELSE fields := fields || jsonb_build_object('metadata',jsonb_set(p.metadata,'{gifts}',gift)); END IF;
    END IF;

    -- Typed merge preserves omitted fields. Any later exception rolls this UPDATE back too.
    IF fields <> '{}'::jsonb THEN
        p := jsonb_populate_record(p, fields);
        IF length(btrim(p.name)) = 0 OR p.price < 0 OR
            ((fields ? 'price' OR fields ? 'compare_price') AND p.compare_price IS NOT NULL AND p.compare_price <= p.price) THEN
            RAISE EXCEPTION 'PRODUCT_EDIT_INVALID';
        END IF;
        IF jsonb_typeof(p.metadata->'gifts'->'mediaRoles')='object' AND EXISTS (
            SELECT 1 FROM jsonb_each(p.metadata->'gifts'->'mediaRoles') r
            WHERE r.key NOT IN ('openBox','closedBox') OR jsonb_typeof(r.value)<>'number'
               OR r.value::text !~ '^[0-9]+$' OR length(r.value::text)>2
               OR (r.value::text)::integer >= coalesce(array_length(p.images,1),0)
        ) THEN RAISE EXCEPTION 'PRODUCT_EDIT_INVALID_GIFT_MEDIA'; END IF;
        UPDATE public.products target SET
            name=p.name, description=p.description, price=p.price, compare_price=p.compare_price,
            cost_per_item=p.cost_per_item, images=p.images, category=p.category, product_type=p.product_type,
            vendor=p.vendor, track_inventory=p.track_inventory, sku=p.sku, barcode=p.barcode,
            sell_when_oos=p.sell_when_oos, is_physical=p.is_physical, weight=p.weight, weight_unit=p.weight_unit,
            country_of_origin=p.country_of_origin, importer_details=p.importer_details, hs_code=p.hs_code, hsn_code=p.hsn_code,
            url_handle=p.url_handle, seo_title=p.seo_title, seo_description=p.seo_description, charge_tax=p.charge_tax,
            shipping_profile_id=p.shipping_profile_id, is_active=p.is_active, is_featured=p.is_featured,
            tags=p.tags, metadata=p.metadata, display_order=p.display_order, status=p.status,
            updated_by=p_actor_id, updated_at=clock_timestamp()
        WHERE target.id=p_product_id AND target.store_id=p_store_id;
    END IF;

    IF jsonb_typeof(p.metadata->'gifts'->'mediaRoles')='object' AND EXISTS (
        SELECT 1 FROM jsonb_each(p.metadata->'gifts'->'mediaRoles') r
        WHERE r.key NOT IN ('openBox','closedBox') OR jsonb_typeof(r.value)<>'number'
           OR r.value::text !~ '^[0-9]+$' OR length(r.value::text)>2
           OR (r.value::text)::integer >= coalesce(array_length(p.images,1),0)
    ) THEN RAISE EXCEPTION 'PRODUCT_EDIT_INVALID_GIFT_MEDIA'; END IF;

    IF p_mutation ? 'product_options' THEN
        options := p_mutation->'product_options';
        IF jsonb_typeof(options) IS DISTINCT FROM 'array' OR jsonb_array_length(options)>10
           OR EXISTS (SELECT 1 FROM jsonb_array_elements(options) o WHERE jsonb_typeof(o) <> 'object'
                OR nullif(btrim(o->>'name'),'') IS NULL OR jsonb_typeof(o->'values') IS DISTINCT FROM 'array')
           OR (SELECT count(*) FROM jsonb_array_elements(options)) <>
              (SELECT count(DISTINCT lower(btrim(o->>'name'))) FROM jsonb_array_elements(options) o) THEN
            RAISE EXCEPTION 'PRODUCT_EDIT_INVALID';
        END IF;
        SELECT coalesce(jsonb_agg(jsonb_build_object('name',name,'position',position,'values',values) ORDER BY position,id),'[]'::jsonb)
            INTO current_options FROM public.product_options WHERE product_id=p_product_id;
        SELECT coalesce(jsonb_agg(jsonb_build_object('name',o->>'name','position',n-1,'values',o->'values') ORDER BY n),'[]'::jsonb)
            INTO options FROM jsonb_array_elements(options) WITH ORDINALITY AS entries(o,n);
        -- A full form often resends unchanged options. Replacing them would transiently
        -- invalidate an approved listing's material fingerprint even for a stock-only edit.
        IF current_options IS DISTINCT FROM options THEN
            DELETE FROM public.product_options WHERE product_id=p_product_id;
            INSERT INTO public.product_options(product_id,name,position,values)
                SELECT p_product_id, o->>'name', (n-1)::integer, o->'values'
                FROM jsonb_array_elements(options) WITH ORDINALITY AS entries(o,n);
        END IF;
    END IF;
    SELECT array_agg(name ORDER BY position,id) INTO option_names FROM public.product_options WHERE product_id=p_product_id;

    IF jsonb_typeof(p.metadata->'beauty')='object' AND jsonb_array_length(coalesce(p.metadata->'beauty'->'shades','[]'::jsonb))>0
        AND EXISTS(SELECT 1 FROM jsonb_array_elements(p.metadata->'beauty'->'shades') shade
            WHERE NOT EXISTS(SELECT 1 FROM public.product_options po WHERE po.product_id=p_product_id
                AND po.name=coalesce(p.metadata->'beauty'->>'shadeOptionName','Shade') AND po.values ? (shade->>'value'))) THEN
        RAISE EXCEPTION 'PRODUCT_EDIT_INVALID_BEAUTY_OPTION';
    END IF;

    IF p_mutation ? 'variants' THEN
        IF jsonb_typeof(p_mutation->'variants') IS DISTINCT FROM 'array' OR jsonb_array_length(p_mutation->'variants')>100 THEN
            RAISE EXCEPTION 'PRODUCT_EDIT_INVALID';
        END IF;
        FOR item IN SELECT value FROM jsonb_array_elements(p_mutation->'variants') LOOP
            IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR nullif(btrim(item->>'title'),'') IS NULL
               OR EXISTS (SELECT 1 FROM jsonb_object_keys(item) k WHERE k NOT IN ('id','title','price','price_override','compare_price','sku','barcode','stock','options','metadata')) THEN
                RAISE EXCEPTION 'PRODUCT_EDIT_INVALID';
            END IF;
            IF item ? 'metadata' AND (
                jsonb_typeof(item->'metadata') IS DISTINCT FROM 'object'
                OR octet_length((item->'metadata')::text)>131072
                OR (item->'metadata')-ARRAY['toys','food','furniture','sports','books']::text[] <> '{}'::jsonb
                OR EXISTS(SELECT 1 FROM jsonb_each(item->'metadata') f WHERE jsonb_typeof(f.value) NOT IN ('object','null'))
            ) THEN RAISE EXCEPTION 'PRODUCT_EDIT_INVALID_VARIANT_METADATA'; END IF;
            existing := NULL;
            IF item ? 'id' THEN
                v_variant_id := (item->>'id')::uuid;
                IF v_variant_id IS NULL OR v_variant_id = ANY(retained) THEN RAISE EXCEPTION 'PRODUCT_EDIT_VARIANT_ID'; END IF;
                SELECT * INTO existing FROM public.product_variants WHERE id=v_variant_id AND product_id=p_product_id FOR UPDATE;
                IF NOT FOUND THEN RAISE EXCEPTION 'PRODUCT_EDIT_VARIANT_ID'; END IF;
            ELSE
                v_variant_id := gen_random_uuid();
            END IF;
            retained := array_append(retained,v_variant_id);
            option_values := ARRAY[existing.option1,existing.option2,existing.option3];
            IF item ? 'options' THEN
                IF jsonb_typeof(item->'options') IS DISTINCT FROM 'object' OR
                    (SELECT count(*) FROM jsonb_object_keys(item->'options'))>3 THEN RAISE EXCEPTION 'PRODUCT_EDIT_INVALID'; END IF;
                -- Canonical option positions, including explicit legacy unnamed slots. Do not
                -- depend on JSON key iteration order or truncate additional option dimensions.
                IF option_names IS NULL THEN
                    SELECT array_agg(key ORDER BY key) INTO option_names FROM jsonb_each(item->'options');
                END IF;
                IF EXISTS (SELECT 1 FROM jsonb_object_keys(item->'options') k WHERE NOT k=ANY(coalesce(option_names,ARRAY[]::text[])))
                    OR coalesce(array_length(option_names,1),0)>3 THEN RAISE EXCEPTION 'PRODUCT_EDIT_INVALID'; END IF;
                option_values := ARRAY[item->'options'->>option_names[1],item->'options'->>option_names[2],item->'options'->>option_names[3]];
            END IF;
            IF existing.id IS NULL THEN
                INSERT INTO public.product_variants(id,product_id,title,price,compare_price,sku,barcode,inventory_qty,option1,option2,option3,position,metadata)
                    VALUES(v_variant_id,p_product_id,item->>'title',coalesce((item->>'price')::numeric,(item->>'price_override')::numeric,p.price),
                        (item->>'compare_price')::numeric,item->>'sku',item->>'barcode',0,option_values[1],option_values[2],option_values[3],idx,coalesce(item->'metadata','{}'::jsonb));
            ELSE
                UPDATE public.product_variants SET title=item->>'title',
                    price=CASE WHEN item ? 'price' OR item ? 'price_override' THEN coalesce((item->>'price')::numeric,(item->>'price_override')::numeric,p.price) ELSE existing.price END,
                    compare_price=CASE WHEN item ? 'compare_price' THEN (item->>'compare_price')::numeric ELSE existing.compare_price END,
                    sku=CASE WHEN item ? 'sku' THEN item->>'sku' ELSE existing.sku END,
                    barcode=CASE WHEN item ? 'barcode' THEN item->>'barcode' ELSE existing.barcode END,
                    metadata=CASE WHEN item ? 'metadata' THEN item->'metadata' ELSE existing.metadata END,
                    option1=option_values[1], option2=option_values[2], option3=option_values[3], position=idx, updated_at=clock_timestamp()
                    WHERE id=v_variant_id AND product_id=p_product_id;
            END IF;
            IF item ? 'stock' OR existing.id IS NULL THEN
                IF item ? 'stock' AND (jsonb_typeof(item->'stock') <> 'number' OR (item->>'stock') !~ '^[0-9]+$') THEN
                    RAISE EXCEPTION 'PRODUCT_EDIT_INVALID';
                END IF;
                PERFORM public.set_inventory_level_available(p_product_id,v_variant_id,NULL,coalesce((item->>'stock')::integer,0),
                    p_actor_id,'adjustment','product.update',p_idempotency_key::text||':'||v_variant_id::text);
            END IF;
            idx := idx+1;
        END LOOP;
        SELECT array_agg(id) INTO removed FROM public.product_variants WHERE product_id=p_product_id AND NOT id=ANY(retained);
        -- Stable stock/history/reservation references cannot be destroyed by an omitted ID.
        IF EXISTS (SELECT 1 FROM public.inventory_levels WHERE variant_id=ANY(removed))
           OR EXISTS (SELECT 1 FROM public.product_price_observations WHERE variant_id=ANY(removed))
           OR EXISTS (SELECT 1 FROM public.inventory_reservations WHERE variant_id=ANY(removed))
           OR EXISTS (SELECT 1 FROM public.inventory_adjustments WHERE variant_id=ANY(removed))
           OR EXISTS (SELECT 1 FROM public.inventory_events WHERE variant_id=ANY(removed))
           OR EXISTS (SELECT 1 FROM public.fulfillment_order_lines WHERE variant_id=ANY(removed))
           OR EXISTS (SELECT 1 FROM public.inventory_transfer_lines WHERE variant_id=ANY(removed))
           OR EXISTS (SELECT 1 FROM public.inventory_transfer_receipts WHERE variant_id=ANY(removed))
           OR EXISTS (SELECT 1 FROM public.purchase_order_lines WHERE variant_id=ANY(removed))
           OR EXISTS (SELECT 1 FROM public.purchase_order_receipts WHERE variant_id=ANY(removed))
           OR EXISTS (SELECT 1 FROM public.restock_events WHERE variant_id=ANY(removed))
           OR EXISTS (SELECT 1 FROM public.return_lines WHERE variant_id=ANY(removed)) THEN
            RAISE EXCEPTION 'PRODUCT_EDIT_VARIANT_REMOVAL';
        END IF;
        DELETE FROM public.product_variants WHERE product_id=p_product_id AND id=ANY(removed);
    END IF;
    IF p_mutation ? 'stock' THEN
        IF jsonb_typeof(p_mutation->'stock') <> 'number' OR (p_mutation->>'stock') !~ '^[0-9]+$' THEN RAISE EXCEPTION 'PRODUCT_EDIT_INVALID'; END IF;
        PERFORM public.set_inventory_level_available(p_product_id,NULL,NULL,(p_mutation->>'stock')::integer,
            p_actor_id,'adjustment','product.update',p_idempotency_key::text||':default');
    END IF;
    -- Existing trigger semantics may advance the version several times inside this atomic
    -- transaction. Return the exact final token; a client must never calculate its next version.
    UPDATE public.products SET variants=public.product_edit_snapshot_v1(p_product_id)->'variants',
        updated_by=p_actor_id,updated_at=clock_timestamp() WHERE id=p_product_id AND store_id=p_store_id;
    response := public.product_edit_snapshot_v1(p_product_id);
    INSERT INTO public.outbox_events(store_id,site_id,aggregate_type,aggregate_id,event_type,payload,idempotency_key,request_id,actor_id,schema_version)
        VALUES(p_store_id,p_store_id,'product',p_product_id::text,'product.updated',
            jsonb_build_object('site_id',p_store_id,'product_id',p_product_id,'handle',coalesce(response->>'url_handle',response->>'slug'),
                'status',coalesce(response->>'status','draft')),
            'product.updated:'||p_idempotency_key::text,request_id,p_actor_id,1);
    INSERT INTO public.audit_activity_events(store_id,actor_id,actor_type,action,resource_type,resource_id,request_id,before_state,after_state,metadata)
        VALUES(p_store_id,p_actor_id,'user','product.updated','product',p_product_id::text,request_id,before_product,response,
            jsonb_build_object('idempotency_key',p_idempotency_key,'expected_version',p_expected_version,'version',response->'version'));
    INSERT INTO public.product_edit_receipts(idempotency_key,operation,store_id,product_id,actor_id,expected_version,mutation,response)
        VALUES(p_idempotency_key,'product.update.v1',p_store_id,p_product_id,p_actor_id,p_expected_version,p_mutation,response);
    RETURN response;
END

DECLARE
  v_target text := coalesce(p_target_id::text,'new');
  v_payload jsonb;
  v_hash text;
  v_receipt public.buyer_support_mutation_receipts%ROWTYPE;
  v_ticket public.support_tickets%ROWTYPE;
  v_message public.ticket_messages%ROWTYPE;
  v_intake jsonb;
  v_response jsonb;
  v_body text;
  v_subject text;
  v_site uuid;
  v_order uuid;
  v_order_site uuid;
  v_now timestamptz;
  v_audit_id uuid;
  v_action text;
BEGIN
  IF p_buyer_account_id IS NULL OR p_session_epoch IS NULL
     OR p_operation IS NULL OR p_operation NOT IN ('create','reply')
     OR (p_operation='create') <> (p_target_id IS NULL)
     OR p_idempotency_key IS NULL OR length(p_idempotency_key) NOT BETWEEN 8 AND 200
     OR p_idempotency_key <> btrim(p_idempotency_key) OR p_idempotency_key ~ '[[:cntrl:]]'
     OR p_payload IS NULL OR jsonb_typeof(p_payload)<>'object'
     OR jsonb_typeof(p_payload->'body') IS DISTINCT FROM 'string' THEN
    RAISE EXCEPTION 'Invalid buyer support mutation' USING ERRCODE='22023';
  END IF;
  v_body := btrim(p_payload->>'body');
  IF length(v_body) NOT BETWEEN 1 AND 4000 THEN
    RAISE EXCEPTION 'Invalid buyer support message' USING ERRCODE='22023';
  END IF;
  IF p_operation='create' THEN
    IF jsonb_typeof(p_payload->'subject') IS DISTINCT FROM 'string' THEN
      RAISE EXCEPTION 'Invalid buyer support subject' USING ERRCODE='22023';
    END IF;
    v_subject := btrim(p_payload->>'subject');
    IF length(v_subject) NOT BETWEEN 1 AND 200 THEN
      RAISE EXCEPTION 'Invalid buyer support subject' USING ERRCODE='22023';
    END IF;
    v_site := (p_payload->>'site_id')::uuid;
    v_order := (p_payload->>'order_id')::uuid;
    v_payload := jsonb_build_object('subject',v_subject,'body',v_body,'site_id',v_site,'order_id',v_order);
  ELSE
    v_payload := jsonb_build_object('body',v_body);
  END IF;

  -- Lock current authority before either a new effect or cached result. A token
  -- passing middleware before revocation cannot bypass this transaction check.
  -- SHARE (not KEY SHARE) also orders session-epoch/status updates against it.
  PERFORM 1 FROM public.buyer_accounts
    WHERE id=p_buyer_account_id AND status='active' AND session_epoch=p_session_epoch FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Buyer session ended' USING ERRCODE='PT401'; END IF;
  IF v_order IS NOT NULL THEN
    SELECT l.site_id INTO v_order_site FROM public.buyer_order_links l
      JOIN public.orders o ON o.id=l.order_id AND o.site_id=l.site_id
      WHERE l.buyer_account_id=p_buyer_account_id AND l.order_id=v_order FOR SHARE OF l,o;
    IF NOT FOUND OR (v_site IS NOT NULL AND v_site<>v_order_site) THEN
      RAISE EXCEPTION 'Order not found' USING ERRCODE='PT404';
    END IF;
    v_site := v_order_site;
    v_payload := jsonb_set(v_payload,'{site_id}',to_jsonb(v_site));
  END IF;

  -- A buyer's key cannot change operation, resource or normalized intent. The
  -- buyer namespace prevents another actor from observing or taking its result.
  v_hash := encode(sha256(convert_to(jsonb_build_object(
    'operation',p_operation,'target',v_target,'payload',v_payload)::text,'UTF8')),'hex');
  INSERT INTO public.buyer_support_mutation_receipts
    (buyer_account_id,idempotency_key,operation,target,request_hash)
    VALUES(p_buyer_account_id,p_idempotency_key,p_operation,v_target,v_hash)
    ON CONFLICT(buyer_account_id,idempotency_key) DO NOTHING;
  SELECT * INTO STRICT v_receipt FROM public.buyer_support_mutation_receipts
    WHERE buyer_account_id=p_buyer_account_id AND idempotency_key=p_idempotency_key FOR UPDATE;

  IF p_target_id IS NOT NULL OR v_receipt.ticket_id IS NOT NULL THEN
    SELECT * INTO v_ticket FROM public.support_tickets
      WHERE id=coalesce(p_target_id,v_receipt.ticket_id) AND requester_user_id=p_buyer_account_id
        AND requester_type='customer' AND deleted_at IS NULL FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Support ticket not found' USING ERRCODE='PT404'; END IF;
  END IF;
  IF v_receipt.operation<>p_operation OR v_receipt.target<>v_target OR v_receipt.request_hash<>v_hash THEN
    RAISE EXCEPTION 'Support request key is already bound to another intent' USING ERRCODE='PT409';
  END IF;
  IF v_receipt.response IS NOT NULL THEN
    PERFORM 1 FROM public.ticket_messages
      WHERE id=(v_receipt.response->'mutation_receipt'->>'message_id')::uuid
        AND ticket_id=v_ticket.id AND author_type='requester' AND author_id=p_buyer_account_id
        AND visibility='public' AND deleted_at IS NULL FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Support message not found' USING ERRCODE='PT404'; END IF;
    RETURN v_receipt.response;
  END IF;
  v_now := clock_timestamp();

  IF p_operation='create' THEN
    -- Reuse the one canonical complaint+first-message insertion and SLA inputs.
    v_intake := public.open_buyer_support_ticket_with_complaint(p_ticket_ref,
      p_first_response_due_at,p_resolution_due_at,v_site,p_buyer_account_id,v_subject,v_body);
    SELECT * INTO STRICT v_ticket FROM public.support_tickets WHERE id=(v_intake->'ticket'->>'id')::uuid;
    SELECT * INTO STRICT v_message FROM public.ticket_messages WHERE id=(v_intake->'message'->>'id')::uuid;
    IF v_order IS NOT NULL THEN
      UPDATE public.support_tickets SET metadata=metadata||jsonb_build_object('order_id',v_order)
        WHERE id=v_ticket.id;
    END IF;
    v_response := (v_intake->'ticket')||jsonb_build_object(
      'complaint_copy',jsonb_build_object('subject',v_ticket.subject,'body',v_message.body,'recorded_at',v_message.created_at),
      'receipt_confirmed_at',v_message.created_at);
    v_action := 'buyer.support.ticket.create';
  ELSE
    INSERT INTO public.ticket_messages(ticket_id,author_type,author_id,visibility,body,created_at)
      VALUES(v_ticket.id,'requester',p_buyer_account_id,'public',v_body,v_now) RETURNING * INTO v_message;
    UPDATE public.support_tickets SET last_customer_message_at=v_now,
      status=CASE WHEN status='pending_customer' THEN 'pending_internal' ELSE status END
      WHERE id=v_ticket.id;
    v_response := jsonb_build_object('id',v_message.id,'author_type','requester','body',v_message.body,'created_at',v_message.created_at);
    v_site := v_ticket.site_id;
    v_action := 'buyer.support.ticket.reply';
  END IF;

  INSERT INTO public.audit_logs(actor_id,actor_type,action,resource_type,resource_id,metadata,created_at)
    VALUES(p_buyer_account_id,'user',v_action,'support_ticket',v_ticket.id,
      jsonb_build_object('realm','buyer','message_id',v_message.id,'request_hash',v_hash),v_now) RETURNING id INTO v_audit_id;
  -- The canonical audit.recorded contract requires a real site. General platform
  -- tickets have no fabricated site and retain their atomic audit row only.
  -- No message body/email is copied to analytics/webhooks; no worker is activated.
  IF v_site IS NOT NULL THEN
    INSERT INTO public.outbox_events(store_id,site_id,aggregate_type,aggregate_id,event_type,payload,idempotency_key,actor_id,schema_version)
      VALUES(v_site,v_site,'audit',v_audit_id::text,'audit.recorded',
        jsonb_build_object('site_id',v_site,'audit_id',v_audit_id,'action',v_action,
          'resource_type','support_ticket','resource_id',v_ticket.id,'message_id',v_message.id),
        'buyer-support-audit:'||v_audit_id::text,p_buyer_account_id,1);
  END IF;
  v_response := v_response||jsonb_build_object('mutation_receipt',jsonb_build_object(
    'key',p_idempotency_key,'operation',p_operation,'ticket_id',v_ticket.id,
    'message_id',v_message.id,'confirmed_at',v_message.created_at));
  UPDATE public.buyer_support_mutation_receipts SET ticket_id=v_ticket.id,response=v_response
    WHERE buyer_account_id=p_buyer_account_id AND idempotency_key=p_idempotency_key;
  RETURN v_response;
END

DECLARE
 v public.money_ledger_reconciliation_traversal;
 receipt public.money_ledger_reconciliation_batches;
 site record; reconciliation public.money_ledger_site_reconciliations;
 prior_revision bigint; count_checked integer:=0; count_verified integer:=0;
 count_mismatches integer:=0; count_failed integer:=0;
 site_status text; variance bigint; failure_code text; items jsonb:='[]'::jsonb;
 result jsonb; pass_complete boolean; overall_status text; affected integer;
BEGIN
 IF p_request_key IS NULL OR p_request_key<>btrim(p_request_key) OR length(p_request_key) NOT BETWEEN 1 AND 200
  OR p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 500 THEN
  RAISE EXCEPTION 'Valid reconciliation request key and bounded limit are required' USING ERRCODE='22023'; END IF;
 IF nullif(current_setting('app.site_id',true),'') IS NOT NULL THEN
  RAISE EXCEPTION 'Global reconciliation traversal refuses tenant-scoped execution' USING ERRCODE='42501'; END IF;

 INSERT INTO public.money_ledger_reconciliation_traversal(id) VALUES('00000000-0000-4000-8000-000000000349') ON CONFLICT(id) DO NOTHING;
 SELECT * INTO STRICT v FROM public.money_ledger_reconciliation_traversal
  WHERE id='00000000-0000-4000-8000-000000000349' FOR UPDATE;
 prior_revision:=v.revision;
 SELECT * INTO receipt FROM public.money_ledger_reconciliation_batches WHERE request_key=p_request_key;
 IF FOUND THEN
  IF receipt.batch_limit<>p_limit THEN RAISE EXCEPTION 'Reconciliation request key is bound to another limit' USING ERRCODE='22023'; END IF;
  RETURN receipt.result||jsonb_build_object('replayed',true);
 END IF;

 IF v.pass_id IS NULL OR v.pass_completed_at IS NOT NULL THEN
  v.pass_id:=gen_random_uuid();v.pass_started_at:=clock_timestamp();v.pass_completed_at:=NULL;
  v.cursor_created_at:=NULL;v.cursor_site_id:=NULL;
  v.checked:=0;v.verified:=0;v.mismatches:=0;v.failed:=0;
  SELECT coalesce(s.created_at,'-infinity'::timestamptz),s.id INTO v.watermark_created_at,v.watermark_site_id
   FROM public.sites s WHERE s.deleted_at IS NULL
   ORDER BY coalesce(s.created_at,'-infinity'::timestamptz) DESC,s.id DESC LIMIT 1;
 END IF;

 -- A failed site is a durable attempted outcome, not a barrier for every later
 -- tenant. A fresh pass retries failures; backdated/new/deleted boundaries do
 -- not move the current pass's fixed watermark or rewind its strict cursor.
 FOR site IN SELECT s.id,s.name,s.store_name,s.subdomain,coalesce(s.created_at,'-infinity'::timestamptz) AS ordered_created_at
  FROM public.sites s WHERE s.deleted_at IS NULL AND v.watermark_site_id IS NOT NULL
   AND (coalesce(s.created_at,'-infinity'::timestamptz),s.id)<=(v.watermark_created_at,v.watermark_site_id)
   AND (v.cursor_site_id IS NULL OR (coalesce(s.created_at,'-infinity'::timestamptz),s.id)>(v.cursor_created_at,v.cursor_site_id))
  ORDER BY coalesce(s.created_at,'-infinity'::timestamptz),s.id LIMIT p_limit
 LOOP
  site_status:=NULL;variance:=NULL;failure_code:=NULL;
  BEGIN
   -- Keep the existing canonical refresh as the only reconciliation authority.
   reconciliation:=public.refresh_money_ledger_site_reconciliation(site.id);
   IF reconciliation.site_id IS DISTINCT FROM site.id OR reconciliation.status IS NULL
    OR reconciliation.status NOT IN('verified','mismatch') OR reconciliation.variance_minor IS NULL
    OR abs(reconciliation.variance_minor::numeric)>9007199254740991
    OR (reconciliation.status='verified') IS DISTINCT FROM (reconciliation.variance_minor=0) THEN
    RAISE EXCEPTION 'Canonical reconciliation reply is invalid or unsafe' USING ERRCODE='22003'; END IF;
   site_status:=reconciliation.status;variance:=reconciliation.variance_minor;
  EXCEPTION WHEN OTHERS THEN
   -- The subtransaction also rolls back an invalid refresh. No fabricated zero
   -- and no raw error/financial source data is copied into operational logs.
   site_status:='failed';variance:=NULL;failure_code:=SQLSTATE;
  END;
  count_checked:=count_checked+1;
  IF site_status='verified' THEN count_verified:=count_verified+1;
  ELSIF site_status='mismatch' THEN count_mismatches:=count_mismatches+1;
  ELSE count_failed:=count_failed+1; END IF;
  items:=items||jsonb_build_array(jsonb_build_object('site_id',site.id,
   'label',coalesce(nullif(site.store_name,''),nullif(site.name,''),nullif(site.subdomain,''),site.id::text),
   'status',site_status,'variance_minor',variance,'failure_code',failure_code,'attempted_at',clock_timestamp()));
  v.cursor_created_at:=site.ordered_created_at;v.cursor_site_id:=site.id;
 END LOOP;
 pass_complete:=NOT EXISTS(SELECT 1 FROM public.sites s WHERE s.deleted_at IS NULL AND v.watermark_site_id IS NOT NULL
  AND (coalesce(s.created_at,'-infinity'::timestamptz),s.id)<=(v.watermark_created_at,v.watermark_site_id)
  AND (v.cursor_site_id IS NULL OR (coalesce(s.created_at,'-infinity'::timestamptz),s.id)>(v.cursor_created_at,v.cursor_site_id)));
 IF pass_complete THEN v.pass_completed_at:=clock_timestamp(); END IF;
 v.checked:=v.checked+count_checked;v.verified:=v.verified+count_verified;
 v.mismatches:=v.mismatches+count_mismatches;v.failed:=v.failed+count_failed;
 v.revision:=prior_revision+1;

 UPDATE public.money_ledger_reconciliation_traversal SET pass_id=v.pass_id,pass_started_at=v.pass_started_at,
  pass_completed_at=v.pass_completed_at,watermark_created_at=v.watermark_created_at,watermark_site_id=v.watermark_site_id,
  cursor_created_at=v.cursor_created_at,cursor_site_id=v.cursor_site_id,checked=v.checked,verified=v.verified,
  mismatches=v.mismatches,failed=v.failed,revision=v.revision
  WHERE id=v.id AND revision=prior_revision;
 GET DIAGNOSTICS affected=ROW_COUNT;
 IF affected<>1 THEN RAISE EXCEPTION 'Reconciliation traversal revision conflict' USING ERRCODE='40001'; END IF;

 overall_status:=CASE WHEN v.failed>0 THEN 'failed' WHEN v.mismatches>0 THEN 'mismatch'
  WHEN pass_complete THEN 'pass_completed' ELSE 'partial' END;
 result:=jsonb_build_object('version',1,'request_id',p_request_key,'pass_id',v.pass_id,'revision',v.revision,
  'pass_started_at',v.pass_started_at,'pass_completed_at',v.pass_completed_at,'pass_completed',pass_complete,
  'status',overall_status,'limit',p_limit,'replayed',false,'checked',count_checked,'verified',count_verified,
  'mismatches',count_mismatches,'failed',count_failed,'results',items,
  'pass_counts',jsonb_build_object('checked',v.checked,'verified',v.verified,'mismatches',v.mismatches,'failed',v.failed),
  'cursor',jsonb_build_object('created_at',v.cursor_created_at,'site_id',v.cursor_site_id),
  'watermark',jsonb_build_object('created_at',v.watermark_created_at,'site_id',v.watermark_site_id));
 INSERT INTO public.money_ledger_reconciliation_batches(request_key,batch_limit,pass_id,result)
  VALUES(p_request_key,p_limit,v.pass_id,result);
 RETURN result;
END;

DECLARE
  v_account public.buyer_accounts%ROWTYPE;
  v_existing public.buyer_ai_operations%ROWTYPE;
  v_day date := (statement_timestamp() AT TIME ZONE 'UTC')::date;
BEGIN
  IF p_session_epoch IS NULL OR p_session_epoch < 0 OR p_conversation_id IS NULL OR p_request_id IS NULL
    OR p_payload_hash IS NULL OR p_payload_hash !~ '^[a-f0-9]{64}$'
    OR p_profile_id IS NULL OR length(p_profile_id) NOT BETWEEN 1 AND 80
    OR p_request_limit IS NULL OR p_request_limit NOT BETWEEN 1 AND 10000
    OR p_token_limit IS NULL OR p_token_limit NOT BETWEEN 1 AND 100000000
    OR p_reserved_tokens IS NULL OR p_reserved_tokens NOT BETWEEN 1 AND 2000000 THEN
    RAISE EXCEPTION 'Invalid AI admission' USING ERRCODE = '22023';
  END IF;
  -- Same lock order in every RPC: live account, then operation/counter. It also
  -- serializes first requests and session revocation against admission.
  SELECT * INTO v_account FROM public.buyer_accounts WHERE id=p_buyer_account_id FOR UPDATE;
  IF NOT FOUND OR v_account.status <> 'active' OR v_account.session_epoch <> p_session_epoch THEN
    RETURN jsonb_build_object('status','unauthorized');
  END IF;
  SELECT * INTO v_existing FROM public.buyer_ai_operations
    WHERE buyer_account_id=p_buyer_account_id AND request_id=p_request_id;
  IF FOUND THEN
    IF v_existing.session_epoch <> p_session_epoch OR v_existing.conversation_id <> p_conversation_id
      OR v_existing.payload_hash <> p_payload_hash OR v_existing.profile_id <> p_profile_id THEN
      RETURN jsonb_build_object('status','conflict');
    END IF;
    RETURN jsonb_build_object('status',CASE v_existing.state
      WHEN 'completed' THEN 'result_unavailable'
      WHEN 'outcome_unknown' THEN 'outcome_unknown' ELSE 'in_progress' END);
  END IF;
  INSERT INTO public.buyer_ai_daily_quotas VALUES(p_buyer_account_id,v_day,0,0)
    ON CONFLICT DO NOTHING;
  UPDATE public.buyer_ai_daily_quotas SET requests_reserved=requests_reserved+1,
      tokens_reserved=tokens_reserved+p_reserved_tokens
    WHERE buyer_account_id=p_buyer_account_id AND quota_day=v_day
      AND requests_reserved < p_request_limit
      AND tokens_reserved <= p_token_limit-p_reserved_tokens;
  IF NOT FOUND THEN RETURN jsonb_build_object('status','quota_exceeded'); END IF;
  INSERT INTO public.buyer_ai_operations(buyer_account_id,request_id,conversation_id,
    session_epoch,payload_hash,profile_id,reserved_tokens,state)
    VALUES(p_buyer_account_id,p_request_id,p_conversation_id,p_session_epoch,
      p_payload_hash,p_profile_id,p_reserved_tokens,'reserved');
  RETURN jsonb_build_object('status','reserved');
END;

DECLARE v_account public.buyer_accounts%ROWTYPE;
BEGIN
  IF NOT ((p_from_state='reserved' AND p_to_state='dispatched') OR
    (p_from_state='dispatched' AND p_to_state IN ('completed','outcome_unknown'))) THEN
    RAISE EXCEPTION 'Invalid AI transition' USING ERRCODE='22023';
  END IF;
  SELECT * INTO v_account FROM public.buyer_accounts WHERE id=p_buyer_account_id FOR UPDATE;
  IF NOT FOUND OR v_account.status <> 'active' OR v_account.session_epoch <> p_session_epoch THEN RETURN false; END IF;
  UPDATE public.buyer_ai_operations SET state=p_to_state, updated_at=statement_timestamp()
    WHERE buyer_account_id=p_buyer_account_id AND session_epoch=p_session_epoch
      AND request_id=p_request_id AND state=p_from_state;
  RETURN FOUND;
END;

DECLARE
  v_receipt public.buyer_support_mutation_receipts%ROWTYPE;
  v_ticket public.support_tickets%ROWTYPE;
  v_message public.ticket_messages%ROWTYPE;
BEGIN
  IF p_buyer_account_id IS NULL OR p_session_epoch IS NULL OR p_site_id IS NULL
    OR p_operation IS NULL OR p_operation NOT IN ('create','reply')
    OR (p_operation='create') <> (p_target_id IS NULL)
    OR p_idempotency_key IS NULL OR length(p_idempotency_key) NOT BETWEEN 8 AND 200
    OR p_idempotency_key<>btrim(p_idempotency_key) OR p_idempotency_key ~ '[[:cntrl:]]' THEN
    RAISE EXCEPTION 'Invalid support receipt request' USING ERRCODE='22023';
  END IF;
  PERFORM 1 FROM public.buyer_accounts WHERE id=p_buyer_account_id
    AND status='active' AND session_epoch=p_session_epoch FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Buyer session ended' USING ERRCODE='PT401'; END IF;
  SELECT * INTO v_receipt FROM public.buyer_support_mutation_receipts
    WHERE buyer_account_id=p_buyer_account_id AND idempotency_key=p_idempotency_key FOR SHARE;
  IF NOT FOUND OR v_receipt.response IS NULL THEN
    -- This is NOT proof that an in-flight action cannot still commit. Keep its key.
    RAISE EXCEPTION 'Support receipt unavailable' USING ERRCODE='PT404';
  END IF;
  IF v_receipt.operation<>p_operation OR v_receipt.target<>coalesce(p_target_id::text,'new') THEN
    RAISE EXCEPTION 'Support receipt action conflict' USING ERRCODE='PT409';
  END IF;
  SELECT * INTO v_ticket FROM public.support_tickets WHERE id=v_receipt.ticket_id
    AND site_id=p_site_id AND requester_type='customer'
    AND requester_user_id=p_buyer_account_id AND deleted_at IS NULL FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Support resource unavailable' USING ERRCODE='PT404'; END IF;
  SELECT * INTO v_message FROM public.ticket_messages
    WHERE id=(v_receipt.response->'mutation_receipt'->>'message_id')::uuid
    AND ticket_id=v_ticket.id AND author_id=p_buyer_account_id AND author_type='requester'
    AND visibility='public' AND deleted_at IS NULL FOR SHARE;
  IF NOT FOUND OR v_message.body IS DISTINCT FROM (CASE WHEN p_operation='create'
    THEN v_receipt.response->'complaint_copy'->>'body' ELSE v_receipt.response->>'body' END)
    OR (p_operation='create' AND v_ticket.subject IS DISTINCT FROM v_receipt.response->'complaint_copy'->>'subject') THEN
    RAISE EXCEPTION 'Support resource unavailable' USING ERRCODE='PT404';
  END IF;
  RETURN v_receipt.response;
END

DECLARE j public.platform_queue_jobs; r public.loyalty_ledger_entries; o public.orders; a public.loyalty_accounts;
 v_valid boolean;v_owed boolean;v_eligible boolean;v_settled boolean;v_conflict boolean;v_identity text;v_fingerprint text;v_reason text;
BEGIN
 SELECT * INTO j FROM public.platform_queue_jobs WHERE id=p_job_id AND deleted_at IS NULL
  AND queue_name='loyalty-refunds' AND job_type='loyalty.restore_redeemed';
 IF NOT FOUND THEN RETURN NULL;END IF;
 SELECT * INTO r FROM public.loyalty_ledger_entries WHERE id=j.event_id AND site_id=j.site_id AND entry_type='redeemed';
 SELECT * INTO o FROM public.orders WHERE id=r.order_id AND store_id=j.site_id AND deleted_at IS NULL;
 SELECT * INTO a FROM public.loyalty_accounts WHERE id=r.loyalty_account_id AND site_id=j.site_id;
 v_valid:=r.id IS NOT NULL AND o.id IS NOT NULL AND a.id IS NOT NULL AND j.site_id IS NOT NULL
  AND j.outbox_event_id IS NULL AND j.schema_version=1
  AND j.idempotency_key='loyalty.refund_restore:'||r.id::text
  AND j.payload=jsonb_build_object('redeemed_entry_id',r.id,'order_id',r.order_id)
  AND EXISTS(SELECT 1 FROM public.sites s WHERE s.id=j.site_id AND s.deleted_at IS NULL);
 SELECT EXISTS(SELECT 1 FROM public.loyalty_ledger_entries c WHERE c.site_id=j.site_id
   AND c.idempotency_key='loyalty.refund_credit:'||r.order_id::text||':'||r.id::text
   AND c.entry_type='refund_credit' AND c.order_id=r.order_id AND c.loyalty_account_id=r.loyalty_account_id
   AND c.points=r.points AND c.metadata=jsonb_build_object('redeemed_entry_id',r.id,'points',r.points,
    'point_value_minor_at_redemption',r.metadata->>'point_value_minor','value_minor_at_redemption',r.metadata->>'value_minor')) INTO v_settled;
 SELECT EXISTS(SELECT 1 FROM public.loyalty_ledger_entries c WHERE c.site_id=j.site_id
  AND c.idempotency_key='loyalty.refund_credit:'||r.order_id::text||':'||r.id::text) AND NOT v_settled INTO v_conflict;
 v_valid:=coalesce(v_valid,false) AND NOT v_conflict;
 v_owed:=v_valid AND public.loyalty_order_reversal_eligible_v1(j.site_id,r.order_id) AND NOT v_settled;
 v_eligible:=coalesce(v_owed,false) AND j.status IN('dead','failed') AND j.attempts>=j.max_attempts
  AND j.max_attempts>=1 AND j.attempts>=1 AND j.attempts<2147483647
  AND j.locked_at IS NULL AND j.locked_by IS NULL AND j.completed_at IS NULL AND j.failed_at IS NOT NULL;
 v_identity:=encode(sha256(convert_to(jsonb_build_object('id',j.id,'site_id',j.site_id,'event_id',j.event_id,
  'outbox_event_id',j.outbox_event_id,'queue_name',j.queue_name,'job_type',j.job_type,'schema_version',j.schema_version,
  'idempotency_key',j.idempotency_key,'payload_hash',encode(sha256(convert_to(j.payload::text,'UTF8')),'hex'),
  'request_id',j.request_id,'trace_id',j.trace_id,'created_at',j.created_at,
  'redeemed_hash',encode(sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex'),
  'account',jsonb_build_array(a.id,a.site_id,a.buyer_account_id),'order',jsonb_build_array(o.id,o.store_id))::text,'UTF8')),'hex');
 v_fingerprint:=encode(sha256(convert_to(jsonb_build_object('source_identity',v_identity,
  'job_hash',encode(sha256(convert_to(to_jsonb(j)::text,'UTF8')),'hex'),
  'order_hash',encode(sha256(convert_to(to_jsonb(o)::text,'UTF8')),'hex'),
  'account_hash',encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex'),'owed',v_owed)::text,'UTF8')),'hex');
 v_reason:=CASE WHEN NOT coalesce(v_valid,false) THEN 'source_unavailable' WHEN NOT coalesce(v_owed,false) THEN 'debt_not_owed'
  WHEN j.locked_at IS NOT NULL OR j.locked_by IS NOT NULL THEN 'lease_present'
  WHEN j.status NOT IN('dead','failed') OR j.completed_at IS NOT NULL THEN 'not_exhausted'
  WHEN j.attempts<j.max_attempts OR j.attempts<1 OR j.max_attempts<1 OR j.failed_at IS NULL THEN 'not_exhausted'
  WHEN j.attempts>=2147483647 THEN 'attempt_limit' ELSE 'eligible' END;
 RETURN jsonb_build_object('id',j.id,'site_id',j.site_id,'queue_name',j.queue_name,'job_type',j.job_type,
  'status',j.status,'attempts',j.attempts,'max_attempts',j.max_attempts,'order_id',o.id,'redeemed_entry_id',r.id,
  'points',r.points::text,'point_value_minor',r.metadata->>'point_value_minor','value_minor',r.metadata->>'value_minor',
  'created_at',j.created_at,'failed_at',j.failed_at,'completed_at',j.completed_at,'eligible',coalesce(v_eligible,false),
  'reason_code',v_reason,'source_valid',coalesce(v_valid,false),'source_identity',v_identity,'source_fingerprint',v_fingerprint);
END

DECLARE v_permission jsonb;v_state jsonb;v_total bigint;v_items jsonb;
BEGIN
 v_permission:=public.console_permission_snapshot_v1(p_session_id,p_cookie_sha256,false);
 IF NOT coalesce((v_permission->>'accepted')::boolean,false) THEN RETURN v_permission;END IF;
 v_state:=v_permission->'session';
 IF NOT coalesce((v_state->>'is_super_admin')::boolean,false) THEN RETURN jsonb_build_object('accepted',false,'code','INDEPENDENT_SUPER_ADMIN_REQUIRED');END IF;
 IF v_permission->>'evidence_hash' IS DISTINCT FROM p_permission_hash THEN RETURN jsonb_build_object('accepted',false,'code','PERMISSION_CHANGED');END IF;
 IF p_page IS NULL OR p_limit IS NULL OR p_page<1 OR p_page>10000 OR p_limit<1 OR p_limit>50 THEN
  RETURN jsonb_build_object('accepted',false,'code','APPROVAL_QUERY_INVALID');END IF;
 IF nullif(current_setting('app.site_id',true),'') IS NOT NULL AND
  (p_site_id IS NULL OR current_setting('app.site_id',true) IS DISTINCT FROM p_site_id::text) THEN
  RETURN jsonb_build_object('accepted',false,'code','APPROVAL_TARGET_NOT_FOUND');END IF;
 SELECT count(*) INTO v_total FROM public.platform_queue_jobs j WHERE j.deleted_at IS NULL
  AND j.queue_name='loyalty-refunds' AND j.job_type='loyalty.restore_redeemed'
  AND(p_site_id IS NULL OR j.site_id=p_site_id) AND(p_job_id IS NULL OR j.id=p_job_id)
  AND(p_job_id IS NOT NULL OR (j.status IN('dead','failed') AND j.attempts>=j.max_attempts));
 SELECT coalesce(jsonb_agg(public.console_platform_job_snapshot_v1(x.id) ORDER BY x.created_at,x.id),'[]'::jsonb) INTO v_items FROM(
  SELECT j.id,j.created_at FROM public.platform_queue_jobs j WHERE j.deleted_at IS NULL
   AND j.queue_name='loyalty-refunds' AND j.job_type='loyalty.restore_redeemed'
   AND(p_site_id IS NULL OR j.site_id=p_site_id) AND(p_job_id IS NULL OR j.id=p_job_id)
   AND(p_job_id IS NOT NULL OR (j.status IN('dead','failed') AND j.attempts>=j.max_attempts))
   ORDER BY j.created_at,j.id LIMIT p_limit OFFSET ((p_page-1)*p_limit)) x;
 RETURN jsonb_build_object('accepted',true,'items',v_items,'total',v_total,'page',p_page,'limit',p_limit,'has_next',p_page::bigint*p_limit<v_total);
END

DECLARE v_permission jsonb;v_state jsonb;v_approval public.sensitive_action_approvals; j public.platform_queue_jobs;
 v_snapshot jsonb;v_payload jsonb;v_hash text;
BEGIN
 v_permission:=public.console_permission_snapshot_v1(p_session_id,p_cookie_sha256,true);
 IF NOT coalesce((v_permission->>'accepted')::boolean,false) THEN RETURN v_permission;END IF;
 v_state:=v_permission->'session';
 IF NOT coalesce((v_state->>'is_super_admin')::boolean,false) THEN RETURN jsonb_build_object('accepted',false,'code','INDEPENDENT_SUPER_ADMIN_REQUIRED');END IF;
 IF v_permission->>'evidence_hash' IS DISTINCT FROM p_permission_hash THEN RETURN jsonb_build_object('accepted',false,'code','PERMISSION_CHANGED');END IF;
 IF p_job_id IS NULL OR p_site_id IS NULL OR p_request_key IS NULL OR p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 8 AND 1000
  OR p_source_fingerprint IS NULL OR p_source_fingerprint!~'^[0-9a-f]{64}$' THEN
  RETURN jsonb_build_object('accepted',false,'code','APPROVAL_INTENT_INVALID');END IF;
 IF nullif(current_setting('app.site_id',true),'') IS NOT NULL AND current_setting('app.site_id',true) IS DISTINCT FROM p_site_id::text THEN
  RETURN jsonb_build_object('accepted',false,'code','APPROVAL_TARGET_NOT_FOUND');END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('letbuyy:approval-request:'||(v_state->>'actor_id')||':'||p_request_key::text,0));
 SELECT * INTO v_approval FROM public.sensitive_action_approvals WHERE protocol_version=1 AND maker_actor_id=(v_state->>'actor_id')::uuid
  AND action='platform.job.redrive' AND request_key=p_request_key;
 -- The request key cannot name a different job or session, even after a reply loss.
 IF FOUND THEN
  IF v_approval.requester_session_id<>p_session_id OR v_approval.site_id IS DISTINCT FROM p_site_id
   OR v_approval.resource_type<>'platform_queue_job' OR v_approval.resource_id<>p_job_id::text
   OR v_approval.reason<>btrim(p_reason) OR v_approval.payload->'job'->>'source_fingerprint' IS DISTINCT FROM p_source_fingerprint THEN
   RETURN jsonb_build_object('accepted',false,'code','IDEMPOTENCY_CONFLICT');END IF;
  v_snapshot:=public.console_platform_job_snapshot_v1(p_job_id);
  IF v_snapshot IS NULL OR NOT coalesce((v_snapshot->>'source_valid')::boolean,false)
   OR v_snapshot->>'source_identity' IS DISTINCT FROM v_approval.payload->'job'->>'source_identity' THEN
   RETURN jsonb_build_object('accepted',false,'code','APPROVAL_TARGET_STATE_CHANGED');END IF;
  RETURN jsonb_build_object('accepted',true,'approval',public.console_approval_view_v1(v_approval.id),'replayed',true);
 END IF;
 SELECT * INTO j FROM public.platform_queue_jobs WHERE id=p_job_id AND site_id=p_site_id AND deleted_at IS NULL FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('accepted',false,'code','APPROVAL_TARGET_NOT_FOUND');END IF;
 PERFORM o.id FROM public.orders o JOIN public.loyalty_ledger_entries r ON r.order_id=o.id
  WHERE r.id=j.event_id AND r.site_id=j.site_id AND o.store_id=j.site_id FOR UPDATE OF o;
 v_snapshot:=public.console_platform_job_snapshot_v1(p_job_id);
 IF v_snapshot IS NULL OR NOT coalesce((v_snapshot->>'eligible')::boolean,false)
  OR v_snapshot->>'source_fingerprint' IS DISTINCT FROM p_source_fingerprint THEN
  RETURN jsonb_build_object('accepted',false,'code','APPROVAL_TARGET_STATE_CHANGED');END IF;
 v_payload:=jsonb_build_object('operation','platform.job.redrive','retry_budget',1,'reason',btrim(p_reason),'job',v_snapshot);
 v_hash:=public.console_approval_payload_hash_v1('platform.job.redrive',p_site_id,'platform_queue_job',p_job_id::text,v_payload);
 INSERT INTO public.sensitive_action_approvals(site_id,action,resource_type,resource_id,maker_actor_id,status,reason,
  protocol_version,requester_session_id,request_key,payload,payload_hash,expires_at,created_by)
 VALUES(p_site_id,'platform.job.redrive','platform_queue_job',p_job_id::text,(v_state->>'actor_id')::uuid,'pending',btrim(p_reason),
  1,p_session_id,p_request_key,v_payload,v_hash,least(clock_timestamp()+interval '10 minutes',(v_state->>'expires_at')::timestamptz,
  (v_state->>'mfa_verified_at')::timestamptz+interval '10 minutes'),(v_state->>'actor_id')::uuid) RETURNING * INTO v_approval;
 INSERT INTO public.audit_logs(actor_id,actor_type,actor_email,action,resource_type,resource_id,metadata)
 VALUES(v_approval.maker_actor_id,'super_admin',v_state->>'email','sensitive_action.requested','sensitive_action_approval',v_approval.id,
  jsonb_build_object('action','platform.job.redrive','site_id',p_site_id,'job_id',p_job_id,'payload_hash',v_hash,'requester_session_id',p_session_id));
 RETURN jsonb_build_object('accepted',true,'approval',public.console_approval_view_v1(v_approval.id),'replayed',false);
END

DECLARE v_approval public.sensitive_action_approvals;v_permission jsonb;v_state jsonb;v_checker jsonb;
 j public.platform_queue_jobs;v_snapshot jsonb;v_result jsonb;v_when timestamptz;
BEGIN
 SELECT * INTO v_approval FROM public.sensitive_action_approvals WHERE id=p_id AND protocol_version=1 FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('accepted',false,'code','APPROVAL_NOT_FOUND');END IF;
 PERFORM id FROM public.sessions_v2 WHERE id=ANY(ARRAY[p_session_id,v_approval.requester_session_id,v_approval.approver_session_id]) ORDER BY id FOR UPDATE;
 v_permission:=public.console_permission_snapshot_v1(p_session_id,p_cookie_sha256,true);
 IF NOT coalesce((v_permission->>'accepted')::boolean,false) THEN RETURN v_permission;END IF;
 v_state:=v_permission->'session';
 IF NOT coalesce((v_state->>'is_super_admin')::boolean,false) THEN RETURN jsonb_build_object('accepted',false,'code','INDEPENDENT_SUPER_ADMIN_REQUIRED');END IF;
 IF v_permission->>'evidence_hash' IS DISTINCT FROM p_permission_hash THEN RETURN jsonb_build_object('accepted',false,'code','PERMISSION_CHANGED');END IF;
 IF v_approval.maker_actor_id IS DISTINCT FROM (v_state->>'actor_id')::uuid OR v_approval.requester_session_id IS DISTINCT FROM p_session_id THEN
  RETURN jsonb_build_object('accepted',false,'code','APPROVAL_REQUESTER_MISMATCH');END IF;
 IF p_job_id IS NULL OR p_site_id IS NULL OR p_request_key IS NULL OR p_reason IS NULL
  OR v_approval.action<>'platform.job.redrive' OR v_approval.resource_type<>'platform_queue_job'
  OR v_approval.resource_id IS DISTINCT FROM p_job_id::text OR v_approval.site_id IS DISTINCT FROM p_site_id
  OR v_approval.request_key IS DISTINCT FROM p_request_key OR v_approval.reason IS DISTINCT FROM btrim(p_reason)
  OR v_approval.payload->>'operation' IS DISTINCT FROM 'platform.job.redrive' OR v_approval.payload->>'retry_budget' IS DISTINCT FROM '1'
  OR v_approval.payload_hash IS DISTINCT FROM public.console_approval_payload_hash_v1(v_approval.action,v_approval.site_id,
   v_approval.resource_type,v_approval.resource_id,v_approval.payload) THEN
  RETURN jsonb_build_object('accepted',false,'code','APPROVAL_PAYLOAD_MISMATCH');END IF;
 IF v_approval.status<>'approved' OR v_approval.approver_session_id IS NULL OR v_approval.checker_actor_id IS NULL
  OR v_approval.checker_actor_id=v_approval.maker_actor_id THEN
  RETURN jsonb_build_object('accepted',false,'code','INDEPENDENT_APPROVAL_REQUIRED');END IF;
 v_checker:=public.console_permission_snapshot_v1(v_approval.approver_session_id,
  (SELECT metadata->>'cookie_sha256' FROM public.sessions_v2 WHERE id=v_approval.approver_session_id),true);
 IF NOT coalesce((v_checker->>'accepted')::boolean,false) OR NOT coalesce((v_checker->'session'->>'is_super_admin')::boolean,false)
  OR v_checker->'session'->>'actor_id' IS DISTINCT FROM v_approval.checker_actor_id::text OR v_approval.expires_at<=clock_timestamp() THEN
  RETURN jsonb_build_object('accepted',false,'code','APPROVAL_EXPIRED_OR_REVOKED');END IF;
 IF nullif(current_setting('app.site_id',true),'') IS NOT NULL AND current_setting('app.site_id',true) IS DISTINCT FROM p_site_id::text THEN
  RETURN jsonb_build_object('accepted',false,'code','APPROVAL_TARGET_NOT_FOUND');END IF;
 SELECT * INTO j FROM public.platform_queue_jobs WHERE id=p_job_id AND site_id=p_site_id AND deleted_at IS NULL FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('accepted',false,'code','APPROVAL_TARGET_NOT_FOUND');END IF;
 PERFORM o.id FROM public.orders o JOIN public.loyalty_ledger_entries r ON r.order_id=o.id
  WHERE r.id=j.event_id AND r.site_id=j.site_id AND o.store_id=j.site_id FOR UPDATE OF o;
 v_snapshot:=public.console_platform_job_snapshot_v1(p_job_id);
 IF v_snapshot IS NULL OR NOT coalesce((v_snapshot->>'source_valid')::boolean,false)
  OR v_snapshot->>'source_identity' IS DISTINCT FROM v_approval.payload->'job'->>'source_identity' THEN
  RETURN jsonb_build_object('accepted',false,'code','APPROVAL_TARGET_STATE_CHANGED');END IF;
 IF v_approval.consumed_at IS NOT NULL THEN RETURN jsonb_build_object('accepted',true,'result',v_approval.result||'{"replayed":true}'::jsonb);END IF;
 IF NOT coalesce((v_snapshot->>'eligible')::boolean,false) OR j.attempts>=2147483647
  OR v_snapshot->>'source_fingerprint' IS DISTINCT FROM v_approval.payload->'job'->>'source_fingerprint' THEN
  RETURN jsonb_build_object('accepted',false,'code','APPROVAL_TARGET_STATE_CHANGED');END IF;
 v_when:=clock_timestamp();
 UPDATE public.platform_queue_jobs SET status='queued',max_attempts=j.attempts+1,available_at=v_when,
  updated_by=v_approval.maker_actor_id,updated_at=v_when WHERE id=j.id;
 v_result:=jsonb_build_object('operation','retry_authorized','operation_id',p_id,'job_id',j.id,'site_id',j.site_id,
  'event_id',j.event_id,'previous_attempts',j.attempts,'max_attempts',j.attempts+1,'retry_budget',1,'queued_at',v_when,'replayed',false);
 INSERT INTO public.audit_logs(actor_id,actor_type,actor_email,action,resource_type,resource_id,metadata)
 VALUES(v_approval.maker_actor_id,'super_admin',v_state->>'email','platform.job.redriven','platform_queue_job',j.id,
  jsonb_build_object('site_id',j.site_id,'approval_id',p_id,'reason',v_approval.reason,'requester_session_id',p_session_id,
  'approver_session_id',v_approval.approver_session_id,'independent_approver_id',v_approval.checker_actor_id,
  'payload_hash',v_approval.payload_hash,'source_fingerprint',v_snapshot->>'source_fingerprint',
  'previous_attempts',j.attempts,'previous_max_attempts',j.max_attempts,'retry_budget',1));
 UPDATE public.sensitive_action_approvals SET consumed_at=v_when,result=v_result,updated_by=v_approval.maker_actor_id WHERE id=p_id;
 -- Session locks serialize committed revocation; also refuse an in-transaction
 -- fault/trigger that changes authority before the atomic receipt can commit.
 v_permission:=public.console_permission_snapshot_v1(p_session_id,p_cookie_sha256,true);
 v_checker:=public.console_permission_snapshot_v1(v_approval.approver_session_id,
  (SELECT metadata->>'cookie_sha256' FROM public.sessions_v2 WHERE id=v_approval.approver_session_id),true);
 IF NOT coalesce((v_permission->>'accepted')::boolean,false) OR NOT coalesce((v_permission->'session'->>'is_super_admin')::boolean,false)
  OR NOT coalesce((v_checker->>'accepted')::boolean,false) OR NOT coalesce((v_checker->'session'->>'is_super_admin')::boolean,false)
  OR v_permission->'session'->>'actor_id' IS DISTINCT FROM v_approval.maker_actor_id::text
  OR v_checker->'session'->>'actor_id' IS DISTINCT FROM v_approval.checker_actor_id::text
  OR v_permission->>'evidence_hash' IS DISTINCT FROM p_permission_hash OR v_approval.expires_at<=clock_timestamp() THEN
  RAISE EXCEPTION 'Protected recovery authority changed before commit' USING ERRCODE='42501';END IF;
 RETURN jsonb_build_object('accepted',true,'result',v_result);
END

DECLARE s public.sites;t public.themes;target public.theme_releases;current_release public.theme_releases;
 receipt public.idempotency_keys;released record;new_release public.theme_releases;
 v_scope text;v_hash text;v_config jsonb;v_response jsonb;v_message text;
BEGIN
 IF p_actor_id IS NULL OR p_store_id IS NULL OR p_target_release_id IS NULL OR p_expected_current_release_id IS NULL
  OR p_key IS NULL OR char_length(p_key) NOT BETWEEN 8 AND 200 OR p_key<>btrim(p_key) OR p_key~'[[:cntrl:]]'
  OR p_make_store_live IS NULL OR (p_rollback_message IS NOT NULL AND char_length(p_rollback_message)>500) THEN
  RAISE EXCEPTION 'A reviewed rollback target, current release and stable key are required' USING ERRCODE='PT400'; END IF;
 s:=public.theme_draft_actor_site_v1(p_actor_id,p_store_id,p_bound_site_id);
 SELECT * INTO t FROM public.themes WHERE slug=p_theme_slug AND is_active=true FOR SHARE;
 IF t.id IS NULL OR(t.is_site_private AND t.owned_by_site_id IS DISTINCT FROM p_store_id) THEN
  RAISE EXCEPTION 'Theme not available' USING ERRCODE='42501'; END IF;
 SELECT * INTO target FROM public.theme_releases WHERE id=p_target_release_id AND store_id=p_store_id AND theme_id=p_theme_slug
  AND deleted_at IS NULL AND release_status IN('published','superseded') AND published_at IS NOT NULL FOR SHARE;
 IF target.id IS NULL OR target.release_version<1 THEN RAISE EXCEPTION 'Reviewed release unavailable' USING ERRCODE='PT409'; END IF;
 SELECT * INTO current_release FROM public.theme_releases WHERE id=s.current_theme_release_id AND store_id=p_store_id
  AND deleted_at IS NULL AND release_status='published' AND is_current FOR SHARE;
 IF current_release.id IS NULL OR current_release.release_version<1 OR current_release.release_version IS DISTINCT FROM s.storefront_release_version
  OR (SELECT count(*) FROM public.theme_releases WHERE store_id=p_store_id AND is_current AND release_status='published' AND deleted_at IS NULL)<>1 THEN
  RAISE EXCEPTION 'Current release cannot be confirmed' USING ERRCODE='PT503'; END IF;
 v_message:=coalesce(p_rollback_message,'Rollback to release '||target.release_version::text);
 v_scope:='theme-release-rollback-v1:'||p_actor_id::text||':'||p_theme_slug;
 v_hash:=encode(sha256(convert_to(jsonb_build_object('actor',p_actor_id,'store',p_store_id,'theme',p_theme_slug,
  'target',p_target_release_id,'expected_current',p_expected_current_release_id,'make_store_live',p_make_store_live,'message',v_message)::text,'UTF8')),'hex');
 SELECT * INTO receipt FROM public.idempotency_keys WHERE site_id=p_store_id AND scope=v_scope AND key=p_key FOR UPDATE;
 IF FOUND THEN
  IF receipt.request_hash IS DISTINCT FROM v_hash THEN RAISE EXCEPTION 'Rollback key belongs to another intent' USING ERRCODE='PT409'; END IF;
  IF receipt.status<>'completed' OR receipt.response_body IS NULL OR receipt.deleted_at IS NOT NULL
   OR receipt.status_code IS DISTINCT FROM 200 OR receipt.resource_type IS DISTINCT FROM 'theme_release'
   OR receipt.response_hash IS DISTINCT FROM encode(sha256(convert_to(receipt.response_body::text,'UTF8')),'hex')
   OR receipt.response_body#>>'{restored_release,id}' IS DISTINCT FROM target.id::text
   OR receipt.response_body#>>'{restored_release,version}' IS DISTINCT FROM target.release_version::text
   OR receipt.response_body#>>'{rollback,release_id}' IS DISTINCT FROM receipt.resource_id::text
   OR receipt.response_body#>>'{theme,id}' IS DISTINCT FROM t.id::text
   OR receipt.response_body#>>'{theme,slug}' IS DISTINCT FROM t.slug
   OR NOT EXISTS(SELECT 1 FROM public.theme_releases r WHERE r.id=receipt.resource_id AND r.store_id=p_store_id AND r.theme_id=p_theme_slug
    AND r.rollback_of_release_id=target.id AND r.idempotency_key=p_key AND r.deleted_at IS NULL AND r.published_at IS NOT NULL
    AND r.release_status IN('published','superseded') AND r.metadata->>'rollback_protocol'='theme-release-rollback-v1'
    AND r.release_version::text=receipt.response_body#>>'{rollback,release_version}') THEN
   RAISE EXCEPTION 'Rollback receipt unavailable' USING ERRCODE='PT503'; END IF;
  RETURN receipt.response_body||jsonb_build_object('replayed',true,'current_release_id',current_release.id,'current_release_version',current_release.release_version);
 END IF;
 IF current_release.id<>p_expected_current_release_id OR target.id=current_release.id OR target.release_version>=current_release.release_version THEN
  RAISE EXCEPTION 'Reviewed current release changed' USING ERRCODE='PT409'; END IF;
 v_config:=CASE WHEN jsonb_typeof(target.template_snapshot)='object' AND target.template_snapshot<>'{}' THEN target.template_snapshot ELSE target.release_config END;
 IF jsonb_typeof(v_config) IS DISTINCT FROM 'object' OR v_config='{}' THEN
  RAISE EXCEPTION 'Reviewed published document unavailable' USING ERRCODE='PT503'; END IF;
 SELECT * INTO released FROM public.publish_theme_release(p_store_id,p_theme_slug,v_config,NULL,NULL,p_actor_id,
  v_message,p_make_store_live,p_request_id,target.id);
 SELECT * INTO new_release FROM public.theme_releases WHERE id=released.release_id AND store_id=p_store_id;
 -- Clone immutable renderer artifacts, rebinding only release identity. Keep the
 -- canonical publisher's new cache tags/instance pointer and every current draft.
 UPDATE public.theme_releases SET
  release_manifest=coalesce(target.release_manifest,'{}')||jsonb_build_object('store_id',p_store_id,'theme_id',p_theme_slug,
   'release_id',released.release_id,'release_version',released.release_version,'theme_instance_id',new_release.theme_instance_id,
   'theme_package_version_id',target.theme_package_version_id),
  template_snapshot=v_config,settings_snapshot=coalesce(target.settings_snapshot,v_config->'themeSettings','{}'),
  asset_manifest=coalesce(target.asset_manifest,'{}'),data_binding_manifest=coalesce(target.data_binding_manifest,'{}'),
  schema_manifest_version=target.schema_manifest_version,engine_version=target.engine_version,
  theme_package_version_id=target.theme_package_version_id,idempotency_key=p_key,
  metadata=coalesce(new_release.metadata,'{}')||jsonb_build_object('rollback_protocol','theme-release-rollback-v1')
 WHERE id=released.release_id AND store_id=p_store_id;
 v_response:=jsonb_build_object('rollback',jsonb_build_object('release_id',released.release_id,'release_version',released.release_version,
   'published_at',to_char(released.published_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')),
  'restored_release',jsonb_build_object('id',target.id,'version',target.release_version,'published_at',to_char(target.published_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')),
  'theme',jsonb_build_object('id',t.id,'slug',t.slug,'name',t.name));
 INSERT INTO public.idempotency_keys(site_id,key,scope,request_hash,response_hash,response_body,status,status_code,resource_type,resource_id,request_id,expires_at)
  VALUES(p_store_id,p_key,v_scope,v_hash,encode(sha256(convert_to(v_response::text,'UTF8')),'hex'),v_response,'completed',200,'theme_release',released.release_id,p_request_id,'infinity');
 RETURN v_response||jsonb_build_object('replayed',false,'current_release_id',released.release_id,'current_release_version',released.release_version);
END

DECLARE
 v_product_id uuid; v_variant_id uuid; v_location_id uuid; effective_location uuid; delta integer;
 reason text; notes text; level_row public.inventory_levels%ROWTYPE;
 receipt public.inventory_adjustment_receipts%ROWTYPE; has_receipt boolean; response jsonb;
BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'app_tenant' THEN
  RAISE EXCEPTION 'INVENTORY_ADJUST_FORBIDDEN' USING ERRCODE='42501';END IF;
 -- The same shared/exclusive maintenance lock is held until this transaction ends.
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('letbuyy:migration:356:inventory-adjustment',0));
 IF p_store_id IS NULL OR p_actor_id IS NULL OR p_key IS NULL OR length(p_key) NOT BETWEEN 8 AND 200 OR p_key<>btrim(p_key)
  OR jsonb_typeof(p_command) IS DISTINCT FROM 'object' OR octet_length(p_command::text)>4096
  OR NOT(p_command ?& ARRAY['product_id','variant_id','location_id','adjustment','reason','notes'])
  OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_command) k WHERE k NOT IN('product_id','variant_id','location_id','adjustment','reason','notes'))
  OR jsonb_typeof(p_command->'product_id') IS DISTINCT FROM 'string'
  OR jsonb_typeof(p_command->'variant_id') NOT IN('string','null')
  OR jsonb_typeof(p_command->'location_id') NOT IN('string','null')
  OR jsonb_typeof(p_command->'adjustment') IS DISTINCT FROM 'number'
  OR p_command->>'adjustment' !~ '^-?[0-9]+$'
  OR jsonb_typeof(p_command->'reason') IS DISTINCT FROM 'string'
  OR p_command->>'reason' NOT IN('received','sold','returned','damaged','correction','transfer','sale','return','adjustment','recount')
  OR jsonb_typeof(p_command->'notes') NOT IN('string','null') OR length(p_command->>'notes')>500 THEN
  RAISE EXCEPTION 'INVENTORY_ADJUST_INVALID';END IF;
 v_product_id:=(p_command->>'product_id')::uuid;v_variant_id:=(p_command->>'variant_id')::uuid;
 v_location_id:=(p_command->>'location_id')::uuid;delta:=(p_command->>'adjustment')::integer;notes:=p_command->>'notes';
 IF delta NOT BETWEEN -99999 AND 99999 THEN RAISE EXCEPTION 'INVENTORY_ADJUST_INVALID';END IF;
 PERFORM public.assert_product_edit_actor_v1(p_store_id,p_actor_id,'products:write');
 PERFORM pg_advisory_xact_lock(hashtextextended('letbuyy:inventory.adjustment.v1:'||p_key,0));
 SELECT * INTO receipt FROM public.inventory_adjustment_receipts WHERE idempotency_key=p_key;
 has_receipt:=FOUND;
 IF has_receipt AND (receipt.operation<>'inventory.adjustment.v1' OR receipt.store_id IS DISTINCT FROM p_store_id
  OR receipt.actor_id IS DISTINCT FROM p_actor_id OR receipt.product_id IS DISTINCT FROM v_product_id OR receipt.command IS DISTINCT FROM p_command) THEN
  RAISE EXCEPTION 'INVENTORY_ADJUST_KEY_CONFLICT';END IF;
 -- An old HTTP cache cannot establish its actor or atomic stock/receipt outcome.
 -- Keep it intact and refuse reapplication, including expired/failed/deleted rows.
 IF NOT has_receipt AND EXISTS(SELECT 1 FROM public.idempotency_keys k WHERE k.site_id=p_store_id
  AND k.scope='http:POST:/inventory/adjust' AND k.key=p_key) THEN
  RAISE EXCEPTION 'INVENTORY_ADJUST_LEGACY_KEY';END IF;
 PERFORM p.id FROM public.products p WHERE p.id=v_product_id AND p.store_id=p_store_id AND p.deleted_at IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'INVENTORY_ADJUST_NOT_FOUND';END IF;
 -- An omitted legacy default stays bound to its originally acknowledged location on retry.
 effective_location:=coalesce(v_location_id,CASE WHEN has_receipt THEN (receipt.response->>'location_id')::uuid END);
 IF effective_location IS NULL THEN effective_location:=public.ensure_default_inventory_location(p_store_id);END IF;
 PERFORM l.id FROM public.inventory_locations l WHERE l.id=effective_location AND l.store_id=p_store_id AND l.deleted_at IS NULL FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'INVENTORY_ADJUST_NOT_FOUND';END IF;
 -- Serialize creation of a missing legacy level without replacing the stock writer.
 PERFORM pg_advisory_xact_lock(hashtextextended('letbuyy:inventory-level:'||v_product_id::text||':'||coalesce(v_variant_id::text,'default')||':'||effective_location::text,0));
 SELECT il.* INTO level_row FROM public.inventory_levels il WHERE il.store_id=p_store_id AND il.product_id=v_product_id
  AND il.variant_id IS NOT DISTINCT FROM v_variant_id AND il.location_id=effective_location FOR UPDATE;
 IF FOUND AND level_row.deleted_at IS NOT NULL THEN RAISE EXCEPTION 'INVENTORY_ADJUST_NOT_FOUND';END IF;
 IF v_variant_id IS NOT NULL THEN
  PERFORM pv.id FROM public.product_variants pv WHERE pv.id=v_variant_id AND pv.product_id=v_product_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'INVENTORY_ADJUST_NOT_FOUND';END IF;
 END IF;
 -- Compatible with existing level -> variant -> parent stock/edit lock ordering.
 PERFORM p.id FROM public.products p WHERE p.id=v_product_id AND p.store_id=p_store_id AND p.deleted_at IS NULL FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'INVENTORY_ADJUST_NOT_FOUND';END IF;
 IF has_receipt THEN
  IF level_row.id IS DISTINCT FROM (receipt.response->>'id')::uuid THEN RAISE EXCEPTION 'INVENTORY_ADJUST_NOT_FOUND';END IF;
  RETURN jsonb_build_object('level',receipt.response,'replayed',true);
 END IF;
 reason:=CASE p_command->>'reason' WHEN 'sold' THEN 'sale' WHEN 'returned' THEN 'return'
  WHEN 'received' THEN 'adjustment' WHEN 'correction' THEN 'adjustment' ELSE p_command->>'reason' END;
 response:=public.adjust_inventory_level(v_product_id,v_variant_id,effective_location,delta,p_actor_id,reason,notes,
  nullif(current_setting('app.request_id',true),''));
 INSERT INTO public.inventory_adjustment_receipts(idempotency_key,operation,store_id,actor_id,product_id,command,response)
 VALUES(p_key,'inventory.adjustment.v1',p_store_id,p_actor_id,v_product_id,p_command,response);
 RETURN jsonb_build_object('level',response,'replayed',false);
END

DECLARE b public.buyer_accounts; c public.store_customers; l public.buyer_store_customers;
 p public.products; provisional_customer uuid; v_review_id uuid;
BEGIN
 IF current_user<>'service_role' THEN RAISE EXCEPTION 'Backend review writer required' USING ERRCODE='42501';END IF;
 -- A repeatable-read snapshot could miss a winner after waiting for the buyer
 -- lock. The canonical PostgREST transport uses read committed; refuse others.
 IF current_setting('transaction_isolation')<>'read committed' THEN RETURN jsonb_build_object('accepted',false,'code','REVIEW_SOURCE_BUSY');END IF;
 IF p_buyer IS NULL OR p_site IS NULL OR p_epoch IS NULL OR p_epoch<1 OR p_product IS NULL
  OR p_rating IS NULL OR p_rating NOT BETWEEN 1 AND 5 OR length(p_title)>120 OR length(p_body)>2000 THEN
  RETURN jsonb_build_object('accepted',false,'code','VALIDATION');END IF;
 IF(nullif(current_setting('app.site_id',true),'') IS NOT NULL AND current_setting('app.site_id',true) IS DISTINCT FROM p_site::text)
  OR(nullif(current_setting('app.tenant_id',true),'') IS NOT NULL AND current_setting('app.tenant_id',true) IS DISTINCT FROM p_site::text) THEN
  RETURN jsonb_build_object('accepted',false,'code','BUYER_SCOPE_MISMATCH');END IF;
 -- This review-only lock is never acquired by255 link resolution. It serializes
 -- duplicate decisions for a canonical subject without upgrading the buyer row.
 PERFORM pg_advisory_xact_lock(hashtextextended('letbuyy:buyer-review:'||p_buyer::text,0));
 SELECT * INTO b FROM public.buyer_accounts WHERE id=p_buyer FOR SHARE NOWAIT;
 IF NOT FOUND OR b.session_epoch IS DISTINCT FROM p_epoch THEN RETURN jsonb_build_object('accepted',false,'code','BUYER_SESSION_INVALID');END IF;
 IF b.status IS DISTINCT FROM 'active' THEN RETURN jsonb_build_object('accepted',false,'code','BUYER_DISABLED');END IF;
 PERFORM 1 FROM public.sites WHERE id=p_site AND deleted_at IS NULL AND site_type='store' FOR SHARE NOWAIT;
 IF NOT FOUND THEN RETURN jsonb_build_object('accepted',false,'code','NOT_FOUND');END IF;
 -- A provisional lookup is not authority. Lock customer BEFORE link, matching
 --255's customer->link order, then re-read the exact relationship under its lock.
 SELECT store_customer_id INTO provisional_customer FROM public.buyer_store_customers WHERE buyer_account_id=p_buyer AND site_id=p_site;
 IF NOT FOUND THEN RETURN jsonb_build_object('accepted',false,'code','STORE_ACCOUNT_NOT_LINKED');END IF;
 SELECT * INTO c FROM public.store_customers WHERE id=provisional_customer AND store_id=p_site FOR SHARE NOWAIT;
 IF NOT FOUND THEN RETURN jsonb_build_object('accepted',false,'code','STORE_ACCOUNT_NOT_LINKED');END IF;
 SELECT * INTO l FROM public.buyer_store_customers WHERE buyer_account_id=p_buyer AND site_id=p_site
  AND store_customer_id=provisional_customer FOR SHARE NOWAIT;
 IF NOT FOUND OR l.verified_at IS NULL OR l.link_basis NOT IN('verified_email','operator_resolution') OR nullif(btrim(c.email),'') IS NULL THEN
  RETURN jsonb_build_object('accepted',false,'code','STORE_ACCOUNT_NOT_LINKED');END IF;
 IF c.status IS DISTINCT FROM 'active' OR c.deleted_at IS NOT NULL THEN RETURN jsonb_build_object('accepted',false,'code','STORE_ACCOUNT_UNAVAILABLE');END IF;
 SELECT * INTO p FROM public.products WHERE id=p_product AND store_id=p_site AND deleted_at IS NULL FOR SHARE NOWAIT;
 IF NOT FOUND THEN RETURN jsonb_build_object('accepted',false,'code','NOT_FOUND');END IF;
 IF p.is_active IS FALSE OR p.status='archived' THEN RETURN jsonb_build_object('accepted',false,'code','PRODUCT_UNAVAILABLE');END IF;
 -- Historical/anonymous contact matches are not authorship. Only this private
 -- immutable edge establishes canonical authorship; soft-deleted content stays retained.
 IF EXISTS(SELECT 1 FROM public.buyer_review_links e JOIN public.product_reviews r ON r.id=e.review_id
  WHERE e.buyer_account_id=p_buyer AND e.site_id=p_site AND e.product_id=p_product AND r.deleted_at IS NULL) THEN
  RETURN jsonb_build_object('accepted',false,'code','CONFLICT');END IF;
 INSERT INTO public.product_reviews(store_id,product_id,customer_name,customer_email,rating,title,body,is_verified,is_approved,status)
 VALUES(p_site,p_product,coalesce(nullif(c.full_name,''),'Customer'),c.email,p_rating,nullif(btrim(p_title),''),nullif(btrim(p_body),''),true,false,'pending')
 RETURNING id INTO v_review_id;
 INSERT INTO public.buyer_review_links(review_id,buyer_account_id,site_id,store_customer_id,product_id)
 VALUES(v_review_id,p_buyer,p_site,c.id,p_product);
 -- Locks serialize external changes. Recheck also catches changes caused by an
 -- in-transaction trigger/fault, rolling back BOTH writes rather than returning a false receipt.
 IF NOT EXISTS(SELECT 1 FROM public.buyer_accounts bx
  JOIN public.buyer_store_customers lx ON lx.buyer_account_id=bx.id AND lx.site_id=p_site AND lx.store_customer_id=c.id
  JOIN public.store_customers cx ON cx.id=lx.store_customer_id AND cx.store_id=p_site
  JOIN public.sites sx ON sx.id=p_site
  JOIN public.products px ON px.id=p_product AND px.store_id=p_site
  JOIN public.product_reviews rx ON rx.id=v_review_id AND rx.store_id=p_site AND rx.product_id=p_product
  JOIN public.buyer_review_links ex ON ex.review_id=rx.id AND ex.buyer_account_id=p_buyer AND ex.site_id=p_site AND ex.store_customer_id=c.id AND ex.product_id=p_product
  WHERE bx.id=p_buyer AND bx.status='active' AND bx.session_epoch=p_epoch
   AND lx.verified_at IS NOT NULL AND lx.link_basis IN('verified_email','operator_resolution')
   AND cx.status='active' AND cx.deleted_at IS NULL AND cx.email IS NOT DISTINCT FROM c.email
   AND sx.deleted_at IS NULL AND sx.site_type='store' AND px.deleted_at IS NULL AND px.is_active IS DISTINCT FROM false AND px.status IS DISTINCT FROM 'archived'
   AND rx.deleted_at IS NULL AND rx.is_verified AND NOT rx.is_approved AND rx.status='pending'
   AND rx.customer_email IS NOT DISTINCT FROM c.email AND rx.rating=p_rating
   AND rx.title IS NOT DISTINCT FROM nullif(btrim(p_title),'') AND rx.body IS NOT DISTINCT FROM nullif(btrim(p_body),'')) THEN
  RAISE EXCEPTION 'Review authority changed before commit' USING ERRCODE='42501';END IF;
 RETURN jsonb_build_object('accepted',true,'review_id',v_review_id);
EXCEPTION WHEN lock_not_available THEN
 RETURN jsonb_build_object('accepted',false,'code','REVIEW_SOURCE_BUSY');
END

DECLARE v_permission jsonb;v_after jsonb;v_state jsonb;v_schedule public.oncall_schedules;v_projection jsonb;
 v_factor jsonb;v_after_factor jsonb;v_fingerprint text;
 v_now timestamptz:=clock_timestamp();
BEGIN
 IF current_user<>'service_role' THEN RAISE EXCEPTION 'Backend Console reader required' USING ERRCODE='42501';END IF;
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'Current Console snapshot required' USING ERRCODE='40001';END IF;
 IF nullif(current_setting('app.site_id',true),'') IS NOT NULL OR nullif(current_setting('app.tenant_id',true),'') IS NOT NULL THEN
  RAISE EXCEPTION 'Platform Console scope required' USING ERRCODE='42501';END IF;
 v_permission:=public.console_permission_snapshot_v1(p_session_id,p_cookie_sha256,false);
 IF NOT coalesce((v_permission->>'accepted')::boolean,false) THEN RETURN v_permission;END IF;
 v_state:=v_permission->'session';
 IF NOT coalesce((v_state->>'is_super_admin')::boolean,false) OR NOT coalesce((v_permission->'input'->>'isSuperAdmin')::boolean,false) THEN
  RETURN jsonb_build_object('accepted',false,'code','INDEPENDENT_SUPER_ADMIN_REQUIRED');END IF;
 IF p_permission_hash IS NULL OR p_permission_hash!~'^[0-9a-f]{64}$' OR v_permission->>'evidence_hash' IS DISTINCT FROM p_permission_hash THEN
  RETURN jsonb_build_object('accepted',false,'code','PERMISSION_CHANGED');END IF;
 -- Reuse the canonical configured-factor owner; a retained MFA claim alone
 -- cannot outlive a changed, retired or reset-required stored factor.
 v_factor:=public.console_mfa_reset_target_v1((v_state->>'actor_id')::uuid)->'factor';
 SELECT metadata->>'console_factor_fingerprint' INTO v_fingerprint FROM public.sessions_v2 WHERE id=p_session_id;
 IF v_factor IS NULL OR v_fingerprint IS NULL OR v_fingerprint!~'^[0-9a-f]{64}$'
  OR v_factor->>'fingerprint' IS DISTINCT FROM v_fingerprint
  OR coalesce((v_factor->>'reset_required')::boolean,false) OR coalesce(v_factor->'retired','[]'::jsonb)?v_fingerprint THEN
  RETURN jsonb_build_object('accepted',false,'code','CONSOLE_FACTOR_PROOF_REQUIRED');END IF;
 SELECT * INTO v_schedule FROM public.oncall_schedules s WHERE s.active AND s.deleted_at IS NULL
  AND s.starts_at<=v_now AND(s.ends_at IS NULL OR s.ends_at>v_now)
  ORDER BY s.starts_at DESC,s.id DESC LIMIT 1 FOR SHARE NOWAIT;
 IF FOUND THEN
  v_projection:=jsonb_build_object('id',v_schedule.id,'team_name',v_schedule.team_name,'rotation_name',v_schedule.rotation_name,
   'primary_employee_id',v_schedule.primary_employee_id,'paging_adapter',v_schedule.paging_adapter);
 ELSE v_projection:=NULL;END IF;
 INSERT INTO public.audit_logs(actor_id,actor_type,actor_email,action,resource_type,resource_id,metadata)
 VALUES((v_state->>'actor_id')::uuid,'super_admin',v_state->>'email','console.oncall.current.read','oncall_schedule',v_schedule.id,
  jsonb_build_object('permission_scope','incident:view','session_id',p_session_id,'display_only',true));
 -- A trigger in this transaction cannot revoke authority and still release a
 -- successful projection/read audit. Raising rolls back that entire statement.
 v_after:=public.console_permission_snapshot_v1(p_session_id,p_cookie_sha256,false);
 IF NOT coalesce((v_after->>'accepted')::boolean,false)
  OR NOT coalesce((v_after->'session'->>'is_super_admin')::boolean,false)
  OR v_after->>'evidence_hash' IS DISTINCT FROM p_permission_hash THEN
  RAISE EXCEPTION 'Current Console authority changed' USING ERRCODE='42501';END IF;
 v_after_factor:=public.console_mfa_reset_target_v1((v_state->>'actor_id')::uuid)->'factor';
 IF v_after_factor IS DISTINCT FROM v_factor OR(SELECT metadata->>'console_factor_fingerprint' FROM public.sessions_v2 WHERE id=p_session_id)IS DISTINCT FROM v_fingerprint THEN
  RAISE EXCEPTION 'Current Console factor changed' USING ERRCODE='42501';END IF;
 RETURN jsonb_build_object('accepted',true,'schedule',v_projection);
END

DECLARE
 v_auth record;v_actor uuid;v_row public.reel_upload_intents;v_replayed boolean:=false;
 v_hash text;v_proof_hash text;v_key text;v_now timestamptz;v_bytes bigint;v_count bigint;v_charged numeric;
 v_media uuid;v_provenance uuid;v_internal jsonb;
BEGIN
 -- Preserve the canonical session helper's protective reuse revocations: a
 -- rejected session returns an error result instead of aborting its updates.
 SELECT * INTO v_auth FROM public.validate_and_rotate_merchant_session(p_session,false);
 IF NOT coalesce(v_auth.accepted,false) OR v_auth.user_id IS DISTINCT FROM p_actor THEN RETURN jsonb_build_object('status',401,'error','REEL_UPLOAD_SESSION_REQUIRED');END IF;
 v_actor:=public.reel_actor_v1(v_auth.user_id,p_site,NULL,p_action NOT IN('read','list'));
 PERFORM set_config('app.site_id',p_site::text,true);
 IF p_action NOT IN('begin','read','list','claim_transfer','claim_reconcile','finish','unknown') OR p_site IS NULL THEN RAISE EXCEPTION 'REEL_UPLOAD_REQUEST_INVALID';END IF;
 IF p_action='list' THEN
  RETURN jsonb_build_object('data',jsonb_build_object('items',(SELECT coalesce(jsonb_agg(public.reel_upload_public_v1(to_jsonb(x),false) ORDER BY x.created_at DESC,x.id),'[]'::jsonb)
   FROM(SELECT * FROM public.reel_upload_intents WHERE site_id=p_site AND actor_id=v_actor ORDER BY created_at DESC,id LIMIT 50)x)));
 END IF;
 IF p_action='read' THEN
  SELECT * INTO v_row FROM public.reel_upload_intents WHERE id=p_intent AND site_id=p_site AND actor_id=v_actor;
  IF v_row.id IS NULL THEN RAISE EXCEPTION 'REEL_UPLOAD_NOT_FOUND';END IF;
  RETURN jsonb_build_object('data',public.reel_upload_public_v1(to_jsonb(v_row),false));
 END IF;
 IF p_command IS NULL OR jsonb_typeof(p_command) IS DISTINCT FROM 'object'
  OR jsonb_typeof(p_command->'idempotency_key') IS DISTINCT FROM 'string'
  OR length(p_command->>'idempotency_key') NOT BETWEEN 8 AND 200
  OR p_command->>'idempotency_key'<>btrim(p_command->>'idempotency_key')
  OR(p_command->>'idempotency_key')~'[[:space:][:cntrl:]]' THEN RAISE EXCEPTION 'REEL_UPLOAD_REQUEST_INVALID';END IF;
 v_key:=p_command->>'idempotency_key';
 -- Admission is supplied only by the trusted Gateway profile resolver. It is
 -- never accepted in client JSON. It contains no invented fallback budgets.
 IF p_admission IS NULL OR jsonb_typeof(p_admission) IS DISTINCT FROM 'object'
  OR p_admission-ARRAY['profile_ref','profile_digest','max_bytes','max_intents','max_charged_bytes','reservation_ttl_seconds','lease_seconds','max_wall_ms']<>'{}'::jsonb
  OR jsonb_typeof(p_admission->'profile_ref') IS DISTINCT FROM 'string' OR length(p_admission->>'profile_ref') NOT BETWEEN 1 AND 200
  OR coalesce(p_admission->>'profile_digest','')!~'^[a-f0-9]{64}$'
  OR EXISTS(SELECT 1 FROM unnest(ARRAY['max_bytes','max_intents','max_charged_bytes','reservation_ttl_seconds','lease_seconds','max_wall_ms']) AS limits(name)
    WHERE jsonb_typeof(p_admission->limits.name) IS DISTINCT FROM 'number' OR coalesce(p_admission->>limits.name,'')!~'^[1-9][0-9]{0,15}$')
 THEN RAISE EXCEPTION 'REEL_UPLOAD_PROFILE_UNAVAILABLE';END IF;
 IF(p_admission->>'max_bytes')::numeric>9007199254740991 OR(p_admission->>'max_charged_bytes')::numeric>9007199254740991
  OR(p_admission->>'max_intents')::numeric>2147483647 OR(p_admission->>'reservation_ttl_seconds')::numeric>2147483647
  OR(p_admission->>'lease_seconds')::numeric>2147483647 OR(p_admission->>'max_wall_ms')::numeric>2147483647
  OR(p_admission->>'lease_seconds')::numeric*1000<=(p_admission->>'max_wall_ms')::numeric THEN RAISE EXCEPTION 'REEL_UPLOAD_PROFILE_UNAVAILABLE';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('letbuyy:private-reel-intake:'||p_site::text,0));
 v_now:=clock_timestamp();
 IF p_action='begin' THEN
  IF p_command-ARRAY['idempotency_key','filename','content_type','size_bytes','checksum_sha256']<>'{}'::jsonb
   OR jsonb_typeof(p_command->'filename') IS DISTINCT FROM 'string' OR length(p_command->>'filename') NOT BETWEEN 1 AND 180
   OR p_command->>'filename'<>btrim(p_command->>'filename') OR(p_command->>'filename')~'[[:cntrl:]]'
   OR jsonb_typeof(p_command->'content_type') IS DISTINCT FROM 'string' OR jsonb_typeof(p_command->'checksum_sha256') IS DISTINCT FROM 'string'
   OR coalesce(p_command->>'content_type','') NOT IN('video/mp4','video/webm')
   OR coalesce(p_command->>'checksum_sha256','')!~'^[a-f0-9]{64}$'
   OR jsonb_typeof(p_command->'size_bytes') IS DISTINCT FROM 'number' OR coalesce(p_command->>'size_bytes','')!~'^[1-9][0-9]{0,15}$'
  THEN RAISE EXCEPTION 'REEL_UPLOAD_REQUEST_INVALID';END IF;
  v_bytes:=(p_command->>'size_bytes')::bigint;
  IF v_bytes<16 OR v_bytes>(p_admission->>'max_bytes')::bigint OR v_bytes>9007199254740991 THEN RAISE EXCEPTION 'REEL_UPLOAD_LIMIT';END IF;
  v_hash:=encode(sha256(convert_to(p_command::text,'UTF8')),'hex');
  SELECT * INTO v_row FROM public.reel_upload_intents WHERE site_id=p_site AND actor_id=v_actor AND idempotency_key=v_key FOR UPDATE;
  IF FOUND THEN
   IF v_row.request_sha256<>v_hash THEN RAISE EXCEPTION 'REEL_UPLOAD_IDEMPOTENCY_CONFLICT';END IF;
   IF v_row.admission IS DISTINCT FROM p_admission THEN RAISE EXCEPTION 'REEL_UPLOAD_PROFILE_CHANGED';END IF;
   RETURN jsonb_build_object('data',public.reel_upload_public_v1(to_jsonb(v_row),true));
  END IF;
  -- Every retained/uncertain intent remains charged; expiry is not authority to
  -- delete an original or free physical-storage capacity under an unknown PUT.
  SELECT count(*),coalesce(sum(charged_bytes),0) INTO v_count,v_charged FROM public.reel_upload_intents WHERE site_id=p_site;
  IF v_count>=(p_admission->>'max_intents')::bigint OR v_charged+v_bytes>(p_admission->>'max_charged_bytes')::bigint THEN RAISE EXCEPTION 'REEL_UPLOAD_QUOTA';END IF;
  INSERT INTO public.reel_upload_intents(site_id,actor_id,session_id,idempotency_key,request_sha256,filename,content_type,size_bytes,checksum_sha256,
   profile_ref,profile_digest,admission,charged_bytes,expires_at,created_by,updated_by)
  VALUES(p_site,v_actor,v_auth.session_id,v_key,v_hash,p_command->>'filename',p_command->>'content_type',v_bytes,p_command->>'checksum_sha256',
   p_admission->>'profile_ref',p_admission->>'profile_digest',p_admission,v_bytes,v_now+make_interval(secs=>(p_admission->>'reservation_ttl_seconds')::integer),v_actor,v_actor)
  RETURNING * INTO v_row;
  PERFORM public.reel_upload_event_v1(to_jsonb(v_row),'reserve');
  RETURN jsonb_build_object('data',public.reel_upload_public_v1(to_jsonb(v_row),false));
 END IF;
 IF p_command-ARRAY['idempotency_key','expected_version']<>'{}'::jsonb OR jsonb_typeof(p_command->'expected_version') IS DISTINCT FROM 'number' OR coalesce(p_command->>'expected_version','')!~'^[1-9][0-9]{0,8}$' THEN RAISE EXCEPTION 'REEL_UPLOAD_REQUEST_INVALID';END IF;
 SELECT * INTO v_row FROM public.reel_upload_intents WHERE id=p_intent AND site_id=p_site AND actor_id=v_actor FOR UPDATE;
 IF v_row.id IS NULL THEN RAISE EXCEPTION 'REEL_UPLOAD_NOT_FOUND';END IF;
 IF v_row.idempotency_key<>v_key THEN RAISE EXCEPTION 'REEL_UPLOAD_IDEMPOTENCY_CONFLICT';END IF;
 IF v_row.admission IS DISTINCT FROM p_admission THEN RAISE EXCEPTION 'REEL_UPLOAD_PROFILE_CHANGED';END IF;
 v_internal:=jsonb_build_object('object_nonce',v_row.object_nonce,'object_version',v_row.object_version,'profile_digest',v_row.profile_digest,
  'checksum_sha256',v_row.checksum_sha256,'size_bytes',v_row.size_bytes,'content_type',v_row.content_type);
 IF p_action IN('claim_transfer','claim_reconcile') THEN
  IF p_evidence IS NULL OR jsonb_typeof(p_evidence) IS DISTINCT FROM 'object' OR jsonb_typeof(p_evidence->'lease_token') IS DISTINCT FROM 'string' OR p_evidence-ARRAY['lease_token']<>'{}'::jsonb OR coalesce(p_evidence->>'lease_token','')!~'^[a-f0-9-]{36}$' THEN RAISE EXCEPTION 'REEL_UPLOAD_REQUEST_INVALID';END IF;
  IF v_row.state='received_unprocessed' THEN RETURN jsonb_build_object('data',public.reel_upload_public_v1(to_jsonb(v_row),true),'internal',v_internal);END IF;
  IF v_row.version<>(p_command->>'expected_version')::integer THEN RAISE EXCEPTION 'REEL_UPLOAD_VERSION_CONFLICT';END IF;
  IF v_row.state='expired' OR(p_action='claim_transfer' AND v_row.expires_at<=v_now) THEN
   IF v_row.state='reserved' THEN UPDATE public.reel_upload_intents SET state='expired',version=version+1,updated_at=v_now,updated_by=v_actor WHERE id=v_row.id RETURNING * INTO v_row;PERFORM public.reel_upload_event_v1(to_jsonb(v_row),'expire');END IF;
   RETURN jsonb_build_object('status',409,'error','REEL_UPLOAD_EXPIRED','data',public.reel_upload_public_v1(to_jsonb(v_row),false));
  END IF;
  IF v_row.state='receiving' AND v_row.lease_expires_at>v_now THEN RAISE EXCEPTION 'REEL_UPLOAD_BUSY';END IF;
  IF p_action='claim_reconcile' AND v_row.state='reserved' THEN RAISE EXCEPTION 'REEL_UPLOAD_OBJECT_UNCONFIRMED';END IF;
  UPDATE public.reel_upload_intents SET state='receiving',version=version+1,
   lease_sha256=encode(sha256(convert_to(p_evidence->>'lease_token','UTF8')),'hex'),
   lease_expires_at=v_now+make_interval(secs=>(p_admission->>'lease_seconds')::integer),last_error_code=NULL,
   updated_at=v_now,updated_by=v_actor WHERE id=v_row.id RETURNING * INTO v_row;
  PERFORM public.reel_upload_event_v1(to_jsonb(v_row),'claim');
  RETURN jsonb_build_object('data',public.reel_upload_public_v1(to_jsonb(v_row),false),'internal',v_internal);
 END IF;
 IF p_action='finish' THEN
  IF p_evidence IS NULL OR jsonb_typeof(p_evidence) IS DISTINCT FROM 'object'
   OR p_evidence-ARRAY['lease_token','object_key','object_version','actual_bytes','actual_sha256','content_type','profile_digest','verification_scope']<>'{}'::jsonb
   OR jsonb_typeof(p_evidence->'lease_token') IS DISTINCT FROM 'string'
   OR EXISTS(SELECT 1 FROM unnest(ARRAY['object_key','object_version','actual_sha256','content_type','profile_digest','verification_scope']) fields(name) WHERE jsonb_typeof(p_evidence->fields.name) IS DISTINCT FROM 'string')
   OR p_evidence->>'verification_scope' IS DISTINCT FROM 'r2-private-original-bytes-v1'
   OR p_evidence->>'object_key' IS DISTINCT FROM 'private-reel-originals/'||p_site::text||'/'||v_row.id::text||'/'||v_row.object_nonce::text
   OR p_evidence->>'profile_digest' IS DISTINCT FROM v_row.profile_digest
   OR p_evidence->>'actual_sha256' IS DISTINCT FROM v_row.checksum_sha256
   OR p_evidence->>'content_type' IS DISTINCT FROM v_row.content_type
   OR jsonb_typeof(p_evidence->'actual_bytes') IS DISTINCT FROM 'number' OR coalesce(p_evidence->>'actual_bytes','')!~'^[1-9][0-9]{0,15}$'
   OR(p_evidence->>'actual_bytes')::numeric IS DISTINCT FROM v_row.size_bytes::numeric
   OR coalesce(p_evidence->>'object_version','')!~'^[A-Za-z0-9._:-]{1,196}$' THEN RAISE EXCEPTION 'REEL_UPLOAD_CUSTODY_PROOF_INVALID';END IF;
  v_proof_hash:=encode(sha256(convert_to((p_evidence-'lease_token')::text,'UTF8')),'hex');
  IF v_row.state='received_unprocessed' THEN
   IF v_row.completion_sha256 IS DISTINCT FROM v_proof_hash OR v_row.object_version IS DISTINCT FROM p_evidence->>'object_version' THEN RAISE EXCEPTION 'REEL_UPLOAD_COMPLETION_CONFLICT';END IF;
   -- Replay must still have the exact private canonical record pair; the live
   -- session/actor/site/staff checks above always precede this receipt path.
   IF NOT EXISTS(SELECT 1 FROM public.media_assets m JOIN public.reel_asset_provenance p ON p.media_asset_id=m.id
    WHERE m.id=v_row.media_asset_id AND p.id=v_row.provenance_id AND m.site_id=p_site AND p.site_id=p_site
     AND m.public_url IS NULL AND m.deleted_at IS NULL AND p.deleted_at IS NULL AND m.processing_status='pending'
     AND m.checksum_sha256=v_row.checksum_sha256 AND p.checksum_sha256=v_row.checksum_sha256
     AND m.asset_type='video' AND m.storage_provider='r2' AND m.object_key=p_evidence->>'object_key' AND m.storage_path=p_evidence->>'object_key'
     AND m.filename=v_row.filename AND m.content_type=v_row.content_type AND m.size_bytes=v_row.size_bytes AND m.source_channel='web'
     AND m.created_by=v_row.actor_id AND p.created_by=v_row.actor_id AND p.updated_by=v_row.actor_id AND p.kind='video'
     AND m.metadata=jsonb_build_object('source','private-reel-intake','object_version',v_row.object_version,'profile_digest',v_row.profile_digest)
     AND p.custody_verified_at<=clock_timestamp() AND p.asset_version='r2:'||v_row.object_version AND p.provider_asset_id IS NULL) THEN RAISE EXCEPTION 'REEL_UPLOAD_RECEIPT_UNAVAILABLE';END IF;
   RETURN jsonb_build_object('data',public.reel_upload_public_v1(to_jsonb(v_row),true));
  END IF;
  IF v_row.state<>'receiving' OR v_row.version<>(p_command->>'expected_version')::integer OR v_row.lease_expires_at<=v_now
   OR v_row.lease_sha256 IS DISTINCT FROM encode(sha256(convert_to(coalesce(p_evidence->>'lease_token',''),'UTF8')),'hex') THEN RAISE EXCEPTION 'REEL_UPLOAD_LEASE_CONFLICT';END IF;
  INSERT INTO public.media_assets(store_id,site_id,asset_type,storage_provider,storage_path,object_key,public_url,filename,content_type,size_bytes,
   checksum_sha256,processing_status,source_channel,metadata,created_by)
  VALUES(p_site,p_site,'video','r2',p_evidence->>'object_key',p_evidence->>'object_key',NULL,v_row.filename,v_row.content_type,v_row.size_bytes,
   v_row.checksum_sha256,'pending','web',jsonb_build_object('source','private-reel-intake','object_version',p_evidence->>'object_version','profile_digest',v_row.profile_digest),v_actor)
  RETURNING id INTO v_media;
  INSERT INTO public.reel_asset_provenance(site_id,media_asset_id,asset_version,checksum_sha256,kind,provider_asset_id,custody_verified_at,created_by,updated_by)
  VALUES(p_site,v_media,'r2:'||(p_evidence->>'object_version'),v_row.checksum_sha256,'video',NULL,v_now,v_actor,v_actor) RETURNING id INTO v_provenance;
  UPDATE public.reel_upload_intents SET state='received_unprocessed',version=version+1,media_asset_id=v_media,provenance_id=v_provenance,
   object_version=p_evidence->>'object_version',completion_sha256=v_proof_hash,lease_sha256=NULL,lease_expires_at=NULL,last_error_code=NULL,
   updated_at=v_now,updated_by=v_actor WHERE id=v_row.id RETURNING * INTO v_row;
  PERFORM public.reel_upload_event_v1(to_jsonb(v_row),'receive');
  RETURN jsonb_build_object('data',public.reel_upload_public_v1(to_jsonb(v_row),false));
 END IF;
 IF p_action='unknown' THEN
  IF p_evidence IS NULL OR jsonb_typeof(p_evidence) IS DISTINCT FROM 'object' OR jsonb_typeof(p_evidence->'lease_token') IS DISTINCT FROM 'string' OR p_evidence-ARRAY['lease_token']<>'{}'::jsonb THEN RAISE EXCEPTION 'REEL_UPLOAD_REQUEST_INVALID';END IF;
  IF v_row.state='received_unprocessed' THEN RETURN jsonb_build_object('data',public.reel_upload_public_v1(to_jsonb(v_row),true));END IF;
  IF v_row.state<>'receiving' OR v_row.version<>(p_command->>'expected_version')::integer
   OR v_row.lease_sha256 IS DISTINCT FROM encode(sha256(convert_to(coalesce(p_evidence->>'lease_token',''),'UTF8')),'hex') THEN RAISE EXCEPTION 'REEL_UPLOAD_LEASE_CONFLICT';END IF;
  UPDATE public.reel_upload_intents SET state='transfer_unknown',version=version+1,lease_sha256=NULL,lease_expires_at=NULL,
   last_error_code='REEL_UPLOAD_TRANSFER_UNCERTAIN',updated_at=v_now,updated_by=v_actor WHERE id=v_row.id RETURNING * INTO v_row;
  PERFORM public.reel_upload_event_v1(to_jsonb(v_row),'uncertain');
  RETURN jsonb_build_object('data',public.reel_upload_public_v1(to_jsonb(v_row),false));
 END IF;
 RAISE EXCEPTION 'REEL_UPLOAD_REQUEST_INVALID';
END

DECLARE s public.sites%ROWTYPE;b public.billing_history%ROWTYPE;
BEGIN
 SELECT * INTO s FROM public.sites WHERE id=p_site AND deleted_at IS NULL FOR SHARE;
 IF NOT FOUND OR NOT coalesce(p_actor=s.custom_user_id OR p_actor=s.user_id,false) THEN RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_OWNER_REQUIRED');END IF;
 SELECT * INTO b FROM public.billing_history WHERE site_id=p_site AND user_id=p_actor AND subscription_checkout_key=p_key;
 IF NOT FOUND THEN RETURN jsonb_build_object('accepted',true,'missing',true);END IF;
 IF b.deleted_at IS NOT NULL OR b.subscription_checkout_request IS DISTINCT FROM p_request THEN RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_CHECKOUT_CONFLICT');END IF;
 IF b.amount>0 AND NOT public.valid_subscription_tax_snapshot_360(b.subscription_tax_snapshot) THEN RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_TAX_REVIEW_REQUIRED');END IF;
 RETURN jsonb_build_object('accepted',true,'claimed',false,'charge',to_jsonb(b));
END

DECLARE s public.subscriptions%ROWTYPE;o public.sites%ROWTYPE;b public.billing_history%ROWTYPE;prior public.billing_history%ROWTYPE;source public.billing_history%ROWTYPE;
 actor uuid;site uuid;sub uuid;pay text;status text;started timestamptz;finished timestamptz;
BEGIN
 -- Internal provider notifications resolve through their immutable payment
 -- source. Derive actor/site/cycle here, then take the existing current-owner
 -- lock and compare every amount/period below. No caller-supplied tenant wins.
 IF nullif(btrim(p_input->>'external_subscription_id'),'') IS NOT NULL THEN
  SELECT * INTO b FROM public.billing_history WHERE payment_gateway=p_input->>'payment_gateway' AND payment_id=p_input->>'payment_id' AND deleted_at IS NULL;
  IF NOT FOUND THEN RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_TAX_REVIEW_REQUIRED');END IF;
  IF (SELECT count(*) FROM public.billing_history WHERE payment_gateway=p_input->>'payment_gateway' AND payment_id=p_input->>'payment_id' AND deleted_at IS NULL)<>1 THEN
   RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_PAYMENT_CONFLICT');END IF;
  SELECT * INTO s FROM public.subscriptions WHERE id=b.subscription_id AND external_subscription_id=p_input->>'external_subscription_id' AND deleted_at IS NULL;
  IF NOT FOUND THEN RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_CHECKOUT_CONFLICT');END IF;
  p_input:=p_input||jsonb_build_object('user_id',b.user_id,'store_id',b.site_id,'subscription_id',s.id,
   'invoice_number',coalesce(p_input->>'invoice_number',b.invoice_number),'description',coalesce(p_input->>'description',b.description),
   'period_start',coalesce(p_input->>'period_start',b.period_start::text),'period_end',coalesce(p_input->>'period_end',b.period_end::text));
 END IF;
 actor:=(p_input->>'user_id')::uuid;site:=(p_input->>'store_id')::uuid;sub:=(p_input->>'subscription_id')::uuid;
 pay:=nullif(btrim(p_input->>'payment_id'),'');status:=p_input->>'payment_status';started:=(p_input->>'period_start')::timestamptz;finished:=(p_input->>'period_end')::timestamptz;
 IF pay IS NULL OR length(pay)>200 OR status NOT IN('paid','failed') OR started IS NULL OR finished IS NULL OR finished<=started
  OR nullif(btrim(p_input->>'invoice_number'),'') IS NULL OR length(p_input->>'invoice_number')>80
  OR p_input->>'currency' IS DISTINCT FROM 'INR' THEN RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_CONTEXT_INVALID');END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('letbuyy:subscription:invoice:'||pay,0));
 SELECT * INTO o FROM public.sites WHERE id=site AND deleted_at IS NULL FOR UPDATE;
 IF NOT FOUND OR NOT coalesce(actor=o.custom_user_id OR actor=o.user_id,false) THEN RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_OWNER_REQUIRED');END IF;
 SELECT * INTO s FROM public.subscriptions WHERE id=sub AND deleted_at IS NULL FOR UPDATE;
 IF NOT FOUND OR s.user_id IS DISTINCT FROM actor OR s.store_id IS DISTINCT FROM site THEN RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_CHECKOUT_CONFLICT');END IF;
 SELECT * INTO prior FROM public.billing_history WHERE provider_payment_reference=pay OR (payment_gateway=p_input->>'payment_gateway' AND payment_id=pay);
 IF FOUND THEN
  IF prior.deleted_at IS NOT NULL OR prior.subscription_id IS DISTINCT FROM sub OR prior.site_id IS DISTINCT FROM site OR prior.user_id IS DISTINCT FROM actor
   OR prior.payment_gateway IS DISTINCT FROM p_input->>'payment_gateway' OR prior.currency IS DISTINCT FROM p_input->>'currency'
   OR prior.amount IS DISTINCT FROM (p_input->>'amount')::bigint OR prior.tax_amount IS DISTINCT FROM (p_input->>'tax_amount')::bigint
   OR prior.total_amount IS DISTINCT FROM (p_input->>'total_amount')::bigint OR prior.payment_status IS DISTINCT FROM status
   OR prior.invoice_number IS DISTINCT FROM p_input->>'invoice_number' OR prior.description IS DISTINCT FROM p_input->>'description'
   OR prior.period_start IS DISTINCT FROM started OR prior.period_end IS DISTINCT FROM finished
   OR (p_input->>'billing_period' IS NOT NULL AND prior.billing_period IS DISTINCT FROM p_input->>'billing_period') THEN
   RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_PAYMENT_CONFLICT');END IF;
  RETURN jsonb_build_object('accepted',true,'invoice',to_jsonb(prior),'replayed',true);
 END IF;
 SELECT * INTO source FROM public.billing_history WHERE id=s.subscription_tax_source_id FOR UPDATE;
 IF NOT FOUND OR NOT public.valid_subscription_tax_snapshot_360(source.subscription_tax_snapshot) THEN RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_TAX_REVIEW_REQUIRED');END IF;
 IF source.site_id IS DISTINCT FROM site OR source.user_id IS DISTINCT FROM actor OR source.subscription_tax_snapshot IS DISTINCT FROM s.subscription_tax_snapshot
  OR (p_input->>'amount')::bigint IS DISTINCT FROM source.amount OR (p_input->>'total_amount')::bigint IS DISTINCT FROM source.amount
  OR (p_input->>'tax_amount')::bigint IS DISTINCT FROM (source.subscription_tax_snapshot->>'tax_minor')::bigint
  OR p_input->>'payment_gateway' IS DISTINCT FROM source.payment_gateway
  OR (p_input->>'billing_period' IS NOT NULL AND p_input->>'billing_period' IS DISTINCT FROM source.billing_period) THEN
  RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_CHECKOUT_CONFLICT');END IF;
 -- A verified activation already owns each paid invoice. This ingress may read
 -- it but cannot invent another payment or renewal from arbitrary notification data.
 IF status='paid' THEN RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_CHECKOUT_CONFLICT');END IF;
 IF source.subscription_checkout->>'mode' IS DISTINCT FROM 'sandbox_activation' OR source.payment_status IS DISTINCT FROM 'pending'
  OR pay NOT LIKE 'sandbox_failed:%' OR source.subscription_checkout_request->>'sandbox_payment_status' IS DISTINCT FROM 'failed' THEN
  RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_CHECKOUT_CONFLICT');END IF;
 UPDATE public.billing_history SET subscription_id=sub,invoice_number=p_input->>'invoice_number',description=p_input->>'description',
  tax_amount=(subscription_tax_snapshot->>'tax_minor')::bigint,total_amount=amount,payment_id=pay,payment_status='failed',period_start=started,period_end=finished,updated_at=now()
 WHERE id=source.id RETURNING * INTO b;
 PERFORM public.issue_subscription_tax_invoice_360(b.id);
 RETURN jsonb_build_object('accepted',true,'invoice',to_jsonb(b),'replayed',false);
END

DECLARE writer text:=regexp_replace(current_setting('application_name',true),':347:360$',':360');b public.billing_history%ROWTYPE;t jsonb;
BEGIN
 IF TG_TABLE_NAME='billing_history' THEN
  IF NEW.amount<=0 OR (NEW.subscription_checkout IS NULL AND NEW.subscription_id IS NULL AND NEW.subscription_tax_snapshot IS NULL) THEN RETURN NEW;END IF;
  IF writer IS NULL OR writer NOT IN('claim_merchant_subscription_checkout_v1:360','activate_merchant_subscription_v1:360','record_merchant_subscription_invoice_v1:360') THEN
   RAISE EXCEPTION 'positive subscription history requires the current canonical writer';END IF;
  t:=NEW.subscription_tax_snapshot;
  IF NOT public.valid_subscription_tax_snapshot_360(t) OR NEW.amount IS DISTINCT FROM (t->>'gross_minor')::bigint
   OR NEW.total_amount IS DISTINCT FROM NEW.amount OR NEW.currency IS DISTINCT FROM 'INR'
   OR t->'source'->>'actor_id' IS DISTINCT FROM NEW.user_id::text OR t->'source'->>'site_id' IS DISTINCT FROM NEW.site_id::text
   OR t->'source'->>'billing_period' IS DISTINCT FROM NEW.billing_period THEN RAISE EXCEPTION 'positive subscription history lacks its exact tax source';END IF;
  IF writer='claim_merchant_subscription_checkout_v1:360' THEN
   IF NEW.subscription_tax_source_id IS DISTINCT FROM NEW.id OR NEW.subscription_id IS NOT NULL OR NEW.payment_status IS DISTINCT FROM 'pending'
    OR t->'source'->>'request_key' IS DISTINCT FROM NEW.subscription_checkout_key
    OR NEW.subscription_checkout->'subscription_tax_snapshot' IS DISTINCT FROM t THEN RAISE EXCEPTION 'subscription quote source identity is invalid';END IF;
  ELSE
   SELECT * INTO b FROM public.billing_history WHERE id=NEW.subscription_tax_source_id;
   IF NOT FOUND OR (b.subscription_tax_snapshot IS DISTINCT FROM t AND (b.subscription_checkout->>'mode' IS DISTINCT FROM 'razorpay_subscription' OR b.subscription_checkout->'recurring_tax_snapshot' IS DISTINCT FROM t)) OR b.site_id IS DISTINCT FROM NEW.site_id OR b.user_id IS DISTINCT FROM NEW.user_id THEN
    RAISE EXCEPTION 'subscription cycle requires its retained quote source';END IF;
  END IF;
 ELSE
  IF coalesce(NEW.amount_paid,0)<=0 THEN RETURN NEW;END IF;
  IF writer IS NULL OR writer NOT IN('activate_merchant_subscription_v1:360','record_merchant_subscription_failure_v1:360') THEN
   RAISE EXCEPTION 'positive subscription requires the current canonical activation writer';END IF;
  SELECT * INTO b FROM public.billing_history WHERE id=NEW.subscription_tax_source_id;
  IF NOT FOUND OR b.deleted_at IS NOT NULL OR NOT public.valid_subscription_tax_snapshot_360(b.subscription_tax_snapshot)
   OR (NEW.subscription_tax_snapshot IS DISTINCT FROM b.subscription_tax_snapshot AND (b.subscription_checkout->>'mode' IS DISTINCT FROM 'razorpay_subscription' OR b.subscription_checkout->'recurring_tax_snapshot' IS DISTINCT FROM NEW.subscription_tax_snapshot)) OR NEW.amount_paid IS DISTINCT FROM (NEW.subscription_tax_snapshot->>'gross_minor')::bigint
   OR NEW.currency IS DISTINCT FROM 'INR' OR NEW.user_id IS DISTINCT FROM b.user_id OR NEW.site_id IS DISTINCT FROM b.site_id
   OR NEW.store_id IS DISTINCT FROM b.store_id OR NEW.plan_id::text IS DISTINCT FROM b.subscription_tax_snapshot->'source'->>'plan_id'
   OR NEW.plan IS DISTINCT FROM b.subscription_tax_snapshot->'source'->>'plan_slug' OR NEW.billing_period IS DISTINCT FROM b.billing_period THEN
   RAISE EXCEPTION 'positive subscription lacks its exact retained tax source';END IF;
 END IF;
 RETURN NEW;
END

DECLARE o public.sites%ROWTYPE;b public.billing_history%ROWTYPE;sub public.subscriptions%ROWTYPE;v jsonb;actor uuid;site uuid;pay text;
BEGIN
 actor:=(p_input->>'user_id')::uuid;site:=(p_input->>'store_id')::uuid;pay:=p_input->>'payment_id';
 IF pay IS NULL OR length(pay)>200 THEN RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_CONTEXT_INVALID');END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('letbuyy:subscription:invoice:'||pay,0));
 SELECT * INTO o FROM public.sites WHERE id=site AND deleted_at IS NULL FOR UPDATE;
 IF NOT FOUND OR NOT coalesce(actor=o.custom_user_id OR actor=o.user_id,false) THEN RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_OWNER_REQUIRED');END IF;
 SELECT * INTO b FROM public.billing_history WHERE id=(p_input->>'source_id')::uuid FOR UPDATE;
 IF NOT FOUND OR b.deleted_at IS NOT NULL OR b.site_id IS DISTINCT FROM site OR b.user_id IS DISTINCT FROM actor
  OR NOT public.valid_subscription_tax_snapshot_360(b.subscription_tax_snapshot)
  OR b.subscription_checkout->>'mode' IS DISTINCT FROM 'sandbox_activation'
  OR b.subscription_checkout_request->>'sandbox_payment_status' IS DISTINCT FROM 'failed'
  OR pay IS DISTINCT FROM 'sandbox_failed:'||b.subscription_checkout_key THEN RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_CHECKOUT_CONFLICT');END IF;
 IF b.subscription_id IS NOT NULL THEN
  SELECT * INTO sub FROM public.subscriptions WHERE id=b.subscription_id;
  IF b.payment_status IS DISTINCT FROM 'failed' OR sub.store_id IS DISTINCT FROM site OR sub.user_id IS DISTINCT FROM actor THEN RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_CHECKOUT_CONFLICT');END IF;
  RETURN jsonb_build_object('accepted',true,'subscription',to_jsonb(sub),'invoice',to_jsonb(b),'replayed',true);
 END IF;
 IF b.payment_status IS DISTINCT FROM 'pending' OR NOT EXISTS(SELECT 1 FROM public.plans p WHERE p.id=(b.subscription_checkout->'plan'->>'id')::uuid AND p.is_active)
  OR (p_input->>'period_end')::timestamptz<=(p_input->>'period_start')::timestamptz THEN RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_CONTEXT_INVALID');END IF;
 INSERT INTO public.subscriptions(user_id,store_id,site_id,plan,plan_id,status,billing_period,current_period_start,current_period_end,
  payment_gateway,external_subscription_id,amount_paid,currency,mandate_id,idempotency_key,dunning_status,dunning_attempts,next_dunning_at,subscription_tax_snapshot,subscription_tax_source_id)
 VALUES(actor,site,site,b.subscription_checkout->'plan'->>'slug',(b.subscription_checkout->'plan'->>'id')::uuid,'past_due',b.billing_period,
  (p_input->>'period_start')::timestamptz,(p_input->>'period_end')::timestamptz,'razorpay',b.subscription_checkout_reference,b.amount,'INR',
  nullif(p_input->>'mandate_id','')::uuid,b.subscription_checkout_key,p_input->>'dunning_status',(p_input->>'dunning_attempts')::integer,
  nullif(p_input->>'next_dunning_at','')::timestamptz,b.subscription_tax_snapshot,b.id) RETURNING * INTO sub;
 v:=public.record_merchant_subscription_invoice_v1(jsonb_build_object('user_id',actor,'store_id',site,'subscription_id',sub.id,
  'invoice_number',p_input->>'invoice_number','description',p_input->>'description','amount',b.amount,'currency','INR',
  'tax_amount',(b.subscription_tax_snapshot->>'tax_minor')::bigint,'total_amount',b.amount,'payment_gateway','razorpay','payment_id',pay,
  'payment_status','failed','billing_period',b.billing_period,'period_start',p_input->>'period_start','period_end',p_input->>'period_end'));
 IF v->>'accepted' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'canonical failed invoice source unavailable';END IF;
 RETURN jsonb_build_object('accepted',true,'subscription',to_jsonb(sub),'invoice',v->'invoice','replayed',false);
END

DECLARE b public.billing_history%ROWTYPE;t jsonb;
BEGIN
 IF TG_TABLE_SCHEMA<>'public' OR TG_TABLE_NAME<>'merchant_billing_invoices' THEN RAISE EXCEPTION 'unexpected subscription tax invoice retention relation';END IF;
 IF TG_OP='TRUNCATE' THEN
  IF EXISTS(SELECT 1 FROM public.merchant_billing_invoices i LEFT JOIN public.billing_history h ON h.id=i.billing_history_id
   WHERE i.metadata->>'policy_version'='D-SUB-TAX-INCLUSIVE-V1' OR i.metadata?'provider_invoice'
    OR h.subscription_tax_snapshot IS NOT NULL OR (h.amount>0 AND h.subscription_id IS NOT NULL)) THEN
   RAISE EXCEPTION 'retained subscription billing documents cannot be truncated';END IF;
  RETURN NULL;
 END IF;
 IF TG_OP<>'INSERT' THEN
  IF EXISTS(SELECT 1 FROM public.billing_history WHERE id=OLD.billing_history_id AND subscription_tax_snapshot IS NOT NULL) THEN RAISE EXCEPTION 'issued subscription tax invoice is immutable';END IF;
  IF TG_OP='DELETE' THEN
   IF EXISTS(SELECT 1 FROM public.billing_history h WHERE h.id=OLD.billing_history_id AND h.amount>0 AND h.subscription_id IS NOT NULL) THEN
    RAISE EXCEPTION 'retained subscription billing document is immutable';END IF;
   RETURN OLD;
  END IF;
 END IF;
 SELECT * INTO b FROM public.billing_history WHERE id=NEW.billing_history_id;t:=b.subscription_tax_snapshot;
 IF t IS NULL AND NEW.metadata->>'policy_version'='D-SUB-TAX-INCLUSIVE-V1' THEN RAISE EXCEPTION 'tax invoice metadata requires its canonical history source';END IF;
 IF t IS NULL AND EXISTS(SELECT 1 FROM public.subscriptions WHERE id=NEW.subscription_id AND subscription_tax_snapshot IS NOT NULL) THEN RAISE EXCEPTION 'tax-backed subscription invoice requires canonical tax history';END IF;
 IF t IS NOT NULL AND (NOT public.valid_subscription_tax_snapshot_360(t) OR b.payment_status NOT IN('paid','failed')
  OR NEW.site_id IS DISTINCT FROM b.site_id OR NEW.subscription_id IS DISTINCT FROM b.subscription_id OR NEW.invoice_number IS DISTINCT FROM b.invoice_number
  OR NEW.currency IS DISTINCT FROM 'INR' OR NEW.subtotal_minor IS DISTINCT FROM (t->>'taxable_minor')::bigint
  OR NEW.cgst_minor IS DISTINCT FROM (t->>'cgst_minor')::bigint OR NEW.sgst_minor IS DISTINCT FROM (t->>'sgst_minor')::bigint
  OR NEW.igst_minor IS DISTINCT FROM (t->>'igst_minor')::bigint OR NEW.total_minor IS DISTINCT FROM b.amount
  OR NEW.period_start IS DISTINCT FROM b.period_start OR NEW.period_end IS DISTINCT FROM b.period_end
  OR NEW.status IS DISTINCT FROM CASE WHEN b.payment_status='paid' THEN 'issued' ELSE 'payment_failed' END
  OR NEW.metadata->>'source_id' IS DISTINCT FROM b.id::text OR NEW.metadata->>'basis' IS DISTINCT FROM 'inclusive'
  OR NEW.metadata->>'policy_version' IS DISTINCT FROM 'D-SUB-TAX-INCLUSIVE-V1') THEN RAISE EXCEPTION 'subscription tax invoice differs from canonical source';END IF;
 IF NEW.metadata?'provider_invoice' AND (
  t IS NULL OR b.payment_status IS DISTINCT FROM 'paid' OR jsonb_typeof(NEW.metadata->'provider_invoice') IS DISTINCT FROM 'object'
  OR NOT coalesce((NEW.metadata->'provider_invoice'->>'invoice_id')~'^inv_[A-Za-z0-9]{1,116}$',false)
  OR NEW.metadata->'provider_invoice'->>'payment_id' IS DISTINCT FROM b.provider_payment_reference
  OR NEW.metadata->'provider_invoice'->>'gross_minor' IS DISTINCT FROM b.amount::text
  OR (NEW.metadata->'provider_invoice'->>'period_start')::timestamptz IS DISTINCT FROM b.period_start
  OR (NEW.metadata->'provider_invoice'->>'period_end')::timestamptz IS DISTINCT FROM b.period_end
  OR NOT EXISTS(SELECT 1 FROM public.billing_history origin WHERE origin.id=b.subscription_tax_source_id
   AND origin.subscription_checkout->>'mode'='razorpay_subscription' AND origin.subscription_checkout_reference=NEW.metadata->'provider_invoice'->>'subscription_reference'
   AND ((NEW.metadata->'provider_invoice'->>'phase'='initial_with_upfront' AND origin.id=b.id AND origin.subscription_tax_snapshot=t
         AND (origin.subscription_checkout->'charge_schedule'->>'upfront_gross_minor')::bigint>0)
     OR (NEW.metadata->'provider_invoice'->>'phase'='base_cycle' AND origin.subscription_checkout->'recurring_tax_snapshot'=t)))) THEN
  RAISE EXCEPTION 'provider invoice evidence differs from its immutable billing source';END IF;
 RETURN NEW;
END

DECLARE ref text:=nullif(btrim(p_input->>'external_subscription_id'),'');state text:=p_input->>'status';site uuid;
 o public.sites%ROWTYPE;s public.subscriptions%ROWTYPE;b public.billing_history%ROWTYPE;started timestamptz;finished timestamptz;
BEGIN
 IF ref IS NULL OR length(ref)>200 OR state IS NULL OR state NOT IN('active','cancelled','past_due','trialing') THEN
  RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_CONTEXT_INVALID');END IF;
 IF p_input->>'current_period_start' IS NOT NULL THEN started:=(p_input->>'current_period_start')::timestamptz;END IF;
 IF p_input->>'current_period_end' IS NOT NULL THEN finished:=(p_input->>'current_period_end')::timestamptz;END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('letbuyy:subscription:status:'||ref,0));
 SELECT store_id INTO site FROM public.subscriptions WHERE external_subscription_id=ref AND deleted_at IS NULL
  ORDER BY current_period_start DESC NULLS LAST,created_at DESC,id DESC LIMIT 1;
 IF NOT FOUND THEN RETURN jsonb_build_object('accepted',true,'subscription',NULL);END IF;
 SELECT * INTO o FROM public.sites WHERE id=site AND deleted_at IS NULL FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_OWNER_REQUIRED');END IF;
 -- Cached frames waiting behind retirement must observe the current binding.
 IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.sync_merchant_subscription_state_v1(jsonb)')
  AND 'application_name=sync_merchant_subscription_state_v1:360'=ANY(proconfig)) THEN
  RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_CONTEXT_INVALID');END IF;
 SELECT * INTO s FROM public.subscriptions WHERE external_subscription_id=ref AND store_id=site AND deleted_at IS NULL
  ORDER BY current_period_start DESC NULLS LAST,created_at DESC,id DESC LIMIT 1 FOR UPDATE;
 IF NOT FOUND OR s.site_id IS DISTINCT FROM site OR NOT coalesce(s.user_id=o.custom_user_id OR s.user_id=o.user_id,false) THEN
  RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_OWNER_REQUIRED');END IF;
 -- An external reference may never ambiguously select another tenant/actor.
 IF EXISTS(SELECT 1 FROM public.subscriptions x WHERE x.external_subscription_id=ref AND x.deleted_at IS NULL
  AND (x.store_id IS DISTINCT FROM site OR x.site_id IS DISTINCT FROM site OR x.user_id IS DISTINCT FROM s.user_id)) THEN
  RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_CHECKOUT_CONFLICT');END IF;
 IF (started IS NOT NULL AND started IS DISTINCT FROM s.current_period_start)
  OR (finished IS NOT NULL AND finished IS DISTINCT FROM s.current_period_end) THEN
  RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_CHECKOUT_CONFLICT');END IF;
 IF s.subscription_tax_snapshot IS NOT NULL THEN
  SELECT * INTO b FROM public.billing_history WHERE id=s.subscription_tax_source_id FOR SHARE;
  IF NOT FOUND OR b.deleted_at IS NOT NULL OR b.subscription_id IS DISTINCT FROM s.id OR b.site_id IS DISTINCT FROM site
   OR b.user_id IS DISTINCT FROM s.user_id OR b.payment_status IS DISTINCT FROM 'paid'
   OR b.subscription_tax_snapshot IS DISTINCT FROM s.subscription_tax_snapshot OR NOT public.valid_subscription_tax_snapshot_360(b.subscription_tax_snapshot)
   OR b.amount IS DISTINCT FROM s.amount_paid OR b.currency IS DISTINCT FROM s.currency
   OR b.period_start IS DISTINCT FROM s.current_period_start OR b.period_end IS DISTINCT FROM s.current_period_end THEN
   RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_TAX_REVIEW_REQUIRED');END IF;
 END IF;
 UPDATE public.subscriptions SET status=state,cancelled_at=CASE WHEN state='cancelled' THEN coalesce(cancelled_at,now()) ELSE NULL END,
  updated_at=now() WHERE id=s.id RETURNING * INTO s;
 RETURN jsonb_build_object('accepted',true,'subscription',to_jsonb(s));
EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN
 RETURN jsonb_build_object('accepted',false,'code','SUBSCRIPTION_CONTEXT_INVALID');
END

BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'app_tenant' OR current_setting('session_replication_role') IS DISTINCT FROM 'origin'
